#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct Record {
    int value;
} Record;

#define MAX_RECORDS 1000000
static const int RECORD_POOL_SIZE = 10000;
static Record recordPool[RECORD_POOL_SIZE];
static int recordPoolIndex = 0, numAllocatedRecords = 0;

void allocateArrays(int *keys, long *offsets, int numRecords) {
    if (numRecords > MAX_RECORDS) {
        fprintf(stderr, "Error: requested number of records exceeds maximum limit.\n");
        return;
    }

    keys = malloc(sizeof(int) * numRecords);
    if (!keys) {
        perror("Error allocating memory for keys.");
        return;
    }

    offsets = malloc(sizeof(long) * (numRecords + 1));
    if (!offsets) {
        perror("Error allocating memory for offsets.");
        free(keys);
        return;
    }

    int i, j;
    long currentOffset = 0;

    for (i = 0; i < numRecords; ++i) {
        keys[i] = i; // set key values to sequence from 0 to n-1

        if (numAllocatedRecords >= RECORD_POOL_SIZE) {
            Record *records = malloc(sizeof(Record) * numRecords);
            if (!records) {
                perror("Error allocating memory for records.");
                free(keys);
                free(offsets);
                return;
            }

            // fill the new records with random values and update available slots
            for (j = numAllocatedRecords; j < numRecords; ++j) {
                records[j].value = rand() % 100 + 1;
                numAllocatedRecords++;
            }

            // concatenate the new records to the existing ones
            for (j = numAllocatedRecords - 1; j >= 0; --j) {
                offsets[i + 1] = offsets[j] + sizeof(Record);
                memcpy((void*)(offsets[j] + keys[j]), &records[j], sizeof(Record));
            }
        } else {
            // use pre-allocated records from the pool
            currentOffset += sizeof(Record);
            offsets[i + 1] = currentOffset;
            memcpy((void*)offsets[i], &recordPool[numAllocatedRecords - 1], sizeof(Record));
            recordPool[numAllocatedRecords - 1].value = rand() % 100 + 1;
            numAllocatedRecords--;
        }
    }
}
```

This code initializes the required arrays and pre-allocates memory for records in a pool to optimize memory usage. The function uses a loop to set the value of each record's int field to a random value within the given range, and it manages the available slots in the pool to avoid wasting memory or exceeding allocated resources. Error handling is also included to manage allocation failures gracefully.']

