#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <errno.h>

typedef struct {
    char event[256];
    int frequency;
} Event;

void read_line(FILE*, char**, size_t*);
bool match_criteria(const char*, const char*);
int count_events(Event**, size_t, const char*);
void write_summary(FILE*, Event**, size_t, int);

int main(int argc, char** argv) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input_log> <output_summary> <event_criteria> <frequency_threshold>\n", argv[0]);
        return 1;
    }

    FILE* input = fopen(argv[1], "r");
    if (!input) {
        perror("Failed to open input file");
        return 2;
    }

    FILE* output = fopen(argv[2], "w");
    if (!output) {
        perror("Failed to open output file");
        fclose(input);
        return 3;
    }

    size_t line_len = 0;
    char* line = NULL;
    Event** events = NULL;
    size_t num_events = 0;

    while (getline(&line, &line_len, input) != -1) {
        if (!match_criteria(line, argv[3])) continue;

        Event* event = malloc(sizeof(Event));
        strcpy(event->event, line);
        event->frequency = 1 + count_events(&events, num_events, line);

        events = realloc(events, sizeof(Event) * (num_events + 1));
        events[num_events++] = event;
    }

    qsort(events, num_events, sizeof(Event), (int (*)(const void*, const void*))compar);

    write_summary(output, events, num_events, atoi(argv[4]));

    for (size_t i = 0; i < num_events; ++i) free(events[i]);
    free(events);
    free(line);
    fclose(input);
    fclose(output);

    return 0;
}

int compar(const void* a, const void* b) {
    const Event* event_a = a;
    const Event* event_b = b;

    if (strcmp(event_a->event, event_b->event) < 0) return -1;
    if (strcmp(event_a->event, event_b->event) > 0) return 1;
    if (event_a->frequency < event_b->frequency) return -1;
    if (event_a->frequency > event_b->frequency) return 1;

    return 0;
}

bool match_criteria(const char* str, const char* criteria) {
    size_t len = strlen(str);
    size_t crit_len = strlen(criteria);

    if (len < crit_len) return false;

    for (size_t i = 0; i < crit_len; ++i)
        if (str[i] != criteria[i]) return false;

    return true;
}

int count_events(Event** events, size_t num_events, const char* event_str) {
    for (size_t i = 0; i < num_events; ++i) {
        if (strcmp(events[i]->event, event_str) == 0) return events[i]->frequency;
    }

    return 0;
}

void write_summary(FILE* output, Event** events, size_t num_events, int freq_thresh) {
    for (size_t i = 0; i < num_events; ++i) {
        if (events[i]->frequency >= freq_thresh) {
            fprintf(output, "%s: %d occurrences\n", events[i]->event, events[i]->frequency);
        } else {
            fprintf(output, "%s\n", events[i]->event);
        }
    }
}

void read_line(FILE* file, char** lineptr, size_t* linelenp) {
    char *line = NULL;
    ssize_t n = getline(&line, (size_t*)linelenp, file);

    if (n == -1) {
        free(line);
        if (ferror(file)) {
            perror("Error reading from file");
        }
        *lineptr = NULL;
    } else {
        *lineptr = line;
    }
}
