```c
#include <arpa/inet.h>
#include <curl/curl.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>

// Rate limiting constants
const unsigned int MAX_QUERIES = 10; // Maximum number of simultaneous DNS queries
const unsigned long long RATE_LIMIT_INTERVAL_MS = 1000; // Interval in milliseconds for rate limiting
pthread_rwlock_t rwlock;
unsigned int num_queries = 0;

CURLcode curl_easy_init(CURL **curl, const char *hostname);
void curl_easy_cleanup(CURL *curl);
size_t write_function(void *ptr, size_t size, size_t nmemb, void *userdata);
int resolve_dns(const char *hostname, u_char **ip_addr);

// Rate limiting function
bool rate_limited() {
    pthread_rwlock_wrlock(&rwlock);
    if (num_queries >= MAX_QUERIES) {
        pthread_rwlock_unlock(&rwlock);
        usleep(RATE_LIMIT_INTERVAL_MS * 1000); // Sleep for the rate limit interval
        pthread_rwlock_wrlock(&rwlock);
    }
    num_queries++;
    int ret = num_queries >= MAX_QUERIES;
    pthread_rwlock_unlock(&rwlock);
    return ret;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <hostname>\n", argv[0]);
        return EXIT_FAILURE;
    }

    pthread_rwlock_init(&rwlock, NULL);

    u_char ip_addr[INET6_ADDRSTRLEN];
    if (resolve_dns(argv[1], &ip_addr)) {
        fprintf(stderr, "Error resolving DNS: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("IP address for %s: %s\n", argv[1], inet_ntop(AF_INET6, ip_addr, NULL, sizeof(ip_addr)));

    pthread_rwlock_destroy(&rwlock);
    return EXIT_SUCCESS;
}

// DNS resolution function using libcurl
int resolve_dns(const char *hostname, u_char **ip_addr) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init(&curl);
    if (!curl) {
        fprintf(stderr, "Unable to initialize libcurl\n");
        return -1;
    }

    if (rate_limited()) {
        curl_easy_cleanup(curl);
        return -2; // Rate limited error code
    }

    res = curl_easy_setopt(curl, CURLOPT_URL, "http://www.google.com/dns-query");
    if (res != CURLE_OK) {
        fprintf(stderr, "Error setting URL: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -3;
    }

    res = curl_easy_setopt(curl, CURLOPT_POSTFIELDS, hostname);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error setting postfields: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -4;
    }

    res = curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_function);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error setting write function: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -5;
    }

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error performing DNS query: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -6;
    }

    curl_easy_cleanup(curl);

    // Extract the IP address from the response and store it in ip_addr
    // This example assumes that the response contains a single IPv6 address.
    // You may need to modify this code for different use-cases or response formats.

    return 0;
}
```

This code uses libcurl for DNS resolution and pthread for concurrency, but it does not handle UDP communication directly since it relies on an HTTP endpoint that performs DNS queries. To integrate with an existing network service using UDP, you may need to modify the URL in the `CURLOPT_URL` option or implement a custom UDP-based DNS client. Additionally, you will likely want to use performance optimization techniques such as caching resolved IP addresses and fine-tuning the rate limiting to accommodate your specific use case.']

