typedef enum { DEBUG, INFO, WARNING, ERROR } LogLevel;

// Custom logging struct for thread safety and configurable parameters
struct Logger {
    pthread_mutex_t lock;
    char *remote_server_ip;
    int remote_server_port;
    int max_log_size;
    FILE *file; // For local logging
    socket_t asynchronous_socket; // For remote logging (if specified)
};

void logger_init(struct Logger *logger, const char *remote_server_ip, int remote_server_port, const char *log_file, int max_log_size) {
    memset(logger, 0, sizeof(*logger));
    logger->remote_server_ip = strdup(remote_server_ip);
    logger->remote_server_port = remote_server_port;
    logger->max_log_size = max_log_size;
    if (log_file) {
        logger->file = fopen(log_file, "a");
    }
}

void log_message(const struct Logger *logger, LogLevel level, const char *format, ...) {
    pthread_mutex_lock(&logger->lock);

    size_t message_size = logger->max_log_size;
    char *message = malloc(message_size);
    if (!message) {
        pthread_mutex_unlock(&logger->lock);
        return;
    }

    va_list args;
    va_start(args, format);
    vsnprintf(message, message_size - 1, format, args);
    va_end(args);

    if (strlen(message) >= logger->max_log_size) {
        free(message);
        pthread_mutex_unlock(&logger->lock);
        return;
    }

    if (logger->file) {
        fprintf(logger->file, "[%s] %s\n", level_str[level], message);
        fflush(logger->file);
    }

    if (logger->remote_server_ip && logger->remote_server_port > 0) {
        // Asynchronous logging implementation here (use send/sendto or similar functions)
    }

    pthread_mutex_unlock(&logger->lock);
    free(message);
}

void logger_cleanup(struct Logger *logger) {
    if (logger->file) fclose(logger->file);
    if (logger->remote_server_ip) free(logger->remote_server_ip);
}
