OAuth2TokenResponse* parse_json(const char *json_str) {
    json_object *root = json_tokener_parse(json_str);
    if (!root) return NULL;

    OAuth2TokenResponse *token = malloc(sizeof(OAuth2TokenResponse));
    if (!token) goto error;

    token->access_token = json_object_get_string(json_object_object_get(root, "access_token"));
    token->expires_in = json_object_get_int(json_object_object_get(root, "expires_in"));
    token->token_type = json_object_get_string(json_object_object_get(root, "token_type"));
    if (json_object_object_get(root, "refresh_token"))
        token->refresh_token = json_object_get_string(json_object_object_get(root, "refresh_token"));

    if (!token->access_token || !token->expires_in || (strcmp(token->token_type, "Bearer") != 0) || token->expires_in <= 0) {
        free(token);
        goto error;
    }

    return token;

error:
    if (token) free(token);
    ERR_clear_errors();
    json_object_put(root);
