public class PokemonUtil {

    public static String modifyKickstartConfig(Pokemon pokemon, Map<String, String> configParams) throws Exception {
        String name = pokemon.getName();
        String type = pokemon.getType();

        StringBuilder weaknesses = new StringBuilder();
        switch (type) {
            case "Fire":
                weaknesses.append("Water");
                break;
            case "Water":
                weaknesses.append("Fire");
                break;
            // Add more cases for other Pokemon types
            default:
                throw new Exception("Invalid Pokemon type: " + type);
        }

        ProcessBuilder pb = new ProcessBuilder("sed", "-i", format("s/%pName%=\"[^\"]+\"/\"%s\"/", name), format("s/%pType%=\"[^\"]+\"/\"%s\"/", type));
        pb.directory(Paths.get("/path/to/your/working/directory")); // Replace with your working directory
        Process process = pb.start();
        int exitValue = process.waitFor();
        if (exitValue != 0) {
            throw new Exception("Failed to modify the Kickstart configuration file");
        }

        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(128); // 128 bit key
        SecretKey secretKey = keyGen.generateKey();

        Cipher cipher = Cipher.getInstance("AES");
        cipher.init(Cipher.ENCRYPT_MODE, secretKey);

        byte[] encryptedNameType = cipher.doFinal((name + type).getBytes());
        String encryptedNameTypeBase64 = Base64.getEncoder().encodeToString(encryptedNameType);

        process = new ProcessBuilder("echo", format("%s=\"%s\" >> %s", "pEncryptedNameType", encryptedNameTypeBase64, configParams.get("configFilePath")));
        process.directory(Paths.get("/path/to/your/working/directory")); // Replace with your working directory
        process.start().waitFor();

        return configParams.get("configFilePath");
    }
}

