['```c
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <queue>
#include <mutex>
#include <condition_variable>

template<typename TaskType>
class ThreadPool {
private:
    std::vector<std::thread> workers;
    std::queue<TaskType> tasks;
    int max_threads;
    bool stop;
    std::mutex queue_mutex;
    std::condition_variable cv_queue_not_empty, cv_all_tasks_done;

public:
    ThreadPool(int num_threads) : max_threads(num_threads), stop(false) {}

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        cv_all_tasks_done.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void enqueue(TaskType task) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            tasks.push(task);
            cv_queue_not_empty.notify_one();
        }
    }

    void run() {
        for (int i = 0; i < max_threads; ++i) {
            workers.emplace_back([this] {
                for (;;) {
                    TaskType task;
                    {
                        std::unique_lock<std::mutex> lock(queue_mutex);
                        cv_queue_not_empty.wait(lock, [this] { return !tasks.empty() || stop; });
                        if (stop) {
                            return;
                        }
                        task = tasks.front();
                        tasks.pop();
                    }
                    task();
                }
            });
        }
    }
};
