fn validate_path(path: &str) -> bool {
    let re_symlink = Regex::new(r"^[a-zA-Z]:\\|/\.").unwrap();
    let re_relative = Regex::new(r"^\\..*|/..*/").unwrap();
    let re_special = Regex::new(r"[\W]+").unwrap();

    path.chars().all(|c| c.is_whitespace() || !re_symlink.is_match(&format!("./{}", c)) && !re_relative.is_match(&format("./{}", c)) && !re_special.is_match(&c.to_string()))
}

fn custom_lexer(s: &str) -> Vec<&str> { // Implement your custom lexer here }

fn custom_parser() -> Parser { // Implement your custom parser here }

fn optimize(llvm_code: &mut Module, loops: usize, inlines: usize) {
    let context = llvm_code.context();

    for func in llvm_code.functions() {
        if func.is_definition() && func.name().starts_with("func.") {
            let loop_count = func.get_loop_nesting_level();

            if loop_count < loops || func.has_inline() {
                continue;
            }

            if let Ok(inline_threshold) = env::var("INLINE_THRESHOLD").ok().and_then(|s| s.parse::<usize>().ok()) {
                if func.num_uses() <= inline_threshold {
                    func.set_inline(true);
                }
            }

            func.loop_unroll(loop_count as u32);
        }
    }
}

struct Config {
    target: Target,
    opt_level: String,
}

fn parse_config() -> Result<Config, Box<dyn Error>> {
    let args: Vec<String> = env::args().collect();

    if args.len() < 3 {
        return Err(Box::new(std::io::Error::new(std::io::ErrorKind::InvalidArgument, "Not enough arguments provided.")));
    }

    let target_arch = &args[1];
    let opt_level = &args[2];

    match Target::new(target_arch, Some("x86_64"), None) {
        Ok(t) => Ok(Config {
            target: t,
            opt_level: String::from(opt_level),
        }),
        Err(_) => Err(Box::new(std::io::Error::new(std::io::ErrorKind::NotFound, "Invalid target architecture."))),
    }
}

fn generate_llvm_ir(path: &str) -> Result<String, Box<dyn Error>> {
    if !validate_path(path) {
        return Err(Box::new(std::io::Error::new(std::io::ErrorKind::PermissionDenied, "Invalid file path.")));
    }

    let config = parse_config()?;
    let mut ctx = Context::create();
    let target_triple = config.target.get_target_triple();
    let module = Module::new(&format!("main_{}", target_triple), &ctx);

    let source = BufReader::new(File::open(path)?;);
    let mut tokens = custom_lexer(&source.lines().next()?.unwrap());
    let parser = custom_parser();
    let ast = parser.parse(&mut tokens)?;

    optimize(&module, 4, 20);

    let llvm_code = module.to_string(false);

    Ok(llvm_code)
}

fn main() {
    let paths: Vec<String> = env::args().skip(1).collect();

    let mut lock = Mutex::new(());

    if paths.is_empty() {
        println!("Usage: {} [target] [optimization level] <file>", env::current_exe().unwrap().to_str().unwrap());
        return;
    }

    let mut handles = vec![];

    {
        let mut guard = lock.lock().unwrap();
        for path in paths {
            handles.push(thread::spawn(move || generate_llvm_ir(&path)));
        }
    }

    let results: Vec<Result<String, Box<dyn Error>>> = handles.into_par_iter().collect();

    // Do something with the generated LLVM IR code here
}
