#include <memory>
#include <map>
#include <string>
#include <optional>

struct Node {
    std::string value;
    std::shared_ptr<Node> left;
    std::shared_ptr<Node> right;

    Node(const std::string& val) : value(val), left(), right() {}
};

void insertRight(std::shared_ptr<Node>& root, const std::string& key, const std::string& value) {
    auto node = root;
    std::optional<Node*> parent;

    while (node) {
        if (node->value == key) {
            if (!node->right || !std::holds_alternative<Node*>(*node->right)) {
                node->right.reset(new Node(value));
                return;
            } else {
                parent = std::exchange(parent, node);
            }
        }
        parent = node;
        node = node->left ? std::get<Node*>(*node->left) : nullptr;
    }

    if (!root || !std::holds_alternative<Node*>(*root)) {
        root.reset(new Node(key));
        root->right.reset(new Node(value));
        return;
    } else {
        if (parent) (*parent->left = std::move(*root));
        else root.reset(std::make_shared<Node>(key));
        root->right.reset(new Node(value));
    }
}
