const apiLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour window
  max: 500 // limit each IP to 500 requests per hour
});

router.use(apiLimiter);

interface User {
  id: string;
  name: string;
  email: string;
}

function createOrUpdateUser(req, res) {
  const userData = req.body as Omit<User, 'id'>;
  let user: User | undefined;

  if (userCache.has(userData.email)) {
    user = userCache.get(userData.email);
  } else {
    user = { id: v4(), ...userData };
    userCache.set(user.email, user);
  }

  res.status(user ? 200 : 201).json({ id: user?.id || '', name: user?.name || '', email: user?.email || '' });
}

router.post('/', createOrUpdateUser);
router.put('/', createOrUpdateUser);

// Cache frequently accessed users for better performance
