import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5Hash {

    public static String getMD5(String input) throws Exception {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty.");
        }
        if (input.length() > 1024) {
            throw new RuntimeException("Input string is too long. Maximum allowed length is 1024 characters.");
        }

        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digestOfInput = md.digest(input.getBytes());

        BigInteger number = new BigInteger(1, digestOfInput);
        StringBuilder hashedString = new StringBuilder();
        hashedString.append("MD5:").append(number.toString(16));

        return hashedString.toString();
    }
}
