function rateLimit() {
    static $rateLimiter = [];
    $ip = $_SERVER['REMOTE_ADDR'];

    if (!isset($rateLimiter[$ip])) {
        $rateLimiter[$ip] = 60; // Rate limit of 60 requests per minute
    }

    --$rateLimiter[$ip];
    if ($rateLimiter[$ip] < 0) {
        sleep(60 - $rateLimiter[$ip]); // Sleep the remaining time before resetting the counter
        $rateLimiter[$ip] = 59; // Reset the counter to allow a new request
    }
}

function handleRequest() {
    rateLimit();

    $request = $_REQUEST;

    if (!isset($request['name']) || !isset($request['email']) || !isset($request['password']) || (!isset($request['id']) && !isset($request['sub_action']))) {
        http_response_code(400);
        echo json_encode(['message' => 'error', 'details' => 'Missing required fields: name, email, password, id or sub_action']);
        exit;
    }

    $user = new User($request['id'], $request['name'], $request['email'], $request['password']);

    switch ($request['sub_action']) {
        case 'create':
            $user->save();
            break;
        case 'update':
            $user->save();
            break;
        case 'delete':
            $user->delete();
            break;
        default:
            http_response_code(400);
            echo json_encode(['message' => 'error', 'details' => 'Invalid sub_action']);
            exit;
    }

    http_response_code(200);
    echo json_encode(['message' => 'success', 'details' => '']);
}
