const fs = require('fs-extra');
const path = require('path');
const chalk = require('chalk');
const { promisify } = require('util');

const log = (...messages) => console.log(chalk.gray(`[FileReader]`), ...messages);

const readFileAsync = promisify(fs.readFile);

async function readSpecifiedFile(directory, filename) {
  const filePath = path.resolve(directory, filename);

  try {
    const stats = await fs.lstat(filePath);

    if (!stats.isFile()) {
      log(`${filename} is not a file.`);
      return null;
    }

    // Add your external dependencies validation here...

    const content = await readFileAsync(filePath, 'utf8');
    return content;
  } catch (error) {
    if (error.code === 'ENOENT' || error.code === 'EACCES') {
      log(`Error reading ${filename}:`, error.message);
    } else {
      log(`Unexpected error reading ${filename}:`, error.message);
    }
    return null;
  }
}
```

