const loadedModules = new Set();

function runModuleTests(moduleName, testCases, blueslipMock) {
  if (loadedModules.has(moduleName)) return; // Prevent circular dependencies
  loadedModules.add(moduleName);

  const modulePath = `/src/modules/${moduleName}`;
  try {
    const module = require(modulePath);
    const startTest = (testLabel) => blueslipMock.log(`[${moduleName} - ${testLabel}] test started`);
    const endTest = (testLabel, duration) => {
      const message = blueslipMock.getLogs().slice(-1)[0]; // Get the last log message
      blueslipMock.reset(); // Reset the logger for the next test
      return { pass: true, message, duration };
    };

    const results = {};
    for (const testCase of testCases) {
      startTest(testCase.label);
      const { pass, message, duration } = testCase(module); // Execute the test case
      results[testCase.label] = { pass, message, duration };
    }

    return results;
  } catch (error) {
    blueslipMock.log(`Failed to load module ${moduleName}: ${error}`);
    return { [moduleName]: { pass: false, message: `Failed to load module ${moduleName}: ${error}`, duration: 0 } };
  }
}
```

