const Buffer = require('buffer').Buffer; // Ensure you have 'buffer' package installed

function copyBytes(srcBuffers, destOffset, numBytes, destBuffer) {
  let srcIndex = 0;
  const chunkSize = Math.min(numBytes, srcBuffers[srcIndex].length);

  while (numBytes > 0) {
    if (srcIndex === srcBuffers.length) break; // Ensure we don't go out of bounds

    const srcChunk = srcBuffers[srcIndex];
    const destEnd = Math.min(destOffset + numBytes, destBuffer.length);
    const copyLength = Math.min(chunkSize, destEnd - destOffset);

    destBuffer.set(srcChunk.slice(0, copyLength), destOffset);

    srcIndex++;
    numBytes -= copyLength;
    destOffset += copyLength;

    if (numBytes < chunkSize) {
      chunkSize = numBytes; // Adjust chunk size for remaining bytes
    }
  }

  return destBuffer;
}
```

You can use this function in your data processing pipeline as follows:

