            $stmt = $this->db->prepare("UPDATE users SET password = ? WHERE id = ?");
            $stmt->execute([$newPassword, $userId]);

            if ($stmt->rowCount() === 0) {
                throw new Exception("User not found.");
            }

            $this->db->commit();
        } catch (Exception $e) {
            // Handle errors from the database connection, e.g., connection problems
