class OctreeNode {
public:
    std::array<std::unique_ptr<OctreeNode>, 8> children;
    int dataCapacity = 0;
    std::vector<double> data;
    std::mutex nodeMutex;

    OctreeNode() {}
};

class Octree {
private:
    std::unique_ptr<OctreeNode> root;
    size_t leafNodes;
    double featureSize;
    size_t maxDataCapacity;
    std::mutex octreeMutex;
    bool isSerialized = false;

public:
    Octree(double featureSize, size_t leafNodes, size_t maxDataCapacity)
        : root(std::make_unique<OctreeNode>()), leafNodes(leafNodes),
          featureSize(featureSize), maxDataCapacity(maxDataCapacity) {}

    void allocateMemory() {
        if (root->dataCapacity >= maxDataCapacity) {
            splitNode(*root);
        }
    }

    void splitNode(OctreeNode& node) {
        std::lock_guard<std::mutex> lock(node.nodeMutex);
        for (auto &child : node.children) {
            if (child != nullptr) {
                splitNode(*child);
            }
        }
        if (!node.data.empty()) {
            auto halfSize = node.data.size() / 2;
            std::vector<double> newData1(halfSize), newData2(node.data.size() - halfSize);
            std::copy(node.data.begin(), node.data.begin() + halfSize, newData1.begin());
            std::copy(node.data.begin() + halfSize, node.data.end(), newData2.begin());

            auto newNode1 = std::make_unique<OctreeNode>();
            auto newNode2 = std::make_unique<OctreeNode>();
            node.children[0] = std::move(newNode1);
            node.children[4] = std::move(newNode2);

            newNode1->data = std::move(newData1);
            newNode2->data = std::move(newData2);
            for (size_t i = 0; i < 8; ++i) {
                if (node.children[i] != nullptr) {
                    auto &child = *node.children[i];
                    if (!child->data.empty()) {
                        splitNode(child);
                    }
                    child->parent = i < 4 ? newNode1.get() : newNode2.get();
                }
            }
        }
    }

    // Implement serialization and deserialization functions using cereal library
    void serialize(cereal::BinaryOArchive &archive) {
        archive(leafNodes, featureSize, maxDataCapacity, *root);
    }

    void deserialize(cereal::BinaryIArchive &archive) {
        archive(leafNodes, featureSize, maxDataCapacity, root);
    }

    // Implement thread-safe insertion and query functions
};
```

