struct transaction {
    int id;
    int age;
    double weight;
};

typedef struct transaction Transaction;

struct node {
    Transaction data;
    struct node *next;
};

typedef struct node Node;

volatile unsigned long long max_weighted_sum = 0, transactions = 0, log_size = 0, log_index = 0;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;

void push(Transaction t) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) return;
    new_node->data = t;
    new_node->next = head;
    head = new_node;
}

void pop() {
    Node *temp = head;
    if (head != NULL) head = head->next;
    free(temp);
}

double calculate_weighted_sum(Transaction t) {
    return t.age * t.weight;
}

int compare_and_swap(unsigned long long* var, unsigned long long old_val, unsigned long long new_val, ...) {
    va_list args;
    va_start(args, old_val);
    unsigned long long result = __sync_val_compare_and_swap(var, old_val, new_val, *args);
    va_end(args);
    return (result == old_val) ? 1 : 0;
}

void* process_transaction(void* arg) {
    Transaction t;
    while (scanf("%d%d%lf", &t.id, &t.age, &t.weight) != EOF) {
        double weighted_sum = calculate_weighted_sum(t);
        if (compare_and_swap(&transactions, transactions + 1, transactions + 1)) {
            push(t);
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
            }
            time_t now = time(NULL);
            struct tm* local = localtime(&now);
            if (difftime(now, (time_t)(local->tm_sec)) > 3) {
                pthread_mutex_lock(&log_mutex);
                if (log_size < 5000) {
                    log_size++;
                } else {
                    pop();
                    transactions--;
                }
                printf("Transaction ID: %d, Rejected at: %d-%02d-%04d %02d:%02d:%02d\n", t.id, local->tm_year + 1900, local->tm_mon + 1, local->tm_mday, local->tm_hour, local->tm_min, local->tm_sec);
                log_index = (log_index + 1) % 5000;
                pthread_mutex_unlock(&log_mutex);
            }
        }
    }
}

unsigned long long get_max_weighted_sum() {
    return max_weighted_sum;
}

unsigned long long get_total_transactions() {
    unsigned long long temp = transactions;
    transactions = 0;
    return temp;
}
```

