#include <chrono>
#include <thread>
#include <unordered_map>
#include <mutex>

// AttackStrategy structure with required fields: name, cooldown, manaCost, criticalHitCooldownReduction
struct AttackStrategy {
    std::string name;
    unsigned int cooldown;
    unsigned int manaCost;
    unsigned int criticalHitCooldownReduction;
};

// GameCharacter structure with required fields: currentAttack, state, strategies
struct GameCharacter {
    const AttackStrategy* currentAttack;
    std::shared_ptr<const std::unordered_map<std::string, AttackStrategy>> strategies;
    std::mutex stateMutex;
};

// Function to select an attack strategy for a game character based on in-game conditions and resource availability
void selectAttack(GameCharacter* character) {
    if (character->currentAttack) return; // Return immediately if currently executing an attack

    auto now = std::chrono::high_resolution_clock::now();
    unsigned long long cooldownEnd = character->strategies->at(character->currentAttack->name).cooldown;

    // Check cooldown status, health level, and available mana
    if (cooldownEnd <= now.time_since_epoch().count()) {
        // Choose a new attack based on preferences or randomization
        character->currentAttack = &(character->strategies->at((*character->strategies)["attack1"].name == "attack1" ? "attack2" : "attack1"));
    } else {
        // Adjust cooldown based on critical hit conditions (e.g., reduce cooldown by 50% for critical hits)
        float reductionFactor = character->currentAttack->criticalHitCooldownReduction / 100.0;
        unsigned long long reducedCooldownEnd = cooldownEnd - cooldownEnd * reductionFactor;

        if (now.time_since_epoch().count() >= reducedCooldownEnd) {
            character->currentAttack = &(character->strategies->at((*character->strategies)["attack1"].name == "attack1" ? "attack2" : "attack1"));
        }
    }

    // Update the character's state for synchronization across threads or processes
    std::unique_lock<std::mutex> lock(character->stateMutex);
    character->strategies->at(character->currentAttack->name).cooldown = cooldownEnd + 9 * (1.0 - reductionFactor) > now.time_since_epoch().count() ?
                                                                now.time_since_epoch().count() + 9 * (1.0 - reductionFactor) : character->strategies->at(character->currentAttack->name).cooldown;
    lock.unlock();
}
```

