public class RandomValueGenerator
{
    private enum ValueType { Float, Integer }
    private struct RangeDefinition
    {
        public ValueType Type;
        public float Min;
        public float Max;

        public RangeDefinition(float min, float max, ValueType type)
        {
            Min = Mathf.Min(min, max);
            Max = Mathf.Max(min, max);
            Type = type;
        }
    }

    private readonly Random _random = new();
    private RangeDefinition _currentRange;
    private System.Random _unityRNG;

    public void SetRange(ValueType type, float min, float max) => _currentRange = new RangeDefinition(min, max, type);

    public override string ToString() => $"Current Range: {_currentRange.Min}, {_currentRange.Max} ({_currentRange.Type})";

    public float NextFloatInclusive()
    {
        if (_currentRange.Type == ValueType.Float)
            return _currentRange.Min + (_random.Next((int)(_currentRange.Max - _currentRange.Min)) * (1f / Int32.MaxValue)) + (_currentRange.Min - _currentRange.Min % 1f);
        else throw new InvalidOperationException("Invalid range type");
    }

    public float NextFloatExclusive()
    {
        if (_currentRange.Type == ValueType.Float)
            return _random.Next((int)((_currentRange.Max - _currentRange.Min) * (1f / Int32.MaxValue))) + _currentRange.Min;
        else throw new InvalidOperationException("Invalid range type");
    }

    public int NextIntInclusive()
    {
        if (_currentRange.Type == ValueType.Integer)
            return (int)(_random.Next((int)((_currentRange.Max - _currentRange.Min) + 1)) + _currentRange.Min);
        else throw new InvalidOperationException("Invalid range type");
    }

    public int NextIntExclusive()
    {
        if (_currentRange.Type == ValueType.Integer)
            return (int)((_random.Next((int)((_currentRange.Max - _currentRange.Min)))) + _currentRange.Min);
        else throw new InvalidOperationException("Invalid range type");
    }

    public Vector3 NextVector3Inclusive()
    {
        if (_currentRange.Type == ValueType.Float)
        {
            float x = NextFloatInclusive();
            float y = NextFloatInclusive();
            float z = NextFloatInclusive();
            return new Vector3(x, y, z);
        }
        else throw new InvalidOperationException("Invalid range type");
    }

    public Vector3 NextVector3Exclusive()
    {
        if (_currentRange.Type == ValueType.Float)
        {
            float x = NextFloatExclusive();
            float y = NextFloatExclusive();
            float z = NextFloatExclusive();
            return new Vector3(x, y, z);
        }
        else throw new InvalidOperationException("Invalid range type");
    }

    public Quaternion NextQuaternion()
    {
        if (_currentRange.Type == ValueType.Float)
        {
            float x = NextFloatInclusive();
            float y = NextFloatInclusive();
            float z = NextFloatInclusive();
            float w = NextFloatInclusive();
            return new Quaternion(x, y, z, w);
        }
        else throw new InvalidOperationException("Invalid range type");
    }
}
