```javascript
const reduceAsync = (arr, initialValue, callback, config) => {
  let accumulator = initialValue;
  const { maxConcurrentRequests = 10, onError = console.error } = config || {};
  const promises = arr.map((item, index) =>
    fetch(item) // Assuming the API returns JSON by default
      .then(response => response.json())
      .then(data => callback(accumulator, data, index))
      .catch(error => onError(`Error at index ${index}:`, error))
  );

  let activeRequests = 0;
  const processNextRequest = () => {
    if (!arr.length || activeRequests >= maxConcurrentRequests) return;

    activeRequests++;
    promises[activeRequests - 1]
      .then(value => {
        accumulator = value;
        activeRequests--;
        processNextRequest();
      })
      .catch(error => onError(`Error at index ${activeRequests}:`, error));
  };

  processNextRequest();

  return new Promise((resolve, reject) => {
    if (!arr.length) {
      resolve(accumulator);
      return;
    }

    arr.push({ value: accumulator, done: false });

    const checkCompleted = () => {
      let completedCount = 0;
      for (let i = 0; i < arr.length; i++) {
        if (!arr[i].done) continue;
        completedCount++;
      }

      if (completedCount === arr.length) resolve(accumulator);
    };

    setInterval(() => checkCompleted(), 100);
  });
};
```

To use this function, you can call it with your array and desired configuration options:

```javascript
reduceAsync([1, 2, 3, 4, 5], 0, (accumulator, currentNum, index) => accumulator + currentNum, { maxConcurrentRequests: 3 })
  .then(result => console.log(`Result: ${result}`))
  .catch(error => console.error(`Error:`, error));
```

This example demonstrates the function's usage for simple addition, but you can replace the callback with custom reduction logic as needed. The function gracefully handles network errors and performs efficiently when dealing with large datasets by limiting the number of concurrent requests and checking for completion iteratively."]

