#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <dirent.h>
#include <fcntl.h>
#include <sys/stat.h>

typedef enum {
    ITEM_TYPE_UNKNOWN = 0,
    ITEM_TYPE_IMAGE,
    ITEM_TYPE_AUDIO,
    ITEM_TYPE_TEXT,
    // Add more item types as needed
} ItemType;

struct ResourceReport {
    size_t numItems;
    ItemType* itemTypes;
    size_t* itemSizes;
};

int loadResourceBundle(const char* path, struct ResourceReport** report, size_t maxFiles) {
    DIR *dir = NULL;
    struct dirent *entry = NULL;
    int numLoadedFiles = 0;
    int errorCode = 0;

    if (!(dir = opendir(path))) {
        perror("opendir");
        errorCode = -1;
        goto cleanup;
    }

    struct ResourceReport* currentReport = NULL;
    size_t totalItems = 0;

    while ((entry = readdir(dir)) && numLoadedFiles < maxFiles) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char fullPath[1024];
        snprintf(fullPath, sizeof(fullPath), "%s/%s", path, entry->d_name);

        struct stat fileStat;
        if (lstat(fullPath, &fileStat) == -1) {
            perror("lstat");
            errorCode = -1;
            goto cleanup;
        }

        if (!S_ISREG(fileStat.st_mode)) {
            printf("%s is not a regular file.\n", fullPath);
            continue;
        }

        currentReport = realloc(currentReport, sizeof(struct ResourceReport) + totalItems * (sizeof(ItemType) + sizeof(size_t)));
        if (!currentReport) {
            perror("realloc");
            errorCode = -1;
            goto cleanup;
        }

        int result = loadResourceFile(fullPath, &currentReport->itemTypes[totalItems], &currentReport->itemSizes[totalItems]);
        if (result != 0) {
            errorCode = result;
            goto cleanup;
        }

        totalItems++;
        numLoadedFiles++;
    }

    closedir(dir);

    if (errorCode == 0) {
        *report = currentReport;
        (*report)->numItems = totalItems;
        errorCode = 0;
    } else {
        free(currentReport);
    }

cleanup:
    return errorCode;
}

int loadResourceFile(const char* path, ItemType* itemType, size_t* itemSize) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    struct stat fileStat;
    if (fstat(fd, &fileStat) == -1) {
        perror("fstat");
        close(fd);
        return -1;
    }

    *itemSize = fileStat.st_size;

    switch (fileStat.st_mtime % 3) {
        case 0:
            *itemType = ITEM_TYPE_IMAGE;
            break;
        case 1:
            *itemType = ITEM_TYPE_AUDIO;
            break;
        case 2:
            *itemType = ITEM_TYPE_TEXT;
            break;
        default:
            *itemType = ITEM_TYPE_UNKNOWN;
    }

    close(fd);
    return 0;
}
```

This code defines a `ResourceReport` structure and two functions to load resource bundles from files. The `loadResourceBundle` function takes a path to a directory and an optional maximum number of files to load, and returns a dynamically allocated `ResourceReport` containing the number of items, their types, and sizes. It also handles multiple item types and sizes, ensuring that each item is correctly categorized and sized. The code includes error handling for cases like opening directories or files. Note that this example assumes a simple heuristic to classify files based on their modification time. You may want to replace it with more accurate methods for your specific use case.']

