#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h> // For thread safety

char* safe_strcat(const char* str, size_t size_limit, bool strict_length_check) {
    if (!str || size_limit == 0) return NULL;

    size_t str_len = strlen(str);

    // Allocate memory for the new string with a slash appended (if necessary) and null terminator.
    char* result = malloc(str_len + (strict_length_check && (str_len == size_limit) ? 0 : 1) + 1);
    if (!result) return NULL; // Handle out-of-memory error

    // Copy the input string into the allocated memory using strncpy_s, which is a safer string copying method.
    int ret = strncpy_s(result, size_limit + 1, str, str_len);
    if (ret != EOK) {
        free(result); // Free the incorrectly-sized memory and return NULL
        return NULL;
    }

    // Append a slash if the input string does not exceed the size limit or strict_length_check is false.
    if (!strict_length_check || (str_len + 1 < size_limit)) {
        result[str_len] = '/';
        result[str_len + 1] = '\0';
    }

    return result;
}
```
