void rename_file(char *input_filename) {
    // Check for empty filenames or filenames exceeding 256 characters
    if (strlen(input_filename) >= 256 || strlen(input_filename) == 0) return;

    int dot_index = strlen(input_filename);
    while (dot_index > 0 && input_filename[dot_index - 1] == '.') dot_index--;

    // Determine the length of the digits to append and check if the filename ends with a dot
    int len_without_ext = strlen(input_filename) - (dot_index < strlen(input_filename) ? dot_index : strlen(input_filename));
    int num_digits = ceil(log10((double)len_without_ext + 1)) - 1;
    char extension[6] = ".txt"; // Default file type is .txt

    if (dot_index < strlen(input_filename)) {
        // If the filename ends with a dot, replace the extension instead of appending to it
        strncpy(extension, input_filename + dot_index, 5);
    }

    char checksum[7];
    sprintf(checksum, "%llx", strtoll(input_filename, NULL, 16)); // Compute the checksum from the original filename's contents using lowercase hexadecimal representation

    int new_len = len_without_ext + num_digits + strlen(extension) + strlen(checksum);
    char new_name[257];

    // Ensure that no part of the generated filename exceeds 256 characters
    if (new_len > 256) {
        printf("Error: The new name would be too long.\n");
        return;
    }

    strncpy(new_name, input_filename, len_without_ext); // Copy the filename up to the extension position
    snprintf(new_name + len_without_ext, num_digits + 1, "%d", (int)strtoll(checksum, NULL, 16)); // Append the digits derived from the checksum
    strncat(new_name + len_without_ext + num_digits, extension, strlen(extension)); // Append the file extension
    strncat(new_name + len_without_ext + num_digits + strlen(extension), checksum, strlen(checksum)); // Append the checksum

    printf("The new filename is: %s\n", new_name);
}
```

