sem_t semaphore;
int compress(char *src, char *dest, int level) {
    pid_t pid = fork();
    if (pid == -1) return 1;
    if (pid == 0) { // child process
        long page_size = sysconf(_SC_PAGE_SIZE);
        size_t chunk_size = page_size * getpagesize() / 2;
        char *buffer = mmap(NULL, chunk_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (buffer == MAP_FAILED) return 1;

        sem_init(&semaphore, 0, MAX_CONCURRENT);
        sem_wait(&semaphore);

        int ret = system(sprintf("zip -q %d -T %s %s", level, src, dest));
        munmap(buffer, chunk_size);
        sem_post(&semaphore);
        return ret;
    } else { // parent process
        wait(NULL);
        return 0;
    }
}
