['```c
#include <stdio.h>
#include <stdlib.h>
#include <sys/wait.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define MAX_RETRIES 5

typedef struct {
    pid_t pid;
    int status;
    int retries_left;
} Command;

void handle_child_exit(int status, siginfo_t *info, void *ctx) {
    Command* cmd = (Command*)info->si_value.sival_ptr;
    cmd->status = WEXITSTATUS(status);
    cmd->retries_left--;
}

void retry_command(Command* cmd) {
    if (cmd->retries_left > 0) {
        if (kill(cmd->pid, SIGCONT) == -1) {
            perror("Failed to continue child process");
        }
    } else {
        kill(cmd->pid, SIGTERM);
        cmd->pid = 0;
    }
}

int execute_command_in_background(const char* command, int retries) {
    Command* cmd = malloc(sizeof(Command));
    cmd->pid = 0;
    cmd->status = -1;
    cmd->retries_left = retries;

    pid_t child_pid = fork();

    if (child_pid == -1) {
        perror("Failed to fork process");
        free(cmd);
        return 1;
    }

    if (!child_pid) { // Child process
        execl("/bin/bash", "/bin/bash", "-c", command, NULL);
        perror("Failed to execute command");
        _exit(127);
    }

    signal(SIGCHLD, handle_child_exit);

    // Parent process
    while (cmd->pid) {
        int child_status;
        waitid(P_ALL, cmd->pid, &child_status, WEXITED | WSTOPPED | WCONTINUED);
        if (WIFEXITED(child_status)) {
            handle_child_exit(child_status.si_status, &child_status, NULL);
            break;
        } else if (WIFSIGNALED(child_status)) {
            perror("Child process received a signal");
            retry_command(cmd);
        } else if (WIFSTOPPED(child_status)) {
            retry_command(cmd);
        }
    }

    if (cmd->retries_left == 0) {
        printf("Command '%s' failed after %d retries\n", command, MAX_RETRIES);
        free(cmd);
        return 1;
    }

    if (cmd->status != 0) {
        printf("Command '%s' returned status %d\n", command, cmd->status);
    } else {
        printf("Command '%s' executed successfully\n", command);
    }

    free(cmd);
    return cmd->status;
}
```
This function `execute_command_in_background()` takes a command as string and the number of retries. It forks the process, handles the child process using `waitid()` and manages resources effectively by checking if the command has finished executing or not before restarting it. The function logs the success or failure of each command execution and attempts to restart failed commands up to a specified number of times before returning an error status. It also gracefully handles potential race conditions using signals.']

