    {
        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath)) return null;

        // Initialize legacy application (non-standard configuration) handling
        var legacyApps = new Dictionary<string, Action>
        {
            ["LegacyApp1"] = () => { /* Custom initialization logic for LegacyApp1 */ },
            ["LegacyApp2"] = () => { /* Custom initialization logic for LegacyApp2 */ }
        };

        var siteDirectoryPath = Path.Combine(directoryPath, siteName);
        if (!Directory.Exists(siteDirectoryPath)) Directory.CreateDirectory(siteDirectoryPath);

        // Optimization: Parallel loop to process multiple sites simultaneously
        Parallel.ForEach(legacyApps.Keys, app =>
        {
            var appDirectoryPath = Path.Combine(siteDirectoryPath, app);
            if (Directory.Exists(appDirectoryPath)) legacyApps[app]();
        });

        // Handle potential performance bottlenecks with LINQ's AsParallel() method
        var childDirectories = Directory.GetDirectories(siteDirectoryPath).AsParallel().ToList();
        foreach (var childDirectory in childDirectories)
            AddAndStartWebsite(childDirectory, siteName);

        return new Website { Name = siteName };
    }
}

public class Website
{
    public string Name { get; set; }
}
