import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import javax.annotation.PostConstruct;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import com.google.common.collect.ImmutableMap;

@Component
public class CommandExecutor {
    private static final Logger LOGGER = LoggerFactory.getLogger(CommandExecutor.class);

    @Value("${commandExecutor.timeout}")
    private long timeout;

    @Value("${commandExecutor.logLevel}")
    private String logLevel;

    @Value("${commandExecutor.loggingServiceUrl}")
    private String loggingServiceUrl;

    private final Map<String, Command> supportedCommands = new HashMap<>();

    private final File workingDirectory;

    public CommandExecutor() {
        this.workingDirectory = new File(System.getProperty("user.dir"));
    }

    @PostConstruct
    public void init() {
        // Load commands from configuration or default commands here
        supportedCommands.put("command1", new Command("command1", command1Exec, command1Env));
        supportedCommands.put("command2", new Command("command2", command2Exec, command2Env));
        // ... add more commands as needed
    }

    public void executeCommand(String commandName, Path workingDirectory, String[] commandArgs) throws IOException {
        File commandFile = new File(workingDirectory, commandName);
        if (!commandFile.exists()) {
            LOGGER.error("Specified command does not exist: {}", commandFile.getAbsolutePath());
            return;
        }

        Command command = supportedCommands.getOrDefault(commandName, null);
        if (command == null) {
            LOGGER.error("Unsupported command: {}", commandName);
            return;
        }

        // Check for required environment variables and log a warning if missing
        command.checkEnvVars();

        synchronized (commandFile) {
            // Delete the file if it exists to avoid race conditions when multiple threads are involved
            if (Files.exists(commandFile.toPath())) {
                Files.deleteIfExists(commandFile.toPath());
            }
        }

        ProcessBuilder builder = new ProcessBuilder(commandArgs).directory(workingDirectory);
        try {
            Process process = builder.start();

            // Read output and error streams using BufferedReader and limit execution time to 5 seconds
            executeCommandWithTimeout(process.getInputStream(), process.getErrorStream(), timeout, logLevel);

            int exitValue = process.waitFor();
            if (exitValue != 0) {
                LOGGER.error("Command execution failed with exit value: {}", exitValue);
            }
        } catch (InterruptedException | ExecutionException e) {
            LOGGER.error("Error during command execution", e);
        }
    }

    private void executeCommandWithTimeout(InputStream input, InputStream errorStream, long timeout, String logLevel) {
        Thread thread = new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(input))) {
                String line;
                while ((line = reader.readLine()) != null && !Thread.currentThread().isInterrupted()) {
                    LOGGER.info(line, logLevel);
                }
            } catch (IOException e) {
                LOGGER.error("Error reading command output", e);
            }
        });
        thread.start();

        Thread errorThread = new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(errorStream))) {
                String line;
                while ((line = reader.readLine()) != null && !Thread.currentThread().isInterrupted()) {
                    LOGGER.error(line, logLevel);
                }
            } catch (IOException e) {
                LOGGER.error("Error reading command error", e);
            }
        });
        errorThread.start();

        try {
            thread.join(timeout);
            errorThread.join(timeout);
        } catch (InterruptedException e) {
            // Ignore interrupt and continue logging errors until the thread is finished
        } finally {
            if (!thread.isAlive() && !errorThread.isAlive()) {
                try {
                    errorStream.close();
                    input.close();
                } catch (IOException e) {
                    LOGGER.error("Error closing command streams", e);
                }
            }
        }
    }

    // Replace these methods with your own command execution logic and environment variable checks
    private String[] command1Exec = {"command1", "arg1", "arg2"};
    private Map<String, String> command1Env = ImmutableMap.<String, String>builder()
        .put("VAR1", "value1")
        .build();

    private String[] command2Exec = {"command2", "arg1", "arg2"};
    private Map<String, String> command2Env = ImmutableMap.<String, String>builder()
        .put("VAR2", "value2")
        .build();

    // Add more commands and their execution logic as needed

    // Integrate with an external logging service here, e.g., using a library like Logback-SLF4J or Log4j2

    // Implement unit tests for each component of the program to ensure all edge cases are covered
}
