bool validate_oauth2_token(const char *json_str) {
    json_t *root;
    json_error_t error;
    bool valid = true;

    root = json_loads(json_str, 0, &error);
    if (!root) {
        fprintf(stderr, "Failed to parse JSON: %s\n", error.text);
        return false;
    }

    if (!json_object_get_string_field(root, "access_token") || strlen(json_object_get_string_field(root, "access_token")) == 0) {
        valid = false;
    }

    if (json_object_get_integer_field(root, "expires_in") < 0 || json_object_get_integer_field(root, "expires_in") > 3600) {
        valid = false;
    }

    if (!json_strcmp(json_object_get_string_field(root, "token_type"), "Bearer")) {
        valid = false;
    }

    if (json_object_exists(root, "refresh_token") && json_object_get_integer_field(root, "expires_in") > 1800 && strlen(json_object_get_string_field(root, "refresh_token")) == 0) {
        valid = false;
    }

    json_decref(root);
    return valid;
}
