    public LinkedListNode<T> Next { get; set; }
}

public class AlgorithmsManager
{
    private readonly LinkedList<Algorithm> _algorithms = new LinkedList<Algorithm>();

    public void Register(Algorithm algorithm)
    {
        // Implement validation, error handling, and dynamic list updating here.
    }

    public Algorithm GetAlgorithmByName(string name)
    {
        var node = _algorithms.FirstOrDefault(n => n.Data.Name == name);
        return node?.Data;
    }

    public string DecryptBase64EncodedMessage(string base64Message, string algorithmName, byte[] key, byte[] iv)
    {
        var algorithm = GetAlgorithmByName(algorithmName);
        if (algorithm == null)
            throw new Exception("Unsupported algorithm");

        using (var ms = new MemoryStream(Convert.FromBase64String(base64Message)))
        {
            ms.Position = 0;
            var cipherText = new byte[ms.Length];
            ms.Read(cipherText, 0, cipherText.Length);

            algorithm.Initialize?.Invoke(key);
            var decryptedData = algorithm.Decrypt(cipherText);
            algorithm.Cleanup?.Invoke();

            return Encoding.UTF8.GetString(decryptedData);
        }
    }
}
