    {
        switch (compressionMode)
        {
            case CompressionMode.GZip:
                using (var reader = new GzipStream(fileStream, compressionMode))
                    break;
            case CompressionMode.Deflate:
                using (var reader = new DeflateStream(fileStream, compressionMode))
                    break;
            default:
                throw new ArgumentException("Invalid compression mode.");
        }

        using (var jsonReader = new StreamReader(reader))
        {
            string jsonContent = jsonReader.ReadToEnd();
            return JsonConvert.DeserializeObject<MyDataStruct>(jsonContent);
        }
    }
}
