function loadAndExecuteScript(filePath, callback) {
    let script = document.createElement('script');
    script.src = filePath;

    script.onload = () => {
        if (callback && typeof callback === 'function') {
            try {
                callback();
            } catch (error) {
                console.error(`Error while executing loaded script: ${error}`);
            }
        }
    };

    script.onerror = () => {
        console.error(`Error while loading script at path: ${filePath}`);
    };

    document.head.appendChild(script);
}
