    public int RandomInt(int min, int max) => _randomGenerator.Next(min, max);
    public int RandomIntInclusive(int min, int max) => _randomGenerator.Next(min, max + 1);

    public Vector3 RandomVector3(float min, float max) => new Vector3(_randomFloat(min, max), _randomFloat(min, max), _randomFloat(min, max));

    public Quaternion RandomQuaternion(float min, float max)
    {
        var x = (float)_randomGenerator.NextDouble() * (max - min) + min;
        var y = (float)_randomGenerator.NextDouble() * (max - min) + min;
        var z = (float)_randomGenerator.NextDouble() * (max - min) + min;
