#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef enum { AUDIO, VIDEO } MEDIA_TYPE;
typedef enum { AAC, MP3, PCM, OPUS, UNKNOWN } ENCODING_FORMAT;
typedef struct __MEDIA_STREAM_INFO {
    const char* stream_id;
    MEDIA_TYPE media_type;
    ENCODING_FORMAT encoding_format;
    size_t buffer_length;
    void* buffer;
    pthread_mutex_t mutex;
} MEDIA_STREAM_INFO;

int initialize_media_stream(MEDIA_STREAM_INFO** stream, const char* stream_id, MEDIA_TYPE media_type, ENCODING_FORMAT encoding_format, size_t buffer_length) {
    if (buffer_length == 0 || encoding_format >= OPUS)
        return -1; // Error: Invalid buffer length or unsupported encoding format

    MEDIA_STREAM_INFO* new_stream = (MEDIA_STREAM_INFO*)malloc(sizeof(MEDIA_STREAM_INFO));
    if (!new_stream)
        return -2; // Error: Allocation failure

    new_stream->stream_id = stream_id;
    new_stream->media_type = media_type;
