from concurrent.futures import ThreadPoolExecutor
from functools import lru_cache
from itertools import islice
from pathlib import Path
import logging

class ProgressLogger:
    def __init__(self, log_file):
        self.log = logging.getLogger(__name__)
        self.log_file = log_file
        self.handler = logging.FileHandler(self.log_file)
        self.handler.setLevel(logging.INFO)
        self.formatter = logging.Formatter('%(asctime)s - %(message)s')
        self.handler.setFormatter(self.formatter)
        self.log.addHandler(self.handler)

    def update_progress(self, file_name, processed_bytes, total_size):
        progress = (processed_bytes / total_size) * 100
        self.log.info(f"Processing {file_name}: {progress:.2f}% complete")

class MD5Hasher:
    MAX_CHUNK_SIZE = 65536

    @staticmethod
    @lru_cache(maxsize=None)
    def _is_skippable_filetype(filetype):
        with open('skipped_filetypes.txt', 'r') as f:
            for skip_filetype in f.readlines():
                skip_filetype = skip_filetype.strip()
                if filetype == skip_filetype:
                    return True
        return False

    @staticmethod
    def _is_symbolic_link(path):
        return os.path.islink(path)

    def __init__(self, chunk_size=None, log_file=None):
        self.chunk_size = chunk_size or self.MAX_CHUNK_SIZE
        self.log_progress = ProgressLogger(log_file) if log_file else None
        self.hasher = hashlib.md5()

    def _process_file(self, file_path):
        total_size = file_path.stat().st_size
        processed_bytes = 0
        with open(file_path, 'rb') as f:
            while True:
                chunk = f.read(self.chunk_size)
                if not chunk:
                    break
                self.hasher.update(chunk)
                processed_bytes += len(chunk)
                self.log_progress and self.log_progress.update_progress(file_path, processed_bytes, total_size)
        return self.hasher.hexdigest()

    def process_file(self, file_path):
        if not Path(file_path).is_file():
            raise FileNotFoundError(f"File '{file_path}' not found.")
        if self._is_symbolic_link(file_path):
            file_path = file_path.resolve()
        if self._is_skippable_filetype(Path(file_path).suffix):
            return None
        return self._process_file(file_path)

    def process_files(self, files, concurrent=True):
        if not concurrent:
            for file in files:
                processed_hash = self.process_file(file)
                if processed_hash is not None:
                    yield processed_hash
            return

        with ThreadPoolExecutor() as executor:
            hashes = executor.map(self.process_file, files)
            for hash in filter(None, hashes):
                yield hash

def calculate_md5_hashes(files, chunk_size=None, log_file='md5_log.txt', concurrent=True):
    md5 = MD5Hasher(chunk_size, log_file)
    for file in files:
        if not os.path.isabs(file):
            raise ValueError("All file paths must be absolute.")
        try:
            calculated_hash = md5.process_files([Path(file)], concurrent=concurrent)
        except Exception as e:
            print(f"Error processing '{file}': {str(e)}")
        else:
            if calculated_hash is not None:
                print(f"MD5 Hash for '{file}': {calculated_hash}")
