#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    EVP_CIPHER_CTX *aes_ctx;
    EVP_CIPHER_CTX *camellia_ctx;
    EVP_MD_CTX *md5_ctx;
    EVP_MD_CTX *sha1_ctx;
    EVP_MD_CTX *sha256_ctx;
    RSA *rsa;
} crypto_context;

static pthread_once_t once_control = PTHREAD_ONCE_INIT;
static crypto_context *global_crypto_ctx;

void init_cryptographic_resources() {
    global_crypto_ctx = malloc(sizeof(crypto_context));

    // Initialize AES and Camellia ciphers
    EVP_CIPHER_CTX_init(&global_crypto_ctx->aes_ctx);
    EVP_CIPHER_CTX_init(&global_crypto_ctx->camellia_ctx);

    // Add AES-128-CBC and AES-256-CBC as aliases to the OpenSSL framework
    EVP_add_cipher(EVP_aes_128_cbc());
    EVP_add_cipher(EVP_aes_256_cbc());

    // Add Camellia-128-CBC and Camellia-256-CBC as aliases to the OpenSSL framework
    EVP_add_cipher(EVP_camellia_128_cbc());
    EVP_add_cipher(EVP_camellia_256_cbc());

    // Initialize MD5, SHA1, and SHA256 digests
    global_crypto_ctx->md5_ctx = EVP_MD_CTX_new();
    global_crypto_ctx->sha1_ctx = EVP_MD_CTX_new();
    global_crypto_ctx->sha256_ctx = EVP_MD_CTX_new();

    // Add MD5, SHA1, and SHA256 as aliases to the OpenSSL framework
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_sha256());

    // Add SHA1 as an alias for RSA-SHA1 signature
    EVP_add_digest_alias("rsa_sha1", EVP_sha1(), NULL);
}

void cryptographic_operation(const char *input, unsigned char **encrypted, unsigned long *len) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_once(&once_control, init_cryptographic_resources);

    // Perform cryptographic operations in a separate thread and manage resources efficiently
    pthread_t thread_id;
    crypto_context *local_crypto_ctx = global_crypto_ctx;

    pthread_mutex_lock(&lock);

    int ret = pthread_create(&thread_id, NULL, &cryptographic_operation_handler, (void*)input, encrypted, len);
    if(ret != 0) {
        ERR_print_errors_fp(stderr);
        pthread_mutex_unlock(&lock);
        return;
    }

    pthread_mutex_unlock(&lock);
}

void* cryptographic_operation_handler(void *args) {
    void *input = args;
    unsigned char *encrypted = NULL;
    unsigned long len = 0;

    // Perform cryptographic operations on the given input using OpenSSL functions and return the result
    EVP_CIPHER_CTX *ctx;
    const EVP_MD_CTX *digest_ctx;

    pthread_mutex_lock(&global_crypto_ctx->aes_ctx->lock);
    ctx = global_crypto_ctx->aes_ctx;
    pthread_mutex_unlock(&global_crypto_ctx->aes_ctx->lock);

    unsigned char *output = NULL;
    int output_len = 0;
    int ret = EVP_EncryptUpdate(ctx, &output, &output_len, (const unsigned char*)input, strlen((char*)input));
    if(ret <= 0) {
        ERR_print_errors_fp(stderr);
        pthread_exit(NULL);
    }

    ret = EVP_EncryptFinal_ex(ctx, &output[output_len], &output_len);
    if(ret <= 0) {
        ERR_print_errors_fp(stderr);
        pthread_exit(NULL);
    }

    output_len += ret;

    digest_ctx = global_crypto_ctx->sha256_ctx;
    unsigned char digest[EVP_MAX_MD_SIZE];
    EVP_DigestUpdate(digest_ctx, (const unsigned char*)input, strlen((char*)input));
    EVP_DigestFinal_ex(digest_ctx, digest, NULL);

    encrypted = realloc(encrypted, output_len + sizeof(digest));
    memcpy(encrypted, output, output_len);
    memcpy(encrypted + output_len, digest, sizeof(digest));

    pthread_exit(NULL);
}

char* modify_filename(const char *original) {
    if (!original || strlen(original) < 5)
        return original;

    const char *dot = strchr(original, '.');
    int extension_len = (dot ? (int)(dot - original + 1) : 0);
    int num_digits = 6;
    if(extension_len > 4) {
        num_digits = 5;
        extension_len -= 3;
    } else if(extension_len > 2) {
        num_digits = 4;
        extension_len -= 2;
    }

    char *new_name = malloc(strlen(original) + num_digits + extension_len + 1);
    sprintf(new_name, "%s%0*d.%s", original, num_digits, (rand() % (int)(pow(10, num_digits))) + 1, &original[extension_len]);
    return new_name;
}
