typedef struct {
    int FRAME_WIDTH;
    int FRAME_HEIGHT;
    double FRAMERATE;
} VIDEO_PROCESSOR_CONFIG;

#define MAX_INITIALIZATIONS 10 // Maximum concurrent initialization requests
static int num_init = 0;        // Number of active initializations
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;   // Mutex for synchronization

VIDEO_PROCESSOR_CONFIG* initialize_video_processor(int frame_width, int frame_height, double framerate, size_t buffer_size, size_t num_frames) {
    if (frame_width <= 0 || frame_height <= 0 || framerate <= 0 || buffer_size == 0 || num_frames == 0) {
        fprintf(stderr, "Invalid parameters\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    if (num_init >= MAX_INITIALIZATIONS) {
        fprintf(stderr, "Too many simultaneous initialization requests\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    num_init++;
    pthread_mutex_unlock(&mutex);

    VIDEO_PROCESSOR_CONFIG* config = malloc(sizeof(VIDEO_PROCESSOR_CONFIG));
    if (!config) {
        fprintf(stderr, "Memory allocation failed\n");
        num_init--;
        pthread_mutex_lock(&mutex);
        return NULL;
    }

    config->FRAME_WIDTH = frame_width;
    config->FRAME_HEIGHT = frame_height;
    config->FRAMERATE = framerate;

    unsigned char* buffer = malloc(buffer_size);
    if (!buffer) {
        free(config);
        num_init--;
        pthread_mutex_lock(&mutex);
        return NULL;
    }

    for (size_t i = 0; i < num_frames; ++i) {
        // Fill buffer with pseudo-random pixels
        for (int j = 0; j < buffer_size; ++j) {
            buffer[j] = rand() % 256;
        }
    }

    config->buffer = buffer;
    config->num_frames = num_frames;

    return config;
}
