// Thread-safe initializer and accessor for the scan request array
WIFI_SCAN_REQUEST* wifi_scan_requests = NULL;
int num_scan_requests = 0;
pthread_mutex_t scan_req_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_wifi_scan_requests(size_t size) {
    if (wifi_scan_requests != NULL) return;

    wifi_scan_requests = mmap(NULL, sizeof(WIFI_SCAN_REQUEST) * size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (wifi_scan_requests == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    num_scan_requests = size;
}

WIFI_SCAN_REQUEST* get_next_scan_request() {
    WIFI_SCAN_REQUEST *req;

    pthread_mutex_lock(&scan_req_mutex);
    if (num_scan_requests == 0) {
        req = NULL;
    } else {
        req = wifi_scan_requests++;
        num_scan_requests--;
    }
    pthread_mutex_unlock(&scan_req_mutex);

    return req;
}

