import hashlib
import os
import sys
from threading import Thread

MAX_CHUNK_SIZE = 65536
PREDEFINED_SKIP_FILETYPES = [".tmp", ".bak"]

def md5sum(filepath):
    if any(filetype in filepath for filetype in PREDEFINED_SKIP_FILETYPES):
        return None

    hasher = hashlib.md5()
    processed_bytes = 0
    block_size = MAX_CHUNK_SIZE

    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(block_size), b''):
            hasher.update(chunk)
            processed_bytes += len(chunk)
            progress = processed_bytes / os.path.getsize(filepath) * 100
            sys.stdout.write(f'\rProcessing {filepath} ({progress:.2f}%)')
            sys.stdout.flush()

    hashed_md5 = hasher.hexdigest()
    print(f'\nFile {filepath}'
          f' MD5 checksum: {hashed_md5}\n')

    return hashed_md5

def parallelize_md5sum(files):
    threads = []
    for file in files:
        t = Thread(target=md5sum, args=(file,))
        t.start()
        threads.append(t)

    for t in threads:
        t.join()
