            SecretKeySpec key = new SecretKeySpec("mySecretKey".getBytes(), "AES");
            Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
            cipher.initEncrypt(key);
            byte[] encryptedNameAndType = cipher.doFinal((name + "_" + type).getBytes());
            return Base64.getEncoder().encodeToString(encryptedNameAndType);
        } catch (Exception e) {
            throw new RuntimeException("Encryption failed.", e);
        }
    }
}
