class RandomListModifier {
public:
    void insertAfter(const std::string& target, const std::string& value) {
        auto it = stdRange_.begin();
        if (it == stdRange_.end()) {
            stdRange_.push_back(value);
            return;
        }

        for (; it != stdRange_.end(); ++it) {
            if (*it == target) {
                stdRange_.insert(++it, value);
                break;
            }
        }
    }

    void setRandomRange(double min, double max) {
        if (min >= max) {
            std::cerr << "Invalid range: Minimum value must be less than maximum value." << std::endl;
            return;
        }
        randomGenerator_.reset(std::uniform_real_distribution<double>(min, max).ptr());
    }

    double getRandomFloat(bool inclusive) const {
        return randomGenerator_->operator()(inclusive);
    }

    int getRandomInt(bool inclusive) const {
        std::uniform_int_distribution<> distribution{0, static_cast<int>(getRandomFloat(true))};
        if (inclusive)
            return distribution(randomGenerator_);
        else
            return static_cast<int>(distribution(randomGenerator_) + 1.0);
    }

    std::vector<float> getRandomVector3() const {
        std::vector<float> v;
        for (size_t i = 0; i < v.size(); ++i)
            v[i] = getRandomFloat(true);
        return v;
    }

