        os << "List: ";
        for (const auto& str : stdRange_)
            os << str << ' ';
        os << "\nRandom Range: ("
           << getRandomFloat(false) << ", "
           << getRandomFloat(true) << ")";
        return os.str();
    }

private:
    std::forward_list<std::string> stdRange_;
    std::mt19937 randomGenerator_; // Mersenne Twister pseudo-random number generator
};
