#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>
#include <libzip/gzlib.h>
#include <libzip/zip.h>

typedef struct {
    char *src_path;
    char *dst_path;
    int compression_level;
    int concurrency_limit;
} CompressData;

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log(const char *msg) {
    time_t now;
    struct tm *tm_now;
    char time_buf[32];

    time(&now);
    tm_now = localtime(&now);
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", tm_now);
    pthread_mutex_lock(&log_mutex);
    printf("[%s] %s\n", time_buf, msg);
    pthread_mutex_unlock(&log_mutex);
}

int compress_file(CompressData *data) {
    int ret = 0;
    zipFile zf = NULL;
    char src[4096], dst[4096];
    struct stat st;
    time_t timestamp;
    size_t read;
    gzFile gzf = NULL;

    snprintf(src, sizeof(src), "%s", data->src_path);
    snprintf(dst, sizeof(dst), "%s-%lu.zip", data->dst_path, timestamp = time(NULL));

    if (stat(src, &st) != 0 || S_ISDIR(st.st_mode)) {
        log("Error: Invalid source file path.");
        ret = 1;
        goto cleanup;
    }

    zf = zipOpen(dst, 0, NULL);
    if (!zf) {
        log("Error: Failed to open destination ZIP file.");
        ret = 1;
        goto cleanup;
    }

    gzf = gzopen(src, "rb");
    if (!gzf) {
        log("Error: Failed to open source file for reading.");
        ret = 1;
        goto zip_close;
    }

    while ((read = gzread(gzf, src, sizeof(src))) > 0) {
        int rc = zipWriteInFile(zf, src, read);
        if (rc < 0) {
            log("Error: Failed to write data to ZIP file.");
            ret = 1;
            goto gzclose;
        }
    }

gzclose:
    gzclose(gzf);
zip_close:
    rc = zipClose(zf);
    if (rc < 0) {
        log("Error: Failed to close destination ZIP file.");
        ret = 1;
    }
cleanup:
    free(data->src_path);
    free(data);

    return ret;
}

void *compress_thread(void *arg) {
    CompressData *data = arg;

    int ret = compress_file(data);

    if (ret == 0) {
        log("Successfully compressed file.");
    } else {
        log("Error: Failed to compress file.");
    }

    return NULL;
}

int compress_multiple_files(char *dst_path, char *compress_tool, int compression_level, int concurrency_limit) {
    DIR *dir;
    struct dirent *entry;
    int num_threads = concurrency_limit;
    pthread_t threads[concurrency_limit];
    CompressData *data_array[concurrency_limit];
    int i, ret = 0;

    dir = opendir(".");
    if (!dir) {
        log("Error: Failed to open current directory.");
        ret = 1;
        goto cleanup;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char src[4096], dst[4096];
        snprintf(src, sizeof(src), "./%s", entry->d_name);
        snprintf(dst, sizeof(dst), "%s/%s.zip", dst_path, entry->d_name);

        data_array[i] = malloc(sizeof(CompressData));
        data_array[i]->src_path = strdup(src);
        data_array[i]->dst_path = strdup(dst);
        data_array[i]->compression_level = compression_level;
        data_array[i]->concurrency_limit = concurrency_limit;

        pthread_create(&threads[i], NULL, compress_thread, data_array[i]);
        i++;

        if (i == num_threads) {
            for (int j = 0; j < num_threads; j++) {
                pthread_join(threads[j], NULL);
            }
            i = 0;
        }
    }

cleanup:
    closedir(dir);

    return ret;
}
