using System;
using System.Collections.Generic;
using System.IO;
using System.Xml;
using System.Xml.XPath;
using System.Xml.Linq;
using System.Threading.Tasks;
using System.ComponentModel;
using System.Runtime.CompilerServices;
using Microsoft.Extensions.Logging;
using System.Security.Cryptography;

public class XPathParser
{
    private readonly ILogger _logger;
    private readonly Dictionary<string, CachedElement> _cache = new Dictionary<string, CachedElement>();
    private readonly object _lockObject = new object();
    private readonly XmlReaderSettings _readerSettings = new XmlReaderSettings { IgnoreProcessingInstruction = true };

    public XPathParser(ILogger logger)
    {
        _logger = logger;
    }

    public async Task<IList<ElementWithAttributes>> GetElementsAsync(Stream xmlStream, string xpathExpression, string elementName, Dictionary<string, string> attributeFilters = null)
    {
        var elements = new List<ElementWithAttributes>();

        using (var reader = XmlReader.Create(xmlStream, _readerSettings))
        {
            if (IsCompressedXml(xmlStream))
                reader = DecompressAndCreateXmlReader(xmlStream);

            XDocument document;
            try
            {
                document = XDocument.Load(reader);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error while loading XML document.");
                throw new Exception("Invalid XML document.");
            }

            var xmlNamespaceManager = new XmlNamespaceManager(new NameTable());
            xmlNamespaceManager.AddNamespace("x", document.Root.Name.NamespaceName); // Assuming default namespace is 'x'

            var xpathNavigator = document.CreateNavigator().SelectSingleNode(xpathExpression, xmlNamespaceManager) as XPathNavigator;
            if (xpathNavigator == null)
                throw new Exception($"No elements found matching '{elementName}' with '{attributeFilters?.Keys?.Aggregate((a, b) => a + ", " + b)}'.");

            var cacheKey = $"{elementName}|{string.Join("|", attributeFilters?.Keys ?? Enumerable.Empty<string>())}";
            if (_cache.TryGetValue(cacheKey, out var cached))
                elements.AddRange(cached.Elements);

            lock (_lockObject)
            {
                if (!_cache.ContainsKey(cacheKey))
                {
                    _cache[cacheKey] = new CachedElement(elementName, attributeFilters, reader.ReadToEnd());

                    ParseAndCacheElements(_cache[cacheKey], elements);
                }
            }
        }

        return elements;
    }

    private bool IsCompressedXml(Stream stream)
    {
        using (var reader = new BinaryReader(stream))
        {
            var gzipId = new byte[] { 0x1f, 0x8b }; // GZIP magic number
            return reader.ReadBytes(2).SequenceEqual(gzipId);
        }
    }

    private XmlReader DecompressAndCreateXmlReader(Stream stream)
    {
        using var decompressor = new System.IO.Compression.GZipStream(stream, CompressionMode.Decompress);
        return XmlReader.Create(decompressor);
    }

    private void ParseAndCacheElements(CachedElement cached, IList<ElementWithAttributes> elements)
    {
        var xPathNavigator = new XPathNavigator(cached.XmlDocument);

        int index = 0;
        while (!xPathNavigator.IsAfterLastSibling)
        {
            if (xPathNavigator.Name == cached.ElementName)
            {
                var elementAttributes = new Dictionary<string, string>();
                foreach (var attribute in xPathNavigator.MoveToFirstAttribute())
                {
                    if (cached.AttributeFilters?.ContainsKey(attribute.Name) == true && attribute.Value == cached.AttributeFilters[attribute.Name])
                        elementAttributes[attribute.Name] = attribute.Value;
                }

                elements.Add(new ElementWithAttributes(xPathNavigator.MoveToElement(), elementAttributes));
            }

            xPathNavigator.MoveToNext();
            index++;
        }
    }
}

public class CachedElement
{
    public string ElementName { get; set; }
    public Dictionary<string, string> AttributeFilters { get; set; }
    public string XmlDocument { get; set; }
    public XDocument XmlDocumentObject => XDocument.Parse(XmlDocument);
}

public class ElementWithAttributes : INotifyPropertyChanged
{
    private XElement _element;
    private Dictionary<string, string> _attributes;

    public ElementWithAttributes(XElement element, Dictionary<string, string> attributes)
    {
        _element = element;
        _attributes = attributes;
    }

    public XElement Element => _element;

    public IReadOnlyDictionary<string, string> Attributes
