using System.Random;

namespace DynamicMediaProcessor
{
    public class DynamicMediaProcessor
    {
        private readonly Random _random;
        private MediaFormat _currentFormat;
        private MediaOutputParameters _outputParameters;
        private MultimediaProcessingLibrary _library;

        public DynamicMediaProcessor(MultimediaProcessingLibrary library)
        {
            _library = library;
            _random = new Random(_library.GenerateSeed());
        }

        public void SetupFormat(MediaFormat format, MediaOutputParameters parameters)
        {
            _currentFormat = format;
            _outputParameters = parameters;
        }

        public float GetRandomFloat(bool inclusiveLowerBound, bool inclusiveUpperBound)
        {
            if (inclusiveLowerBound && inclusiveUpperBound)
                return _random.NextDouble();
            else if (!inclusiveLowerBound && !inclusiveUpperBound)
                return _random.NextDouble() + 1;
            else if (inclusiveLowerBound)
                return _random.NextDouble() + (1 - (_random.NextDouble()));
            else //if (inclusiveUpperBound)
                return _random.NextDouble();
        }

        public int GetRandomInt(bool inclusiveLowerBound, bool inclusiveUpperBound)
        {
            if (inclusiveLowerBound && inclusiveUpperBound)
                return _random.Next(_outputParameters.MinimumInputSize, _outputParameters.MaximumInputSize + 1);
            else if (!inclusiveLowerBound && !inclusiveUpperBound)
                return _random.Next(_outputParameters.MinimumInputSize + 1, _outputParameters.MaximumInputSize + 1);
            else if (inclusiveLowerBound)
                return _random.Next(_outputParameters.MinimumInputSize, _outputParameters.MaximumInputSize + 1 - _random.Next(_outputParameters.MinimumInputSize));
            else //if (inclusiveUpperBound)
                return _random.Next(_outputParameters.MinimumInputSize + _random.Next(1, _outputParameters.MaximumInputSize - _outputParameters.MinimumInputSize + 1), _outputParameters.MaximumInputSize + 1);
        }

        public Color GetRandomColor()
        {
            var r = GetRandomInt(false, true) / 255;
            var g = GetRandomInt(false, true) / 255;
            var b = GetRandomInt(false, true) / 255;
            return Color.FromArgb((int)(GetRandomFloat(true, false) * 255), (int)r, (int)g, (int)b);
        }

        public async Task ProcessAsync(Stream input, Stream output)
        {
            try
            {
                var task = _library.ProcessMediaAsync(_currentFormat, input, _outputParameters, CancellationToken.None);
                using var resultTask = await task.ContinueWith(t => t.Result).ConfigureAwait(false);

                using (var writer = new BinaryWriter(output))
                {
                    await resultTask.CopyToAsync(output).ConfigureAwait(false);
                }
            }
            catch (OperationCanceledException) when (_library.IsProcessingCancelled)
            {
                throw; // Rethrow the exception, as it should be propagated upwards
            }
            catch (IOException ex)
            {
                if (!_library.IsTemporaryError(ex))
                    throw; // Re-throw non-transient errors

                await Task.Delay(_library.GetBackoffDuration(ex), CancellationToken.None).ConfigureAwait(false);
                ProcessAsync(input, output); // Retry processing the same input with backoff delay
            }
        }
    }
}
