public class DynamicMediaProcessor
{
    private readonly Random _random;
    private readonly ConcurrentDictionary<string, TaskCompletionSource<bool>> _processingTasks;
    private FFPROBEG _ffprobe;
    private MediaInfo _mediaInfo;
    private OutputFormat _outputFormat;
    private string _metadataServiceUrl;

    public DynamicMediaProcessor()
    {
        _random = new Random((int)DateTime.Now.Ticks);
        _processingTasks = new ConcurrentDictionary<string, TaskCompletionSource<bool>>();
    }

    public void SetUp(OutputFormat outputFormat, string metadataServiceUrl)
    {
        if (outputFormat is null || metadataServiceUrl is null)
            throw new ArgumentNullException();

        _outputFormat = outputFormat;
        _metadataServiceUrl = metadataServiceUrl;
    }

    public float GetRandomFloat(float min, float max, bool inclusive = true)
    {
        if (min > max)
            throw new ArgumentOutOfRangeException(nameof(min));

        var range = inclusive ? (max - min) : (max - min + 1);
        return _random.NextSingle() * range + (inclusive ? min : -range / 2 + min);
    }

    public int GetRandomInt(int min, int max, bool inclusive = true)
    {
        if (min > max)
            throw new ArgumentOutOfRangeException(nameof(min));

        var range = inclusive ? (max - min + 1) : (max - min);
        return _random.Next(range) + (inclusive ? min : -range / 2 + min);
    }

    public Color GetRandomColor()
    {
        return new Color(_random.Next(0, 256), _random.Next(0, 256), _random.Next(0, 256));
    }

    public async Task<bool> ProcessMediaFileAsync(string inputFilePath, string outputFilePath)
    {
        var taskSource = new TaskCompletionSource<bool>();
        _processingTasks[inputFilePath] = taskSource;

        try
        {
            if (_ffprobe == null)
                _ffprobe = await FFPROBEG.CreateNewAsync();

            _mediaInfo = await _ffprobe.ProbeInput(inputFilePath);
            var inputFormat = FindFormat(_mediaInfo.FormatName);
            var outputFormat = FindOutputFormat(_outputFormat);

            if (inputFormat is null || outputFormat is null)
                throw new Exception("Invalid input or output format.");

            await ProcessMediaFileAsync(inputFilePath, outputFormat, outputFilePath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing media file: {ex}");
        }

        _processingTasks.TryRemove(inputFilePath, out _);
        return taskSource.Task;
    }

    private async Task ProcessMediaFileAsync(string inputFilePath, OutputFormat outputFormat, string outputFilePath)
    {
        try
        {
            var transcodingTask = FFMPT.CreateNew()
                .SetInput(new Uri(inputFilePath))
                .AddOutput(outputFormat.GetFFMpegFormat(), new Uri(outputFilePath));

            await transcodingTask.Start();
            await transcodingTask.WaitCompletionAsync();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error while transcoding media file: {ex}");
            RetryProcessing(inputFilePath);
        }
    }

    private FFXG FindFormat(string formatName) => FFXG.Formats.FirstOrDefault(f => f.ShortName == formatName || f.LongName == formatName) ?? throw new Exception("Invalid input format.");

    private FFXG FindOutputFormat(OutputFormat outputFormat) => FindFormat(outputFormat.FFMpegFormat);

