#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Record {
    int value;
} Record;

struct MemoryPool {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity; // Total number of allocated records
    size_t count; // Current number of used records
    size_t slot_count; // Current number of available slots
    pthread_mutex_t mutex;
};

struct MemoryPool* createMemoryPool(size_t initial_capacity) {
    struct MemoryPool *pool = malloc(sizeof(*pool));
    if (!pool) return NULL;

    pool->offsets = calloc(initial_capacity + 1, sizeof(long));
    if (!pool->offsets) goto error;
    pool->keys = calloc(initial_capacity, sizeof(int));
    if (!pool->keys) goto error;
    pool->records = malloc(sizeof(*(pool->records)) * initial_capacity);
    if (!pool->records) goto error;

    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->slot_count = initial_capacity;
    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
error:
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool);
    return NULL;
}

void destroyMemoryPool(struct MemoryPool *pool) {
    pthread_mutex_destroy(&pool->mutex);
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool);
}

Record* allocateRecord(struct MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->slot_count > 0) {
        size_t index = pool->offsets[pool->count];
        pool->keys[index] = -1; // Mark as unused
        pool->offsets[pool->count] = ++pool->offsets[index];
        pool->records[index].value = 0;
        pool->slot_count--;
        pool->count++;
    } else if (pool->count < pool->capacity) {
        for (size_t i = 0; i < pool->capacity; ++i) {
            if (pool->keys[i] == -1) { // Available slot found
                pool->offsets[pool->count] = pool->offsets[i];
                pool->keys[i] = pool->count++;
                break;
            }
        }
    } else {
        size_t new_capacity = pool->capacity * 2;
        long *new_offsets = realloc(pool->offsets, (new_capacity + 1) * sizeof(*pool->offsets));
        int *new_keys = realloc(pool->keys, new_capacity * sizeof(*pool->keys));
        Record *new_records = realloc(pool->records, new_capacity * sizeof(*pool->records));

        if (new_offsets && new_keys && new_records) {
            pool->offsets = new_offsets;
            pool->keys = new_keys;
            pool->records = new_records;
            pool->capacity = new_capacity;
        } else {
            // Handle error, log the issue, and return NULL to indicate allocation failure.
        }
    }
    pthread_mutex_unlock(&pool->mutex);

    if (pool->slot_count <= pool->capacity / 10) {
        // Log pool expansion event for monitoring purposes.
    }

    return pool->records + pool->offsets[pool->count - 1];
}

int main() {
    struct MemoryPool *pool = createMemoryPool(10);
    if (!pool) return 1;

    // Use the memory pool as needed, logging relevant metrics for monitoring.

    destroyMemoryPool(pool);

    return 0;
}
