#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <limits.h>

typedef struct {
    int value;
} Record;

struct pool_data {
    Record *records;
    size_t capacity;
    size_t count;
    sem_t lock;
    sem_t empty;
    sem_t full;
};

void init_pool(struct pool_data *pool, size_t chunk_size, size_t num_threads) {
    pool->records = malloc(chunk_size * sizeof(Record));
    if (!pool->records) {
        fprintf(stderr, "Failed to allocate memory for the record pool\n");
        exit(EXIT_FAILURE);
    }
    pool->capacity = chunk_size;
    pool->count = 0;

    sem_init(&pool->lock, 0, 1);
    sem_init(&pool->empty, 0, chunk_size);
    sem_init(&pool->full, 0, 0);
}

void *worker(void *arg) {
    struct pool_data *pool = arg;
    while (true) {
        // Wait until there is a slot available or an error occurs
        sem_wait(&pool->empty);
        sem_wait(&pool->lock);

        if (pool->count == pool->capacity) {
            printf("Record pool is full, cannot allocate more records\n");
            sem_post(&pool->lock);
            sem_post(&pool->full);
            break;
        }

        Record *record = &pool->records[pool->count];
        // Initialize the record with a placeholder value or perform validation here
        record->value = 0;
        pool->count++;

        sem_post(&pool->lock);
        sem_post(&pool->full);
    }

    return NULL;
}

Record get_record(struct pool_data *pool) {
    Record result;

    sem_wait(&pool->full);
    sem_wait(&pool->lock);

    if (pool->count == 0) {
        fprintf(stderr, "No records available in the pool\n");
        result.value = -1; // Set error value or throw an exception
    } else {
        Record *record = &pool->records[pool->count - 1];
        memmove(&result, record, sizeof(Record));
        pool->count--;
    }

    sem_post(&pool->lock);
    sem_post(&pool->empty);

    return result;
}

void cleanup(struct pool_data *pool) {
    free(pool->records);
    sem_destroy(&pool->lock);
    sem_destroy(&pool->empty);
    sem_destroy(&pool->full);
}

int main(int argc, char **argv) {
    size_t chunk_size = 1024; // Default value for chunk size
    size_t num_threads = 4;    // Default value for number of threads

    if (argc > 1) chunk_size = atoi(argv[1]);
    if (argc > 2) num_threads = atoi(argv[2]);

    struct pool_data pool;
    init_pool(&pool, chunk_size, num_threads);

    pthread_t threads[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        int rc = pthread_create(&threads[i], NULL, worker, &pool);
        if (rc) {
            fprintf(stderr, "Failed to create thread %ld: %s\n", i + 1, strerror(-rc));
            cleanup(&pool);
            return EXIT_FAILURE;
        }
    }

    // Main loop for inserting or retrieving records
    // ...

    // Wait for worker threads to finish
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup(&pool);

    return EXIT_SUCCESS;
}
```

