    private const string ConnectionString = "Your connection string";

    public async Task<DataTableReader> SendBytesToDatabase(byte[] bytes)
    {
        if (_client == null || !_client.Connected)
        {
            _client = new TcpClient(ConnectionString);
            _stream = _client.GetStream();
        }

        await Task.Factory.StartNew(() =>
        {
            var writer = new BinaryWriter(_stream);
            writer.Write(bytes);
            writer.Flush();
        });

        var command = "Your query string"; // Query to process the received bytes
        return ExecuteQuery(command);
    }

    private DataTableReader ExecuteQuery(string command)
    {
        using (var connection = new SqlConnection(ConnectionString))
        {
            connection.Open();
            var cmd = new SqlCommand(command, connection);
            return cmd.ExecuteReader();
        }
    }
}
