int main(int argc, char** argv) {
    int max_chunk_size = argc > 1 ? atoi(argv[1]) : MAX_CHUNK_SIZE;
    int num_workers = argc > 2 ? atoi(argv[2]) : MIN_WORKERS;
    bool enable_logging = argc > 3 && strcmp(argv[3], "true") == 0 ? true : false;

    validate_params(max_chunk_size, num_workers, enable_logging);

    pthread_t* threads = malloc(num_workers * sizeof(pthread_t));
    NFAPI_CRC_INDICATION_PDU_T* chunk = NULL;
    NFAPI_CRC_INDICATION_PDU_T** data = NULL;
    int total_items = 0;
    int processed_items = 0;

    if (enable_logging) {
        printf("Start time: %s\n", ctime(&start_time));
    }

    chunk = malloc(max_chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    data = malloc(num_workers * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < num_workers; ++i) {
        data[i] = chunk;
    }

    for (int i = 0; i < max_chunk_size; ++i) {
        chunk[i].rx_ue_information_tag = i + 1;
        chunk[i].rnti = i + 2;
        chunk[i].crc_flag = rand() % 2;
    }

    total_items = max_chunk_size * num_workers;

    progress_indicator(total_items, processed_items);

    for (int i = 0; i < num_workers; ++i) {
        pthread_create(&threads[i], NULL, worker, &data[i]);
    }

    // Wait for all workers to finish processing
    for (int i = 0; i < num_workers; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(chunk);
    free(data);
    free(threads);

    if (enable_logging) {
        printf("End time: %s\n", ctime(&end_time));
    }

    return 0;
}

void* worker(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    int chunk_size = MAX_CHUNK_SIZE / sizeof(NFAPI_CRC_INDICATION_PDU_T);

