#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

static Node* head = NULL;
static unsigned int capacity = 0;
static unsigned int size = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void resize() {
    if (capacity / 2 < size) {
        capacity *= 2;
        Node** nodes = realloc(head, sizeof(Node) * capacity);
        if (!nodes) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        head = nodes;
    }
}

void push(const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&mutex);
    if (size == capacity) resize();
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        pthread_mutex_unlock(&mutex);
        exit(EXIT_FAILURE);
    }
    new_node->data = *data;
    new_node->next = head;
    head = new_node;
    size++;
    pthread_mutex_unlock(&mutex);
}

void remove_by_rnti(RNTI rnti) {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    Node** previous = &head;

    while (current != NULL && current->data.rnti == rnti) {
        *previous = current->next;
        free(current);
        size--;
        current = (*previous);
    }

    if (current == head) pthread_mutex_unlock(&mutex);
}

void update_crcflag(RNTI rnti, bool crcflag) {
    pthread_mutex_lock(&mutex);
    Node* current = head;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            current->data.crc_indication_rel8_tag.crcflag = crcflag;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&mutex);
}
```

