Manager* manager_init(size_t initial_capacity) {
    Manager* manager = malloc(sizeof(Manager));
    manager->array = calloc((initial_capacity), sizeof(Node*));
    manager->capacity = initial_capacity;
    manager->length = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void manager_add(Manager* manager, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (manager->length >= manager->capacity) {
        manager->capacity *= 2;
        manager->array = realloc((manager->array), sizeof(Node*) * manager->capacity);
    }

    Node** current = &manager->array[manager->length++];
    *current = malloc(sizeof(Node));
    (*current)->data = *data;
    (*current)->next = NULL;
}

bool manager_remove(Manager* manager, uint32_t rnti) {
    for (size_t i = 0; i < manager->length; ++i) {
