        pdu->rnti = i % MAX_RNTIS;
        pdu->crc_flag = rand() % 2;
    }
    return NULL;
}

void create_list(size_t n, size_t chunk_size, size_t num_threads, bool log, size_t *allocs, size_t *frees) {
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for list.\n");
        exit(EXIT_FAILURE);
    }
    ++*allocs;

    pthread_t threads[num_threads];
    struct worker_arg args[num_threads];
    size_t chunk_count = n / chunk_size + (n % chunk_size > 0);
    size_t chunk_step = n / chunk_size;

    for (size_t i = 0; i < num_threads; ++i) {
        args[i].start = i * chunk_step;
        if (i == num_threads - 1) {
            args[i].end = n;
        } else {
            args[i].end = (i + 1) * chunk_step;
        }
        args[i].list = list;
    }

    clock_t start = clock();

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, worker, &args[i]);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    clock_t end = clock();

    if (log) {
        printf("List created in %.3fs\n", (double)(end - start) / CLOCKS_PER_SEC);
        printf("Memory allocations: %zu\n", *allocs);
        printf("Memory frees: %zu\n", *frees);
    }

    free(list);
    ++*frees;
}

int main(int argc, char **argv) {
    size_t n = 0, chunk_size = RAND_MAX / 2, num_threads = 1, log = 0;

    const char *short_opts = "n:c:t:l";
    const struct option long_opts[] = {
        {"num", required_argument, NULL, 'n'},
        {"chunk", required_argument, NULL, 'c'},
        {"threads", required_argument, NULL, 't'},
        {"log", no_argument, NULL, 'l'},
        {0}
    };

    while (1) {
        int option_index = 0;
        int c = getopt_long(argc, argv, short_opts, long_opts, NULL);
        if (c == -1) break;

        switch (c) {
            case 'n': n = atol(optarg); break;
            case 'c': chunk_size = atoi(optarg); break;
            case 't': num_threads = atoi(optarg); break;
            case 'l': log = 1; break;
        }
    }

    if (n <= 0 || chunk_size >= RAND_MAX / 2 || num_threads <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return EXIT_FAILURE;
    }

    size_t allocs = 0, frees = 0;
    create_list(n, chunk_size, num_threads, log, &allocs, &frees);
    return EXIT_SUCCESS;
}
