class DynamicArray {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::mutex mtx;
    std::unordered_set<int> rntiSet; // For fast RNTI lookup and unique count

public:
    void addElement(const NFAPI_CRC_INDICATION_PDU_T& element) {
        std::unique_lock<std::mutex> lock(mtx);

        if (data.size() == data.capacity())
            data.resize(data.capacity() * 2); // Double capacity on resize

        data[data.size() - 1] = element;
        rntiSet.insert(element.rnti);
    }

    bool removeElementByRNTI(int rnti) {
        std::unique_lock<std::mutex> lock(mtx);

        if (rntiSet.find(rnti) == rntiSet.end())
            return false; // RNTI not found

        auto it = std::find_if(data.begin(), data.end(), [rnti](const NFAPI_CRC_INDICATION_PDU_T& e) { return e.rnti == rnti; });

        if (it != data.end()) {
            it->crc_indication.crcflag = static_cast<uint32_t>(std::random_device{}()); // Set CRCFLAG to a random value
            rntiSet.erase(rnti);
            return true;
        }

        return false;
    }

    void updateCRCFLAGConditionally(int rnti) {
        std::unique_lock<std::mutex> lock(mtx);

        auto it = std::find_if(data.begin(), data.end(), [rnti](const NFAPI_CRC_INDICATION_PDU_T& e) { return e.rnti == rnti; });

        if (it != data.end()) {
            it->crc_indication.crcflag = static_cast<uint32_t>(std::random_device{}()); // Set CRCFLAG to a random value if condition is met
        }
    }

    size_t getUniqueRNTICount() const {
        std::unique_lock<std::mutex> lock(mtx);
        return rntiSet.size();
    }
};

