} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static Node **head = NULL;
static unsigned int capacity = 0, size = 0;

void resize() {
    if (capacity == size) {
        capacity *= 2;
        Node** new_array = realloc(head, capacity * sizeof(Node*));
        if (!new_array) {
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }
        head = new_array;
    }
}

int add(NFAPI_CRC_INDICATION_PDU_T data) {
    resize();
    Node **ptr = head + size;
    *ptr = malloc(sizeof(Node));
    if (!*ptr) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }
    (*ptr)->data = data;
    (*ptr)->next = NULL;
    size++;
    return 0;
}

int remove_by_rnti(RNTI rnti) {
    if (size == 0) return -1;

    Node **ptr = head;
    Node *prev, *current;

    pthread_mutex_lock(&mutex);
    for (current = *ptr; current != NULL; current = current->next) {
        if (current->data.rnti == rnti) {
            if (prev == NULL) {
                *ptr = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            size--;
            pthread_mutex_unlock(&mutex);
            return 0;
        }
        prev = current;
    }
    pthread_mutex_unlock(&mutex);
