#include <time.h>

typedef struct Record {
    long offset;
    int key;
    double timestamp;
    struct Record *next;
} Record;

Record* initialize_list(size_t size) {
    if (size > 10000) {
        printf("Error: maximum number of records is 10,000\n");
        return NULL;
    }

    Record *head = malloc(sizeof(Record));
    head->offset = 0;
    head->key = 0;
    head->timestamp = ((double)rand() / (RAND_MAX)) * 1000.0;
    head->next = NULL;

    Record *records = malloc(size * sizeof(Record));
    for (size_t i = 0; i < size; ++i) {
        records[i].offset = i;
        records[i].key = i;
        records[i].timestamp = ((double)rand() / (RAND_MAX)) * 1000.0;
        records[i].next = (i > 0) ? &records[(i - 1) % size] : head;
    }

    // Validate the linked list
    bool valid = true;
    for (size_t i = 0; i < size && valid; ++i) {
        Record *current = &records[i];
        if (!current || !current->next) continue;

        valid &= is_reachable(current, head);
    }

    // Cleanup memory
    free(head);
    return records;
}

bool is_reachable(Record *node, Record *start) {
    if (!node || !node->next || node == start) return true;

    return is_reachable(node->next, start);
}
```
