struct MemoryPool {
    size_t capacity;
    size_t used;
    Record* data;
    pthread_mutex_t lock;
};

struct MemoryPool* memory_pool_create(size_t initial_capacity) {
    struct MemoryPool* pool = malloc(sizeof(*pool));
    if (!pool) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    pool->capacity = initial_capacity;
    pool->used = 0;
    pool->data = calloc(initial_capacity, sizeof(Record));
    if (!pool->data) {
        perror("calloc");
        free(pool);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* memory_pool_alloc(struct MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used < pool->capacity) {
        void* record = &pool->data[pool->used];
        pool->used++;
        pthread_mutex_unlock(&pool->lock);
        return record;
    }

    // Handle memory reallocation and potential failure
    ...
}

void memory_pool_free(struct MemoryPool* pool, void* record) {
    pthread_mutex_lock(&pool->lock);

    if (record >= &pool->data[0] && record < &pool->data[pool->used]) {
        pool->used--;
    } else {
        fprintf(stderr, "Invalid memory pool record\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_unlock(&pool->lock);
}

// Function to process records in parallel using multiple threads
