    for (int i = 0; i < num_threads; ++i) {
        records[i] = memory_pool_alloc(pool);
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        int rc = pthread_create(&threads[i], NULL, process_record, &records[i]);
        if (rc) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(records);
}

void* process_record(void* record) {
    // Process the given record, log memory usage, and potentially integrate with external data sources
    ...
    memory_pool_free(pool, record);
    return NULL;
}
