typedef struct {
    char *key;
    char *value;
    pthread_mutex_t lock;
} Config;

typedef struct ListNode {
    Config* config;
    struct ListNode* next;
} ListNode;

ListNode* head = NULL;
pthread_mutex_t list_lock;

void init_list() {
    pthread_mutex_init(&list_lock, NULL);
}

Config* create_config(char *key, char *value) {
    Config* new_config = (Config*)malloc(sizeof(Config));
    new_config->key = key;
    new_config->value = value;
    pthread_mutex_init(&new_config->lock, NULL);
    return new_config;
}

void add_config(Config* config) {
    pthread_mutex_lock(&list_lock);
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    new_node->config = config;
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&list_lock);
}

Config* find_config(char *key) {
    ListNode* current = head;
    while (current != NULL) {
        pthread_mutex_lock(&current->config->lock);
        if (strcmp(current->config->key, key) == 0) {
            pthread_mutex_unlock(&current->config->lock);
            return current->config;
        }
        pthread_mutex_unlock(&current->config->lock);
        current = current->next;
    }
    return NULL;
}

void remove_config(char *key) {
    pthread_mutex_lock(&list_lock);
    ListNode* previous = NULL;
    ListNode* current = head;
    while (current != NULL) {
        if (strcmp(current->config->key, key) == 0) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current->config->key);
            free(current->config->value);
            free(current->config);
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

