        // Open the input file using memory-mapped I/O
        if ((fd = open(opts.output_file, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
            perror("Error opening output file");
            return 1;
        }

        if (posix_mmap(0, mmap_size = lseek(fd, 0, SEEK_END), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0) == MAP_FAILED) {
            perror("Error memory-mapping input file");
            close(fd);
            return 1;
        }

        mmap_addr = mmap(NULL, mmap_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);

        if (mmap_addr == MAP_FAILED) {
            perror("Error memory-mapping input file");
            close(fd);
            return 1;
        }

        pthread_t threads[argc]; // Assuming the number of input files is equal to argc - 1 (excluding the program name itself)

        for (int i = 1; i < argc; ++i) {
            size_t lines = count_lines(mmap_addr, mmap_size);

            // Send line count to external service
            send_to_external(lines);

            // Create and start a thread for each input file
            pthread_create(&threads[i - 1], NULL, process_input, (void*)&opts);
        }

        munmap(mmap_addr, mmap_size);
        close(fd);

        // Wait for all threads to finish
        for (int i = 0; i < argc - 1; ++i) {
            pthread_join(threads[i], NULL);
        }
    }

    return 0;
}
```

