        free(node->data);
        gsl_rbtree_node *n;
        while ((n = gsl_rbtree_minimum(coll->tree)))
            if (n != coll->tree) {
                gsl_rbtree_rotate_right(coll->tree, n);
                gsl_rbtree_delete(coll->tree, n);
                free(n->data);
                gsl_rbtree_node *nn;
                while ((nn = gsl_rbtree_minimum(coll->tree)))
                    if (nn != coll->tree) {
                        gsl_rbtree_rotate_right(coll->tree, nn);
                        break;
                    }
            }
    }
    pthread_mutex_unlock(&coll->mutex);
    return true;
}

bool update_PHY_TXDU(NFAPI_L1_API_T *coll, uint32_t TX_FRAME_ID, PHY_TXDU newItem) {
    pthread_mutex_lock(&coll->mutex);
    gsl_rbtree_node *node = gsl_rbtree_find(coll->tree, &TX_FRAME_ID);
