#include <pthread.h>

#define MAX_CACHE_SIZE 1024
#define BUFFER_LEN 1024
#define MAX_ID_LEN 64
#define MAX_FILE_SIZE 1GB // Adjust as per requirement

typedef struct {
    char *content;
    size_t size;
    time_t timestamp;
} file_metadata;

typedef struct btree_node {
    int key;
    struct btree_node **children;
    struct btree_node *parent;
    struct btree_node *right_sibling;
    file_metadata data;
    pthread_mutex_t lock;
} btree_node;

void btree_init(btree_node *node) {
    node->children = calloc((MAX_FILE_SIZE / BUFFER_LEN + 1), sizeof(btree_node*));
    node->parent = NULL;
    node->right_sibling = NULL;
    pthread_mutex_init(&node->lock, NULL);
}

void btree_destroy(btree_node *node) {
    for (int i = 0; i <= MAX_FILE_SIZE / BUFFER_LEN; ++i) {
        if (node->children[i]) free(node->children[i]);
    }
    free(node->children);
    pthread_mutex_destroy(&node->lock);
}

btree_node* find_leaf(btree_node *node, size_t key) {
    for (int i = MAX_FILE_SIZE / BUFFER_LEN; i >= 0; --i) {
        if (!node->children[i]) continue;
        btree_node *child = node->children[i];
        if (key < child->key) {
            node = child;
            continue;
        } else if (child->key == key) {
            return child;
        }
    }
    return NULL;
}

void insert(btree_node *root, file_metadata data) {
    btree_node *new_node = malloc(sizeof(btree_node));
    memcpy(&new_node->data, &data, sizeof(file_metadata));
    new_node->key = data.size;
    btree_init(new_node);

    btree_node *leaf = root;
    while (1) {
        leaf = find_leaf(leaf, data.size);
        if (!leaf) {
            leaf = new_node;
            break;
        }
        // Insertion logic and balancing/rotation mechanisms go here
    }

    if (!leaf->parent) root->children[0] = leaf;
    else {
        leaf->parent->children[leaf->key] = leaf;
        balance(leaf->parent);
    }
}

void* cache_buffer;
size_t cache_index;
pthread_mutex_t cache_lock;

void* get_cached_buffer() {
    pthread_mutex_lock(&cache_lock);
    if (cache_index < MAX_CACHE_SIZE) {
        void *tmp = cache_buffer;
        cache_buffer = cache_buffer + BUFFER_LEN;
        cache_index++;
        return tmp;
    }

    // LRU eviction logic goes here to find the least recently used buffer and replace it

    pthread_mutex_unlock(&cache_lock);
    return malloc(BUFFER_LEN);
}

file_metadata create_file_metadata(const char *base, const char *id) {
    file_metadata data;
    size_t len = strlen(base) + 1 + strlen(id) + 1;
    if (len > BUFFER_LEN) return data;

    void *buffer = get_cached_buffer();
    snprintf(buffer, BUFFER_LEN, "%s%s", base, id);
    data.size = len;
    data.timestamp = time(NULL);
    data.content = buffer;
    return data;
}
