NFAPI_CRC_INDICATION_PDU_T *list;
pthread_mutex_t list_mutex;
int num_structures = 0;

void populate_list(int N) {
    // Ensure list is initialized only once
    static pthread_once_t once = PTHREAD_ONCE_INIT;

    if (num_structures > 0) return;

    pthread_mutex_init(&list_mutex, NULL);

    // Allocate memory for the structures and set initial values
    list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < MAX_STRUCTURES && i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = i * 123456789;
        list[i].RNTI = i + 12345;
        list[i].CRC_INDICATION_REL8_TAG[0] = (i / 10) % 256;
        list[i].CRC_INDICATION_REL8_TAG[1] = (i / 100) % 256;
        list[i].CRC_INDICATION_REL8_TAG[2] = (i / 1000) % 256;
        list[i].CRC_INDICATION_REL8_TAG[3] = (i / 10000) % 256;
        list[i].CRCFLAG = rand() % 2;
    }

    num_structures = N < MAX_STRUCTURES ? N : MAX_STRUCTURES;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T *new_entry) {
    if (num_structures >= MAX_STRUCTURES) return;

    pthread_mutex_lock(&list_mutex);

    // Find an empty slot in the list
    int i = num_structures;
    while (i < MAX_STRUCTURES && list[i].RX_UE_INFORMATION_TAG != 0) ++i;

    if (i == MAX_STRUCTURES) {
        perror("List is full");
        exit(EXIT_FAILURE);
    }

    // Copy the new entry and increment number of structures
    memcpy(&list[i], new_entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    num_structures++;

    pthread_mutex_unlock(&list_mutex);
}

