#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 10000
#define UPDATE_RATE 1000000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct list {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

void init_list(struct list *list) {
    list->data = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = 1;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void push_to_list(struct list *list) {
    if (list->count + 1 == list->capacity) {
        list->data = realloc(list->data, (list->capacity * 2) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->capacity *= 2;
    }

    list->data[list->count].RX_UE_INFORMATION_TAG = rand();
    list->data[list->count].RNTI = rand();
    list->data[list->count].CRC_INDICATION_REL8_TAG = rand();
    list->data[list->count].CRCFLAG = rand() % 2 == 0;

    pthread_mutex_lock(&list->mutex);
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void update_list(struct list *list) {
    if (clock() - list->last_update > UPDATE_RATE / UPDATE_RATE) {
        push_to_list(list);
        list->last_update = clock();
    }
}

int main() {
    struct list list;
    init_list(&list);
    pthread_t threads[MAX_THREADS];

    for (size_t i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, update_list_thread, &list);
    }

    // Manage and join all threads here...

    return 0;
}

void *update_list_thread(void *arg) {
    struct list *list = arg;

    while (true) {
        update_list(list);
        usleep(1000); // Adjust sleep time for desired throughput
    }

    return NULL;
}
