class ConnectionDetails {
public:
    std::string ip;
    int port;

    ConnectionDetails(const std::string& ip, int port) : ip(ip), port(port) {}
};

class UserSessionInfo {
public:
    uint64_t sessionID;
    time_t timestamp;
    std::vector<ConnectionDetails> connections;

    UserSessionInfo(uint64_t sessionID, const time_t& timestamp) : sessionID(sessionID), timestamp(timestamp) {}
};

class ThreadSafeList {
private:
    std::mutex mtx;
    std::vector<UserSessionInfo> sessions;
    std::map<uint64_t, size_t> sessionIndices;

    std::condition_variable cv;
    bool isExporting = false;

public:
    ThreadSafeList() {}

    void addSession(const UserSessionInfo& session) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !isExporting; });

        sessions.push_back(session);
        sessionIndices[session.sessionID] = sessions.size() - 1;
    }

    void removeSession(uint64_t sessionID) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, sessionID] { return sessionIndices.find(sessionID) != sessionIndices.end(); });

        auto it = sessions.begin();
        for (; it != sessions.end(); ++it) {
            if (it->sessionID == sessionID) {
                size_t indexToErase = it - sessions.begin();
                it = sessions.erase(it);

                sessionIndices.erase(sessionID);
                for (auto& pair : sessionIndices) {
                    if (pair.second > indexToErase)
                        pair.second--;
                }
                break;
            }
        }
    }

    void updateConnection(uint64_t sessionID, const ConnectionDetails& connection) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, sessionID] { return sessionIndices.find(sessionID) != sessionIndices.end(); });

        auto it = sessions.begin();
        for (; it != sessions.end(); ++it) {
            if (it->sessionID == sessionID) {
                it->connections.push_back(connection);
                break;
            }
        }
    }

    void exportToCSV() {
        isExporting = true;
        std::stringstream ss;
        std::unique_lock<std::mutex> lock(mtx);
        cv.notify_all();

        // Thread-safe CSV file creation and data formatting are handled here
        // ...
    }

    void loadFromCSV() {
        // Data validation and storage of loaded data is handled here
        // ...
    }
};
