import os
import hashlib
from Crypto.Cipher import AES, Camellia
from Crypto.Hash import SHA1, MD5
from Crypto.PublicKey import RSA
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging
from datetime import timedelta
import requests
import sys
import psutil

class CryptographicLibrary:
    def __init__(self):
        self.aes = AES.new(b'my_secret_key', AES.MODE_CFB, b'my_iv')  # Replace with your key and iv
        self.camellia = Camellia.new(b'your_secret_key', Camellia.MODE_CFB, b'your_iv')  # Replace with your key and iv
        self.md5 = hashlib.md5()
        self.sha1 = SHA1.new()
        self.rsa = RSA.construct((n=..., e=...))  # Load your RSA keys here

def progress_indicator(completed, total):
    percentage = (completed / total) * 100 if total != 0 else 0
    sys.stderr.write(f"{percentage:.2f}% completed\r")
    sys.stderr.flush()

def hash_file(library, file_path):
    with open(file_path, 'rb') as f:
        for chunk in iterate_chunks(f, max_chunk_size):
            library.md5.update(chunk)

def compute_digest(library, file_path, digest_type):
    if digest_type == 'MD5':
        return library.md5.hexdigest()
    elif digest_type == 'SHA1':
        return library.sha1.hexdigest()
    else:
        raise ValueError(f"Unsupported digest type: {digest_type}")

def process_file(library, file_path):
    try:
        if os.path.islink(file_path) or not any(file_path.endswith(ext) for ext in skip_extensions):
            logging.info(f"Processing {file_path}")
            digest = compute_digest(library, file_path, 'MD5')
            logging.debug(f"MD5 hash of {file_path}: {digest}")
        else:
            logging.info(f"Skipping {file_path} (skip extensions match)")
    except Exception as e:
        logging.error(f"Error processing {file_path}: {str(e)}", exc_info=True)

def iterate_chunks(file, max_chunk_size):
    position = 0
    while True:
        chunk = file.read(max_chunk_size)
        if not chunk:
            break
        yield chunk
        position += len(chunk)

def process_directory(library, dir_path, skip_extensions=['.exe', '.dll']):
    total_files = sum(1 for _ in os.scandir(dir_path) if _.is_file())
    progress_indicator(0, total_files)

    executor = ThreadPoolExecutor(max_workers=psutil.cpu_count() * 2)
    futures = {executor.submit(process_file, library, os.path.join(dir_path, file_name)): file_name for _, (dirpath, dirnames, filenames) in os.scandir(dir_path) if _.is_dir() for file_name in filenames}

    try:
        for future in as_completed(futures):
            progress_indicator(len({future for future in futures if not future.done()}), total_files)
    except KeyboardInterrupt:
        logging.info("Interrupted, resuming...")
        for future in as_completed(futures):
            try:
                future.result()
            except Exception as e:
                logging.error(f"Error resuming: {str(e)}", exc_info=True)

def main():
    library = CryptographicLibrary()
    log_filename = "cryptography_log.txt"
    with open(log_filename, 'w') as logfile:
        logging.basicConfig(filename=log_filename, level=logging.DEBUG)
    process_directory(library, sys.argv[1], skip_extensions=sys.argv[2:])

if __name__ == "__main__":
    main()
```

