typedef struct {
    unsigned int NODE_ID;
    char MAC_ADDRESS[6];
    int CONNECTION_STATUS;
    char IP_ADDRESS[16];
} NODE_INFO;

struct node_manager {
    NODE_INFO** nodes;
    size_t num_nodes;
    pthread_mutex_t lock;
};

void init_node_info(NODE_INFO* node, unsigned int id) {
    time_t t = time(NULL);
    srand((unsigned int)t * (int)(id % 10000));
    snprintf(node->IP_ADDRESS, sizeof(node->IP_ADDRESS), "%u.%u.%u.%u", id / 256, id % 256, id / 65536, id % 65536);
}

int validate_node_info(const NODE_INFO* node) {
    // Add your custom validation checks here
    return strlen(node->IP_ADDRESS) == 15;
}

void update_connection_status(NODE_INFO* node, int status) {
    node->CONNECTION_STATUS = status;
}

struct node_manager* create_node_manager(size_t num_nodes, unsigned int seed) {
    struct node_manager* manager = malloc(sizeof(struct node_manager));
    if (!manager) {
        perror("Error allocating memory for the node manager.");
        return NULL;
    }

    manager->num_nodes = num_nodes;
    pthread_mutex_init(&manager->lock, NULL);

    manager->nodes = calloc(num_nodes, sizeof(NODE_INFO*));
    if (!manager->nodes) {
        perror("Error allocating memory for the node array.");
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < num_nodes; ++i) {
        manager->nodes[i] = malloc(sizeof(NODE_INFO));
        if (!manager->nodes[i]) {
            perror("Error allocating memory for a node.");
            for (size_t j = 0; j < i; ++j) {
                free(manager->nodes[j]);
            }
            free(manager->nodes);
            free(manager);
            return NULL;
        }

        init_node_info(manager->nodes[i], i + seed);
    }

    return manager;
}

void destroy_node_manager(struct node_manager* manager) {
    for (size_t i = 0; i < manager->num_nodes; ++i) {
        free(manager->nodes[i]);
    }
    free(manager->nodes);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Access function with locking to ensure thread safety
NODE_INFO* get_node_info(struct node_manager* manager, unsigned int id) {
    NODE_INFO* node = manager->nodes[id];

    pthread_mutex_lock(&manager->lock);
    if (!validate_node_info(node)) {
        printf("Error: Invalid node info.\n");
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }
    pthread_mutex_unlock(&manager->lock);

    return node;
}
