    struct Record *prev, *next;
} Record;

struct LinkedList {
    size_t size;
    Record *head;
    Record **data;
    pthread_mutex_t mutex;
};

void init_linked_list(struct LinkedList *ll, size_t capacity) {
    ll->size = 0;
    ll->head = NULL;
    ll->capacity = capacity;
    ll->data = malloc(sizeof(Record*) * capacity);
    for (size_t i = 0; i < capacity; ++i) {
        ll->data[i] = NULL;
    }
    pthread_mutex_init(&ll->mutex, NULL);
}

Record* create_record(size_t index) {
    Record *record = malloc(sizeof(Record));
    record->offset = index;
    record->key = index;
    record->timestamp = (double)rand() / RAND_MAX * 1000.0;
    record->prev = NULL;
    record->next = NULL;
    return record;
}

bool add_to_linked_list(struct LinkedList *ll, Record *record) {
    pthread_mutex_lock(&ll->mutex);
    if (ll->size == 0) {
        ll->head = record;
    } else {
        Record *current = ll->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    }
    ll->data[record->offset] = record;
    ++ll->size;
    pthread_mutex_unlock(&ll->mutex);
    return true;
}

void validate_linked_list(struct LinkedList *ll) {
    // Implement a validation mechanism to ensure the integrity of the linked list, checking for cycles and ensuring every record is reachable from the head node.
