    init_linked_list(ll, capacity);
    Record **records = malloc(capacity * sizeof(Record*));
    for (size_t i = 0; i < capacity; ++i) {
        records[i] = create_record(i);
        add_to_linked_list(ll, records[i]);
    }
    // Fetch metadata asynchronously and concurrently.
    pthread_t threads[capacity];
    for (size_t i = 0; i < capacity; ++i) {
        pthread_create(&threads[i], NULL, (void*(*)(void*))fetch_metadata, records[i]);
    }
    // Wait for all threads to complete.
    for (size_t i = 0; i < capacity; ++i) {
        pthread_join(threads[i], NULL);
    }
    validate_linked_list(ll);
    // Deallocate memory for records and handle any failures gracefully.
    for (size_t i = 0; i < capacity; ++i) {
        free(records[i]);
    }
    free(records);
    return ll;
}
