namespace RandomGenerator {
    class StringHasher {
        public:
            std::mt19937 gen;

            StringHasher() : gen((std::chrono::high_resolution_clock::now().time_since_epoch()).count()) {}
            ~StringHasher() {}

            static std::mt19937& getGen() { return instance; }

            std::vector<unsigned char> getMD5Hash(const std::string& input) {
                unsigned char digest[SHA_DIGEST_LENGTH];
                SHA256_CTX ctx;
                SHA256_Init(&ctx);
                SHA256_Update(&ctx, input.c_str(), input.size());
                SHA256_Final(digest, &ctx);
                return std::vector<unsigned char>(digest, digest + sizeof(digest));
            }

        private:
            static std::mt19937 instance;
    };

    std::mt19937 StringHasher::instance;

