struct Record {
    long offset;
    int key;
    double timestamp;
    char status_flag;
    float precision_level;
    bool validity;
};

typedef std::list<Record> RecordList;

struct Stats {
    size_t total_requests;
    size_t successful_requests;
    size_t failed_requests;
    enum FailureType { API, NETWORK } failure_type;
};

Stats create_linked_list(RecordList* list, const int max_nodes) {
    Stats stats = {};
    RecordList nodes(max_nodes);

    std::mutex mtx; // For thread-safety
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, nullptr);

    for (int i = 0; i < max_nodes && i < 10000; ++i) {
        Record* node = &nodes[i];
        node->offset = static_cast<long>(i);
        node->key = i;
        node->timestamp = (double)(rand() % 1000 + 1);
        node->status_flag = rand() % 2 == 0 ? 'Y' : 'N';
        node->precision_level = static_cast<float>(rand() % 5 + 1);
        node->validity = true;

        // Asynchronous API call with fallback strategy
        if (!api_call(node->key, &node->validity)) {
            usleep(100000); // Retry delay
            if (!api_call(node->key, &node->validity)) {
                node->validity = false;
                ++stats.failed_requests;
                stats.failure_type = FAILURE_TYPE::API;
            }
        } else {
            ++stats.successful_requests;
        }

        // Link the nodes in a circular singly linked list
        if (i > 0)
            node->next = &nodes[(i + 1) % max_nodes];
        else
            node->next = &nodes[max_nodes - 1];
    }

    RecordList::iterator it = nodes.begin();
    Record* head = *it;
    for (++it; it != nodes.end(); ++it) {
        (*it)->prev = it == nodes.begin() ? nullptr : it->prev;
        (*it)->next = it + 1 == nodes.end() ? head : it + 1;
    }
    head->prev = nodes.rbegin().base();

    // Integrity check: Check for cycles and ensure every record is reachable from the head node
    std::vector<Record*> visited;
    Record* current = head;
    while (current != nullptr) {
        if (std::find(visited.begin(), visited.end(), current) != visited.end()) {
            // Cycle detected, log error and break loop
            LOG4CXX_ERROR("Detected cycle in linked list");
            break;
        }
        visited.push_back(current);
        if (current->next == nullptr || std::find(visited.begin(), visited.end(), current->next) == visited.end()) {
            // Unreachable node, log error and break loop
            LOG4CXX_ERROR("Unreachable node in linked list");
            break;
        }
        current = current->next;
    }

    pthread_mutex_destroy(&lock);

    // Initialize summary of validity indicators for each record
    std::vector<bool> validity_summaries(max_nodes, true);
    for (auto& node : nodes) {
        if (!node.validity) {
            validity_summaries[node.key] = false;
        }
    }

    return stats;
}
