int is_reachable(struct node *node, struct node *head) {
    if (!node || !head || node == head) {
        return 1;
    }

    if (node->prev && node->prev != head && is_reachable(node->prev, head)) {
        return 1;
    }

    if (node->next && is_reachable(node->next, head)) {
        return 1;
    }

    return 0;
