#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char buffer[256];
} entry;

entry* load_entries(const char *filename, size_t *num_entries) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t total_size = ftell(file);
    rewind(file);

    entry *entries = malloc((total_size - 1) / sizeof(entry)); // subtract one for the double value and account for padding
    if (!entries) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    size_t current_offset = 0;
    while (fread(&entries[current_offset], sizeof(entry), 1, file) > 0) {
        entries[current_offset].buffer[sizeof(entries[current_offset].value)] = '\0'; // ensure string termination
        current_offset++;
    }

    *num_entries = current_offset;
    fclose(file);

    return entries;
}

double calculate_average(const entry *entries, size_t num_entries) {
    double sum = 0.0;
    for (size_t i = 0; i < num_entries; ++i)
        sum += entries[i].value;
    return sum / num_entries;
}
