from contextlib import suppress
from concurrent.futures import ThreadPoolExecutor, as_completed
from io import BufferedReader

class FileHasher:
    def __init__(self, filepath, chunk_size=65536, num_workers=os.cpu_count()):
        self.filepath = filepath
        self.chunk_size = chunk_size
        self.num_workers = num_workers
        self.hasher = hashlib.md5()
        self.log = logging.getLogger(__name__)
        self.setup_logger()

    def setup_logger(self):
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        console_handler = logging.StreamHandler(sys.stderr)
        console_handler.setLevel(logging.INFO)
        console_handler.setFormatter(formatter)
        self.log.addHandler(console_handler)

    def get_chunk(self, file):
        return file.read(self.chunk_size), len(file.read(sys.maxsize))

    def process_chunk(self, chunk, size):
        with suppress(Exception):
            self.hasher.update(chunk[0])
        self.log.info(f'Hashed {size} bytes')

    def hash_file(self):
        with open(self.filepath, 'rb') as file:
            processed = 0
            with ThreadPoolExecutor(max_workers=self.num_workers) as executor:
                future_to_chunk = {executor.submit(self.process_chunk, chunk, size): chunk for chunk, size in iterate_chunks(file)}
                for future in as_completed(future_to_chunk):
                    processed += future.result()
            self.log.info(f'Hashed the entire file: {self.hasher.hexdigest()}')

    def validate_hash(self, expected_md5):
        calculated_md5 = self.hasher.hexdigest()
        if calculated_md5 != expected_md5:
            raise ValueError(f'Calculated hash does not match the expected value: {calculated_md5} != {expected_md5}')
        self.log.info('Hash validation succeeded')

def iterate_chunks(file, buffer_size=4 * (1024 ** 2)):
    buffer = BufferedReader(file, buffer_size)
    while True:
        chunk, size = get_next_chunk(buffer)
        if not chunk:
            break
        yield chunk, size

def get_next_chunk(buffer):
    return buffer.read(), len(buffer.read(sys.maxsize))
