["Here's a Python solution that fulfills your requirements for calculating MD5 hashes of large files efficiently:

```python
import os
import sys
import hashlib
import argparse
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed

class FileHash:
    def __init__(self, filepath, chunk_size=65536):
        self.filepath = filepath
        self.chunk_size = chunk_size
        self.hasher = hashlib.md5()

    def _read_and_hash(self):
        with open(self.filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(self.chunk_size), b''):
                self.hasher.update(chunk)

    def calculate(self):
        try:
            self._read_and_hash()
            return self.hasher.hexdigest()
        except Exception as e:
            raise ValueError(f'Failed to calculate hash: {e}')

    def compare(self, expected_hash):
        calculated_hash = self.calculate()
        if calculated_hash != expected_hash:
            raise ValueError(f'Hash mismatch! Expected: {expected_hash}, Calculated: {calculated_hash}')

class RecordPool:
    def __init__(self, pool_size):
        self.pool = [None] * pool_size
        self.available_slots = pool_size

    def allocate(self):
        if self.available_slots <= 0:
            raise ValueError('Pool is full')
        index = -1
        for i in range(len(self.pool)):
            if self.pool[i] is None:
                index = i
                break
        self.pool[index] = Record()
        self.available_slots -= 1
        return index

    def release(self, index):
        if index < 0 or index >= len(self.pool):
            raise ValueError('Invalid index')
        if self.pool[index] is not None:
            self.pool[index] = None
            self.available_slots += 1

class Record:
    def __init__(self):
        self.value = None
        self.lock = threading.Lock()

def main(args):
    filepath = args.filepath
    expected_hash = args.expected_hash
    chunk_size = int(args.chunk_size) or 65536
    threads = int(args.threads) or os.cpu_count() * 2

    file_hash = FileHash(filepath, chunk_size)
    with ThreadPoolExecutor(max_workers=threads) as executor:
        for future in executor.map(partial(file_hash._read_and_hash, file_hash), range(threads)):
            pass

    try:
        calculated_hash = file_hash.calculate()
        if calculated_hash != expected_hash:
            logging.error(f'Hash mismatch! Expected: {expected_hash}, Calculated: {calculated_hash}')
            sys.exit(1)
    except Exception as e:
        logging.error(f'Error while calculating hash: {e}')
        sys.exit(1)

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--filepath', required=True, help='Path to the file')
    parser.add_argument('--expected-hash', required=True, help='Expected MD5 hash of the file')
    parser.add_argument('--chunk-size', help='Chunk size for reading the file (default: 65536)')
    parser.add_argument('--threads', help='Number of worker threads (default: double the number of available CPUs)')
    args = parser.parse_args()
    main(args)
```

