struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint32_t crcflag;
};

typedef struct node {
    struct NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

struct thread_data {
    Node** array;
    pthread_mutex_t mutex;
};

Node* create_node(const struct NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = *data;
    new_node->next = NULL;
    return new_node;
}

void set_crcflag(Node* node, uint32_t value) {
    node->data.crcflag = value;
}

uint32_t get_unique_rnti(const Node** array, size_t size) {
    uint64_t unique_count = 0;
    for (size_t i = 0; i < size; ++i) {
        if ((*array)[i].rnti > unique_count) {
            unique_count = (*array)[i].rnti;
        }
    }
    return unique_count + 1;
}

void array_resize(Node** array, size_t* size, size_t new_size) {
    Node** new_array = realloc(*array, new_size * sizeof(Node*));
    if (!new_array) return;
    memmove(new_array, *array, *size * sizeof(Node*));
    for (size_t i = *size; i < new_size; ++i) {
        new_array[i] = NULL;
    }
    *array = new_array;
    *size = new_size;
}

void add_element(Node** array, size_t* size, const struct NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&((struct thread_data*)array[0])->mutex);
    if (*size >= *array) {
        array_resize(array, size, *size * 2);
    }
    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&((struct thread_data*)array[0])->mutex);
        return;
    }
    size_t rnti_index = new_node->data.rnti - 1;
    Node** current = array;
    for (size_t i = 0; i < rnti_index; ++i) {
        current = &((*current)->next);
    }
    new_node->next = (*current);
    *current = new_node;
    pthread_mutex_unlock(&((struct thread_data*)array[0])->mutex);
}

