Record* create_list(const char *path, size_t max_nodes) {
    pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
    Record *head = NULL, **current = &head;
    struct HashData hash_data;
    size_t num_nodes = 0;

    FILE *file = fopen(path, "rb");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    void* buf = mmap(NULL, 4096, PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (buf == MAP_FAILED) {
        perror("Error mapping file");
        fclose(file);
        return NULL;
    }

    hash_data.size = 0;
    MD5_Init(&hash_data.md5);

    while (num_nodes < max_nodes && fread(buf, 1, 4096, file) > 0) {
        size_t index = num_nodes++;
        Record *node = malloc(sizeof(Record));
        if (!node) {
            perror("Error allocating memory");
