    class RandomState:
        def __init__(self):
            self._state = 0

        def randfloat(self, low: float, high: float, is_inclusive=True) -> float:
            if is_inclusive:
                return (low + self._state * (high - low)) % (high - low + 1) + low
            else:
                return (low + self._state * (high - low)) % (high - low) + low

        def randint(self, low: int, high: int, is_inclusive=True) -> int:
            if is_inclusive:
                return int((self.randfloat(low, high + 1) - low))
            else:
                return int((self.randfloat(low, high) - low))

        def randcolor(self, rgb_range=(0, 255)):
            r = self.randint(*rgb_range)
            g = self.randint(*rgb_range)
            b = self.randint(*rgb_range)
            return (r, g, b)

