        else:
            file = input_source

        try:
            async with osasyncio.scopes().get_event_loop().create_task(self._read_chunk(file)):
                data = await self._read_chunk(file)
                for chunk in data:
                    self._process(chunk)
                    if output_stream:
                        await output_stream.write(chunk)
        except (OSError, TimeoutError) as e:
            # Handle transient errors with exponential backoff
            backoff = 2 ** (self._random.randint(0, max=len(self._log)))
            await asyncio.sleep(backoff)
            if len(self._log) > backoff:
                self._log.pop(backoff - 1)
            else:
