    FILE *file = fopen(path, "rb");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    void *map_ptr = mmap(NULL, chunk_size, PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (map_ptr == MAP_FAILED) {
        perror("Error mapping file");
        fclose(file);
        return NULL;
    }

    size_t bytes_read = 0;
    Record *current_node = head, *new_node;
    unsigned int records_processed_locally = 0;

    while (records_processed_locally < max_records && !feof(file)) {
        if (bytes_read + chunk_size > ftell(file)) {
            // Adjust chunk size based on file size and system resources
            chunk_size = ftell(file) - bytes_read;
        }

        void *data = mmap(NULL, chunk_size, PROT_READ, MAP_PRIVATE, fileno(file), bytes_read);
        if (data == MAP_FAILED) {
            perror("Error mapping file");
            munmap(map_ptr, chunk_size);
            fclose(file);
            return NULL;
        }

        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, read_file_chunk, data)) {
            perror("Error creating thread");
            munmap(data, chunk_size);
            continue;
        }

        bytes_read += chunk_size;
    }

    if (bytes_read != ftell(file)) {
        void *data = mmap(NULL, ftell(file) - bytes_read, PROT_READ, MAP_PRIVATE, fileno(file), bytes_read);
        if (data == MAP_FAILED) {
            perror("Error mapping file");
            fclose(file);
            return NULL;
        }

        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, read_file_chunk, data)) {
            perror("Error creating thread");
            munmap(data, ftell(file) - bytes_read);
            return NULL;
        }

        bytes_read = ftell(file);
    }

    fclose(file);
    munmap(map_ptr, chunk_size);

    void *data = mmap(NULL, bytes_read, PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (data == MAP_FAILED) {
        perror("Error mapping file");
        return NULL;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, read_file_chunk, data)) {
        perror("Error creating thread");
        munmap(data, bytes_read);
        return NULL;
    }

    // Wait for all threads to finish processing the file chunks
    while (pthread_join(thread_id, NULL)) {}

    if (!head) {
        free(data);
        return NULL;
    }

    // Calculate MD5 hash and store as part of the last node in the list
    unsigned char digest[MD5_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    Record *last_node = head;
    while (last_node->next) {
        last_node = last_node->next;
        SHA256_Update(&ctx, (unsigned char*)last_node, sizeof(Record));
    }
    SHA256_Final(digest, &ctx);
    memcpy(last_node->prev, digest, MD5_DIGEST_LENGTH);

    // Validate the integrity of the linked list
    if (!validate_list(head)) {
        free_list(head);
        return NULL;
    }

    return head;
}

