int convert_jpeg_to_pdf(const char* input, const char* output) {
  char cmd[256];
  snprintf(cmd, sizeof(cmd), "convert %s %s", input, output);
  pid_t child_pid = fork();

  if (child_pid == -1) {
    // Fork failure
    return 1;
  } else if (child_pid > 0) {
    // Parent: continue with parent process
    wait(NULL);
    return 0;
  } else {
    // Child: execute command
    if (execl("/usr/bin/convert", "convert", input, output, NULL) < 0) {
      // Execution failure
      perror("Error while executing convert command");
      exit(1);
    }
  }
}
