    MD5_CTX md5_context;
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    int verbosity;
    size_t chunk_size;
    FILE *file;
    Record *head, *tail;
} Context;

void create_record(Record **node) {
    *node = malloc(sizeof(Record));
    if (!*node) {
        perror("malloc");
        exit(1);
    }
    memset(*node, 0, sizeof(Record));
}

void init_context(Context *ctx, const char *path, int verbosity, size_t chunk_size) {
    ctx->file = fopen(path, "rb");
    if (!ctx->file) {
        perror("fopen");
        exit(1);
    }
    ctx->verbosity = verbosity;
    ctx->chunk_size = chunk_size;
    pthread_mutex_init(&ctx->mutex, NULL);
}

void destroy_context(Context *ctx) {
    Record *node = ctx->head;
    while (node) {
        Record *next = node->next;
        free(node);
        node = next;
    }
    fclose(ctx->file);
    pthread_mutex_destroy(&ctx->mutex);
}

void* read_and_process(void *arg) {
    Context *ctx = arg;
    char buffer[ctx->chunk_size];
    size_t bytes_read;

    while ((bytes_read = fread(buffer, sizeof(char), ctx->chunk_size, ctx->file))) {
        pthread_mutex_lock(&ctx->mutex);
        Record *node = malloc(sizeof(Record));
        if (!node) {
            perror("malloc");
            break;
        }
        memcpy(node, buffer, bytes_read);
        node->prev = ctx->tail;
        node->next = NULL;

        MD5_Update(&node->md5_context, buffer, bytes_read);
        if (ctx->tail) {
            ctx->tail->next = node;
        } else {
            ctx->head = node;
        }
        ctx->tail = node;

        if (++(ctx->tail->key) >= NUM_RECORDS) {
            break;
        }

        // Implement API call and metadata processing here, using a fallback strategy for failed requests.

        pthread_mutex_unlock(&ctx->mutex);
    }

    return NULL;
}

Record* create_list(const char *path, int verbosity, size_t chunk_size) {
    Context ctx = { 0 };
    init_context(&ctx, path, verbosity, chunk_size);

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, &read_and_process, &ctx)) {
            perror("pthread_create");
            destroy_context(&ctx);
            return NULL;
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Perform additional list validation, logging, and progress indicators here.

