Regarding the Java method, here's a simple outline of its implementation in Rust using the `native-tls` crate:

```rust
use std::ffi::{CString, CStr};
extern "C" {
    fn OpenSSL_MD5_init(_: *mut libc::c_void) -> *mut libc::c_void;
    fn OpenSSL_MD5_update(_: *mut libc::c_void, _: &[u8], _: usize) -> ();
    fn OpenSSL_MD5_final(_: *mut libc::c_void, _: &mut u8) -> ();
}

pub fn md5_hash(s: &str) -> String {
    let mut hasher = unsafe { OpenSSL_MD5_init(std::ptr::null_mut()) };
    let c_s = CString::new(s).unwrap();
    let slice = c_s.as_bytes();

    for chunk in slice.chunks(64) {
        unsafe {
            OpenSSL_MD5_update(&mut hasher, chunk.as_ptr(), chunk.len());
        }
    }

    let mut digest = [0u8; 16];
    unsafe {
        OpenSSL_MD5_final(&mut hasher, digest.as_mut_ptr());
    }

    let mut result = String::new();
    for byte in &digest {
        result += format!("{:02x}", byte).as_str();
    }

    result
}
