Next, implement the custom dynamic array with a wrapper for thread-safety:

```c
#include <pthread.h>

typedef struct {
    Node** data;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
} Array;

Array* array_new(size_t capacity) {
    Array* arr = (Array*)malloc(sizeof(Array));
    if (!arr) return NULL;
    arr->capacity = capacity;
    arr->length = 0;
    arr->data = (Node**)calloc(arr->capacity, sizeof(Node*));
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

void array_push(Array* arr, LTE_PHY_FRAME_INFO info) {
    if (!arr || arr->length >= arr->capacity) return;
    Node** current = &arr->data[arr->length];
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;
    newNode->frameInfo = info;
    newNode->prev = NULL;
    newNode->next = NULL;

    *current = newNode;
    arr->length++;
}
```

