#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <curl/curl.h>
#include <pthread.h>
#include <semaphore.h>

static sem_t sem; // Semaphore for limiting concurrent requests
static size_t max_concurrent = 5; // Maximum number of concurrent requests

typedef struct {
    char *url;
    CURL *curl;
    char *response_body;
} RequestData;

static size_t writefunc(void *ptr, size_t size, size_t nmemb, void *userdata) {
    RequestData *request = userdata;
    request->response_body = realloc(request->response_body, request->response_body ? strlen(request->response_body) + size * nmemb : size * nmemb);
    memcpy(&(request->response_body[strlen(request->response_body)]), ptr, size * nmemb);
    return size * nmemb;
}

int http_get(const char **urls, int urls_num) {
    if (sem_init(&sem, 0, max_concurrent) != 0) {
        perror("Failed to initialize semaphore");
        return -1;
    }

    RequestData *requests = malloc(urls_num * sizeof(RequestData));
    for (int i = 0; i < urls_num; ++i) {
        requests[i].url = strdup(urls[i]);
        requests[i].response_body = NULL;
        requests[i].curl = curl_easy_init();
        if (!requests[i].curl) {
            perror("Failed to initialize cURL");
            return -1;
        }

        curl_easy_setopt(requests[i].curl, CURLOPT_URL, requests[i].url);
        curl_easy_setopt(requests[i].curl, CURLOPT_WRITEFUNCTION, writefunc);
        curl_easy_setopt(requests[i].curl, CURLOPT_WRITEDATA, &requests[i]);
    }

    pthread_t threads[urls_num];
    for (int i = 0; i < urls_num; ++i) {
        if (sem_wait(&sem) != 0) {
            perror("Failed to acquire semaphore");
            return -1;
        }

        int rc = pthread_create(threads + i, NULL, curl_easy_perform, &requests[i]);
        if (rc) {
            fprintf(stderr, "Failed to create thread: %s\n", strerror(rc));
            return -1;
        }
    }

    for (int i = 0; i < urls_num; ++i) {
        pthread_join(threads[i], NULL);
        sem_post(&sem);
    }

    for (int i = 0; i < urls_num; ++i) {
        free(requests[i].url);
        curl_easy_cleanup(requests[i].curl);
        free(requests[i].response_body);
    }
    free(requests);

    return 0;
}
```

This code uses the libcurl library for handling HTTP requests asynchronously. It takes an array of URLs and performs GET requests on them, limiting the number of concurrent requests to `max_concurrent`. The function returns response bodies as strings and handles errors gracefully.']

