#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int id;
    int value;
    time_t timestamp;
} Transaction;

int compare(const void *a, const void *b) {
    return (*(const Transaction *)a - *(const Transaction *)b);
}

int max_weighted_sum(Transaction **transactions, int size) {
    int sum[3] = {0, 0, 0}; // last three seconds
    time_t current_time = time(NULL);

    for (int i = 0; i < size; ++i) {
        if (current_time - transactions[i]->timestamp < 3) {
            sum[(current_time - transactions[i]->timestamp) / 3] += transactions[i]->value;
        }
    }

    int max_index = 0;
    for (int i = 1; i <= 2; ++i) {
        if (sum[i] > sum[max_index]) {
            max_index = i;
        }
    }

    return sum[max_index];
}

void process_input(Transaction **transactions, int *capacity, int *size) {
    char input;
    int value;

    while (scanf("%c", &input) == 1 && input != '\n') {
        if (sscanf(stdin, "%d", &value) != 1 || value < INT_MIN || value > INT_MAX) continue;

        if (*size == *capacity) {
            *capacity *= 2;
            Transaction *new_transactions = realloc(*transactions, sizeof(Transaction) * *capacity);
            if (!new_transactions) return;
            *transactions = new_transactions;
        }

        transactions[*size]->id = *(transactions + *size - 1)->id + 1;
        transactions[*size]->value = value;
        transactions[*size]->timestamp = time(NULL);
        ++(*size);
    }
}

void print_largest(Transaction *transactions, int size) {
    qsort(transactions, size, sizeof(Transaction), compare);
    printf("Largest integer: %d\n", transactions[0]->value);
}

int main() {
    Transaction *transactions = NULL;
    int capacity = 1;
    int size = 0;

    process_input(&transactions, &capacity, &size);
    print_largest(transactions, size);
    int max_weighted = max_weighted_sum(&transactions, size);

    printf("Maximum weighted sum: %d\n", max_weighted);

    free(transactions);

    return 0;
}
