#include <stdio.h>
#include <stdarg.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

typedef enum { DEBUG, INFO, WARNING, ERROR } LogLevel;

struct Logger {
    pthread_mutex_t mutex;
    FILE *file; // Local error log file
    int remote_socket; // Socket for remote logging if applicable
    char remote_addr[INET6_ADDRSTRLEN];
    unsigned int remote_port;
    LogLevel level;
    size_t max_entry_size;
    bool async_logging;
};

void logger_init(struct Logger *logger, const char *local_log_file, const char *remote_addr, unsigned int remote_port, LogLevel default_level, size_t max_entry_size, bool async_logging) {
    memset(logger, 0, sizeof(*logger));

    logger->level = default_level;
    logger->max_entry_size = max_entry_size;
    logger->async_logging = async_logging;

    if (local_log_file) {
        logger->file = fopen(local_log_file, "a"); // Append the logs to the file
        if (!logger->file) {
            perror("Failed to open local log file");
        }
    }

    if (remote_addr && remote_port > 0) {
        struct sockaddr_in6 remote_address;
        memset(&remote_address, 0, sizeof(remote_address));
        remote_address.sin6_family = AF_INET6;
        inet_pton(AF_INET6, remote_addr, &remote_address.sin6_addr);
        remote_address.sin6_port = htons(remote_port);

        logger->remote_socket = socket(AF_INET6, SOCK_STREAM, 0);
        if (logger->remote_socket < 0) {
            perror("Failed to create socket for remote logging");
        }

        if (connect(logger->remote_socket, (struct sockaddr*)&remote_address, sizeof(remote_address)) < 0) {
            perror("Failed to connect to remote server for logging");
        }

        strlcpy(logger->remote_addr, remote_addr, sizeof(logger->remote_addr));
        logger->remote_port = remote_port;
    }
}

void log(struct Logger *logger, LogLevel level, const char *format, ...) {
    pthread_mutex_lock(&logger->mutex);

    size_t entry_size = 256; // Initial buffer size
    char *entry = malloc(entry_size);

    if (!entry) {
        perror("Failed to allocate memory for log entry");
        pthread_mutex_unlock(&logger->mutex);
        return;
    }

    while (1) {
        va_list args;
        va_start(args, format);

        size_t required_size = snprintf(entry, entry_size, format, args);
        if (required_size < entry_size) {
            break; // Enough space for the formatted message
        }

        // Reallocate memory to accommodate the growing log entry
        entry_size *= 2;
        char *new_entry = realloc(entry, entry_size);
        if (!new_entry) {
            perror("Failed to reallocate memory for log entry");
            free(entry); // Free the old memory before exiting the function
            pthread_mutex_unlock(&logger->mutex);
            return;
        }
        entry = new_entry;
    }

    va_end(args);

    if (logger->file) {
        fprintf(logger->file, "[%s] [%s]: %s\n", level_str(level), __func__, entry);
    }

    if (logger->async_logging && logger->remote_socket >= 0) {
        send(logger->remote_socket, entry, strlen(entry), 0);
    }

    // If the log entry exceeds the maximum allowed size, truncate it
    if (strlen(entry) > logger->max_entry_size) {
        entry[logger->max_entry_size] = '\0';
    }

    pthread_mutex_unlock(&logger->mutex);

    free(entry);
}

const char *level_str(LogLevel level) {
    switch (level) {
        case DEBUG: return "DEBUG";
        case INFO: return "INFO";
        case WARNING: return "WARNING";
        case ERROR: return "ERROR";
        default: return "<INVALID LEVEL>";
    }
}
```

This code provides a thread-safe logger that supports multiple log levels, dynamic memory allocation for log messages, and configurable logging settings such as maximum entry size, async logging, and remote logging. The logger is designed to handle varying degrees of external data dependency without failing gracefully under adverse conditions. You may need to adjust the function for your specific use case or system requirements.']

