static size_t count = 0;

void worker(void *arg) {
    while (1) {
        pthread_mutex_lock(&tasks_mutex);
        while (count == 0 && !is_shutdown) {
            pthread_cond_wait(&tasks_cond, &tasks_mutex);
        }
        if (is_shutdown) break;

        struct Task task = tasks[--count];
        free(tasks);
        if (capacity == count) {
            capacity *= 2;
            tasks = realloc(tasks, capacity * sizeof(struct Task));
        }

        task.func(&task.data);
        free(task.data);
        pthread_mutex_unlock(&tasks_mutex);
    }
}

void enqueueTask(Record *data, TaskFunc func) {
    pthread_mutex_lock(&tasks_mutex);
    if (count == capacity) {
        capacity *= 2;
        tasks = realloc(tasks, capacity * sizeof(struct Task));
    }

    struct Task task = { data, func };
    tasks[count++] = task;
    pthread_cond_signal(&tasks_cond);
    pthread_mutex_unlock(&tasks_mutex);
}

void threadPoolInit(int num_workers) {
    this->num_workers = num_workers;
    is_shutdown = false;
    workers = malloc(num_workers * sizeof(pthread_t));
    for (int i = 0; i < num_workers; ++i) {
        if (pthread_create(&workers[i], NULL, &worker, NULL)) {
            fprintf(stderr, "Failed to create worker thread\n");
            exit(1);
        }
    }
}

void threadPoolShutdown() {
    is_shutdown = true;
    pthread_mutex_lock(&tasks_mutex);
    pthread_cond_broadcast(&tasks_cond);
    pthread_mutex_unlock(&tasks_mutex);

    for (int i = 0; i < num_workers; ++i) {
        if (pthread_join(workers[i], NULL)) {
            fprintf(stderr, "Failed to join worker thread\n");
            exit(1);
        }
    }
}
```

This code defines a thread pool with the specified number of worker threads. It uses dynamic memory allocation for tasks and manages it efficiently to minimize fragmentation. The `enqueueTask()` function allows specifying a dynamic number of records at runtime, and the `threadPoolInit()` and `threadPoolShutdown()` functions handle graceful shutdown of the pool. However, thread safety, synchronization, memory leak detection, precise timing, and external data source integration are not included in this implementation. For these features, you may want to explore other libraries such as Boost.Asio or libevent, depending on your specific use case requirements.']

