struct Node {
    std::string value;
    std::shared_ptr<Node> left, right;
};

void insertOrAppendChild(std::shared_ptr<Node>& root, const std::string& target, const std::string& value) {
    auto current = root;
    auto searchMap = [&](auto node) -> Node* {
        if (!node) return nullptr;
        if (node->value == target) return node.get();
        auto cmp = node->value < target ? 1 : -1;
        return cmp > 0 ? searchMap(node->left) : searchMap(node->right);
    };
    auto found = searchMap(current);
    if (!found) {
        if (!current) root = std::make_shared<Node>();
        if (searchMap(root, value)) return; // Handle duplicate values
        if (target < current->value) std::swap(value, target);
        auto toInsert = std::make_shared<Node>(value);
        toInsert->left = current;
        current = toInsert;
    } else {
        if (searchMap(root, value) || (current != found && found->value == value)) return; // Handle duplicate values
        found->right = std::make_shared<Node>(value);
    }
}
