[' Here is the multi-threaded task scheduler using a custom thread pool encapsulated within a namespace named `TaskScheduler`. The class `ThreadPool` has a constructor, destructor, and a static member variable for managing the thread pool. It utilizes `std::thread`, `std::mutex`, and `std::condition_variable` functionalities to ensure safe and efficient execution of tasks across multiple threads.

```cpp
#include <deque>
#include <functional>
#include <memory>
#include <mutex>
#include <queue>
#include <condition_variable>
#include <vector>
#include <limits>

namespace TaskScheduler {
class Task;  // Forward declaration of the base task class

class ThreadPool {
public:
    explicit ThreadPool(size_t numThreads);
    ~ThreadPool();

    void submitTask(std::unique_ptr<Task> task, int priority);
    void shutdown();

    size_t getActiveThreadCount() const;
    size_t getQueuedTaskCount() const;

private:
    struct ThreadData {
        std::thread thread;
        std::function<void()> task;
        int priority;
        std::mutex taskMutex;
        std::condition_variable cv;
    };

    void worker();
    bool isShutdown_() const;
    void runPriorityQueueTasks(std::priority_queue<std::unique_ptr<Task>, std::vector<std::unique_ptr<Task>>, std::greater<int>>& queue);

    static const size_t kDefaultNumThreads = std::thread::hardware_concurrency();
    mutable std::mutex tasksMutex_;
    std::vector<ThreadData> threads_;
    std::priority_queue<std::unique_ptr<Task>, std::vector<std::unique_ptr<Task>>, std::greater<int>> taskQueue_;
};
}  // namespace TaskScheduler
```

This is the base task class that will be inherited by specific task types:

```cpp
#include <functional>
#include <memory>

namespace TaskScheduler {
class Task {
public:
    virtual void operator()() = 0;
};
}  // namespace TaskScheduler
```

Below is the implementation of the `ThreadPool` class. It includes a constructor, destructor, and member functions to submit tasks, shut down the pool gracefully, and query the current status of the pool. The class utilizes the provided task queue that supports dynamic task prioritization based on user-defined priorities:

```cpp
#include "ThreadPool.h"
#include <algorithm>
#include < chrono >
#include <iostream>
#include <numeric>
#include <thread>

namespace TaskScheduler {
ThreadPool::ThreadPool(size_t numThreads)
    : threads_(numThreads), tasksMutex_() {
    if (numThreads == 0) {
        numThreads = kDefaultNumThreads;
    }
    std::for_each(std::begin(threads_), std::end(threads_),
                  [this] (auto& threadData) { threadData.thread = std::thread(&ThreadPool::worker, this); });
}

ThreadPool::~ThreadPool() {
    {
        std::unique_lock<std::mutex> lock(tasksMutex_);
        isShutdown_ = true;
    }
    condition_.notify_all();

    for (auto& threadData : threads_) {
        if (threadData.thread.joinable()) {
            threadData.thread.join();
        }
    }
}

void ThreadPool::submitTask(std::unique_ptr<Task> task, int priority) {
    std::lock_guard<std::mutex> lock(tasksMutex_);
    taskQueue_.push(std::move(task));
    taskQueue_.push_heap();  // Adjust the position based on priority.
}

void ThreadPool::shutdown() {
    {
        std::unique_lock<std::mutex> lock(tasksMutex_);
        isShutdown_ = true;
    }
    condition_.notify_all();
}

size_t ThreadPool::getActiveThreadCount() const {
    size_t count = 0;
    {
        std::unique_lock<std::mutex> lock(tasksMutex_);
        for (const auto& threadData : threads_) {
            if (threadData.thread.get_id() != std::this_thread::get_id()) {
                if (!threadData.thread.joinable()) {
                    ++count;
                }
            }
        }
    }
    return count;
}

size_t ThreadPool::getQueuedTaskCount() const {
    size_t count = 0;
    {
        std::unique_lock<std::mutex> lock(tasksMutex_);
        count = taskQueue_.size();
    }
    return count;
}

void ThreadPool::worker() {
    for (;;) {
        if (isShutdown_) {
            break;
        }

        std::unique_ptr<Task> task;
        {
            std::unique_lock<std::mutex> lock(tasksMutex_);
            condition_.wait(lock, [this] { return !taskQueue_.empty() || isShutdown_; });
            if (!isShutdown_) {
                task = std::move(taskQueue_.top());
                taskQueue_.pop();
            }
        }

        if (task) {
            task->operator()();
        }
    }
}

bool ThreadScheduler::ThreadPool::isShutdown_() const {
    std::unique_lock<std::mutex> lock(tasksMutex_);
    return isShutdown_;
}

void ThreadScheduler::ThreadPool::runPriorityQueueTasks(std::priority_queue<std::unique_ptr<Task>, std::vector<std::unique_ptr<Task>>, std::greater<int>>& queue) {
    while (!queue.empty()) {
        auto task = std::move(queue.top());
        queue.pop();
        submitTask(std::move(task));
    }
}
```']

