using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Threading;
using System.Threading.Tasks;
using System.Diagnostics;

namespace CustomAsyncHttpRequests
{
    public class RequestResult
    {
        public Uri Url { get; set; }
        public HttpResponseMessage Response { get; set; }
        public bool Success { get; set; }
    }

    public class CustomHttpClient : HttpClient
    {
        private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(Environment.ProcessorCount, Environment.ProcessorCount);

        public CustomHttpClient()
        {
            DefaultRequestHeaders.Accept.Clear();
            DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
        }

        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
        {
            await _semaphore.WaitAsync(cancellationToken);
            try
            {
                var response = await base.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);
                if (response.IsSuccessStatusCode)
                {
                    return response;
                }
                else
                {
                    // You can handle error cases as needed here
                    throw new Exception($"Request to '{request.RequestUri}' failed with status code: {(int)response.StatusCode}");
                }
            }
            finally
            {
                _semaphore.Release();
            }
        }
    }

    public class BatchAsyncHttpRequests
    {
        private readonly Dictionary<Uri, Stopwatch> _stopwatches = new Dictionary<Uri, Stopwatch>();
        private readonly Dictionary<Uri, int> _successCounts = new Dictionary<Uri, int>();
        private readonly Dictionary<Uri, int> _failureCounts = new Dictionary<Uri, int>();
        private readonly CancellationTokenSource _cancellationTokenSource;
        private readonly CustomHttpClient _httpClient;

        public BatchAsyncHttpRequests(CustomHttpClient httpClient, IEnumerable<Uri> urls, TimeSpan timeout, CancellationToken cancellationToken)
        {
            _httpClient = httpClient;
            _cancellationTokenSource = new CancellationTokenSource();
            foreach (var url in urls)
            {
                _stopwatches[url] = Stopwatch.StartNew();
                Task.Run(async () => await ExecuteRequestAsync(url, timeout, _cancellationTokenSource.Token), _cancellationTokenSource.Token);
            }
        }

        private async Task ExecuteRequestAsync(Uri url, TimeSpan timeout, CancellationToken cancellationToken)
        {
            try
            {
                using var response = await _httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(false);
                if (response.IsSuccessStatusCode)
                {
                    Interlocked.Increment(ref _successCounts[url]);
                }
                else
                {
                    Interlocked.Increment(ref _failureCounts[url]);
                }
            }
            catch (TaskCanceledException) when (!cancellationToken.IsCancellationRequested)
            {
                // Ignore exceptions caused by cancellation token.
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"An error occurred while processing request to '{url}': {ex}");
                Interlocked.Increment(ref _failureCounts[url]);
            }
            finally
            {
                _stopwatches[url].Stop();
            }
        }

        public Dictionary<Uri, RequestResult> GetResults()
        {
            var results = new Dictionary<Uri, RequestResult>();
            foreach (var url in _stopwatches.Keys)
            {
                var elapsedMs = _stopwatches[url].ElapsedMilliseconds;
                var success = _successCounts[url] > 0;
                results[url] = new RequestResult
                {
                    Url = url,
                    Response = null, // You can include response object if needed
                    Success = success
                };
            }
            return results;
        }
    }
}
```

This code defines a `CustomHttpClient` that wraps the standard HttpClient class to optimize concurrency with SemaphoreSlim. The `BatchAsyncHttpRequests` class handles asynchronous HTTP requests for a given list of URLs, tracking total number of successful and failed requests, and returns a dictionary mapping each URL to its corresponding HTTP response. The batch requests are executed using Task.Run and await the SendAsync method, gracefully handling exceptions when necessary.']

