    public PooledDataSource getDataSource() throws IOException {
        Map<String, Object> config = yaml.load(getClass().getResourceAsStream(CONFIG_FILE));
        Integer connectionPoolSize = (Integer) config.get("db.connectionPoolSize");
        Integer batchSize = (Integer) config.get("db.batchSize");
        Integer concurrencyLevel = (Integer) config.get("db.concurrencyLevel");

        PooledDataSource ds = new PooledDataSource();
        BasicDataSourceConfigBuilder builder = new BasicDataSourceConfigBuilder();
        builder.setJdbcUrl("jdbc:mysql://localhost/mydb") // Replace with your database URL
                .setUsername("myusername") // Replace with your username
                .setPassword("mypassword") // Replace with your password
                .setDriverClassName("com.mysql.cj.jdbc.Driver"); // Replace with your driver class
        if (connectionPoolSize != null) {
            builder.setInitialSize(connectionPoolSize);
            ds.setMaxTotal(connectionPoolSize);
        } else {
            builder.setInitialSize(10);
            ds.setMaxTotal(20);
        }
        if (batchSize != null) {
            ds.setMaxStatementPreparationsPerConnection(batchSize);
        }
        if (concurrencyLevel != null) {
            ExecutorService executor = Executors.newFixedThreadPool(concurrencyLevel);
            ds.setConnectionInitSqlExecutor(executor::submit);
