    public DatabaseMonitor(DatabaseConfig config, ExecutorService executor) {
        this.config = config;
        this.executor = executor;
    }

    @Override
    public void run() {
        while (!Thread.currentThread().isInterrupted()) {
            try (Connection connection = config.getDataSource().getConnection()) {
                Statement statement = connection.createStatement();
                ResultSet resultSet = statement.executeQuery("SELECT COUNT(*) FROM some_table");
                if (resultSet.next()) {
                    double activityLevel = (double) resultSet.getDouble(1) / config.getDataSource().getMaxTotal();
                    if (activityLevel > ACTIVITY_THRESHOLD) {
                        int newConnectionPoolSize = Math.min((int) (config.getDataSource().getMaxTotal() * activityLevel), config.getDataSource().getMaxTotal());
                        if (newConnectionPoolSize != config.getDataSource().getMaxTotal()) {
                            config.getDataSource().setMaxTotal(newConnectionPoolSize);
                            System.out.println("Adjusted connection pool size to: " + newConnectionPoolSize);
                        }
                    }
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
            TimeUnit.MILLISECONDS.sleep(MONITOR_INTERVAL_MS);
        }
    }
}
```

