from cachelib import Cache
from rate_limiter import RateLimiter
from auth_service import authenticate_user

cache = Cache()
rate_limiter = RateLimiter(60)

def handle_message_operation(request):
    data = request.get_json()

    if not data or not 'sender_id' in data or not 'receiver_id' in data or not 'message_content' in data or not 'timestamp' in data or not 'operation_type' in data:
        return {'error': 'Missing required fields'}, 400

    sender_id, receiver_id, message_content, timestamp = data['sender_id'], data['receiver_id'], data['message_content'], data['timestamp']

    if len(sender_id) > 100 or len(receiver_id) > 100 or len(message_content) > 255:
        return {'error': 'Field lengths exceeded'}, 400

    if operation_type not in ['send', 'read', 'update', 'delete']:
        return {'error': 'Invalid operation type'}, 400

    authenticated = authenticate_user(sender_id)

    if not authenticated or (operation_type != 'send' and sender_id != receiver_id):
        return {'error': 'Unauthorized'}, 401

    message = {
        'sender_id': sender_id,
        'receiver_id': receiver_id,
        'message_content': message_content,
        'timestamp': timestamp
    }

    cached_messages = cache.get('messages') or []

    if operation_type == 'send':
        messages.append(message)
        cache.set('messages', messages)
    elif operation_type == 'read':
        for m in messages:
            if m['receiver_id'] == receiver_id and m['timestamp'] <= timestamp:
                m['is_read'] = True
        cache.set('messages', messages)
    elif operation_type == 'update':
        for i, m in enumerate(messages):
            if m['sender_id'] == sender_id and (m['timestamp'] == timestamp or m['message_content'] == message_content):
                messages[i] = {k: v for k, v in message.items() if k != 'operation_type'}
        cache.set('messages', messages)
    elif operation_type == 'delete':
        messages = [m for m in messages if (m['sender_id'] != sender_id or m['timestamp'] > timestamp)]
        cache.set('messages', messages)

    logging.basicConfig(format='%(asctime)s - %(levelname)s: %(message)s', level=logging.INFO)
    log_entry = f'{datetime.datetime.now()}: Operation by {sender_id}: {operation_type}'
    logging.info(log_entry)

    return {'success': True} if rate_limiter.limit(sender_id) else {'error': 'Rate limit exceeded'}, 429
```"]

