import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import javax.servlet.http.HttpServletRequest;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.example.service.DocumentService;
import com.example.model.SessionToken;
import com.example.model.DocumentMetadata;
import com.google.gson.Gson;

public class DocumentUpdater {
    private static final Logger LOGGER = LoggerFactory.getLogger(DocumentUpdater.class);
    private static final Gson GSON = new Gson();
    private static final ConcurrentHashMap<String, AtomicLong> TOKEN_COUNTER = new ConcurrentHashMap<>();
    private final DocumentService documentService;

    public DocumentUpdater(DocumentService documentService) {
        this.documentService = documentService;
    }

    public void updateMetadata(HttpServletRequest request, String documentId, long revisionId, DocumentMetadata metadata) {
        String sessionToken = request.getHeader("X-Session-Token");
        Long tokenCounter = TOKEN_COUNTER.getOrDefault(sessionToken, new AtomicLong(0L));
        if (!validateToken(tokenCounter)) {
            // Return an unauthorized response or throw an exception
            return;
        }

        tokenCounter.incrementAndGet();
        TOKEN_COUNTER.putIfAbsent(sessionToken, tokenCounter);

        try {
            boolean updated = documentService.updateMetadata(documentId, revisionId, metadata);

            if (updated) {
                LOGGER.info("Document with ID {} and Revision ID {} was successfully updated", documentId, revisionId);
            } else {
                LOGGER.error("Failed to update Document with ID {} and Revision ID {}", documentId, revisionId);
            }
        } catch (Exception e) {
            LOGGER.error("Error while updating the Document with ID {} and Revision ID {}", documentId, revisionId, e);
            // Return an error response or throw an exception
        } finally {
            TOKEN_COUNTER.computeIfPresent(sessionToken, (k, v) -> v.decrementAndGet());
        }
    }

    private boolean validateToken(Long tokenCounter) {
        // Implement a validation strategy for the session token based on your application's requirements
        return tokenCounter > 0;
    }
}
```

