async function runModuleTests(moduleName, testCases, blueslipMock, dependencyMap) {
    try {
        const modulePath = path.join('/src/modules', moduleName);
        if (!loadedModules.add(modulePath)) {
            log(`Circular dependency detected: ${modulePath}`);
            throw new Error('Circular dependency');
        }

        const Module = require(modulePath); // Dynamic require
        const moduleInstance = new Module(); // Ensure each test case runs in isolation

        const startTime = Date.now();
        for (const testCase of testCases) {
            log(`Test started: ${moduleName} - ${testCase.label}`);
            const result = await promisify(testCase.testFunction)(moduleInstance);
            const duration = Date.now() - startTime;
            blueslipMock = blueslipMock; // Reset blueslipMock for each test

            if (!result.pass) {
                return {
                    [testCase.label]: {
                        ...result,
                        duration
                    }
                };
            }
        }

        return {
            [moduleName]: testCases.reduce((acc, test) => {
                acc[test.label] = {
                    ...test.result,
                    duration: Date.now() - startTime
                };
                return acc;
            }, {})
        };
    } catch (error) {
        if (error.message === 'Circular dependency') {
            // Handle circular dependencies here
        } else {
            throw error;
        }
    }
}
```

