1. Copying bytes from buffered data chunks:

```javascript
function copyBuffer(src, start, length, dest) {
  dest.set(src.slice(start, start + length), start);
}

async function copyNBytes(srcBuf, destBuf, numBytes) {
  let offset = 0;
  while (offset < numBytes) {
    const chunkSize = Math.min(numBytes - offset, srcBuf.byteLength - offset);
    if (!chunkSize) break; // Source buffer exhausted
    copyBuffer(srcBuf, offset, chunkSize, destBuf);
    offset += chunkSize;
  }
}
```

