const hashlib = require('hashlib');

async function computeFileMD5(filePath) {
  const md5 = hashlib.create();
  const chunksSize = 64 * 1024; // 64KB chunk size
  let buffer = Buffer.allocUnsafe(chunksSize);

  const stream = fs.createReadStream(filePath, { highWaterMark: chunksSize });
  for await (const chunk of stream) {
    md5.update(chunk);
  }

  return md5.hex();
}
