3. Parallel processing of a directory with multiple files:

```javascript
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const parallelLimit = require('async-batch')(Math.min); // Adjust this value to balance performance and resources

function walkDir(dirPath, callback) {
  fs.readdir(dirPath, (err, files) => {
    if (err) return callback(err);
    const subTasks = [];
    for (const file of files) {
      const fullPath = path.join(dirPath, file);
      if (fs.statSync(fullPath).isDirectory()) {
        walkDir(fullPath, (err) => err ? callback(err) : null); // Recursive call for subdirectories
      } else {
        subTasks.push((cb) => computeFileMD5(fullPath, cb)); // Non-recursive task for files
      }
    }
    parallelLimit(subTasks, (err) => err ? callback(err) : null); // Process tasks in parallel
  });
}

async function computeDirectoryMD5(dirPath) {
  return new Promise((resolve, reject) => walkDir(dirPath, (err, hash) => err ? reject(err) : resolve(hash)));
}
