['```php
<?php
ini_set('memory_limit', '-1'); // Remove memory limit for large files
set_time_limit(0); // Disable time limit for long running script

require __DIR__ . '/vendor/autoload.php'; // Include autoloader
use App\Config; // Assuming Config class is located in App namespace

class HashDirectory {
    private $filesHash = [];

    public function calculateMD5Hash($directory) {
        $queue = new SplPriorityQueue();
        $queue->insert(array($directory, 0)); // Insert initial directory with priority 0

        $threads = array();
        for ($i = 0; $i < Config::get('num_threads'); $i++) {
            $threads[$i] = new Thread(array($this, 'processDirectory'));
            $threads[$i]->start();
        }

        while(!$queue->isEmpty()) {
            $item = $queue->dequeue();
            list($path, $priority) = $item;

            if (is_dir($path)) {
                $this->recursiveScanDirectory($path, $queue);
            } else {
                $this->calculateFileHash($path);
                $queue->insert(array($path, -$priority)); // Negative priority for processed files
            }
        }

        foreach ($threads as $thread) {
            $thread->join();
        }

        return md5(implode('', $this->filesHash));
    }

    private function recursiveScanDirectory($directory, &$queue) {
        $dir = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($directory), RecursiveIteratorIterator::SKIP_DOTS);

        foreach ($dir as $file) {
            if (!$file->isDir()) {
                $this->calculateFileHash($file->getPathName());
                $queue->insert(array($file->getPathName(), -$file->getSubPathLength())); // Negative priority for processed files
            } else {
                $this->recursiveScanDirectory($file->getPathName(), $queue);
            }
        }
    }

    private function calculateFileHash($file) {
        if (is_readable($file)) {
            $chunkSize = 64 * 1024; // 64KB chunk size
            $handle = fopen($file, 'rb');
            while (!feof($handle)) {
                $chunk = fread($handle, $chunkSize);
                $this->filesHash[] = md5($chunk);
            }
            fclose($handle);
        } else {
            throw new Exception("File '$file' is not readable.");
        }
    }
}

$hashDirectory = new HashDirectory();
$finalHash = $hashDirectory->calculateMD5Hash('path/to/directory');
echo $finalHash;
