    public function updateProfile($userId, array $data)
    {
        $userProfileData = new stdClass();
        $apiEndpoints = [
            'email' => env('API_EMAIL_ENDPOINT'),
            'phone' => env('API_PHONE_ENDPOINT'),
            'subscription' => env('API_SUBSCRIPTION_ENDPOINT'),
        ];

        $this->logger->info("Starting profile update for user: {$userId}", ['timestamp' => time()]);

        foreach ($apiEndpoints as $endpoint => $url) {
            try {
                $response = $this->callApi($url, $data[$endpoint]);

                if (isset($response->error)) {
                    $this->logger->error("API request failed for {$endpoint}: " . json_encode($response), ['timestamp' => time()]);
                } else {
                    $userProfileData->{$endpoint} = $response->data;
                    $this->logger->info("Successfully updated {$endpoint} for user: {$userId}", ['timestamp' => time()]);
                }
            } catch (Exception $e) {
                $this->logger->error("API request error for {$endpoint}: " . $e->getMessage(), ['timestamp' => time()]);
            }
        }

        // Asynchronous processing can be added here if necessary.

        $summary = [
            'user_id' => $userId,
            'endpoints' => $apiEndpoints,
            'responses' => array_map(function ($res) {
                return isset($res->error) ? ['endpoint' => $res->error] : ['endpoint' => $res];
            }, $userProfileData),
        ];

        $this->logger->info("Finished profile update for user: {$userId}", ['timestamp' => time()]);
        return $summary;
    }

    private function callApi($url, $data)
    {
        $attempts = 0;
        $cacheKey = md5($url . json_encode($data));
        if ($cachedData = Redis::get($cacheKey)) {
            return json_decode($cachedData);
        }

        do {
            try {
                $response = $this->client->request('POST', $url, ['json' => $data]);
                $responseJson = json_decode($response->getBody());

                if (isset($responseJson->data)) {
                    Redis::setex($cacheKey, env('API_CACHE_TTL'), json_encode($responseJson));
                    return $responseJson;
                } else {
                    throw new Exception("Invalid API response: " . $response->getBody());
                }
            } catch (Exception $e) {
                sleep(env('API_RETRY_DELAY'));
                $attempts++;
            }
        } while ($attempts < env('API_MAX_ATTEMPTS'));

        throw new Exception("API call failed after max attempts.");
    }
}
```

This code assumes you have properly set up API keys, endpoint URLs, and other environment variables. Make sure to handle the rate limits and quotas imposed by each third-party service in the `callApi()` function as per their documentation. Additionally, you may consider using a queue or job system like Laravel's Queue for asynchronous processing if required.']

