    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void push(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* new_node = create_node(new_data);
    if (!new_node) return;

    new_node->next = *head_ref;
    *head_ref = new_node;
}

int compare(const void *a, const void *b) {
    return ((NFAPI_CRC_INDICATION_PDU_T*)a)->rnti - ((NFAPI_CRC_INDICATION_PDU_T*)b)->rnti;
}

void sort_list(Node** head) {
    if (!head || !*head || (*head)->next == NULL) return;

    qsort(*head, llabs((*head)), sizeof(NFAPI_CRC_INDICATION_PDU_T), compare);
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
void log_and_free(Node** head) {
    pthread_mutex_lock(&mutex);
    int count = 0;
    Node* current = *head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
        count++;
    }
    printf("Successfully created %d structures.\n", count);
    pthread_mutex_unlock(&mutex);
}

void* create_list(unsigned int N, unsigned int max_limit) {
    Node* head = NULL;

    for (unsigned int i = 0; i < N && i < max_limit; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        // Initialize the structure with default values

        push(&head, data);
    }

    sort_list(&head);

    pthread_mutex_lock(&mutex);
    if (head) {
        log_and_free(&head);
    } else {
        printf("Error: Memory allocation failed.\n");
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}
```
