    return ts;
}

bool is_3s_passed() {
    struct timespec current = now();
    double elapsed_seconds = (current.tv_sec - system_data.last_reset.tv_sec) + (current.tv_nsec - system_data.last_reset.tv_nsec) / 1_000_000_000;
    return elapsed_seconds >= 3;
}

