    // ...
}

void increment_transactions_count() {
    ++system_data.transactions_count;
}

double calculate_weighted_sum(const Transaction *transaction) {
    return transaction->age + transaction->weight;
}

int process_transaction(Transaction *transaction, struct SystemData *system_data) {
    if (!system_data || !transaction || !system_data->config.password || !system_data->config.connection || !system_data->config.callback)
        return -1;

    if (is_3s_passed()) {
        discard_oldest();
        system_data->last_reset = now().tv_sec;
    }

    increment_transactions_count();
    double new_weighted_sum = calculate_weighted_sum(transaction);

    if (new_weighted_sum > system_data->max_weighted_sum) {
        system_data->max_weighted_sum = new_weighted_sum;
        system_data->max_id = transaction->id;
    }

    return 0;
}
