#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <libxml/parser.h>
#include <libxml/tree.h>

typedef struct ResourceItem {
    char type[32];
    size_t size;
} ResourceItem;

typedef struct ResourceBundle {
    char configPath[256];
    int tileSize;
    int worldWidth, worldHeight;
    float cameraSpeed;
    int maxFiles;
    int numFilesLoaded;
    ResourceItem** items;
} ResourceBundle;

int loadResourceBundle(const char* dirPath, const char* configPath, int maxFiles) {
    ResourceBundle rb;
    memset(&rb, 0, sizeof(ResourceBundle));
    strcpy(rb.configPath, configPath);
    rb.maxFiles = maxFiles;

    // Load configuration settings from XML file
    xmlDocPtr doc = xmlReadFile(configPath, NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse configuration file: %s\n", configPath);
        return -1;
    }

    // Get tile size, world dimensions, and camera speed from XML settings
    xmlNodeSetPtr nodeSet = xmlFindNodeSet(doc, NULL, BAD_CAST "settings");
    for (xmlNode *node = nodeSet->nodeTab[0]; node != NULL; node = node->next) {
        if (!xmlStrcasecmp(node->name, BAD_CAST "tileSize"))
            rb.tileSize = atoi((char*)xmlNodeGetContent(node));
        else if (!xmlStrcasecmp(node->name, BAD_CAST "worldWidth"))
            rb.worldWidth = atoi((char*)xmlNodeGetContent(node));
        else if (!xmlStrcasecmp(node->name, BAD_CAST "worldHeight"))
            rb.worldHeight = atoi((char*)xmlNodeGetContent(node));
        else if (!xmlStrcasecmp(node->name, BAD_CAST "cameraSpeed"))
            rb.cameraSpeed = atof((char*)xmlNodeGetContent(node));
    }
    xmlFreeDoc(doc);

    DIR *dir = opendir(dirPath);
    if (!dir) {
        fprintf(stderr, "Failed to open directory: %s\n", dirPath);
        return -1;
    }

    struct dirent *entry;
    int numFiles = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (numFiles >= rb.maxFiles) break;

        char filepath[256];
        strcpy(filepath, dirPath);
        strcat(filepath, "/");
        strcat(filepath, entry->d_name);

        struct stat st;
        if (lstat(filepath, &st) == -1 || S_ISDIR(st.st_mode)) continue; // Skip directories and invalid paths

        ResourceItem* item = malloc(sizeof(ResourceItem));
        if (!parseFile(filepath, item)) {
            free(item);
            fprintf(stderr, "Failed to parse file: %s\n", filepath);
            continue;
        }

        rb.items[rb.numFilesLoaded++] = item;
        numFiles++;
    }
    closedir(dir);

    // Allocate memory for the output structure and return an error code if it fails
    rb.items = realloc(rb.items, sizeof(ResourceItem*) * (rb.numFilesLoaded + 1));
    if (!rb.items) {
        fprintf(stderr, "Failed to allocate memory for ResourceBundle\n");
        return -1;
    }

    return 0;
}

// Implement parseFile() function here to handle parsing specific file formats and filling the ResourceItem structure
```']

