        gc(alloc); // Perform garbage collection
    }

    for (size_t i = 0; i < count; ++i) {
        log("Structure #%zu: RNTI=%u, CRCFLAG=%u", i, ((NFAPI_CRC_INDICATION_PDU_T *)list[i])->rnti, ((NFAPI_CRC_INDICATION_PDU_T *)list[i])->crc_indication.crcflag);
    }

    // Free all allocated memory using the custom allocator and standard free() where applicable
    for (size_t i = 0; i < count; ++i) mem_free(alloc, list[i]);
    free(list);
    pthread_mutex_destroy(&alloc->mutex);
    munmap(alloc->base, alloc->total); // Free the custom memory allocator's memory block
}
