void handle_concurrency(NFAPI_CRC_INDICATION_PDU_T** pdus, size_t N) {
    pthread_t threads[MAX_THREADS];
    sem_t throttle_sem;

    sem_init(&throttle_sem, 0, MAX_THREADS); // initialize the semaphore

    for (size_t i = 0; i < N; ++i) {
        pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus[i]) return; // handle memory allocation errors
        init_structure(pdus[i]);
    }

    NFAPI_CRC_INDICATION_PDU_T** current_pdus = pdus;
    for (size_t i = 0; i < MAX_THREADS; ++i) {
