char* process_string(const char *str, size_t size_limit, bool strict_length_check, string_manager *mgr) {
    if (!str) return NULL;

    size_t str_len = strlen(str);

    // Check if the input string exceeds the size limit
    if (strict_length_check && str_len == size_limit)
        return str;

    if (str_len > size_limit) return NULL;

    char *new_str = mgr->allocate(str_len + 2); // Allocate memory for the new string and an extra character for the slash
    if (!new_str) return NULL;

    memcpy(new_str, str, str_len); // Copy input string to the newly allocated memory
