        mgr->active_strings++; // Increment the number of active strings
    } else {
        printf("Allocated memory for a new string: %zu bytes\n", (str_len + 1) * sizeof(char));
    }

    pthread_mutex_unlock(&mgr->mutex); // Unlock the string manager

    return new_str;
