// Custom line-end conversion function
std::string convertLineEnding(const std::string& input) {
    std::string output;
    for (char c : input) {
        if (c == '\r') {
            if (output.empty()) continue;
            output += c;
            if (!output.back() == '\n') output += '\n';
        } else {
            output += c;
        }
    }
    return output;
}

double calculateAverage(const std::vector<double>& numbers) {
    double sum = 0;
    size_t count = 0;
    for (const auto& number : numbers) {
        if (std::isfinite(number)) {
            sum += number;
            ++count;
        }
    }
    return count > 0 ? sum / count : 0.0;
}

void processLine(const std::string& line) {
    std::istringstream iss(convertLineEnding(line));
    std::vector<double> numbers;
    double average = 0.0;
    int fieldCount = 0;
    std::string field;
    while (std::getline(iss, field, ',')) {
        if (!field.empty()) {
            ++fieldCount;
            try {
                double number = std::stod(field);
                numbers.push_back(number);
            } catch (const std::invalid_argument&) {
                // Ignore non-numeric content
            }
        }
    }
    if (numbers.size() < 3) {
        average = calculateAverage(numbers);
    } else {
        average = numbers[0] + numbers[1] + numbers[2] / 3.0;
    }

    std::cout << convertLineEnding(line) << "," << average << "\n";
}

void workerThread(const boost::filesystem::path& directoryPath, std::deque<std::string>& fileQueue) {
    for (auto& filePath : boost::make_iterator_range(boost::filesystem::recursive_directory_iterator(directoryPath))) {
        if (!boost::filesystem::is_regular_file(filePath)) continue;
        std::ifstream file(filePath.string());
        if (!file) continue;

        std::string line;
        while (std::getline(file, line)) {
            processLine(line);
            fileQueue.pop_front();
        }
    }
}

int main() {
    boost::filesystem::path directoryPath("./"); // Directory to process
    std::deque<std::string> fileQueue;
    std::vector<std::thread> workerThreads;
    int numWorkers = std::thread::hardware_concurrency();

    for (auto& entry : boost::make_iterator_range(boost::filesystem::recursive_directory_iterator(directoryPath))) {
        if (!boost::filesystem::is_regular_file(entry)) continue;
        fileQueue.push_back(entry.path().string());
    }

    for (int i = 0; i < numWorkers; ++i) {
        workerThreads.emplace_back(workerThread, directoryPath, std::ref(fileQueue));
    }

    // Integrate with an external logging service here...

    for (auto& thread : workerThreads) {
        thread.join();
    }
}
