typedef struct {
    int width;
    int height;
    int compression; // 0:baseline, 1:progressive
    JSAMPARRAY thumbnail_data; // thumbnail data if available
} jpeg_metadata;

jpeg_error_mgr jerr;
jpeg_decompress_struct cinfo;
jpeg_compptr cptr;

int extract_jpeg_metadata(const char *filename, jpeg_metadata *metadata) {
    FILE *infile = fopen(filename, "rb");
    if (!infile) {
        fprintf(stderr, "Error: Could not open file %s\n", filename);
        return 1;
    }

    struct jpeg_error_initerr = { &jerr };
    jpeg_create_decompress(&cinfo);
    jpeg_set_errors(&cinfo, &jerr);
    jpeg_stdio_src(&cinfo, infile);

    (void) jpeg_read_header(&cinfo, TRUE);
    if (jpeg_get_error_ptr(&cinfo) != NULL) {
        fprintf(stderr, "Error: JPEG error during header processing\n");
        jpeg_destroy_decompress(&cinfo);
        fclose(infile);
        return 1;
    }

    metadata->width = cinfo.image_width;
    metadata->height = cinfo.image_height;
    metadata->compression = cinfo.compressed_data[0] & 0xff; // baseline (0) or progressive (1)

    // Allocate thumbnail data if available
    if (cinfo.num_components > 1 && cinfo.com == 1) {
        metadata->thumbnail_data = jpeg_read_scanlines(&cinfo, NULL, 1);
    }

    (void) jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(infile);

    return 0;
}
```

