['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <dirent.h>
#include <time.h>
#include <limits.h>

typedef struct FileInfo {
    char filename[257]; // Leave one character for the null terminator
    struct stat st;
} FileInfo;

void sort(FileInfo files[], int length) {
    qsort(files, length, sizeof(FileInfo), (int (*)(const void *, const void *))cmp);
}

int cmp(const void *a, const void *b) {
    return ((const FileInfo *)a)->st.st_mtime > ((const FileInfo *)b)->st.st_mtime;
}

int is_allowed_extension(char extension[], int length, char allowed_extensions[][8], int num_extensions) {
    for (int i = 0; i < num_extensions; ++i) {
        if (strcmp(&extension[1], allowed_extensions[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

int read_directory(char path[], FileInfo files[], int size, char allowed_extensions[][8], int num_extensions) {
    DIR *dir = opendir(path);
    if (!dir) {
        perror("opendir");
        return 1;
    }

    struct dirent *entry;
    int count = 0;

    while ((entry = readdir(dir)) != NULL) {
        char filename[257];
        strcpy(filename, path);
        strcat(filename, "/");
        strcat(filename, entry->d_name);

        struct stat st;
        if (stat(filename, &st) == -1) {
            perror("stat");
            continue;
        }

        if (S_ISDIR(st.st_mode)) {
            // Skip directories
            continue;
        }

        char extension[9];
        int ext_len = extract_extension(filename, extension);

        if (!ext_len || !is_allowed_extension(extension, ext_len, allowed_extensions, num_extensions)) {
            // Skip unallowed files or files without extensions
            continue;
        }

        strcpy(files[count].filename, filename);
        files[count].st = st;

        if (++count == size) {
            break;
        }
    }

    closedir(dir);
    sort(files, count);
    return count;
}

int extract_extension(char filename[], char extension[]) {
    int len = strlen(filename);
    int ext_start = len - 1;
    int i;

    for (i = len; i >= 0 && filename[i] != '.'; --i) {}

    if (i == -1 || i > ext_start) {
        return 0;
    }

    for (int j = i + 1, k = 0; j <= ext_start; ++j, ++k) {
        extension[k] = filename[j];
    }
    extension[k] = '\0';

    return i - ext_start;
}
```

Usage:

```c
