    if (argc != 4) {
        fprintf(stderr, "Usage: %s <directory> <extensions...>\n", argv[0]);
        return 1;
    }

    const int num_extensions = argc - 3;
    char allowed_extensions[num_extensions][8];
    for (int i = 1; i < argc - 2; ++i) {
        strcpy(allowed_extensions[i - 1], argv[i]);
    }

    FileInfo files[NUM_FILES]; // Adjust NUM_FILES according to your needs
    int file_count = read_directory(argv[1], files, NUM_FILES, allowed_extensions, num_extensions);

    if (file_count > 0) {
        for (int i = 0; i < file_count && i < NUM_FILES; ++i) {
            printf("%s\n", files[i].filename);
        }
    }

    return 0;
}
