// Global variables for managing cipher contexts
pthread_key_t key;
void* destroy_context(void* ctx) {
    AES_ctx_free(ctx);
    return NULL;
}

AES_ctx* get_context(const char* passphrase) {
    void* ctx = pthread_getspecific(key);
    if (!ctx) {
        ARGON2_CTX ctxArgon2;
        argon2_ctx_init(&ctxArgon2, ARGON2_ID_GENERIC, ARGON2_VERBose_STANDARD);
        size_t keySize = 32;
        size_t ivLength = 16;
        argon2_ctx_set_salt(argon2id, &salt, sizeof(salt));
        argon2_ctx_set_dkey(argon2id, DKLEN);
        argon2_derive(&ctxArgon2, passphrase, strlen(passphrase), keySize + ivLength, outKey, outIv);
        AES_ctx* aesCtx = AES_ctx_init(outKey, outIv);
        pthread_setspecific(key, aesCtx);
        ctx = aesCtx;
    }
    return ctx;
}

void release_context() {
    pthread_key_delete(key);
    key = NULL;
}

// Encryption and Decryption functions
AES_block encryptBlock(const AES_ctx* aesCtx, const uint8_t *in) {
    AES_block out;
    AES_encrypt(aesCtx, in, &out);
    return out;
}

void* encryptData(void* arg) {
    const char* passphrase = (const char*)arg;
    AES_ctx* aesCtx = get_context(passphrase);
    // Assume data and ivLen are provided as input parameters
    uint8_t iv[AES_IV_LENGTH];
    memcpy(iv, aesCtx->iv, sizeof(iv));
    uint8_t* encryptedData = (uint8_t*)malloc(dataSize + AES_BLOCK_SIZE);

    size_t dataLength = dataSize;
    size_t blocksLeft = dataLength / AES_BLOCK_SIZE;
    for (size_t i = 0; i < blocksLeft; ++i) {
        memcpy(&encryptedData[i * AES_BLOCK_SIZE], &iv, sizeof(iv));
        encryptedData[(i + 1) * AES_BLOCK_SIZE] = encryptBlock(aesCtx, &encryptedData[i * AES_BLOCK_SIZE]);
    }

    // Handle remaining bytes if dataSize is not a multiple of block size
    uint8_t* lastBlock = &encryptedData[blocksLeft * AES_BLOCK_SIZE];
    for (size_t i = blocksLeft; i < dataLength / AES_IV_LENGTH; ++i) {
        memcpy(lastBlock, iv, sizeof(iv));
        lastBlock += AES_BLOCK_SIZE;
        encryptedData[(dataLength - (AES_IV_LENGTH + 1) * i) % (AES_IV_LENGTH + 1)] =
            encryptBlock(aesCtx, lastBlock);
    }

    free(aesCtx); // Clean up context after use
    return encryptedData;
}

void* decryptData(void* arg) {
    const char* passphrase = (const char*)arg;
    AES_ctx* aesCtx = get_context(passphrase);
    uint8_t* decryptedData = (uint8_t*)malloc(dataSize + AES_BLOCK_SIZE);

    size_t dataLength = dataSize;
    size_t blocksLeft = dataLength / AES_BLOCK_SIZE;
    for (size_t i = 0; i < blocksLeft; ++i) {
        decryptedData[i * AES_BLOCK_SIZE] = encryptBlock(aesCtx, &decryptedData[(i + 1) * AES_BLOCK_SIZE]);
        memcpy(&aesCtx->iv, &decryptedData[(i * AES_BLOCK_SIZE) + sizeof(uint8_t[AES_IV_LENGTH]), sizeof(uint8_t[AES_IV_LENGTH])], sizeof(iv));
    }

    // Handle remaining bytes if dataSize is not a multiple of block size
    uint8_t* lastBlock = &decryptedData[(blocksLeft * AES_BLOCK_SIZE)];
    for (size_t i = blocksLeft; i < dataLength / AES_IV_LENGTH; ++i) {
        memcpy(&aesCtx->iv, &decryptedData[(dataLength - (AES_IV_LENGTH + 1) * i) % (AES_IV_LENGTH + 1), sizeof(uint8_t[AES_IV_LENGTH])], sizeof(iv));
        lastBlock = &decryptedData[(dataLength - (AES_IV_LENGTH + 1) * i) % (AES_IV_LENGTH + 1)];
        decryptedData[i * AES_BLOCK_SIZE] = encryptBlock(aesCtx, lastBlock);
    }

    free(aesCtx); // Clean up context after use
    return decryptedData;
}
