#define MAX_CMDS 20
#define BACKOFF_BASE 1000 // milliseconds
#define RETRY_ATTEMPTS 5
#define PROGRESS_UPDATE_INTERVAL 1000 // milliseconds

struct command {
    char *command;
    pid_t pid;
    int status;
    sem_t ready;
};

// Dynamic resource management system
int max_concurrent_commands = get_available_cpu_percent() / 10;
pthread_mutex_t resource_lock;
sem_t cmd_semaphore;

// External dependency check and update function (assuming you have a libdeps library)
void check_dependencies(const char *command);

int execute_background_command(char **args) {
    struct command cmd;
    strcpy(cmd.command, basename(*args));
    sem_init(&cmd.ready, 0, 0);

    // Check dependencies
    if (!can_execute_command(cmd.command)) {
        update_dependencies(cmd.command);
        return -1;
    }

    pthread_mutex_lock(&resource_lock);
    while (sem_value(&cmd_semaphore) >= max_concurrent_commands) {
        pthread_cond_wait(&cmd_semaphore, &resource_lock);
    }
    sem_post(&cmd_semaphore);
    pthread_mutex_unlock(&resource_lock);

    pid_t pid = fork();
    if (pid == -1) {
        // Error handling for fork
        return -1;
    } else if (pid == 0) {
        // Child process
        check_dependencies(cmd.command);
        execvp(basename(*args), args);
        fprintf(stderr, "Error: Failed to execute command '%s'\n", cmd.command);
        exit(1);
    } else {
        // Parent process
        cmd.pid = pid;

        int retries = 0;
        while (retries < RETRY_ATTEMPTS) {
            waitpid(cmd.pid, &cmd.status, WNOHANG);
            if (WIFEXITED(cmd.status)) {
                // Command completed successfully
                cmd.status = WEXITSTATUS(cmd.status);
                sem_post(&cmd.ready);
                break;
            } else if (WIFSIGNALED(cmd.status)) {
                // Command terminated by signal
                fprintf(stderr, "Error: Command '%s' terminated by signal %d\n", cmd.command, WTERMSIG(cmd.status));
                sem_post(&cmd.ready);
            } else {
                // Command is still running or encountered an error
                usleep(pow(2, retries) * BACKOFF_BASE);
                retries++;
            }
        }

        if (retries == RETRY_ATTEMPTS && WIFEXITED(cmd.status)) {
            // Command failed after maximum retries
            fprintf(stderr, "Error: Command '%s' failed with exit code %d\n", cmd.command, cmd.status);
        }
    }

    return cmd.status;
}

void *monitor_commands() {
    while (1) {
        pthread_mutex_lock(&resource_lock);
        int running_cmds = sem_value(&cmd_semaphore);
        pthread_mutex_unlock(&resource_lock);

        for (int i = 0; i < MAX_CMDS; ++i) {
            struct command *cmd = &commands[i];
            if (!cmd->command) continue;

            sem_wait(&cmd->ready);

            int status = cmd->status;
            sem_destroy(&cmd->ready);
            free(cmd);

            if (WIFEXITED(status)) {
                // Log success or failure
                log_result(i, status);
            } else if (WIFSIGNALED(status)) {
                // Handle signaled commands gracefully
                fprintf(stderr, "Error: Command %d terminated by signal %d\n", i, WTERMSIG(status));
                log_result(i, -1);
            }
        }

        pthread_mutex_lock(&resource_lock);
        sem_post(&cmd_semaphore);
        pthread_mutex_unlock(&resource_lock);

        usleep(PROGRESS_UPDATE_INTERVAL);
    }
}
