```python
import hashlib
import os
import dns.resolver
import sys
import time

def calculate_md5_with_dns_resolution(file_path, chunk_size=64 * 1024):
    hasher = hashlib.md5()
    host = os.path.splitext(os.path.basename(file_path))[0]
    ip = dns.resolver.resolve(host, 'A').response.answer[0].items[0].address
    with open(file_path, "rb") as f:
        while True:
            chunk = f.read(chunk_size)
            if not chunk: break
            hasher.update(chunk)
            sys.stdout.write(f"Processing {len(chunk)} bytes from {os.path.basename(file_path)}\n")
            sys.stdout.flush()
    return hasher.hexdigest(), ip
