// Custom memory pool class for payload buffers
class PayloadPool {
public:
    void* Allocate(size_t size) {
        if (free_buffer_.empty()) {
            auto buffer = new char[max_buffer_size_];
            used_buffer_.push_back(buffer);
        }
        void* result = free_buffer_.front();
        free_buffer_.pop_front();
        used_buffer_size_ += size;
        return result;
    }

    void Free(void* ptr) {
        auto it = used_buffer_.begin();
        while (it != used_buffer_.end() && it->ptr == ptr) {
            free_buffer_.push_back(it->ptr);
            used_buffer_.erase(it++);
            used_buffer_size_ -= it->size;
        }
    }

private:
    struct Buffer {
        char* ptr;
        size_t size;
    };

    static constexpr size_t max_buffer_size_ = 1000;
    vector<char*> free_buffer_;
    vector<Buffer> used_buffer_;
    size_t used_buffer_size_ = 0;
};

