typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct record {
    long offset;
    int key;
    double timestamp;
    struct record *next;
} record;

record* head = NULL;
int max_records = 10000;
int allocated_pdus = 0;
int total_records = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initBuffer() {
    head = malloc(max_records * sizeof(record));
    if (!head) {
        printf("Buffer exhausted. Max capacity reached.\n");
        max_records = 0;
    } else {
        for (int i = 0; i < max_records; ++i) {
            head[i].offset = i;
            head[i].key = i;
            head[i].timestamp = ((double)rand() / RAND_MAX) * 1000.0;
            head[i].next = &head[(i + 1) % max_records];
        }
    }
}

void* createListThread(void* arg) {
    initBuffer();
    return &head[0];
}

void linkRecords() {
    record *cur, *next;

    pthread_t threads[max_records];

    for (int i = 0; i < max_records; ++i) {
        cur = &head[i];

        if (pthread_create(&threads[i], NULL, createListThread, (void*)(i + 1))) {
            perror("Error creating thread");
            break;
        }
    }

    for (int i = 0; i < max_records; ++i) {
        pthread_join(threads[i], (void**)&next);
        cur->next = next;
        cur = next;
    }
}

NFAPI_CRC_INDICATION_PDU_T* initializeDataStructures(int N) {
    if (N < 0) return NULL;

    allocated_pdus = N > max_records ? max_records : N;
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(allocated_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        allocated_pdus = 0;
        return NULL;
    }

    linkRecords();

    total_records = max_records;

    for (int i = 0; i < allocated_pdus; ++i) {
        pdus[i].rx_ue.presenceIndicator = 1;
        pdus[i].rnti.value = head[i].key;
        pdus[i].crc_indication.tag = (CRC_INDICATION_REL8_TAG){ .crccFlag = rand() % 2 };
    }

    return pdus;
}
