    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
};

void array_init(struct array_data *array) {
    array->elements = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void array_destroy(struct array_data *array) {
    if (array->elements) {
        free(array->elements);
    }
    pthread_mutex_destroy(&array->mutex);
}

void array_resize(struct array_data *array, size_t capacity) {
    NR_RRC_UE_CONTEXT_T *new_elements = realloc(array->elements, capacity * sizeof(NR_RRC_UE_CONTEXT_T));
    if (!new_elements) {
        return; // Handle memory allocation failure
    }

    array->elements = new_elements;
    array->capacity = capacity;
}

size_t find_cell_id(const struct array_data *array, int cell_id) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->elements[i].cell_id == cell_id) {
            return i;
        }
    }
    return SIZE_MAX; // Not found
}

void update_paging_flag(NR_RRC_UE_CONTEXT_T *context, int condition) {
    context->paging_request_flag = condition;
}

void array_add(struct array_data *array, const NR_RRC_UE_CONTEXT_T *context) {
    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        array_resize(array, array->capacity ? array->capacity * 2 : 4);
    }

    memcpy(&array->elements[array->size], context, sizeof(NR_RRC_UE_CONTEXT_T));
    ++array->size;

    pthread_mutex_unlock(&array->mutex);
}

void array_remove(struct array_data *array, int cell_id) {
    size_t index = find_cell_id(array, cell_id);

    if (index != SIZE_MAX) {
        pthread_mutex_lock(&array->mutex);

        memmove(&array->elements[index], &array->elements[index + 1], (array->size - index - 1) * sizeof(NR_RRC_UE_CONTEXT_T));
        --array->size;

        pthread_mutex_unlock(&array->mutex);
    }
}

void array_iterate(struct array_data *array, void (*callback)(NR_RRC_UE_CONTEXT_T *context)) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (callback(&array->elements[i])) {
            break;
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

void update_paging_flag_on_cell(struct array_data *array, int cell_id, int condition) {
    array_iterate(array, (NR_RRC_UE_CONTEXT_T *context) -> {
        if (context->cell_id == cell_id) {
            update_paging_flag(context, condition);
            return 1; // Stop iteration on this context
        }
        return 0;
    });
