```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Org.BouncyCastle.Crypto;
using Org.BouncyCastle.OpenSsl;
using Org.BouncyCastle.Security;

public class CipherContext
{
    public ICipherAlgorithmProvider Cipher { get; set; }
    public byte[] InitializationVector { get; set; }
}

public CipherContext SecureAndAddWebsite(string directoryPath, string siteName, string password)
{
    if (!Directory.Exists(directoryPath))
        throw new DirectoryNotFoundException($"The specified directory does not exist: {directoryPath}");

    var webConfigFilePath = Path.Combine(directoryPath, "web.config");
    if (!File.Exists(webConfigFilePath))
        return null;

    password = HashPassword(password);
    ICipherAlgorithmProvider cipher = CreateAesCipher(password);

    // Initialize other site components here (e.g., web.config modifications, etc.)

    return new CipherContext { Cipher = cipher, InitializationVector = cipher.IV };
}

private byte[] HashPassword(string password)
{
    using var sha1 = SHA1.Create();
    return sha1.ComputeHash(Encoding.UTF8.GetBytes(password));
}

private ICipherAlgorithmProvider CreateAesCipher(byte[] password)
{
    var aesKeyParameter = new KeyParameter(password);
    var cipher = new AesEngine();
    var provider = new PbeParametersWithRsaAndMdc28EncryptionScheme(
        aesKeyParameter,
        Rfc2898DeriveBytes.GetBytes(32, Encoding.UTF8.GetBytes("My Salt")),
        1024,
        SHA1.Create());
    cipher.Init(true, provider);
    return new PbeBlockCipher(cipher);
}

public void CleanupCipher(ICipherAlgorithmProvider cipher)
{
    cipher?.Dispose();
}
