u_char ip_addr[MAX_HOSTNAME_LEN];
pthread_mutex_t file_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function for DNS resolution using system command
int resolve_dns(const char *hostname) {
    pid_t pid;
    int status;
    FILE *pipe;
    char buffer[BUFFER_SIZE];
    snprintf(ip_addr, sizeof(ip_addr), "\0"); // initialize ip_addr to null string

    pipe = popen((char *) "dig +short @8.8.8.8 -t A " + std::string(hostname), "r");
    if (!pipe) {
        perror("Pipe");
        return 1; // error occurred, return 1 to indicate failure
    }

    clock_t start = clock();
    while ((fgets(buffer, BUFFER_SIZE, pipe)) != NULL && (clock() - start) < TIMEOUT * CLOCKS_PER_SEC) {
        if (!strncmp(";; Connection timed out; no servers could be reached", buffer, strlen(";; Connection timed out; no servers could be reached"))) {
            perror("Connection timed out");
            return 1; // connection timed out, return 1 to indicate failure
        }
        if (inet_pton(AF_INET, buffer, &ip_addr)) {
            pclose(pipe);
            return 0; // success, return 0 to indicate success
        }
    }
    pclose(pipe);

    perror("Command execution timed out");
    return 1; // command execution timed out, return 1 to indicate failure
}

// Function for logging with external service
void log_message(const char *message) {
    openlog("dns-resolver", LOG_PID | LOG_PERROR, LOG_USER);
    syslog(LOG_INFO, message);
    closelog();
}

// Function for checking environment variables
int check_env_variables() {
    if (!getenv("EXTERNAL_LOGGING_SERVICE")) {
        log_message("Warning: Missing EXTERNAL_LOGGING_SERVICE environment variable");
    }
    return 1; // always returns success, as the function only logs warnings for missing variables
}

// Function for handling file operations thread-safely
void handle_file(const char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Open");
        return; // error occurred, return without further action
    }

    pthread_mutex_lock(&file_mutex);
    ssize_t read = read(fd, ip_addr, sizeof(ip_addr));
    if (read == -1) {
        perror("Read");
    } else {
        ip_addr[read] = '\0'; // null-terminate the string
    }
    pthread_mutex_unlock(&file_mutex);

    close(fd);
}

// Main function for the program
int main(int argc, char **argv) {
    check_env_variables();

    const char *hostname = argv[1];
    if (!hostname || strlen(hostname) >= MAX_HOSTNAME_LEN) {
        fprintf(stderr, "Usage: %s hostname\n", argv[0]);
        return 1; // invalid input, return 1 to indicate failure
    }

    if (resolve_dns(hostname)) {
        return 1; // error occurred during DNS resolution, return 1 to indicate failure
    }

    handle_file("dns_result.bin"); // replace with dynamic update method

    log_message((char *)ip_addr);
    return 0; // success, return 0 to indicate success
}
```

This code assumes the existence of an environment variable named `EXTERNAL_LOGGING_SERVICE` and a file called "dns_result.bin". To dynamically update the list of commands supported by the program, you can use a shared library or a plugin system. You may also want to consider using asynchronous I/O instead of popen() for improved performance and avoid hanging processes in case of slow command execution. Additionally, don't forget to add proper error handling and unit tests for each component as per your requirements.']

