#include <time.h>

// Assuming RefreshToken is a class with methods loadTokens() and isUsed(const std::string& refreshToken)
class RefreshToken {
public:
    void loadTokens();
    bool isUsed(const std::string& refreshToken);
private:
    std::set<std::string> tokens;
};

bool validateAccessTokenResponse(const std::string& jsonString, const RefreshToken& refreshToken) {
    nlohmann::json j = nlohmann::json::parse(jsonString, nullptr);  // Parse the JSON string allowing for errors

    if (!j.is_object()) return false;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);  // Create a mutex to limit concurrent requests
    static int counter = 0;

    pthread_mutex_lock(&lock);
    if (counter >= 5) {
        pthread_mutex_unlock(&lock);
        return false;   // Limit the number of concurrent requests
    }
    ++counter;
    pthread_mutex_unlock(&lock);

    bool isValid = true;

    if (!j.count("access_token") || j["access_token"].empty()) {
        isValid = false;
    } else if (!nlohmann::json::is_string(j["access_token"])) {
        isValid = false;
    }

    if (!j.count("expires_in")) {
        isValid = false;
    } else if (!nlohmann::json::is_number(j["expires_in"]) || j["expires_in"] < 1 || j["expires_in"] > 3600) {
        isValid = false;
    }

    if (j.count("token_type") && j["token_type"].get<std::string>() != "Bearer") {
        isValid = false;
    }

    if (j.count("refresh_token")) {
        if (!nlohmann::json::is_string(j["refresh_token"]) || j["refresh_token"].empty()) {
            isValid = false;
        } else if (j["expires_in"] <= 1800) {
            isValid = false;
        } else if (!refreshToken.isUsed(j["refresh_token"].get<std::string>())) {
            isValid = false;
        }
    }

    if (isValid && !j.empty()) {  // Ensure the JSON object only contains the required fields
        time_t currentTime = time(nullptr);
        time_t expiresInSeconds = j["expires_in"].get<int>();
        if (currentTime + expiresInSeconds > std::time(nullptr)) {
            isValid = false;  // Account for clock skew
        }
    }

    pthread_mutex_lock(&lock);
    --counter;
    pthread_mutex_unlock(&lock);

    return isValid;
}
