                var reader = command.ExecuteReader();
                item.Item2(reader);
            }
        }
    }

    private void LogPerformanceAndResourceUsage()
    {
        // Implement logging mechanism for query execution times and resource usage here, using a logger of your choice.
    }

    public void StartProcessing()
    {
        var thread = new Thread(ProcessQueue);
