using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using ConcurrentBag = System.Collections.Concurrent.ConcurrentBag<byte[]>;

public class AesGcmDecryptor
{
    private readonly ILogger _logger;
    private readonly byte[] _encryptionKey;
    private readonly byte[] _nonce;

    public AesGcmDecryptor(ILogger logger, byte[] encryptionKey, byte[] nonce)
    {
        _logger = logger;
        _encryptionKey = encryptionKey;
        _nonce = nonce;
    }

    private void ProcessMessage(byte[] message, MemoryStream encryptedDataStream, Stream decryptedDataStream)
    {
        using var aes = Aes.Create();
        using var gcm = new GCMBlockEncryptor(aes, _nonce);
        using var tagVerifier = new GCMBlockDecryptor(aes, _nonce);

        gcm.Initialize(true, _encryptionKey, _nonce);
        tagVerifier.Initialize(false, _encryptionKey, _nonce);

        int length = encryptedDataStream.ReadByte();
        if (length < 0) throw new InvalidOperationException("Incorrectly formatted message.");

        byte[] encryptedMessage = new byte[length];
        encryptedDataStream.Read(encryptedMessage, 0, length);
        byte[] tag = new byte[aes.TagSize];
        decryptedDataStream.Read(tag, 0, tag.Length);

        if (!tagVerifier.BlockCanonicalizeAndAuthenticate(encryptedMessage, 0, encryptedMessage.Length, tag))
            throw new CryptographicException("Message integrity check failed.");

        decryptedDataStream.Read(encryptedMessage, 0, length - tag.Length);
        decryptedDataStream.Reset();
        decryptedDataStream.Write(encryptedMessage, 0, encryptedMessage.Length - tag.Length);

        var messageWithTag = new ArraySegment<byte>(new byte[encryptedMessage.Length + tag.Length]);
        Buffer.BlockCopy(encryptedMessage, 0, messageWithTag, 0, encryptedMessage.Length);
        Buffer.BlockCopy(tag, 0, messageWithTag, encryptedMessage.Length, tag.Length);

        var decryptedMessage = Encoding.UTF8.GetString(gcm.TransformFinalBlock(messageWithTag.Array, messageWithTag.Offset, messageWithTag.Count));
        _logger.LogInformation("Decrypted message: {DecryptedMessage}", decryptedMessage);
    }

    public async Task DecryptAsync(Stream encryptedDataStream)
    {
        var decryptedMessages = new ConcurrentBag<string>();
        var duplicateMessages = new HashSet<string>();
        var batchSize = 100;
        MemoryStream currentBatch = null;

        while (true)
        {
            if (currentBatch == null || currentBatch.Length >= batchSize)
            {
                Stream decryptedDataStream = new MemoryStream();

                if (currentBatch != null)
                {
                    var messageCount = (int)(currentBatch.Length / sizeof(int)) - 1; // Count messages minus the message count byte
                    for (var i = 0; i < messageCount; ++i)
                        ProcessMessage(currentBatch.GetBuffer(), encryptedDataStream, decryptedDataStream);
                }

                int length;
                while ((length = encryptedDataStream.ReadByte()) > 0)
                {
                    byte[] messageBytes = new byte[length];
                    encryptedDataStream.Read(messageBytes, 0, length);
                    var messageWithLength = new ArraySegment<byte>(new byte[sizeof(int) + length]);
                    Buffer.BlockCopy(BitConverter.GetBytes((int)messageBytes.Length), 0, messageWithLength.Array, 0, sizeof(int));
                    Buffer.BlockCopy(messageBytes, 0, messageWithLength.Array, sizeof(int), messageBytes.Length);

                    using (var currentMessageStream = new MemoryStream(messageWithLength.Array))
                    {
                        ProcessMessage(currentMessageStream.ToArray(), encryptedDataStream, decryptedDataStream);
                    }
                }

                var batchMessages = Encoding.UTF8.GetString(decryptedDataStream.ToArray());
                decryptedMessages.AddRange(batchMessages.Split('\n'));

                if (currentBatch != null)
                {
                    currentBatch.Seek(0, SeekOrigin.Begin);
                    foreach (var message in decryptedMessages)
                    {
                        if (duplicateMessages.Contains(message))
                            throw new DuplicateMessageException($"Duplicate message: {message}");

                        duplicateMessages.Add(message);
                    }

                    currentBatch = null;
                }

                decryptedDataStream.Close();
                decryptedDataStream.Dispose();
            }
            else
            {
                currentBatch.WriteByte((byte)encryptedDataStream.ReadByte());
            }
        }
    }
}
```

This code defines an `AesGcmDecryptor` class that can decrypt a stream of messages encrypted with AES-GCM. The function takes in an encryption key and nonce, and manages the memory usage efficiently by batching multiple messages for decryption in parallel while ensuring thread safety and data integrity during the parallel processing.

The `DecryptAsync` method processes the given stream of encrypted data, handling duplicate messages, real-time notifications using an external message broker (not implemented), and gracefully handling both successful and failed decryption attempts without leaving temporary files or sensitive data in memory after processing.']

['```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using SevenZip;
using Newtonsoft.Json;
using System.Runtime.InteropServices;
using System.Numerics;

public class Record
{
    public long Offset { get; set; }
    public int Key { get; set; }
    public double Timestamp { get; set; }
}

public class CustomLinkedList
{
    private readonly List<Record> _nodes = new List<Record>();
    private int _headIndex;

    public Record Head => _nodes[_headIndex];
    public int Count => _nodes.Count;

    public void Add(Record record)
    {
        if (Count >= 10_000) throw new InvalidOperationException("The list has reached its maximum capacity.");

        _nodes.Add(record);

        if (record.Offset < Head.Offset)
        {
            var current = _headIndex;
            while (_nodes[current].Offset > record.Offset) current--;
            _nodes[current].Next = record;
            _nodes[record.Offset].Prev = record;
            record.Next = _nodes[current];
            record.Prev = _nodes[_nodes[current].Offset - 1];
        }
        else
        {
            _nodes[record.Offset].Next = record;
            record.Prev = _nodes[record.Offset];
        }

        _headIndex = (_headIndex + 1) % _nodes.Count;
    }
}

public async Task<CustomLinkedList> LoadFromCompressedFileAsync(string filePath, Func<int, Task<Record>> apiFetcher)
{
    var linkedList = new CustomLinkedList();
    var archive = await ArchiveFactory.Open(filePath);

    using (var stream = await archive.ExtractEntry(0))
    {
        using var reader = new BinaryReader(stream);
        int compressionMethod = reader.ReadInt32();

        switch (compressionMethod)
        {
            case CompressionType.Deflate:
                await ProcessDeflateStreamAsync(reader, async () => await apiFetcher(await reader.ReadInt32()));
                break;
            case CompressionType.GZip:
                await ProcessGZipStreamAsync(reader, async () => await apiFetcher(await reader.ReadInt32()));
                break;
            default:
                throw new InvalidDataException($"Unsupported compression method {compressionMethod}.");
        }
    }

    ValidateList(linkedList);
    return linkedList;
}

private static void ValidateList(CustomLinkedList list)
{
    var reachableNodes = new HashSet<Record>();
    var headNode = list.Head;

    // Depth-first search for cycle detection and validation of node connectivity.
    DFS(headNode, ref reachableNodes);
}

private static void DFS(Record node, ref HashSet<Record> reachableNodes)
{
    if (reachableNodes.Contains(node)) return; // Detected a cycle, abort further processing of this node.

    reachableNodes.Add(node);

    var nextNode = node.Next;
    if (nextNode != null) DFS(nextNode, ref reachableNodes);

    var prevNode = node.Prev;
    if (prevNode != null && prevNode != node) DFS(prevNode, ref reachableNodes);
}

private static async Task ProcessDeflateStreamAsync(BinaryReader reader, Func<Task<Record>> fetcher)
{
    using var deflater = new Deflator() { Mode = CompressionMode.Raw };
    var buffer = new byte[4096];

    while (await reader.Read(buffer, 0, buffer.Length) > 0)
    {
        int readSize = reader.BaseStream.Read(buffer, 0, buffer.Length);
        deflater.Write(buffer, 0, readSize);

        while (true)
        {
            if (!deflater.IsEndOfStreamReached && deflater.Flush(buffer) <= 0) break; // Flushed all compressed data

            var record = await fetcher();

            record.Offset = BitConverter.ToInt64(buffer, 0);
            record.Key = BitConverter.ToInt32(buffer, 8);
            record.Timestamp = (double)BitConverter.ToDoubleBigEndian(buffer, 12 + sizeof(int)); // Timestamp in Big Endian

            linkedList.Add(record);
        }
    }
}

private static async Task ProcessGZipStreamAsync(BinaryReader reader, Func<Task<Record>> fetcher)
{
    using var gzip = new GzIPInputStream(reader.BaseStream);
    var buffer = new byte[4096];

    while (await gzip.ReadAsync(buffer, 0, buffer.Length) > 0)
    {
        int readSize = gzip.Read(buffer, 0, buffer.Length);
        ProcessDeflateStream(buffer, 0, readSize, fetcher);
    }
}

private static void ProcessDeflateStream(byte[] buffer, int offset, int length, Func<Task<Record>> fetcher)
{
    using var deflater = new Deflator() { Mode = CompressionMode.Raw };
    deflater.SetInput(buffer, offset, length);

    while (true)
    {
        if (!deflater.IsEndOfStreamReached && deflater.Flush(buffer) <= 0) break; // Flushed all compressed data

        var record = fetcher().GetAwaiter().GetResult();

        record.Offset = BitConverter.ToInt64(buffer, 0);
        record.Key = BitConverter.ToInt32(buffer, 8);
        record.Timestamp = (double)BitConverter.ToDoubleBigEndian(buffer, 12 + sizeof(int)); // Timestamp in Big Endian

        linkedList.Add(record);
    }
}
```']

