import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.ClassNotFoundException;
import java.util.Locale;

public class Deserializer {
    public static <T> T deserialize(byte[] data) throws IOException, ClassNotFoundException, NoSuchMethodException, InstantiationException, IllegalAccessException, InvocationTargetException, CloneNotSupportedException, RuntimeException {
        ByteArrayInputStream bis = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bis);

        try {
            return (T) ois.readObject();
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize object: Class not found. Offending byte sequence starts at position " + bis.markSupported() ? bis.getMarkerPosition() : -1, e);
        } catch (StreamCorruptedException e) {
            throw new RuntimeException("Failed to deserialize object: Corrupted data detected in the stream. Offending byte sequence starts at position " + bis.markSupported() ? bis.getMarkerPosition() : -1, e);
        } catch (ClassCastException e) {
            throw new RuntimeException("Failed to deserialize object: Deserialized class does not match expected type. Offending byte sequence starts at position " + bis.markSupported() ? bis.getMarkerPosition() : -1, e);
        } catch (Throwable e) { // Catch all other exceptions that might occur during the deserialization process
            throw new RuntimeException("Failed to deserialize object: Unexpected error occurred during deserialization. Offending byte sequence starts at position " + bis.markSupported() ? bis.getMarkerPosition() : -1, e);
        } finally {
            if (bis != null) bis.close();
            if (ois != null) ois.close();
        }
    }
}
