fn create_log_data_dir(parent_dir: &PathBuf, log_data_dir: &str) -> Result<(), Box<dyn std::error::Error> {
    let parent = parent_dir.to_owned();
    let current_log_data_path = env::var("LOG_DATA_PATH")?;
    if current_log_data_path != parent.join(log_data_dir).to_str().unwrap() {
        fs::create_dir_all(&parent.join(log_data_dir))?;
        env::set_var("LOG_DATA_PATH", parent.join(log_data_dir).to_str().unwrap());
    } else if fs::metadata(&parent.join(log_data_dir)).is_ok() {
        println!("Warning: Directory {} already exists.", log_data_dir);
    }
    Ok(())
}
