[' here is a basic implementation of the requested Python class. This code does not cover all the requirements in full detail but should serve as a starting point.

```python
import json
from abc import ABC, abstractmethod
from typing import Any, Dict, Type

class DataTypeRegistry:
    def __init__(self):
        self._registry = {}

    def register(self, id: str, factory: Type[Any]):
        if id in self._registry:
            raise ValueError("Duplicate ID provided")
        self._registry[id] = factory

    def update(self, id: str, new_factory: Type[Any]):
        if id not in self._registry:
            raise KeyError("ID not found in registry")
        self._registry[id] = new_factory

class DataType:
    def __init__(self, data: Any):
        self.data = data

    @abstractmethod
    def to_json(self) -> str:
        pass

    @staticmethod
    def from_json(json_str: str) -> 'DataType':
        raise NotImplementedError()

class JsonParserBuilder:
    def __init__(self):
        self._registry = DataTypeRegistry()
        self._versions = {}
        self._current_version = 0

    def register(self, data_type: Type[DataType], **kwargs) -> None:
        id = kwargs.pop("id", type(data_type).__name__)
        self._registry.register(id, data_type)

    def set_version(self, version: int) -> None:
        self._current_version = version

    def build(self) -> 'JsonParser':
        return JsonParser(self._registry, self._versions, self._current_version)

class JsonParser(ABC):
    def __init__(self, registry: DataTypeRegistry, versions: Dict[str, int], current_version: int):
        self._registry = registry
        self._versions = versions
        self._current_version = current_version

    @abstractmethod
    def parse(self, json_str: str) -> Any:
        pass

    def serialize(self, data: Any) -> str:
        return json.dumps(self._serialize(data))

    def _serialize(self, data: Any, parent_key: str = None):
        if isinstance(data, self.__class__):  # Handle circular references
            raise RecursionError("Circular reference detected")

        if isinstance(data, DataType):
            return data.to_json()

        result = {}
        for key, item in (vars(data) if parent_key is None else data.items()).items():
            serialized_item = self._serialize(item, key)
            if serialized_item:  # Skip non-serializable items
                result[key] = serialized_item
        return result if result else None

    @abstractmethod
    def deserialize(self, json_str: str) -> Any:
        pass
```

Please note that this code requires implementing the abstract methods and creating a specific `JsonParser` subclass to handle the concrete parsing logic. You can find detailed examples of these implementations in the documentation for the `json` module or third-party libraries such as Marshmallow or Pydantic.

You may also need to add unit tests using Python's built-in `unittest` module or popular testing frameworks like PyTest to ensure the correctness of the serialization and deserialization process, covering edge cases such as missing fields, optional fields, and deprecated data structures.']

