public class DatabaseConnectionPoolManager {
    private static final String DATABASE_CONFIG_FILE = "database.properties";
    private static final String CONFIG_TEMPLATE_FILE = "template.properties";
    private static final SimpleDateFormat LOG_FORMATTER = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");

    public static File manageDatabaseConnectionPool(DataSource dataSource, Map<String, Object> params) {
        validateInputParameters(dataSource, params);

        Properties configProps = loadConfigProperties();
        setEnvSpecificParams(configProps, params);

        try (ConnectionPool pool = createConnectionPool(configProps)) {
            performOperations(pool);

            return updateAndSaveConfigFile(configProps, dataSource.getConnection().getCatalog());
        } catch (Exception e) {
            System.err.println("Error while managing connection pool: " + e.getMessage());
        }

        return null;
    }

    private static void validateInputParameters(DataSource dataSource, Map<String, Object> params) {
        if (dataSource == null || params == null)
            throw new IllegalArgumentException("Invalid input parameters");
    }

    private static Properties loadConfigProperties() {
        Properties props = new Properties();
        try (InputStream is = DatabaseConnectionPoolManager.class.getClassLoader().getResourceAsStream(CONFIG_TEMPLATE_FILE)) {
            props.load(is);
        } catch (IOException e) {
            System.err.println("Error while loading configuration template: " + e.getMessage());
        }
        return props;
    }

    private static void setEnvSpecificParams(Properties configProps, Map<String, Object> params) {
        configProps.putAll(params);
        // Replace placeholders in the properties with actual values from parameters
        for (Map.Entry<Object, Object> entry : params.entrySet()) {
            String placeholder = String.format("${%s}", entry.getKey());
            if (configProps.containsKey(placeholder))
                configProps.put(configProps.getProperty(placeholder), entry.getValue());
        }
    }

    private static ConnectionPool createConnectionPool(Properties props) throws SQLException {
        // Initialize and configure the connection pool using properties
        PoolingDataSource dataSource = new PoolingDataSource();
        dataSource.setDriverClassName(props.getProperty("driver"));
        dataSource.setURL(props.getProperty("url"));
        dataSource.setUsername(props.getProperty("username"));
        dataSource.setPassword(props.getProperty("password"));
        // Set other connection pool properties as needed (minimumIdle, maxTotal, testOnBorrow, etc.)
        return dataSource;
    }

    private static void performOperations(ConnectionPool pool) throws SQLException, InterruptedException {
        Random rand = new Random();
        int delayRange = 1000; // in milliseconds
        while (true) {
            Connection connection = pool.getConnection();
            try {
                if (pool.isClosed())
                    throw new SQLException("Pool is closed.");

                if (pool.getNumActive() == pool.getMaxTotal()) {
                    System.out.println("Connection pool is full. Acquisition delayed.");
                    Thread.sleep(rand.nextInt(delayRange));
                    continue;
                }

                long startTime = Instant.now().toEpochMilli();
                connection.createStatement().execute("SELECT 1"); // Example operation
                long duration = Instant.now().toEpochMilli() - startTime;

                System.out.println(String.format("Operation completed in %d ms.", duration));

                if (pool.getNumActive() == 1) {
                    logConnectionPoolState(connection, "active");
                } else {
                    connection.close(); // Release the connection
                }

                Thread.sleep(rand.nextInt(delayRange));
            } catch (SQLException e) {
                System.err.println("Error while acquiring or releasing a connection: " + e.getMessage());
            } finally {
                if (connection != null)
                    connection.close();
            }
        }
    }

    private static void logConnectionPoolState(Connection connection, String state) throws IOException {
        String logEntry = LOG_FORMATTER.format(Instant.now()) + " - Connection pool state: " + state;
        Files.writeString(Paths.get("connection_pool_log.txt"), logEntry + System.lineSeparator(), StandardOpenOption.APPEND);
    }

    private static File updateAndSaveConfigFile(Properties props, String catalog) throws IOException {
        String configFilePath = "database_" + catalog + ".properties";
        List<String> commandArgs = new ArrayList<>();
        commandArgs.add("cp");
        commandArgs.add("-f"); // Overwrite existing files
        commandArgs.add(DATABASE_CONFIG_FILE);
        commandArgs.add(tempFileToConfigFilePath(configFilePath));
        commandArgs.forEach(arg -> commandArgs.add(arg.replaceAll("\\s", "")));

        ProcessBuilder pb = new ProcessBuilder(commandArgs);
        pb.redirectErrorStream(true); // Redirect error stream to standard error
        Process process = pb.start();
        Files.write(new File(tempFileToConfigFilePath(configFilePath)).toPath(), props.propertyNames().stream()
                .map(key -> key + "=" + props.getProperty(key))
                .collect(Collectors.joining("\n"))
                .getBytes());
        process.waitFor();

        if (process.exitValue() != 0) {
            System.err.println("Error while updating configuration file.");
        }

        return new File(configFilePath);
    }

    private static String tempFileToConfigFilePath(String configFileName) throws IOException {
        String tempFileName = "temp_" + UUID.randomUUID().toString() + ".properties";
        File tempFile = File.createTempFile(tempFileName, ".properties");
        Files.deleteIfExists(Paths.get(configFileName));
        return tempFile.getCanonicalPath();
    }
}
```

