```python
import hashlib
import os
import time
import socket
from threading import Thread

def calculate_md5(chunk):
    md5 = hashlib.md5()
    md5.update(chunk)
    return md5.digest()

def calculate_md5_with_dns_resolution(file_path, progress_callback=None):
    total_size = os.path.getsize(file_path)
    chunk_size = 64 * (1024 ** 2)  # Set maximum chunk size here
    chunks = [open(file_path, 'rb').read(chunk_size) for _ in range(total_size // chunk_size + 1)]

    if progress_callback:
        total_chunks = len(chunks)
        progress_callback((i / total_chunks) * 100 for i, chunk in enumerate(chunks))

    md5 = hashlib.md5()
    for chunk in chunks:
        md5.update(calculate_md5(chunk))

    return md5.digest()
