    unsigned int count = 0, allocated = 0;
    unsigned int summary_due = 0;
    log_buffer[0] = '\0';

    list = (NFAPI_CRC_INDICATION_PDU_T*) malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
