typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    pthread_mutex_t lock;
} Node;

Node* head = NULL;
pthread_mutex_t array_lock;

void init() {
    pthread_mutex_init(&array_lock, NULL);
}

void add(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = *data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    pthread_mutex_lock(&array_lock);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&array_lock);
}

void remove(uint64_t rnti) {
    pthread_mutex_lock(&array_lock);

    Node* current = head;
    Node* previous = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (previous == NULL) head = current->next;
    else previous->next = current->next;

    free(current);
    pthread_mutex_unlock(&array_lock);
}

void iterate(void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&array_lock);
    Node* current = head;

    while (current != NULL) {
        Node* next = current->next;
        pthread_mutex_lock(&current->lock);
        func(&current->data);
        pthread_mutex_unlock(&current->lock);
        current = next;
    }

