// Define a custom dynamic list structure
typedef struct DynList {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size; // Current number of elements
    size_t capacity; // Maximum number of elements
    pthread_mutex_t mutex;
    sem_t semaphore;
} DynList;

void init_list(DynList* list, size_t initial_capacity) {
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    sem_init(&list->semaphore, 0, list->capacity); // Initial value is the maximum number of elements that can be processed concurrently
}

void push(DynList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->rnti > 65535 || pdu->rnti < 1) {
        fprintf(stderr, "Error: RNTI out of range (%d)\n", pdu->rnti);
        return;
    }

    size_t index = list->size % list->capacity;

    pthread_mutex_lock(&list->mutex);

    while (list->size == list->capacity && sem_trywait(&list->semaphore) != 0) {
        // Wait if the list is full and there's no space in the semaphore
        pthread_mutex_unlock(&list->mutex);
        pthread_yield();
        pthread_mutex_lock(&list->mutex);
    }

    if (list->size == list->capacity) { // Resize the list when it's full
        DynList temp;
        init_list(&temp, list->capacity * 2);

        for (size_t i = 0; i < list->size; ++i)
            temp.data[i] = list->data[(index + i) % list->capacity];

        free(list->data);

        list->data = temp.data;
        list->capacity *= 2;
        sem_post(&temp.semaphore); // Release the semaphore for the resized list
    }

    list->data[index] = *pdu;
    update_crc_flag(pdu, get_seed());

    ++list->size;
    pthread_mutex_unlock(&list->mutex);
}

