        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < self.retry_backoff:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    logging.error(f"Error occurred: {e}. Retrying in {RETRY_SLEEP_INTERVAL} seconds.")
                    time.sleep(RETRY_SLEEP_INTERVAL)
            raise ValueError("Max retries exceeded.")
        return wrapper

