            self.cache[media_file] = result

        metadata = self.extract_metadata(media_file)
        # Include metadata in the output files here.

    def pause(self):
        self.state["position"] += 1

    def resume(self):
        with self.lock:
            if self.state["current_media"] is None:
                raise ValueError("No media file currently being processed.")
            position = self.state["position"]
            self.state["position"] += 1
            return open(self.state["current_media"], "rb").read(position)

