struct dynamic_array {
    size_t size;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty_cv, full_cv;
};

void init_dynamic_array(struct dynamic_array *da, size_t initial_capacity) {
    da->size = 0;
    da->capacity = initial_capacity;
    da->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->data) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&da->mutex, NULL);
    pthread_cond_init(&da->not_empty_cv, NULL);
    pthread_cond_init(&da->full_cv, NULL);
}

void resize_dynamic_array(struct dynamic_array *da) {
    size_t new_capacity = da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(da->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("realloc");
        exit(EXIT_FAILURE);
    }
    da->data = new_data;
    da->capacity = new_capacity;
}

void push_dynamic_array(struct dynamic_array *da, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (da->size == da->capacity) {
        resize_dynamic_array(da);
    }
    pthread_mutex_lock(&da->mutex);
    while (da->size >= da->capacity / 2) {
        pthread_cond_wait(&da->not_empty_cv, &da->mutex);
    }
    memcpy(&da->data[da->size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->size++;
    if (da->size == 1) {
        pthread_cond_signal(&da->full_cv);
    } else {
        pthread_cond_broadcast(&da->not_empty_cv);
    }
    pthread_mutex_unlock(&da->mutex);
}

void pop_dynamic_array(struct dynamic_array *da, uint32_t rnti) {
    pthread_mutex_lock(&da->mutex);
    size_t i;
    for (i = 0; i < da->size; ++i) {
        if (da->data[i].rnti == rnti) {
            memmove(&da->data[i], &da->data[i + 1], (da->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --da->size;
            pthread_cond_signal(&da->not_empty_cv);
            break;
        }
    }
    if (i == da->size) {
        fprintf(stderr, "RNTI not found\n");
    }
    pthread_mutex_unlock(&da->mutex);
}

