        }

        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
        } else {
            *tail = new_node;
            tail = &new_node->next;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    total_time += (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1.0e9;

