namespace DynamicMediaProcessor
{
    public struct Entry
    {
        public double Value;
        public char[] Buffer;
    }

    public class DynamicMediaProcessor
    {
        private ConcurrentQueue<NetworkStream> _networkStreams = new ConcurrentQueue<NetworkStream>();
        private ConcurrentQueue<FileInfo> _fileQueues = new ConcurrentQueue<FileInfo>();
        private BlockingCollection<Entry> _entries = new BlockingCollection<Entry>();
        private SemaphoreSlim _semaphore = new SemaphoreSlim(Environment.ProcessorCount);
        private Random _random;
        private MediaFormat _currentMediaFormat;

        public DynamicMediaProcessor()
        {
            _random = new Random((int)DateTime.Now.Ticks);
        }

        public void AddNetworkStream(NetworkStream stream) => _networkStreams.Enqueue(stream);

        public void AddFile(FileInfo fileInfo) => _fileQueues.Enqueue(fileInfo);

        public async Task LoadDataAsync()
        {
            var tasks = new List<Task>();

            ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };

            Parallel.ForEach(_networkStreams, options, stream =>
            {
                tasks.Add(Task.Run(() => ProcessNetworkStream(stream)));
            });

            Parallel.ForEach(_fileQueues, options, fileInfo =>
            {
                tasks.Add(Task.Run(() => ProcessFile(fileInfo)));
            });

            await Task.WhenAll(tasks);
        }

        private void ProcessNetworkStream(NetworkStream stream)
        {
            var buffer = new byte[4096];
            int read;

            while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
            {
                _semaphore.Wait();
                try
                {
                    ProcessData(buffer, read);
                    _semaphore.Release();
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing network stream: {ex.Message}");
                    _semaphore.Release();
                }
            }
        }

        private void ProcessFile(FileInfo fileInfo)
        {
            using (var reader = new BinaryReader(fileInfo.OpenRead()))
            {
                int read;

                while ((read = reader.Read(new byte[4096], 0, 4096)) > 0)
                {
                    _semaphore.Wait();
                    try
                    {
                        ProcessData(reader.ReadBytes(read), read);
                        _semaphore.Release();
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Error processing file: {ex.Message}");
                        _semaphore.Release();
                    }
                }
            }
        }

        private void ProcessData(byte[] buffer, int length)
        {
            var entry = new Entry
            {
                Buffer = Encoding.UTF8.GetString(buffer).ToCharArray(),
                Value = _currentMediaFormat switch
                {
                    MediaFormat.Image => ReadDoubleFromImageData(buffer, length),
                    MediaFormat.Audio => ReadDoubleFromAudioData(buffer, length),
                    _ => 0
                }
