['```c
#include <semaphore.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>
#include <errno.h>

typedef struct Semaphore {
    sem_t sem;
    pthread_mutex_t lock;
    bool active;
} Semaphore;

static Semaphore *sem_pool = NULL;
static size_t num_semaphores = 0;
static size_t max_semaphores = 0;

void sem_init(Semaphore **semaphore, int value) {
    if (num_semaphores >= max_semaphores) {
        if (max_semaphores == 0) {
            max_semaphores = 16;
        } else {
            max_semaphores *= 2;
        }

        Semaphore *new_pool = realloc(sem_pool, sizeof(Semaphore) * max_semaphores);
        if (!new_pool) {
            fprintf(stderr, "Failed to allocate memory for semaphores.\n");
            return;
        }
        sem_pool = new_pool;
    }

    Semaphore *sem = &sem_pool[num_semaphores++];
    sem->active = true;
    if (sem_init(&sem->sem, value <= 0 ? 1 : value, value) != 0) {
        fprintf(stderr, "Failed to initialize semaphore.\n");
        sem->active = false;
        return;
    }
    pthread_mutex_init(&sem->lock, NULL);
}

void sem_destroy(Semaphore **semaphore) {
    if (!*semaphore || !(*semaphore)->active) {
        fprintf(stderr, "Invalid or inactive semaphore.\n");
        return;
    }

    (*semaphore)->active = false;
    pthread_mutex_destroy(&(*semaphore)->lock);
}

int sem_wait_timeout(Semaphore *semaphore, const struct timespec *timeout) {
    if (!semaphore || !semaphore->active) {
        fprintf(stderr, "Invalid or inactive semaphore.\n");
        return -1;
    }

    int result = sem_trywait(&semaphore->sem);
    if (result == 0) {
        return 0;
    }

    struct timespec remaining = *timeout;
    while (remaining.tv_sec > 0 || remaining.tv_nsec > 0) {
        int ret = sem_timedwait(&semaphore->sem, &remaining);
        if (ret == 0) {
            return 0;
        }

        if (errno != ETIMEDOUT) {
            fprintf(stderr, "Semaphore operation failed: %s\n", strerror(errno));
            return -1;
        }

        if (remaining.tv_sec > 0) {
            remaining.tv_sec--;
            remaining.tv_nsec += 1000000000;
        } else {
            remaining.tv_sec = 0;
            remaining.tv_nsec += 1000000000;
        }
    }

    return ETIMEDOUT;
}

int sem_post(Semaphore *semaphore) {
    if (!semaphore || !semaphore->active) {
        fprintf(stderr, "Invalid or inactive semaphore.\n");
        return -1;
    }

    int result = sem_post(&semaphore->sem);
    if (result < 0) {
        fprintf(stderr, "Semaphore operation failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void sem_reset_all() {
    for (size_t i = 0; i < num_semaphores; ++i) {
        if (sem_pool[i].active) {
            sem_destroy(&(&sem_pool[i]));
        }
    }
}
```

This code defines a `Semaphore` struct, which includes a semaphore and a mutex. The `sem_init`, `sem_destroy`, `sem_wait_timeout`, `sem_post`, and `sem_reset_all` functions are provided for creating, deleting, waiting on, posting to, and resetting semaphores in the pool.

The main function to manage the pool of semaphores is not implemented here but could be done by maintaining an array of active semaphores and providing additional functions like `sem_create` and `sem_delete`.']

