import os
import sys
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed

def _validate_filepath(filepath):
    if not os.path.isfile(filepath) or not os.access(filepath, os.R_OK):
        raise ValueError("Invalid or inaccessible file path")

def _read_chunk(filepath, chunk_size=128*1024):
    with open(filepath, "rb") as f:
        return f.read(chunk_size)

def _update_hash(hasher, data):
    hasher.update(data)

def compute_sha256(directory, chunk_size=128*1024):
    hasher = hashlib.sha256()

    def process_file(filepath):
        try:
            _validate_filepath(filepath)
            data = _read_chunk(filepath, chunk_size)
            _update_hash(hasher, data)
        except Exception as e:
            print(f"Error processing {filepath}: {e}")

    thread_count = max(1, min(os.cpu_count(), len([name for root, dirs, files in os.walk(directory)])))
    with ThreadPoolExecutor(max_workers=thread_count) as executor:
        file_futures = [executor.submit(process_file, os.path.join(directory, f)) for _, dirs, files in os.walk(directory) for f in files]
        for _ in as_completed(file_futures):
            pass

    return hasher.hexdigest()
```

