struct array* create_array(size_t initial_capacity) {
    struct array *arr = malloc(sizeof(struct array));
    if (!arr) return NULL;
    arr->capacity = initial_capacity;
    arr->size = 0;
    arr->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->data) {
        free(arr);
        return NULL;
    }
    pthread_mutex_init(&arr->lock, NULL);
    sem_init(&arr->resize_sem, 0, initial_capacity / 2);
    arr->data[arr->size].crcflag = rand() % 2; // initialize first element with random crcflag
    return arr;
}

void add(struct array *arr, const NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size == arr->capacity && sem_wait(&arr->resize_sem) < 0) {
        perror("Resize semaphore wait failed");
        pthread_mutex_unlock(&arr->lock);
        return;
    }

    size_t i = arr->size++;
    memcpy(arr->data + i, item, sizeof(*item));
    arr->data[i].crcflag = rand() % 2;

    pthread_mutex_unlock(&arr->lock);
}

void remove(struct array *arr, RNTI rnti) {
    pthread_mutex_lock(&arr->lock);
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->data[i].rnti == rnti) {
            memmove(arr->data + i, arr->data + i + 1, (arr->size - i - 1) * sizeof(*arr->data));
            --arr->size;
