    AsyncEventQueue(size_t initialQueueSize) : queueSize_(initialQueueSize), head_(nullptr), tail_(nullptr), numEvents_(0), md5Hash_(), apiCallsInProgress_(0), logLevel_(0) {}

    ~AsyncEventQueue() {
        clear();
    }

    void setLogLevel(int level) {
        logLevel_ = level;
    }

    Event* getHead() const {
        return head_;
    }

    void enqueue(Event* event) {
        std::unique_lock<std::mutex> lock(queueMutex_);
        if (numEvents_ >= queueSize_) {
            // Wait for space to become available
            spaceAvailable_.wait(lock);
        }
        ++numEvents_;
        event->next = head_;
        head_ = event;
        if (!tail_) {
            tail_ = head_;
        }
        lock.unlock();
        processQueue();
