        std::unique_lock<std::mutex> lock2(queueMutex_);
        tail_->next = current;
        tail_ = current;
        lock2.unlock();
    }

    size_t queueSize_;
    Event* head_, *tail_;
    int numEvents_;
    MD5_CTX md5Hash_;
    std::atomic<int> apiCallsInProgress_;
