pthread_cond_t elements_full_cond, elements_empty_cond;
size_t element_count = 0;
LTE_PHY_RX_PROC_T* data = NULL;

void init_array() {
    pthread_mutex_init(&array_lock, NULL);
    pthread_cond_init(&elements_full_cond, NULL);
    pthread_cond_init(&elements_empty_cond, NULL);
    data = malloc(ELEMENT_COUNT * sizeof(LTE_PHY_RX_PROC_T));
}

void destroy_array() {
    free(data);
    pthread_mutex_destroy(&array_lock);
    pthread_cond_destroy(&elements_full_cond);
    pthread_cond_destroy(&elements_empty_cond);
}

size_t get_current_element_count() {
    return element_count;
}

void add_element(LTE_PHY_RX_PROC_T* new_elem) {
    pthread_mutex_lock(&array_lock);
    if (element_count >= ELEMENT_COUNT) {
        pthread_cond_wait(&elements_full_cond, &array_lock);
    }

    memcpy(data + element_count, new_elem, sizeof(LTE_PHY_RX_PROC_T));
    element_count++;

    if (element_count == 1) {
        pthread_cond_signal(&elements_empty_cond);
    }

    pthread_mutex_unlock(&array_lock);
}

void remove_by_cell_id(uint32_t cell_id) {
