    size_t i;
    for (i = 0; i < element_count; ++i) {
        if (data[i].cell_id == cell_id) {
            memcpy(data + i, data + i + 1, (element_count - i - 1) * sizeof(LTE_PHY_RX_PROC_T));
            --element_count;
            break;
        }
    }

    if (i == element_count) {
        pthread_cond_broadcast(&elements_full_cond);
    } else {
        pthread_cond_signal(&elements_empty_cond);
    }

    pthread_mutex_unlock(&array_lock);
}

void update_status(uint32_t cell_id, enum RECEPTION_STATUS new_status) {
    pthread_mutex_lock(&array_lock);

    size_t i;
