        if (data[i].cell_id == cell_id) {
            data[i].reception_status = new_status;
            break;
        }
    }

    pthread_mutex_unlock(&array_lock);
}

void resize(size_t new_capacity) {
    LTE_PHY_RX_PROC_T* temp = realloc(data, new_capacity * sizeof(LTE_PHY_RX_PROC_T));
    if (!temp) {
        fprintf(stderr, "Failed to reallocate memory.\n");
        exit(EXIT_FAILURE);
    }
    data = temp;
}
