#include <iostream>
#include <vector>
#include <chrono>
#include <random>
#include <memory>
#include <mutex>

struct LTE_PDCP_RX_BUFFER {
    uint32_t PDCP_SN;
    std::shared_ptr<uint8_t[]> LAYER3_PDU;
    std::time_t RX_TIMESTAMP;
    bool ACK_FLAG;
};

class PDCP_BUFFER_MANAGER {
private:
    std::vector<std::shared_ptr<LTE_PDCP_RX_BUFFER>> buffers_;
    std::mutex mutex_;
    uint32_t next_index_ = 0;
    static constexpr size_t buffer_growth_factor_ = 2;

public:
    PDCP_BUFFER_MANAGER() : buffers_(buffer_growth_factor_) {}

    std::shared_ptr<LTE_PDCP_RX_BUFFER> add_buffer() {
        if (next_index_ == buffers_.size()) resize_buffers();
        auto buffer = std::make_shared<LTE_PDCP_RX_BUFFER>();
        buffer->PDCP_SN = next_index_;
        buffer->ACK_FLAG = rand() % 2;
        buffer->LAYER3_PDU = std::make_shared<uint8_t[]>(1024); // PDUs size is a placeholder, replace it with your actual size
        buffer->RX_TIMESTAMP = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        std::unique_lock<std::mutex> lock(mutex_);
        buffers_[next_index_] = buffer;
        ++next_index_;
        return buffer;
    }

    void remove_buffer(uint32_t pdcp_sn) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = buffers_.begin();
        while (it != buffers_.end()) {
            if ((*it)->PDCP_SN == pdcp_sn) {
                it = buffers_.erase(it);
                break;
            }
            ++it;
        }
    }

    size_t count_undelivered_pdus(std::time_t timestamp) const {
        std::unique_lock<std::mutex> lock(mutex_);
        size_t count = 0;
        for (const auto& buffer : buffers_) {
            if (!buffer->ACK_FLAG && buffer->RX_TIMESTAMP <= timestamp) {
                ++count;
            }
        }
        return count;
    }

private:
    void resize_buffers() {
        std::vector<std::shared_ptr<LTE_PDCP_RX_BUFFER>> new_buffers(buffers_.size() * buffer_growth_factor_);
        std::unique_lock<std::mutex> lock(mutex_);
        for (const auto& buffer : buffers_) {
            new_buffers[buffer->PDCP_SN] = buffer;
        }
        buffers_ = new_buffers;
    }
};
```

