typedef struct LTE_PHY_RX_PROC_T {
    PHY_STATS_TAG tag;
    unsigned int CELL_ID;
    int RX_POWER_LEVEL;
    enum RECEPTION_STATUS { SUCCESS, UNSUCCESSFUL } RECEPTION_STATUS;
    atomic_long successful_receptions;
    atomic_long unsuccessful_receptions;
} LTE_PHY_RX_PROC;

struct array_data {
    LTE_PHY_RX_PROC *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

void resize(struct array_data *ad, size_t new_capacity) {
    LTE_PHY_RX_PROC *new_array = realloc(ad->array, new_capacity * sizeof(LTE_PHY_RX_PROC));
    if (!new_array) {
        perror("realloc failed");
        return;
    }

    ad->array = new_array;
    ad->capacity = new_capacity;
}

void init_array(struct array_data *ad) {
    pthread_mutex_init(&ad->mutex, NULL);
    resize(ad, 16);
}

int add_element(struct array_data *ad, LTE_PHY_RX_PROC element) {
    if (ad->size == ad->capacity) {
        resize(ad, ad->capacity ? ad->capacity * 2 : 32);
    }

    pthread_mutex_lock(&ad->mutex);
    ad->array[ad->size] = element;
    ad->size++;
    pthread_mutex_unlock(&ad->mutex);

    return 0;
}

int remove_by_cell_id(struct array_data *ad, unsigned int cell_id) {
    pthread_mutex_lock(&ad->mutex);

    for (size_t i = 0; i < ad->size; ++i) {
        if (ad->array[i].CELL_ID == cell_id) {
            memmove(ad->array + i, ad->array + i + 1, --ad->size - i);
            break;
        }
    }

    pthread_mutex_unlock(&ad->mutex);
    return 0;
}

void update_status(struct array_data *ad, unsigned int cell_id, enum RECEPTION_STATUS status) {
    pthread_mutex_lock(&ad->mutex);

    for (size_t i = 0; i < ad->size; ++i) {
        if (ad->array[i].CELL_ID == cell_id) {
            ad->array[i].RECEPTION_STATUS = status;
            break;
        }
    }

    pthread_mutex_unlock(&ad->mutex);
}

void increment_reception_count(struct array_data *ad, unsigned int cell_id, enum RECEPTION_STATUS status) {
    pthread_mutex_lock(&ad->mutex);

    for (size_t i = 0; i < ad->size; ++i) {
        if (ad->array[i].CELL_ID == cell_id) {
            switch (status) {
                case SUCCESS:
                    atomic_fetch_add(&ad->array[i].successful_receptions, 1);
                    break;
                case UNSUCCESSFUL:
                    atomic_fetch_add(&ad->array[i].unsuccessful_receptions, 1);
                    break;
            }
        }
    }

    pthread_mutex_unlock(&ad->mutex);
}

unsigned long get_success_count(struct array_data *ad, unsigned int cell_id) {
    return atomic_load(&ad->array[cell_id].successful_receptions);
}

unsigned long get_failure_count(struct array_data *ad, unsigned int cell_id) {
    return atomic_load(&ad->array[cell_id].unsuccessful_receptions);
}
```

