#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>
#include <zlib.h>
#include <time.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>

#define MAX_CONCURRENT 10
#define THREAD_STACK_SIZE 64*1024

typedef struct {
    char *src;
    char *dst;
    gzFile zipfile;
    time_t last_modified;
    pid_t process_id;
} CompressionTask;

void *compress_thread(void *data) {
    CompressionTask *task = data;
    char cmd[1024];
    snprintf(cmd, sizeof(cmd), "thirdparty-ziptool -c -r -T %dM -q %d -t zip -o \"%s\" \"%s\"", (int)(max_memory / (1024*1024)), compression_level, task->dst, task->src);
    pid_t pid = fork();
    if(pid == 0) {
        execlp("sh", "sh", "-c", cmd, NULL);
        exit(1);
    } else {
        int status;
        waitpid(pid, &status, 0);
        if(WIFEXITED(status)) {
            if(WEXITSTATUS(status) == 0) {
                // Successfully compressed the file. Update last_modified timestamp in the task structure.
                struct stat st;
                stat(task->src, &st);
                task->last_modified = st.st_mtime;
            } else {
                // Compression failed. Log error and mark task for retry or exclusion based on file conflict handling policy.
                printf("Error compressing %s: Compression tool exited with status %d\n", task->src, WEXITSTATUS(status));
            }
        } else if(WIFSIGNALED(status)) {
            // Compression failed due to a signal. Log error and mark task for retry or exclusion based on file conflict handling policy.
            printf("Error compressing %s: Killed by signal %d\n", task->src, WTERMSIG(status));
        } else {
            // Unknown failure mode. Log error and mark task for retry or exclusion based on file conflict handling policy.
            printf("Error compressing %s: Child process failed to terminate properly\n", task->src);
        }
    }
    free(task->src);
    free(task->dst);
    fclose(task->zipfile);
    free(task);
    return NULL;
}

void compress_directory(char *src_dir, char *dst_zip, int compression_level, int concurrency_limit, long max_memory) {
    DIR *dir = opendir(src_dir);
    struct dirent *entry;
    pthread_t threads[MAX_CONCURRENT];
    CompressionTask *tasks[MAX_CONCURRENT];
    int num_threads = 0, i;

    while((entry = readdir(dir)) != NULL) {
        if(strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char src[4096], dst[4096];
        snprintf(src, sizeof(src), "%s/%s", src_dir, entry->d_name);
        snprintf(dst, sizeof(dst), "%s.%ld.zip", dst_zip, (long)time(NULL));

        struct stat st;
        if(stat(src, &st) == 0 && S_ISDIR(st.st_mode)) {
            // Recursively compress directories
            compress_directory(src, dst, compression_level, concurrency_limit, max_memory);
        } else {
            long memory_chunk = (max_memory / (concurrency_limit * 1024));
            char *src_chunk = malloc(memory_chunk);
            char *dst_chunk = malloc(strlen(src) + strlen(dst) + 32); // Additional space for filename and timestamp suffix.

            FILE *file = fopen(src, "r");
            if(file != NULL) {
                size_t read;
                while((read = fread(src_chunk, memory_chunk, 1, file)) > 0 && num_threads < concurrency_limit) {
                    CompressionTask *task = malloc(sizeof(CompressionTask));
                    task->src = src_chunk;
                    task->dst = dst_chunk;
                    snprintf(task->dst + strlen(dst), sizeof(task->dst) - strlen(task->dst), "/%s", entry->d_name);
                    task->zipfile = gzopen(dst, "ab");
                    task->last_modified = st.st_mtime;
                    task->process_id = 0;

                    pthread_create(&threads[num_threads], NULL, compress_thread, task);
                    tasks[num_threads++] = task;
                }
                fclose(file);
            }

            free(src_chunk);
            free(dst_chunk);
        }
    }

    for(i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
    closedir(dir);
