import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import time
import random
import functools
from typing import Dict, Union, List
import aiohttp
import logging

class Record:
    def __init__(self, index: int):
        self.offset = index
        self.key = index
        self.timestamp = round(random.uniform(0.0, 1000.0), 2)
        self.status_flag = 'U'  # Unprocessed

class Node:
    def __init__(self, data: Record):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def append(self, data: Record):
        if not self.head:
            self.head = Node(data)
            self.tail = self.head
        else:
            new_node = Node(data)
            self.tail.next = new_node
            self.tail = new_node
        self.size += 1

    def find(self, key: int):
        current = self.head
        while current is not None:
            if current.data.key == key:
                return current
            current = current.next
        return None

def md5_file(file_path: str, output_stream=None) -> str:
    hasher = hashlib.md5()
    chunk_size = 8192
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def api_call(key: int) -> Union[Dict, None]:
    url = f'https://api.example.com/metadata/{key}'
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(url, timeout=10) as response:
                if response.status == 200:
                    return await response.json()
    except Exception as e:
        logging.error(f'Failed to fetch metadata for key {key}: {e}')
        return None

def calculate_record_timestamp(index: int) -> float:
    return round(random.uniform(0.0, 1000.0), 2)

def validate_linked_list(head: Node):
    visited = set()
    stack = [head]
    while stack:
        current = stack.pop()
        if current in visited:
            return False
        visited.add(current)
        if current.next is not None:
            stack.append(current.next)
    return True

def create_linked_list(size: int):
    ll = LinkedList()
    for i in range(size):
        ll.append(Record(i))
    return ll, size

@functools.lru_cache(maxsize=128)  # Cache API calls to reduce overhead
def api_stats():
    with aiohttp.ClientSession() as session:
        async with session.get('https://api.example.com/stats') as response:
            return await response.json() if response.status == 200 else None

def md5_hash_file_with_linked_list(file_path: str, linked_list: LinkedList, output_stream=None) -> Tuple[Union[Node, None], Dict]:
    hasher = hashlib.md5()
    chunk_size = 8192
    with open(file_path, 'rb') as f:
        current_node = linked_list.head
        for _ in range(len(linked_list)):
            while current_node and current_node.data.offset < f.tell():
                hasher.update(f.read(chunk_size))
                if output_stream:
                    output_stream.write(f'Processed chunk {current_node.data.offset}:{f.tell()}\n')
                current_node = current_node.next
            if not current_node:
                break
        return hasher.hexdigest(), current_node, api_stats()

if __name__ == "__main__":
    import sys
    import logging.config

    log_file = 'md5_hash.log'
    logging.config.fileConfig(fname=log_file)
    logger = logging.getLogger(__name__)

    file_path = sys.argv[1]
    linked_list, size = create_linked_list(10000)
    md5_hash, head, stats = md5_hash_file_with_linked_list(file_path, linked_list)
    if not validate_linked_list(head):
        logger.error('Linked list contains a cycle')
    else:
        print(f'MD5 hash: {md5_hash}\nLinked list size: {size}\nAPI success count: {stats["success"]} API failure count: {stats["failure"]}\n')
