#include <signal.h>

void print_largest(int *arr, size_t len) {
    int max = arr[0];
    for (size_t i = 1; i < len; ++i) {
        if (max < arr[i]) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

void read_chunk(int *arr, size_t *len, size_t chunk_size) {
    int read;
    char buffer[chunk_size];
    while ((read = fread(buffer, sizeof(int), chunk_size, stdin)) == chunk_size) {
        for (size_t i = 0; i < read; ++i) {
            if (!(*len)) arr[*len++] = buffer[i];
            else if (buffer[i] < INT_MIN || buffer[i] > INT_MAX) {
                fprintf(stderr, "Error: Invalid input %d\n", buffer[i]);
                exit(1);
            } else arr[*len++] = buffer[i];
        }
    }

    if (read < chunk_size) {
        for (size_t i = 0; i < read; ++i) {
            if (!(*len)) arr[*len++] = buffer[i];
            else if (buffer[i] < INT_MIN || buffer[i] > INT_MAX) {
                fprintf(stderr, "Error: Invalid input %d\n", buffer[i]);
                exit(1);
            } else arr[*len++] = buffer[i];
        }
    }
}

void progress_indicator(size_t total, size_t current) {
    double percentage = (double)current / total * 100.0;
    printf("\rProgress: %.2f%%", percentage);
    fflush(stdout);
}

int main() {
    struct rusage start, end;
    getrusage(RUSAGE_SELF, &start);

    int *arr = NULL;
    size_t len = 0, chunk_size = 1024;
    signal(SIGINT, SIG_IGN); // Ignore Ctrl+C interrupts

    while (1) {
        read_chunk(arr, &len, chunk_size);
        if (feof(stdin)) break;
        progress_indicator(len * sizeof(int), ftell(stdin));
    }

    getrusage(RUSAGE_SELF, &end);
    long memory_usage = -1; // To store the difference between max and current RSS values
    rlim_t max_rss, current_rss;
    getrlimit(RLIMIT_DATA, &max_rss);
    current_rss = max_rss;

    while (current_rss == max_rss) { // Keep polling for RLIMIT_DATA until it changes to reflect memory usage.
        getrlimit(RLIMIT_DATA, &max_rss);
        current_rss = max_rss.rlim_cur;
    }

    memory_usage = max_rss.rlim_max - current_rss.rlim_max;

    printf("\nRead %zu integers using approximately %ld bytes of memory.\n", len, memory_usage);
    print_largest(arr, len);

    free(arr);
    return 0;
}
