#include <openssl/sha.h>
#include <random>
#include <algorithm>
#include <functional>

namespace RandomGenerator {
    class StringHasher {
        public:
            std::mt19937 engine;
            static StringHasher& getInstance() {
                static StringHasher instance;
                return instance;
            }

            StringHasher() : engine(std::random_device{}()) {}
            ~StringHasher() = default;

            std::string getMD5Hash(const std::string& input) {
                const unsigned char digest[SHA256_DIGEST_LENGTH] = {0};
                SHA256_CTX ctx;
                SHA256_Init(&ctx);
                SHA256_Update(&ctx, input.c_str(), input.length());
                SHA256_Final(digest, &ctx);

                std::stringstream ss;
                for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
                    ss << std::hex << std::setw(2) << std::uppercase << static_cast<unsigned int>(digest[i]);
                }
                return ss.str();
            }

            int generateRandomInt(int min, int max) {
                std::uniform_int_distribution<> distr(min, max);
                return distr(engine);
            }

            std::string generateRandomString(size_t length) {
                static const char alphanum[] = "0123456789"
                                              "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                                              "abcdefghijklmnopqrstuvwxyz";
                std::random_device rd;
                std::mt19937 gen(rd());
                std::string ret;
                std::generate_n(std::back_inserter(ret), length,
                                std::bind(std::uniform_int_distribution<>(0, sizeof(alphanum)-1), gen)
                );
                std::shuffle(ret.begin(), ret.end, gen);
                return ret;
            }
    };
}

int main() {
    RandomGenerator::StringHasher hasher = RandomGenerator::StringHasher::getInstance();

    std::string input = "Test string";
    std::cout << "MD5 Hash of \"" << input << "\": " << hasher.getMD5Hash(input) << std::endl;

    int min = 10, max = 99;
    std::cout << "Random number between " << min << " and " << max << ": " << hasher.generateRandomInt(min, max) << std::endl;

    size_t length = 10;
    std::cout << "Random alphanumeric string of length " << length << ": " << hasher.generateRandomString(length) << std::endl;

    return 0;
}
