import os
import sys
import gzip
import bz2
import hashlib
import concurrent.futures
from multiprocessing import Pool
from threading import Lock
import logging

class HashFile:
    def __init__(self, file_path, chunk_size=65536, compression='none', log=sys.stderr):
        self.file_path = file_path
        self.chunk_size = chunk_size
        self.compression = compression
        self.log = log
        self.hash = hashlib.md5()
        self.lock = Lock()

    def _read_chunk(self, chunk):
        if self.compression == 'gzip':
            return gzip.decompress(chunk)
        elif self.compression == 'bz2':
            return bz2.decompress(chunk)
        else:
            return chunk

    def _hash_chunk(self, chunk):
        with self.lock:
            self.hash.update(self._read_chunk(chunk))

    def _get_checksum(self, reference_file):
        with open(reference_file, 'rb') as f:
            ref_hash = hashlib.md5()
            for chunk in iter(lambda: f.read(self.chunk_size), b''):
                ref_hash.update(chunk)
        return ref_hash.hexdigest()

    def _verify_integrity(self, checksum):
        self.log.info('Verifying integrity...')
        known_checksum = self._get_checksum(self.file_path + '.ref')
        if checksum != known_checksum:
            self.log.error('Integrity check failed. Retrying hash calculation...')
            self.retry(3)
        return checksum

    def retry(self, attempts):
        if attempts <= 0:
            raise ValueError('No more retries available')
        self.chunk_size *= 2
        self.log.info(f'Retrying hash calculation with chunk size {self.chunk_size}...')

    def hash_file(self):
        with open(self.file_path, 'rb') as f:
            segment_generator = lambda: iter(lambda: f.read(self.chunk_size), b'')
            if self.compression == 'gzip':
                segment_generator = lambda: gzip.GzipFile(fileobj=f).read
            elif self.compression == 'bz2':
                segment_generator = lambda: BZ2File(f).read

            chunk_generator = segment_generator()
            with concurrent.futures.ThreadPoolExecutor() as executor:
                futures = {executor.submit(self._hash_chunk, next(chunk_generator)): i for i in range(10)}
                for future in concurrent.futures.as_completed(futures):
                    future.result()
            return self._verify_integrity(self.hash.hexdigest())

def process_files(file_paths, compression='none', log=sys.stderr):
    for file_path in file_paths:
        hash_file = HashFile(file_path, compression, log)
        if not os.path.exists(file_path + '.ref'):
            hash_file.hash_file()
        else:
            hash_file.verify_integrity()

def main(input_files, output_files, compression='none', num_threads=os.cpu_count()):
    with Pool(num_threads) as pool:
        pool.starmap(process_files, ((file, output_files[i], compression, sys.stderr) for i, file in enumerate(input_files)))
```
In this code snippet, the `HashFile` class is responsible for calculating the MD5 hash of a given file while handling chunking, compression, and integrity checks. The `process_files()` function processes multiple files concurrently by creating instances of the `HashFile` class and verifying their integrity against known reference files. The `main()` function serves as an entry point for processing large numbers of small files in parallel using a multiprocessing pool. The number of threads can be dynamically adjusted based on the available system resources.

Please note that this code is not tested thoroughly and may require adjustments to meet your specific use case or environment. Additionally, error handling and logging are minimal for brevity but should be expanded according to your requirements."]

