#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

typedef struct collection {
    long* offsets;
    int* keys;
    Record* records;
    size_t capacity, size;
    pthread_mutex_t mutex;
} Collection;

Collection* create_collection(size_t initial_capacity) {
    Collection* collection = malloc(sizeof(Collection));
    if (!collection) {
        perror("Error allocating memory for collection");
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->offsets = calloc(initial_capacity, sizeof(long));
    if (!collection->offsets) {
        perror("Error allocating memory for offsets");
        free(collection);
        return NULL;
    }
    collection->keys = malloc(initial_capacity * sizeof(int));
    if (!collection->keys) {
        perror("Error allocating memory for keys");
        free(collection->offsets);
        free(collection);
        return NULL;
    }
    collection->records = calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        perror("Error allocating memory for records");
        free(collection->keys);
        free(collection->offsets);
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_collection(Collection* collection) {
    if (collection) {
        pthread_mutex_destroy(&collection->mutex);
        free(collection->offsets);
        free(collection->keys);
        free(collection->records);
        free(collection);
    }
}

void resize_collection(Collection* collection, size_t new_capacity) {
    Record* temp_records = realloc(collection->records, new_capacity * sizeof(Record));
    if (!temp_records) {
        perror("Error resizing memory for records");
        return;
    }
    collection->records = temp_records;
}

int random_in_range(int min, int max) {
    static unsigned seed = time(NULL);
    if (min > max) {
        int tmp = min;
        min = max;
        max = tmp;
    }
    return rand_r(&seed) % (max - min + 1) + min;
}

void insert_record(Collection* collection, int key, int value) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity) {
        resize_collection(collection, collection->size * 2);
    }

    for (long i = collection->offsets[collection->size]; i < collection->offsets[collection->size + 1]; ++i) {
        if (!collection->keys[i]) {
            collection->keys[i] = key;
            collection->records[i].value = value;
            collection->offsets[collection->size + 1] = i + 1;
            ++collection->size;
            break;
        }
    }

    pthread_mutex_unlock(&collection->mutex);
}

int find_record(Collection* collection, int key) {
    pthread_mutex_lock(&collection->mutex);

    for (long i = collection->offsets[0]; i < collection->offsets[collection->size]; ++i) {
        if (collection->keys[i] == key) {
            int value = collection->records[i].value;
            pthread_mutex_unlock(&collection->mutex);
            return value;
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    return -1;
}
```

This code defines a `Collection` structure to manage the data, including offsets, keys, and records. The `create_collection()` function dynamically allocates memory for these structures, and handles allocation failures gracefully by returning an error message and freeing any previously allocated memory.

The function also initializes a mutex to ensure thread safety when accessing the collection concurrently from multiple threads. It uses a seeded random number generator (`random_in_range()`) to populate record values within a specified range, handling edge cases such as zero or negative range values.

The `insert_record()` function inserts a new record into the collection, expanding its capacity if necessary. If no available slot is found, it doubles the capacity of the collection and reallocates memory accordingly. It also handles concurrent access by locking the mutex before modifying the collection.

Finally, the `find_record()` function searches for a specific record in the collection based on its key, returning the record's value if found or -1 otherwise. It also handles concurrent access by locking the mutex before searching the collection.']

