    size_t read_size;

    while ((read_size = fread(buffer, 1, buffer_size, file)) > 0) {
        SHA256_Update(&ctx, buffer, read_size);
    }

    SHA256_Final(digest, &ctx);

    for (int i = 0; i < MD5_LENGTH; ++i) {
