```python
import hashlib
import os
import sys
import time
from tqdm import tqdm

def md5_file(file_path, chunk_size=64 * 1024, progress_bar=True):
    with open(file_path, "rb") as f:
        if progress_bar:
            hasher = hashlib.md5()
            total_chunks = os.path.getsize(file_path) // chunk_size + 1
            progress = tqdm(total=total_chunks, unit="chunks")
            for chunk in iter(lambda: f.read(chunk_size), b""):
                hasher.update(chunk)
                progress.update(1)
        else:
            hasher = hashlib.md5()
            with time.time():
                while True:
                    chunk = f.read(chunk_size)
                    if not chunk:
                        break
                    hasher.update(chunk)

    return hasher.hexdigest()
```

