DYNAMIC_ARRAY* allocate_dynamic_array(size_t initial_capacity) {
    DYNAMIC_ARRAY* da = malloc(sizeof(DYNAMIC_ARRAY));
    if (!da) return NULL;
    da->elements = calloc(initial_capacity, sizeof(UE_INFO));
    if (!da->elements) {
        free(da);
        return NULL;
    }
    da->capacity = initial_capacity;
    da->length = 0;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}
```

3. Resize the dynamic array:
```c
void resize(DYNAMIC_ARRAY* da) {
    if (da->length == da->capacity) {
        size_t new_capacity = da->capacity ? 2 * da->capacity : DA_INITIAL_CAPACITY;
        UE_INFO* new_elements = realloc(da->elements, new_capacity * sizeof(UE_INFO));
        if (!new_elements) return;
        da->elements = new_elements;
        da->capacity = new_capacity;
    }
}
```

4. Add element:
```c
void add_element(DYNAMIC_ARRAY* da, UE_INFO element) {
    pthread_mutex_lock(&da->mutex);
    resize(da);
    da->elements[da->length++] = element;
    pthread_mutex_unlock(&da->mutex);
}
```

5. Remove element by RNTI:
```c
size_t remove_by_rnti(DYNAMIC_ARRAY* da, uint32_t rnti) {
    size_t index;
    pthread_mutex_lock(&da->mutex);
    for (index = 0; index < da->length; ++index) {
        if (da->elements[index].RNTI == rnti) break;
    }
    if (index < da->length) {
        memmove(&da->elements[index], &da->elements[index + 1], --da->length - index);
        free(da->elements + da->length);
        da->length--;
    }
    pthread_mutex_unlock(&da->mutex);
    return index < da->length;
}
```

6. Update CRCFLAG under specific conditions:
```c
void update_crcflag(DYNAMIC_ARRAY* da, size_t index, bool condition) {
    if (index >= da->length || index < 0) return;
    pthread_mutex_lock(&da->mutex);
    da->elements[index].crcFlag = condition ? CRC_INDICATION_REL8_TAG_SET : CRC_INDICATION_REL8_TAG_UNSET;
    pthread_mutex_unlock(&da->mutex);
}
```

7. Iterate over the array:
```c
void for_each(DYNAMIC_ARRAY* da, void(*function)(UE_INFO)) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->length; ++i) {
        function(da->elements[i]);
    }
    pthread_mutex_unlock(&da->mutex);
}
```

