class CustomAllocator:
    def __init__(self):
        self.allocated_blocks = {}

    def allocate(self, size, align=8):
        if size in self.allocated_blocks:
            return self.allocated_blocks[size]
        aligned_size = (size + align - 1) & ~(align - 1)
        block = self._get_or_create_block(aligned_size)
