#include <vector>
#include <time.h>
#include <random>
#include <boost/mutex.hpp>
#include < boost/thread/mutex.hpp>
#include <boost/thread/locks.hpp>
#include <boost/circular_buffer.hpp>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
    bool crcFlag;
    time_t lastModified;
};

class CRCIndicatorManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    boost::mutex mtx;
    size_t capacity = 1024; // initial capacity for vector

public:
    void addElement(const NFAPI_CRC_INDICATION_PDU_T& elem) {
        boost::unique_lock<boost::mutex> lock(mtx);
        if (data.size() == data.capacity()) {
            reserveCapacity();
        }
        data.push_back(elem);
        data.back().lastModified = time(nullptr);
    }

    bool removeElementByRNTI(uint32_t rnti) {
        boost::unique_lock<boost::mutex> lock(mtx);
        auto it = std::find_if(data.begin(), data.end(), [rnti](const NFAPI_CRC_INDICATION_PDU_T& elem) { return elem.rnti == rnti; });
        if (it != data.end()) {
            data.erase(it);
            return true;
        }
        return false;
    }

    void updateCRCFlagConditionally(uint32_t rnti, bool newValue) {
        boost::unique_lock<boost::mutex> lock(mtx);
        auto it = std::find_if(data.begin(), data.end(), [rnti](const NFAPI_CRC_INDICATION_PDU_T& elem) { return elem.rnti == rnti; });
        if (it != data.end()) {
            it->crcFlag = newValue;
            it->lastModified = time(nullptr);
        }
    }

    void resizeIfNeeded() {
        if (data.size() > capacity * 0.75f) {
            reserveCapacity();
        }
    }

    void reserveCapacity() {
        size_t newCapacity = data.capacity() + data.size();
        std::vector<NFAPI_CRC_INDICATION_PDU_T> temp(newCapacity);
        std::copy(data.begin(), data.end(), temp.begin());
        data.swap(temp);
        capacity *= 2;
    }
};
```

