class HashFile:
    def __init__(self, config_path):
        self.config = ET.parse(config_path)
        self.tile_size = int(self.config.find('settings/tileSize').text)
        self.world_width, self.world_height = map(int, self.config.find('settings/dimensions').text.split('x'))
        self.camera_speed = float(self.config.find('settings/cameraSpeed').text)
        self.checksum_path = self.config.find('settings/checksumPath').text
        self.max_retries = 3
        self.chunk_sizes = [self.tile_size, int(self.tile_size * sqrt(2)), self.world_width]
        self._hash = hashlib.md5()
        self.output = sys.stdout if not config_path else open(os.path.splitext(config_path)[0] + '.log', 'w')
        self.selector = selectors.DefaultSelectors().register(self)
        self.queue = queue.Queue()

    def hash_file(self):
        with open(self.config.find('settings/filePath').text, 'rb') as file:
            selector.select(timeout=1)
            while not file.closed:
                sel = selector.select(timeout=None)
                for key, event in sel:
                    if event == selectors.EVENT_READ:
                        self.hash_chunk(key.fileobj)
            file.close()
        if self.verify_checksum():
            return self._hash.hexdigest()
        else:
            raise Exception('Failed to calculate hash due to integrity check failure')

    def hash_chunk(self, chunk):
