    pthread_mutex_lock(&array_mutex);
    NFAPI_CRC_INDICATION_PDU_T* new_user = (NFAPI_CRC_INDICATION_PDU_T*)realloc(users_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * ++num_users);
