import os
import hashlib
import stat
import sys
from functools import lru_cache

def read_chunked(file, chunk_size=1024*1024):
    with open(file, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            yield data

def md5_hash(data):
    m = hashlib.md5()
    m.update(data)
    return m.hexdigest()

@lru_cache(maxsize=None)
def get_file_size(path):
    try:
        st = os.stat(path)
        return st.st_size
    except OSError:
        return None

def hash_directory(dir, overwrite=True):
    if not os.path.isdir(dir):
        print(f"Error: '{dir}' is not a directory.")
        return False

    hexdigest = {}
    for root, _, files in sorted(os.walk(dir)):
        if root in hexdigest:
            if overwrite or hexdigest[root] == hash_files(files):
                continue
        else:
            hexdigest[root] = hash_files(files)

    return hexdigest

def hash_files(files):
    segments_size = (1024*1024*2**32 - 1) // (1024*1024) + 1
    md5 = hashlib.md5()
    for file in sorted(files, key=get_file_size):
        if not os.path.isfile(file):
            continue

        size = get_file_size(file)
        if size is None:
            print(f"Error: Unable to determine the size of '{file}'.")
            continue

        if size <= 1024*1024:  # Regular file
            with open(file, 'rb') as f:
                while True:
                    data = f.read(1024*1024)
                    if not data:
                        break
                    md5.update(data)
        else:  # File larger than 2GB, divide into segments
            for i in range(segments_size):
                offset = i * (1024*1024)
                with open(file, 'rb') as f:
                    chunk = f.read(offset + 1024*1024) if offset + 1024*1024 <= size else f.read(size % (1024*1024))
                    md5.update(chunk)

        hexdigest = md5.hexdigest()
    return hexdigest

if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="Recursively calculate MD5 hashes of a directory structure.")
    parser.add_argument("dir", help="The directory to hash.")
    parser.add_argument("--overwrite", action='store_true', help="Overwrite existing directories if their hashes change.")
    args = parser.parse_args()

    result = hash_directory(args.dir, overwrite=args.overwrite)

    if isinstance(result, bool):
        print("Error occurred while processing the directory.")
    else:
        for dir_path, hexdigest in sorted(result.items()):
            print(f"{dir_path}: {hexdigest}")
