import os
import sys
import time
import hashlib
from threading import Thread

def sha256_hash(directory, overwrite=True):
    if os.path.exists(directory) and overwrite:
        shred = {}
    else:
        return False

    file_queue = [(os.path.join(directory, file), open(file, 'rb')) for file in os.listdir(directory) if not file.startswith('.')]

    def hash_file(file_path, chunk_size=2**20):
        hash_obj = hashlib.sha256()
        file_size = os.path.getsize(file_path)
        segment_count = 1 + (file_size // chunk_size) if file_size % chunk_size == 0 else 1 + (file_size // chunk_size)
        start_time = time.time()

        for i in range(segment_count):
            chunk = file_path.seek(i * chunk_size, os.SEEK_SET), min(chunk_size, file_size - i * chunk_size)
            file_path.read(*chunk)
            hash_obj.update(file_path.read(chunk[1]))

        processing_time = time.time() - start_time
        file_size /= (1024 ** 2)  # convert bytes to MB

        return {'size': file_size, 'segment_count': segment_count, 'processing_time': processing_time, 'hash': hash_obj.hexdigest()}

    processed_files = []
    thread_pool = []

    def process_thread(queue):
        while queue:
            file_path, file_handle = queue.pop()
            try:
                result = hash_file(file_path, chunk_size=2**20)
                shred[file_path] = result['hash']
                processed_files.append(result)
            except Exception as e:
                print(f"Error processing file {file_path}: {e}")

            for thread in thread_pool:
                if not thread.is_alive():
                    queue.put((file_path, file_handle))
                    break

        for thread in thread_pool:
            thread.join()

    while file_queue:
        if not thread_pool or not any(thread.is_alive() for thread in thread_pool):
            new_thread = Thread(target=process_thread, args=(file_queue,))
            thread_pool.append(new_thread)
            new_thread.start()

    report = {'files': processed_files, 'directory': {os.path.basename(directory): shred[os.path.join(directory, os.path.basename(directory))]}}

    if overwrite:
        for subdir, dirs, files in os.walk(directory):
            for file in files:
                os.remove(os.path.join(subdir, file))
            for dir in dirs:
                os.rmdir(os.path.join(subdir, dir))
        shred = {directory: shred[directory]}

    return shred
```

