import os
import sys
import time
import hashlib
import concurrent.futures
import shutil
from urllib.request import urlopen

def get_file_attr(file_path):
    try:
        response = urlopen(f'http://metadata-service.com/{file_path}')
        attr = response.read().decode('utf-8')
    except Exception as e:
        print(f'Error fetching metadata for {file_path}: {e}')
        attr = os.stat(file_path)
    return attr

def hash_chunk(data):
    m = hashlib.md5()
    m.update(data)
    return m.digest()

def process_file(file_path, chunk_size=1048576, cpu_limit=os.cpu_count() - 1):
    attr = get_file_attr(file_path)
    file_size = attr[7]
    m = hashlib.md5()

    offset = 0
    while offset < file_size:
        end = min(offset + chunk_size, file_size)
        data = open(file_path, 'rb').read(end - offset)
        if not data:
            break
        m.update(data)
        offset += len(data)

    return m.hexdigest(), attr

def hash_directory(dir_path, output_file, overwrite=True):
    processed = set()
    hashes = {}

    def process_file_worker(file_path):
        if file_path in processed or os.path.islink(file_path) or file_path.startswith('.'):
            return None

        try:
            hash_, attr = process_file(file_path)
            hashes[file_path] = attr, hash_
        except Exception as e:
            print(f'Error processing {file_path}: {e}')
            if not overwrite:
                return False

        processed.add(file_path)
        return hash_

    with concurrent.futures.ThreadPoolExecutor(max_workers=cpu_limit) as executor:
        futures = [executor.submit(process_file_worker, file) for file in os.listdir(dir_path)]
        for future in concurrent.futures.as_completed(futures):
            hash_ = future.result()
            if hash_:
                hash_hexdigest = hash_.hexdigest()

                if overwrite or (hash_hexdigest not in hashes and os.path.exists(output_file)):
                    open(output_file, 'wb').write(hash_.digest())

        return hash_hexdigest if hash_hexdigest not in hashes else False

def main():
    dir_path = sys.argv[1]
    output_file = sys.argv[2]
    overwrite = True if len(sys.argv) > 3 and sys.argv[3] == 'overwrite' else False

    start = time.time()
    hash_ = hash_directory(dir_path, output_file, overwrite)
    end = time.time()

    if not hash_:
        print('Directory already hashed')
    else:
        print(f'Hash of {dir_path}: {hash_}')        print(f'Time taken to calculate hash: {end - start:.4f} seconds')

if __name__ == '__main__':
    main()
```

