import os
import sys
import hashlib
import shutil
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
import zipfile
import requests
from urllib.parse import urljoin
import tempfile
import logging

# Custom configuration for logging
LOGGING_CONFIG = {
    'version': 1,
    'formatters': {'verbose': {'format': '[%(asctime)s] [%(levelname)s] %(message)s'},
                   'simple': {'format': '[%(levelname)s] %(message)s'}},
    'handlers': {'console': {'class': 'logging.StreamHandler', 'formatter': 'simple', 'stream': 'ext://sys.stdout'},
                'file': {'class': 'logging.FileHandler', 'formatter': 'verbose', 'filename': 'backup.log', 'mode': 'w'}},
    'root': {'handlers': ['console', 'file'], 'level': 'INFO'},
}

def setup_logger(config=LOGGING_CONFIG):
    logging.basicConfig(**config)

def get_checksum(filepath, chunk_size=100 * (2 ** 20), sha256=hashlib.sha256()):
    with open(filepath, 'rb') as f:
        for _ in iter(lambda: f.read(chunk_size), b''):
            sha256.update(_)
    return sha256.hexdigest()

def calculate_checksum(directory, db_service_url, local_db_checksum_file, config=LOGGING_CONFIG, overwrite=True):
    setup_logger(config)

    def handle_files(path):
        if not os.path.isdir(path):
            if path.endswith('/'):
                logging.info(f'Skipping directory: {path} (empty)')
            elif path.startswith('.'):
                logging.debug(f'Skipping hidden file or symbolic link: {path}')
            else:
                if os.path.islink(path):
                    logging.info(f'Skipping symbolic link: {path}')
                elif not os.path.exists(path):
                    logging.debug(f'File does not exist: {path}')
                else:
                    logging.info(f'Calculating checksum for file: {path}')
                    return get_checksum(path)
        elif path.endswith('/'):
            logging.debug(f'Directory found: {path}')
            files = [os.path.join(path, f) for f in os.listdir(path) if not f.startswith('.')]
            checksums = list(map(handle_files, files))
        else:
            raise ValueError('Invalid path type')

        return checksums

    def chunked_files(directory):
        filepaths = []
        for root, dirs, files in os.walk(directory):
            for file in files:
                filepath = os.path.join(root, file)
                if os.path.getsize(filepath) > (2 ** 37):  # 1GB
                    segments = [os.path.join(root, f'{file}.part_{i}') for i in range(1, int((os.path.getsize(filepath) // chunk_size) + 1))]
                    for part in segments:
                        if not os.path.exists(part):
                            with open(part, 'wb') as f:
                                with open(filepath, 'rb') as z:
                                    while True:
                                        data = z.read(chunk_size)
                                        if not data:
                                            break
                                        f.write(data)
                        filepaths.append(part)
        return filepaths

    def fetch_db_metadata(service_url):
        try:
            response = requests.get(service_url)
            response.raise_for_status()
        except requests.exceptions.RequestException as e:
            logging.error(f'Failed to fetch database metadata from {service_url}. Retrying in 2^n seconds...')
            time.sleep(2 ** (attempt + 1))
            if attempt < 5:
                return fetch_db_metadata(service_url)
            else:
                logging.error('Gave up retrying to fetch database metadata from the service.')
                raise e

        return response.json()

    def parallel_checksum_computation(filepaths, cpu_limit):
        with ThreadPoolExecutor(max_workers=cpu_limit) as executor:
            checksums = list(executor.map(get_checksum, filepaths))
        return checksums

    def compare_and_process(local_checksums, remote_checksums):
        processed_files = {}

        for local, remote in zip(local_checksums, remote_checksums):
            if local == remote:
                logging.info(f'File checksum matches: {local}')
                processed_files[local] = True
            else:
                logging.info(f'File needs to be updated or restored: {local}')
                processed_files[local] = False

        return processed_files, len(processed_files) == len(local_checksums)

    def handle_backup(directory, db_service_url):
        filepaths = chunked_files(directory)
        local_checksums = handle_files(directory)

        cpu_limit = max(1, min(os.cpu_count(), 8))
        remote_checksums = parallel_checksum_computation([db_service_url + f'/tables/{file}' for file in filepaths], cpu_limit)

        processed_files, consistency_status = compare_and_process(local_checksums, remote_checksums)

        if overwrite or not consistency_status:
            logging.info('Starting backup process...')
            with zipfile.ZipFile(os.path.join(directory, 'backup.zip'), mode='w', compression=zipfile.ZIP_DEFLATED) as zf:
                for filepath in filepaths:
                    if not processed_files[hashlib.sha256(open(filepath, 'rb').read()).hexdigest()]:
                        logging.info(f'Adding file to backup: {filepath}')
                        zf.write(filepath)
            shutil.move(os.path.join(directory, 'backup.zip'), os.path.join(directory, 'backup_latest.zip'))

        return consistency_status

    db_metadata = fetch_db_metadata(db_service_url)
    if db_metadata:
        consistency_status = handle_backup(directory, db_service_url)
    else:
        logging.warning('Unable to reach the database service. Falling back to local metadata...')
        try:
            with open(local_db_checksum_file) as f:
                local_metadata = json.load(f)
        except FileNotFoundError:
            logging.error('Local metadata file does not exist. Unable to continue.')
            sys.exit(1)

        consistency_status = handle_backup(directory, '')

    return consistency_status
```

