class DynamicDataProcessor {
private:
    struct Record {
        float value;
        std::string text;
    };

    boost::mutex dataMutex;
    std::vector<Record> records;
    int dataProtocolVersion = 1;
    boost::random::mt19937 rng;

    void handleConnection(boost::asio::ip::tcp::Socket& socket) {
        // Implement network communication logic here
    }

    float calculateStandardDeviation() const {
        if (records.empty()) return 0.0f;

        float mean = std::accumulate(records.begin(), records.end(), 0.0f,
                                     [](float sum, const Record& r) { return sum + r.value; }) / records.size();
        float squareDifferenceSum = 0.0f;

        for (const auto& r : records)
            squareDifferenceSum += std::pow(r.value - mean, 2);

        return std::sqrt(squareDifferenceSum / records.size());
    }

    boost::optional<boost::uuids::uuid> generateUuid() const {
        try {
            return boost::uuids::uuid();
        } catch (const std::exception& e) {
            // Handle exception if necessary
            return boost::none;
        }
    }

    float generateRandomFloat(float min, float max, bool inclusive) const {
        boost::random::uniform_real<double> distribution(min, max);
        if (inclusive)
            return static_cast<float>(distribution(rng));
        else
            return std::max(std::min(static_cast<float>(distribution(rng)), max), min);
    }

    int generateRandomInt(int min, int max, bool inclusive) const {
        boost::random::uniform_int_distribution<> distribution(min, max);
        if (inclusive)
            return distribution(rng);
        else
            return std::max(std::min(distribution(rng), max), min);
    }

public:
    void readDataFromNetwork(boost::asio::ip::tcp::Socket& socket) {
        // Implement data reading from network logic here, using handleConnection as a helper function
    }

    float processData() {
        boost::lock_guard<boost::mutex> lock(dataMutex);
        if (records.empty()) return 0.0f;

        float stdDev = calculateStandardDeviation();

        records.clear();
        return stdDev;
    }

    void setDataProtocolVersion(int version) {
        dataProtocolVersion = version;
    }

    boost::optional<boost::uuids::uuid> generateUuid() const {
        return generateUuid();
    }

    float generateRandomFloat(float min, float max, bool inclusive = true) const {
        return generateRandomFloat(min, max, inclusive);
    }

    int generateRandomInt(int min, int max, bool inclusive = true) const {
        return generateRandomInt(min, max, inclusive);
    }
};
