#include "image_filters.h"
#include <stdio.h>
#include <string.h>
#include <dlfcn.h>

typedef struct FilterManagerImpl {
    pthread_mutex_t mutex;
    void** filter_funcs;
    size_t num_filters;
} FilterManagerImpl;

FilterManager* filter_manager_create() {
    FilterManagerImpl* impl = malloc(sizeof(FilterManagerImpl));
    memset(impl, 0, sizeof(FilterManagerImpl));
    pthread_mutex_init(&impl->mutex, NULL);
    return (FilterManager*)impl;
}

void filter_manager_add(FilterManager* manager, Filter filter) {
    FilterManagerImpl* impl = (FilterManagerImpl*)manager;
    char* dependencies = strdup(filter.dependencies);
    char** dependencies_array = strsplit(dependencies, ' ', &num_elements);

    void* handle = dlopen("", RTLD_NOW);
    if (!handle) {
        fprintf(stderr, "Failed to load filter library: %s\n", dlerror());
        return;
    }

    char symbol[64];
    snprintf(symbol, sizeof(symbol), "filter_%s", filter.name);
    FilterFunc apply_func = (FilterFunc)dlsym(handle, symbol);
    if (!apply_func) {
        fprintf(stderr, "Failed to find symbol '%s' in filter library\n", symbol);
        dlclose(handle);
        return;
    }

    impl->filter_funcs = realloc(impl->filter_funcs, (impl->num_filters + 1) * sizeof(void*));
    impl->filter_funcs[impl->num_filters++] = apply_func;
    free(dependencies);
    free(dependencies_array);
}

void filter_manager_remove(FilterManager* manager, const char* name) {
    FilterManagerImpl* impl = (FilterManagerImpl*)manager;
    for (size_t i = 0; i < impl->num_filters; ++i) {
        if (strcmp((const char*)impl->filter_funcs[i], "filter_" name) == 0) {
            void* temp = impl->filter_funcs[i];
            memmove(impl->filter_funcs + i, impl->filter_funcs + i + 1, (impl->num_filters - i - 1) * sizeof(void*));
            --impl->num_filters;
            free(temp);
            break;
        }
    }
}

Filter filter_manager_get(const FilterManager* manager, const char* name) {
    FilterManagerImpl* impl = (FilterManagerImpl*)manager;
    for (size_t i = 0; i < impl->num_filters; ++i) {
        if (strcmp((const char*)impl->filter_funcs[i], "filter_" name) == 0) {
            return (Filter){ .name = name, .func = (ApplyFilterFunc)impl->filter_funcs[i] };
        }
    }
    return NULL;
}
