    private static final Logger LOGGER = LoggerFactory.getLogger(CustomDataHandler.class);
    private String currentDataFormat;
    private ConcurrentHashMap<String, GenericData.TypeReporter> formatTransformers;
    private int batchSize;
    private long maxBatchId;
    private ExecutorService executor;
    private SpecificAvroSerDe serDe;
