    public void initialize(int batchSize, String dataFormat, SpecificAvroSerDe serDe) {
        this.batchSize = batchSize;
        this.currentDataFormat = dataFormat;
        this.formatTransformers = new ConcurrentHashMap<>();
        this.serDe = serDe;
        this.kafkaSerializer = new KafkaAvroSerializer<>(this.serDe);
        this.executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

