namespace StreamProcessor
{
    public class DataPoint
    {
        public DateTime Timestamp { get; set; }
        public object Value { get; set; }
    }

    public class StreamProcessor
    {
        private readonly ConcurrentQueue<Task> _tasks = new ConcurrentQueue<Task>();
        private readonly ConcurrentDictionary<string, Func<StreamReader, IEnumerable<DataPoint>>> _parsers = new ConcurrentDictionary<string, Func<StreamReader, IEnumerable<DataPoint>>>();

        public StreamProcessor()
        {
            _parsers["json"] = CreateJsonParser;
            _parsers["csv"] = CreateCsvParser;
            _parsers["bin"] = CreateBinParser;
        }

        private Func<StreamReader, IEnumerable<DataPoint>> CreateJsonParser() => reader =>
        {
            var jsonReader = new JsonTextReader(reader);
            var dataPoints = new List<DataPoint>();
            while (jsonReader.Read())
            {
                if (jsonReader.TokenType == JsonToken.StartObject)
                {
                    var dp = new DataPoint();
                    jsonReader.Read(); // timestamp
                    dp.Timestamp = DateTime.Parse(jsonReader.Value.ToString());
                    jsonReader.Read(); // value
                    dp.Value = JsonConvert.DeserializeObject(jsonReader.Value.ToString(), typeof(object));
                    dataPoints.Add(dp);
                }
            }
            return dataPoints;
        };

        private Func<StreamReader, IEnumerable<DataPoint>> CreateCsvParser() => reader =>
        {
            var csv = new CsvReader(reader, CultureInfo.InvariantCulture);
            var dataPoints = new List<DataPoint>();
            while (csv.Read())
            {
                dataPoints.Add(new DataPoint { Timestamp = DateTime.Parse(csv.GetField<string>(0)), Value = csv.GetField<object>(1) });
            }
            return dataPoints;
        };

        private Func<StreamReader, IEnumerable<DataPoint>> CreateBinParser() => reader =>
        {
            // Implement binary stream parsing logic here
            throw new NotImplementedException();
        };

        public async Task Process(Stream inputStream, string format, Action<IEnumerable<DataPoint>> onData)
        {
            using (var reader = new StreamReader(inputStream))
            {
                var parser = _parsers[format];
                var dataPoints = await Task.Run(() => parser(reader));
                onData(dataPoints);
            }
        }

        public void Start()
        {
            Task.Factory.StartNew(() =>
            {
                while (_tasks.TryDequeue(out var task))
                {
                    if (task.Status != TaskStatus.RanToCompletion)
                    {
                        _tasks.Enqueue(task);
                    }
                }
            });
        }

        public void AddTask(Func<Stream, Stream, TimeSpan> mergeFunction, Func<Stream, string> formatFunc, Action<IEnumerable<DataPoint>> onData)
        {
            var mergedStream = new MergedStream(mergeFunction, formatFunc);
            _tasks.Enqueue(Task.Run(() => Process(mergedStream, "mixed", onData)));
        }
    }
}
