from zipfile import ZipFile

class SHA256Checksummer:
    def __init__(self, config):
        self.config = config
        self.cpu_limit = int(config.get('cpu_limit', 1))
        self.log_level = config.get('log_level', 'info').upper()
        self.database_url = config.get('database_url')
        self.backup_dir = config.get('backup_dir')
        self.overwrite = bool(config.get('overwrite', True))
        self.checksum_cache = {}
        self.retry_delay = int(config.get('retry_delay', 1000))

    def _log(self, msg):
        if self.log_level <= 'DEBUG':
            print(msg)

    def _fetch_schema(self):
        try:
            with urlopen(self.database_url + '/schema') as response:
                return response.read()
        except Exception as e:
            self._log(f'Error fetching schema ({e}): retrying...')
            time.sleep(self.retry_delay)
            return self._fetch_schema()

    def _get_checksum(self, filepath, chunk_size=100 * (2 ** 20)):
        if os.path.exists(filepath) and os.path.isfile(filepath):
            if filepath in self.checksum_cache:
                return self.checksum_cache[filepath]

            sha = hashlib.sha256()

            with open(filepath, 'rb') as f:
                while True:
                    data = f.read(chunk_size)
                    if not data:
                        break
                    sha.update(data)

            self.checksum_cache[filepath] = sha.hexdigest()
            return sha.hexdigest()

        return False

    def _process_file(self, filepath):
        if not os.path.exists(filepath):
            self._log(f'Skipping non-existent file: {filepath}')
            return 0
        elif os.path.islink(filepath):
            self._log(f'Skipping symbolic link: {filepath}')
            return 0
        elif filepath.startswith('.'):
            self._log(f'Skipping hidden file: {filepath}')
            return 0

        checksum = self._get_checksum(filepath)
        if checksum:
            if self.overwrite or checksum != self.checksum_cache.get(filepath, None):
                self._log(f'Processing file: {filepath}')
                return 1
            else:
                self._log(f'File unchanged: {filepath}')
                return 0
        else:
            self._log(f'Calculating checksum for: {filepath}')
            return 1

    def _process_directory(self, dirpath):
        if not os.path.exists(dirpath) or not os.path.isdir(dirpath):
            return 0

        count = 0
        for root, _, files in sorted(os.walk(dirpath), key=lambda x: len(x[2])):
            for file in files:
                full_path = os.path.join(root, file)
                count += self._process_file(full_path)

        return count

    def checksum_backup(self):
        start_time = time.time()
        with ThreadPoolExecutor(max_workers=self.cpu_limit) as executor:
            futures = [executor.submit(self._process_directory, path) for path in sorted(os.listdir(self.backup_dir), key=lambda x: len(x)) if not x.startswest with as_completed(futures):
                for future in futures:
                    result = future.result()
                    if result:
                        count += result

        schema = self._fetch_schema()
        end_time = time.time()

        if count > 0:
            backup_checksum = hashlib.sha256(open(os.path.join(self.backup_dir, 'backup.bin'), 'rb').read()).hexdigest()
            self.checksum_cache.clear()
            return backup_checksum
        else:
            self._log('Backup checksum calculation completed without changes')
            return False
```

