#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdio.h>
#include <semaphore.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom allocator for efficient memory usage and reduced fragmentation
typedef struct MemoryPool {
    void *start;
    void *end;
    size_t blockSize;
    size_t count;
} MemoryPool;

void* mempool_alloc(MemoryPool *mp) {
    if (mp->count > 0) {
        mp->count--;
        return (char *)mp->start + mp->blockSize * mp->count;
    } else {
        void *new_start = mp->end;
        size_t new_size = ((char *)mp->end - (char *)mp->start) * 2;
        mp->start = new_start;
        mp->end = (char *)realloc(new_start, new_size);
        mp->blockSize = new_size / mp->count + 1;
        return mp->start + mp->blockSize * mp->count++;
    }
}

void mempool_free(MemoryPool *mp, void *ptr) {
    (void)ptr; // suppress unused warning
    mp->count--;
}

// Thread-safe dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct DynamicArray {
    MemoryPool pool;
    size_t capacity;
    size_t length;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* da_new(size_t initialCapacity) {
    DynamicArray *da = (DynamicArray *)mempool_alloc(&((MemoryPool *)NULL));
    da->capacity = initialCapacity;
    da->length = 0;
    da->data = (NFAPI_CRC_INDICATION_PDU_T *)mempool_alloc(&da->pool);
    da->pool.blockSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    da->pool.count = initialCapacity;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void da_delete(DynamicArray *da) {
    free(da->data);
    mempool_free(&da->pool, da);
    pthread_mutex_destroy(&da->lock);
}

bool da_add(DynamicArray *da, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (da->length == da->capacity) {
        da->capacity *= 2;
        da->data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(da->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * da->capacity);
    }
    pthread_mutex_lock(&da->lock);
    memcpy((void *)&da->data[da->length], (const void *)pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->length++;
    pthread_mutex_unlock(&da->lock);
    return true;
}

bool da_remove_by_rnti(DynamicArray *da, uint16_t rnti) {
    size_t i;
    bool found = false;
    pthread_mutex_lock(&da->lock);
    for (i = 0; i < da->length && !found; ++i) {
        if (da->data[i].RNTI == rnti) {
            memmove(&da->data[i], &da->data[i+1], (da->length-i-1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --da->length;
            found = true;
        }
    }
    pthread_mutex_unlock(&da->lock);
    return found;
}

void da_iterate(DynamicArray *da, bool (*updateFunc)(NFAPI_CRC_INDICATION_PDU_T *pdu)) {
    pthread_mutex_lock(&da->lock);
    size_t i;
    for (i = 0; i < da->length; ++i) {
        if (updateFunc(&da->data[i]))
            continue; // break on update success
        if (!pthread_mutex_trylock(&da->data[i].CRCFLAG)) {
            updateFunc(&da->data[i]);
            pthread_mutex_unlock(&da->data[i].CRCFLAG);
        } else {
            sem_t *sem = (sem_t *)mempool_alloc(&((MemoryPool *)NULL));
            if (pthread_mutex_trylock(sem)) {
                sem_wait(sem);
                updateFunc(&da->data[i]);
                sem_post(sem);
                mempool_free((void *)sem, sem);
            } else {
                // handle error situation gracefully
            }
        }
    }
    pthread_mutex_unlock(&da->lock);
}
