typedef struct memory_block {
    Record* data;
    size_t capacity;
    size_t count;
    sem_t mutex;
} MemoryBlock;

MemoryBlock* init_memory_block(size_t capacity) {
    MemoryBlock* block = malloc(sizeof(MemoryBlock));
    if (!block) return NULL;

    block->data = calloc(capacity, sizeof(Record));
    if (!block->data) goto cleanup;

    block->capacity = capacity;
    block->count = 0;
    sem_init(&block->mutex, 0, 1);

    return block;
cleanup:
    free(block);
    return NULL;
}

MemoryBlock* allocate_records(size_t num_records) {
    MemoryBlock* blocks = calloc(num_records, sizeof(MemoryBlock));
    if (!blocks) return NULL;

    for (size_t i = 0; i < num_records; ++i) {
        blocks[i] = init_memory_block(1000);
        if (!blocks[i]) goto cleanup;
    }

    return blocks;
cleanup:
    for (size_t i = 0; i < num_records; ++i) {
        MemoryBlock* block = &blocks[i];
        if (block) free(block);
    }
    free(blocks);
    return NULL;
}

void init_record(Record* record, long offset, int key) {
