int fill_memory_block(MemoryBlock* block) {
    if (!block || !block->data || block->count >= block->capacity) return -1;

    sem_wait(&block->mutex);
    int filled = 0;

    for (size_t i = 0; i < block->capacity && filled < block->capacity; ++i) {
        if (!block->data[i].key) {
            init_record(&block->data[i], i, rand() % 1000); // Modify this to set the key based on your requirements.
            filled++;
        }
    }

    block->count = filled;
    sem_post(&block->mutex);
    return filled;
}

