// Custom memory pool allocator
typedef struct MemPool {
    void *start;
    void *end;
    size_t size;
} MemPool;

MemPool *create_mempool(size_t size) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    MemPool *pool = malloc(sizeof(MemPool));
    pool->start = ptr;
    pool->end = ptr + size;
    pool->size = size;
    return pool;
}

void *mempool_malloc(MemPool *pool, size_t size) {
    if (pool->end - pool->start < size) {
        perror("Out of memory in mempool");
        exit(EXIT_FAILURE);
    }
    void *ptr = pool->start;
    pool->start += size;
    return ptr;
}

void mempool_free(MemPool *pool, void *ptr) {
    if (ptr < pool->start) {
        perror("Invalid memory address in mempool");
        exit(EXIT_FAILURE);
    }
    pool->start = ptr;
}

