    Record *record = mempool_malloc(cache_mempool, sizeof(Record));
    record->value = rand() % MAX_RANDOM_VALUE; // Modify this to set the value range
    return record;
}

void free_record(Record *record) {
    mempool_free(cache_mempool, record);
}

