typedef struct _CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} CRC_INDICATION_PDU_T;

static CRC_INDICATION_PDU_T* pdu_queue = NULL;
static size_t total_allocated_pdus = 0;
static size_t max_allocated_pdus = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t queue_size = 0;

void allocate_and_populate_PDU(CRC_INDICATION_PDU_T** pdus, size_t n) {
    if (queue_size + n > max_allocated_pdus) {
        return; // Queue incoming structures until space becomes available.
    }

    *pdus = realloc(*pdus, sizeof(CRC_INDICATION_PDU_T) * n);

    for (size_t i = 0; i < n; ++i) {
        // Populate each structure with valid data.
        pdus[i]->ue_information = generate_ue_information();
        pdus[i]->rnti = generate_rnti();
        pdus[i]->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG.
    }

    pthread_mutex_lock(&mutex);
    total_allocated_pdus += n;
    queue_size += n;
    pthread_mutex_unlock(&mutex);
}

CRC_INDICATION_PDU_T* dequeue_PDU() {
    if (queue_size == 0) {
        return NULL; // No more structures available.
    }

    CRC_INDICATION_PDU_T* pdu = pdu_queue;
    pdu_queue = pdu_queue->next;
    queue_size--;

    return pdu;
}

void free_all_PDUs() {
    while (pdu_queue) {
        CRC_INDICATION_PDU_T* temp = pdu_queue;
        pdu_queue = pdu_queue->next;
        free(temp);
    }

    pdu_queue = NULL;
}

size_t get_total_allocated_pdus() {
    pthread_mutex_lock(&mutex);
    size_t count = total_allocated_pdus;
    pthread_mutex_unlock(&mutex);

    return count;
}
