// Define the global variables for tracking the total number of messages and MAX_ALLOCATED_MESSAGES
static atomic_long_t total_messages = 0;
static size_t max_allocated_messages = MAX_ALLOCATED_MESSAGES;
static LTE_RRC_CU_MESSAGE *message_list = NULL;
static pthread_mutex_t message_list_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t queue_not_full = PTHREAD_COND_INITIALIZER;

void lte_rrc_cu_message_queue(LTE_RRC_CU_MESSAGE *msg) {
    pthread_mutex_lock(&message_list_lock);

    // If message queue is full, wait for a free slot to become available
    while (sizeof(message_list) / sizeof(LTE_RRC_CU_MESSAGE) >= max_allocated_messages) {
        pthread_cond_wait(&queue_not_full, &message_list_lock);
    }

    // Add the message to the queue and set its queued status accordingly
    msg->queued = true;
    memcpy(msg, message_list + sizeof(message_list) / sizeof(LTE_RRC_CU_MESSAGE) - 1, sizeof(LTE_RRC_CU_MESSAGE));
    total_messages++;

    pthread_mutex_unlock(&message_list_lock);
}

LTE_RRC_CU_MESSAGE *lte_rrc_cu_message_dequeue() {
    LTE_RRC_CU_MESSAGE *msg;

    pthread_mutex_lock(&message_list_lock);

    // If the message queue is empty, wait for a new message to become available
    while (sizeof(message_list) / sizeof(LTE_RRC_CU_MESSAGE) <= 1) {
        pthread_cond_wait(&queue_not_full, &message_list_lock);
    }

    // Dequeue the first message from the list and update its queued status accordingly
    msg = message_list;
    memmove(msg, msg + 1, sizeof(message_list) / sizeof(LTE_RRC_CU_MESSAGE) - 1);
    total_messages--;

    pthread_mutex_unlock(&message_list_lock);

    // Initialize the queued status of the dequeued message to false
    msg->queued = false;

    return msg;
}

