// Custom dynamic array structure
struct DynamicArray<T> {
    data: Arc<Mutex<VecDeque<T>>>,
}

impl<T> DynamicArray<T> {
    fn new(initial_capacity: usize) -> Self {
        DynamicArray {
            data: Arc::new(Mutex::new(VecDeque::with_capacity(initial_capacity))),
        }
    }
}

impl<T> Index<usize> for DynamicArray<T> {
    type Output = T;

    fn index(&self, index: usize) -> &Self::Output {
        let data = self.data.lock().unwrap();
        data[index]
    }
}

impl<T> IndexMut<usize> for DynamicArray<T> {
    fn index_mut(&mut self, index: usize) -> &mut Self::Output {
        let mut data = self.data.lock().unwrap();
        data[index]
    }
}

impl<T> Extend<T> for DynamicArray<T> {
    fn extend<I: IntoIterator<Item=T>>(&mut self, iter: I) {
        let mut data = self.data.lock().unwrap();
        data.extend(iter);
        // Resize the array if necessary
        if data.len() > data.capacity() {
            let new_capacity = (data.len() + 1) * 2;
            let new_data = Arc::new(Mutex::new(VecDeque::with_capacity(new_capacity)));
            std::mem::swap(&mut self.data, &mut new_data);
        }
    }
}

impl<T> Iterator for DynamicArray<T> {
    type Item = T;

    fn next(&mut self) -> Option<Self::Item> {
        let data = self.data.lock().unwrap();
        data.pop_front()
    }
}

