import os
import xml.etree.ElementTree as ET
import hashlib
import threading
import queue
import requests
from zipfile import ZipFile
import tempfile
import logging
from xml.sax.saxutils import escape

def validate_xml(file_path):
    try:
        tree = ET.parse(file_path)
        tree.validate(ET.XMLSchema(filesystem=True, referencelist=(('schema.xsd', 'schema.xsd'))))
    except ET.ParseError as e:
        return False

    root = tree.getroot()
    for elem in root:
        if elem.tag not in ('settings',):
            return False

    settings = {}
    for setting_elem in root.findall('settings/setting'):
        name = escape(setting_elem.attrib['name'])
        value = escape(setting_elem.text)
        if not value.isnumeric() or (len(value) > 0 and value[0] != '.' and not value.replace('.', '').isnumeric()):
            return False
        settings[name] = float(value) if '.' in value else int(value)

    return settings

def read_file_chunked(file, chunk_size=262144):  # 262144 bytes = 256 MB
    buffer = file.read(chunk_size)
    while buffer:
        yield buffer
        buffer = file.read(chunk_size)

def compute_md5(file, hash=hashlib.md5()):
    for chunk in read_file_chunked(file):
        hash.update(chunk)
    return hash.hexdigest()

def get_settings():
    xml_path = 'config.xml'
    if not os.path.isfile(xml_path):
        logging.error(f"Error: XML file '{xml_path}' not found.")
        raise FileNotFoundError

    settings = validate_xml(xml_path)
    if not settings:
        logging.error("Error: XML file is malformed.")
        raise ValueError

    return settings

def hash_file(file_path, output_dir='.', api_key='', resume=False):
    if not os.path.isfile(file_path):
        logging.error(f"Error: File '{file_path}' does not exist.")
        raise FileNotFoundError

    settings = get_settings()
    tile_size = settings['tile_size']
    world_width = settings['world_width']
    world_height = settings['world_height']
    camera_speed = settings['camera_speed']

    hash_queue = queue.Queue()
    hashes = {}

    def process_hash(hash_obj):
        hash_str, file_path = hash_obj
        if resume and hashes.get(file_path) != hash_str:
            hashes[file_path] = hash_str
            return True
        else:
            logging.info(f"Calculating MD5 for {file_path}")
            hashes[file_path] = compute_md5(open(file_path, 'rb'))
            return False

    threads = []
    chunk_size = tile_size * tile_size

    with ZipFile(file_path, 'r') as z:
        if resume:
            for file in hashes:
                hash_queue.put((hashes[file], file))

        for i in range(0, z.namelength, chunk_size):
            j = min(i + chunk_size, z.namelength)
            files_in_chunk = ziprange(i, j, chunk_size)
            for file in files_in_chunk:
                file_path = z.filename(file)
                hash_queue.put((None, file_path))

    for thread_id, thread in enumerate(threads):
        thread.start()

    while not hash_queue.empty():
        hash_obj = hash_queue.get()
        if process_hash(hash_obj):
            threads[thread_id].join()

    logging.info("All hashes calculated.")

    for file in z.namelist():
        hash_str = hashes.get(file)
        if not hash_str:
            logging.warning(f"Couldn't calculate MD5 for {file}")
            continue

        if api_key:
            response = requests.get(f"https://api.example.com/checkhash?file={hash_str}&key={api_key}")
            if response.ok:
                status, metadata = parse_response(response.json())
            else:
                status = 'error'
                logging.warning(f"API request failed for {file}: {response.reason}")
        else:
            status = 'unverified'

        file_path = os.path.join(output_dir, file)
        with open(file_path, 'wb') as f:
            with z.open(file) as z_f:
                f.write(z_f.read())

        log_entry = {
            "File": file,
            "Status": status,
            "Size": os.path.getsize(file_path),
            "Start Time": datetime.now().isoformat(),
            "End Time": None,
            "Metadata": metadata or {}
        }
        logging.info(f"{log_entry}")

def parse_response(json):
    status = json['status']
    metadata = json.get('metadata', {})
    return status, metadata

if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument("file", help="The file path to hash")
    parser.add_argument("-o", "--output-dir", default='.', help="Custom output directory for temporary files and logs")
    parser.add_argument("-k", "--api-key", help="API key for checking the integrity of the calculated hash")
    args = parser.parse_args()

    resume = False
    if os.path.exists(f"{args.output_dir}/hash_{args.file}.md5"):
        logging.info(f"Resuming hash calculation for {args.file}")
        resume = True

    hash_file(args.file, args.output_dir, args.api_key, resume)
```']

