import os
import json
import hashlib
import zipfile
import concurrent.futures
import aiohttp
from jsonschema import validate, Draft7Validator, ValidationError
import logging
import argparse
from pathlib import Path
from threading import Lock
import zipp
from aiofiles.os import Scandir as AsyncScandir

# JSON Schema validation
JSON_SCHEMA = {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "properties": {
        "compression_level": {"type": "number", "minimum": 1, "maximum": 9},
        "num_threads": {"type": "integer", " minimum": 1},
        "timeout": {"type": "number"},
    },
    "required": ["compression_level", "num_threads", "timeout"]
}

def validate_json(data):
    try:
        validate(instance=data, schema=JSON_SCHEMA)
    except ValidationError as e:
        raise ValueError("Invalid JSON configuration") from e

def sha256hash(path, chunk_size=65536):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            h.update(data)
    return h.hexdigest()

def get_config():
    config_file = Path("config.json")
    if not config_file.exists():
        raise FileNotFoundError("Configuration file not found.")

    with open(config_file, "r") as f:
        data = json.load(f)

    validate_json(data)
    return data

def get_hash(root_path, config):
    lock = Lock()
    processed_files = set()
    hash_obj = hashlib.sha256()

    def process_file(file_path):
        if file_path in processed_files:
            return
        processed_files.add(file_path)

        with open(file_path, "rb") as f:
            while True:
                data = f.read(config["chunk_size"])
                if not data:
                    break
                lock.acquire()
                try:
                    hash_obj.update(data)
                finally:
                    lock.release()

    async def process_directory(directory, thread_id):
        async for entry in AsyncScandir(directory):
            if not entry.is_file():
                await process_directory(entry, thread_id)
            else:
                process_file(entry)

    with zipp.open(root_path, "r") as zfile:
        for member in zfile.inflatemeber_stream().getmembers():
            if member.is_dir():
                async with concurrent.futures.ThreadPoolExecutor(max_workers=config["num_threads"]) as executor:
                    futures = [executor.submit(process_directory, member, thread_id) for _ in range(config["num_threads"])]
                for future in concurrent.futures.as_completed(futures):
                    future.result()
            elif member.is_file():
                process_file(member)

    return hash_obj.hexdigest()

def save_hash(hash, config, output_dir=None):
    if not output_dir:
        output_dir = Path.cwd() / "output"
        if not output_dir.exists():
            os.makedirs(output_dir, exist_ok=True)

    hash_file = output_dir / f"hash_{os.path.basename(root_path)}.json"
    with open(hash_file, "w") as f:
        data = {
            "hash": hash,
            "config": config
        }
        json.dump(data, f, indent=4)

def main():
    parser = argparse.ArgumentParser()
