["```python
import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging
from functools import lru_cache

@lru_cache(maxsize=128)
def md5_hash(filepath):
    with open(filepath, 'rb') as f:
        h = hashlib.md5()
        while chunk := f.read(8192):
            h.update(chunk)
        return h.hexdigest()

def find_files(directory):
    for root, _, files in os.walk(directory):
        for file in files:
            yield os.path.relpath(os.path.join(root, file), directory)

def calculate_md5hashes(directory, max_workers=16):
    logging.basicConfig(level=logging.WARNING)

    pending = list(find_files(directory))
    result = {}
    executor = ThreadPoolExecutor(max_workers=max_workers)

    completed = []

    for file in pending:
        future = executor.submit(md5_hash, os.path.join(directory, file))
        future.add_error_callback(lambda e, f: logging.warning(f'Error processing {file}: {e}'))
        completed.append((file, future))

    for _, future in as_completed(completed):
        try:
            hash_value = future.result()
            result[future.arguments[0]] = hash_value
        except KeyboardInterrupt:
            logging.warning('Keyboard Interrupted. Exiting...')
            break

    executor.shutdown(wait=False)
    return result
```

