import os
import sys
import hashlib
import concurrent.futures
import gzip
import time
from datetime import datetime
import logging

def md5_files(directory, batch_size=10, max_workers=os.cpu_count()*2, retry_limit=3, backoff_factor=2):
    retries = {file: 0 for file in os.listdir(directory)}
    processed = set()
    results = {}
    logger = logging.getLogger(__name__)

    def hash_file(file):
        try:
            with open(os.path.join(directory, file), 'rb') as f:
                if f.name.endswith('.gz'):
                    with gzip.GzipFile(f'rb', f) as zf:
                        md5 = hashlib.md5()
                        for chunk in iter(lambda: zf.read(4096), b''):
                            md5.update(chunk)
                else:
                    md5 = hashlib.md5()
                    for chunk in iter(lambda: f.read(4096), b''):
                        md5.update(chunk)
                return (file, md5.hexdigest())
        except IOError as e:
            if retries[file] < retry_limit:
                logger.warning(f"Failed to hash file {file}: {e}, retrying...", extra={'retry': retries[file]})
                retries[file] += 1
                time.sleep((2 ** retries[file]) * backoff_factor)
                return (file, None)
            else:
                logger.error(f"Gave up on file {file}: {e}")
        finally:
            processed.add(file)

    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = [executor.submit(hash_file, file) for file in sorted(os.listdir(directory)) if file not in processed]
        for _, res in concurrent.futures.as_completed(futures):
            if res is None:
                continue
            results[res[0]] = res[1]
        unhashed = [file for file in os.listdir(directory) if file not in results and file not in retries]
        if unhashed:
            logger.error(f"The following files were skipped due to errors or access issues: {', '.join(unhashed)}")
    return results

def process_files(function, directory, batch_size=10):
    results = {}
    processed = set()

    while True:
        batch = [f for f in os.listdir(directory) if f not in processed and len(results) < batch_size]
        if not batch:
            break
        current_batch = {file: function({'directory': directory, 'batch': batch})[file] for file in batch}
        results.update(current_batch)
        processed.update(current_batch.keys())
    return results

# Set up logging
logging.basicConfig(filename='md5_hasher.log', level=logging.INFO, format='%(asctime)s - %(levelname)s: %(message)s')
