import os
import hashlib
import threading
from concurrent.futures import ThreadPoolExecutor
import gzip
import zipfile
from datetime import timedelta
import logging

class MD5Hasher:
    def __init__(self, retry_limit=3, backoff_factor=2):
        self.retry_limit = retry_limit
        self.backoff_factor = backoff_factor
        self.logger = logging.getLogger(__name__)

    def _md5(self, filepath):
        hasher = hashlib.md5()
        with open(filepath, 'rb') as f:
            while True:
                data = f.read(8192)
                if not data:
                    break
                hasher.update(data)
        return hasher.hexdigest()

    def _process_file(self, filepath):
        try:
            return self._md5(filepath)
        except Exception as e:
            self.logger.error(f"Error processing {filepath}: {e}")
            if self.retry_limit > 0:
                delay = min(timedelta(seconds=self.backoff_factor ** (self.retry_limit - 1)), timedelta(seconds=60))
                return self._process_file(filepath) if self.retry_limit > 1 else None
            else:
                raise e

    def _is_compressed(self, filepath):
        return filepath.lower().endswith(('.gz', '.gzip'))

    def process_directory(self, directory_path):
        hashes = {}
        processed_files = set()

        def process_file(filepath):
            if filepath in processed_files:
                return
            processed_files.add(filepath)

            if self._is_compressed(filepath):
                with gzip.open(filepath, 'rb') as f:
                    hashes[os.path.relpath(filepath, directory_path)] = self._md5(f)
            else:
                hashes[os.path.relpath(filepath, directory_path)] = self._process_file(filepath)

        with ThreadPoolExecutor() as executor:
            for root, _, files in os.walk(directory_path):
                executor.map(process_file, [os.path.join(root, f) for f in files])

        return hashes
