        self.retry_limit = retry_limit
        self.backoff_factor = backoff_factor

    def _hash_file(self, filepath, md5):
        try:
            with open(filepath, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b''):
                    md5.update(chunk)
            return md5.hexdigest()
        except PermissionError:
            self._handle_lock_error(filepath)
        except Exception as e:
            self._handle_exception(filepath, e)

    def _hash_compressed_file(self, filepath, md5):
        try:
            with gzip.open(filepath, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b''):
                    md5.update(chunk)
            return md5.hexdigest()
        except PermissionError:
            self._handle_lock_error(filepath)
        except Exception as e:
            self._handle_exception(filepath, e)

    def _hash_encrypted_file(self, filepath, key, iv, md5):
        try:
            with aes.AESFileOpenMode(filepath, 'rb', key=key, iv=iv) as f:
                for chunk in iter(lambda: f.read(4096), b''):
                    md5.update(chunk)
            return md5.hexdigest()
        except PermissionError:
            self._handle_lock_error(filepath)
        except Exception as e:
            self._handle_exception(filepath, e)

    def _hash_zip_entry(self, zip_file, entry, md5):
        with zip_file.open(entry) as f:
            for chunk in iter(lambda: f.read(4096), b''):
                md5.update(chunk)

    def _handle_lock_error(self, filepath):
        logging.warning(f"File {filepath} is locked or inaccessible.")

    def _handle_exception(self, filepath, exception):
        retry = self.retry_limit - 1
        sleep_time = 2**self.backoff_factor * (1 << retry) if retry else 0
        logging.error(f"Error processing file {filepath}: {exception}")
        if retry > 0:
            sleep(sleep_time)
            raise exception

def calculate_md5_hashes(directory, key=None, iv=None):
    md5 = hashlib.md5()
    results = {}
    executor = ThreadPoolExecutor(max_workers=os.cpu_count() * 2)

    def process_file(filepath):
        file_name, extension = os.path.splitext(filepath)
        if not extension:
            return None

        if extension in ('.gz', '.zip'):
            worker = _hash_compressed_file if extension == '.gz' else _hash_zip_entry
        elif key and iv:
            worker = _hash_encrypted_file
        else:
            worker = _hash_file

        return {file_name + extension: worker(filepath, md5)}

    for root, dirs, files in os.walk(directory):
        for file in files:
            full_filepath = os.path.join(root, file)
            results.update(process_file(full_filepath))

    return {k: v[0] for k, v in sorted(results.items(), key=lambda x: len(x[1]))}
