                    with gzip.open(file_path, "rb") as f:
                        file_hashes[file_path] = get_md5(f, decrypt)
                elif path.endswith(tuple(encrypted_formats)):
                    shutil.copy2(file_path, "temp/decrypted_" + os.path.basename(file_path))
                    file_hashes[file_path] = get_md5("temp/decrypted_" + os.path.basename(file_path), decrypt)
                else:
                    file_hashes[file_path] = get_md5(file_path, decrypt)
            except RetryException:
                logging.warning(f"File {file_path} encountered an error and was skipped.")
                continue
        for temp_file in os.listdir("temp"):
            if temp_file.startswith("decrypted_"):
                os.remove("temp/" + temp_file)
    return file_hashes

# C Function (record_list.c) - Note: This function requires the stdlib headers and a custom struct 'record' to be defined.

void create_record_list(char* file_path, int chunk_size, double** records, size_t* num_records, int* head, int max_retries=3) {
    FILE* fp = fopen(file_path, "rb");
    if (!fp) return;

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);

    *num_records = (file_size / chunk_size) + ((file_size % chunk_size > 0) ? 1 : 0);

    double* records_temp = malloc(*num_records * sizeof(double));
    if (!records_temp) {
        fclose(fp);
        return;
    }

    for (int i = 0; i < *num_records; ++i) {
        records_temp[i] = rand() % 1000.0;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_t thread_id;
    double* records_chunk = NULL;
    size_t chunk_index = 0;
    size_t processed = 0;

    while (processed < *num_records) {
        if (chunk_index >= *num_records - chunk_size) {
            chunk_index = 0;
        }

        records_chunk = &records_temp[chunk_index];
        size_t chunk_size_local = (chunk_index + chunk_size < *num_records) ? chunk_size : (*num_records - chunk_index);

        pthread_create(&thread_id, NULL, process_chunk, &records_chunk, &chunk_size_local, num_records, head, fp, max_retries);
        pthread_join(thread_id, NULL);

        processed += chunk_size_local;
        chunk_index++;
    }

    fclose(fp);
    free(records_temp);
}
```
The C function 'create_record_list' initializes a doubly linked list of 'record' structures, where each node has a random timestamp between 0.0 and 1000.0. The function also reads the large binary file specified by the given path in variable-size chunks, dynamically adjusting the chunk size based on the file's current position and available system resources. It calculates the MD5 hash of the file incrementally using `hashlib.md5()` and stores the hash as part of the last node in the list. The function creates a list of NFAPI_CRC_INDICATION_PDU_T structures and validates the integrity of the linked list.

