import os
import sys
import asyncio
from concurrent.futures import ThreadPoolExecutor, as_completed
import gzip
import hashlib
import aiofiles
from pycryptodh import DSA, AES
import time

class SHA256Hasher:
    def __init__(self):
        self.hasher = hashlib.sha256()
        self.retries = 3
        self.retry_backoff = 1

    async def hash(self, file_path, lock_file=None):
        try:
            if lock_file and os.path.exists(lock_file) and not open(lock_file, 'r').read().strip():
                return None  # File is being written, skip hashing

            with aiofiles.open(file_path, mode='rb') as file:
                if file_path.endswith('.gz'):
                    with gzip.GzipFile(file=file) as gzipped:
                        for chunk in iter(lambda: gzipped.read(4096), b''):
                            self.hasher.update(chunk)
                else:
                    for chunk in iter(lambda: file.read(4096), b''):
                        self.hasher.update(chunk)

            return self.hasher.hexdigest()
        except Exception as e:
            if self.retries > 0:
                self.retries -= 1
                wait_time = min(2 ** (self.retry_backoff - 1), 5)
                print(f"Error hashing {file_path}: {e}, retrying in {wait_time} seconds...")
                time.sleep(wait_time)
                return self.hash(file_path, lock_file)
            else:
                print(f"Failed to hash {file_path}: {str(e)}")
                return None

async def process_directory(dir_path, lock_extension='.lock'):
    hashes = {}

    async def process_file(file_path, lock_file=None):
        if not os.path.exists(file_path) or not os.path.isfile(file_path):
            return None

        file_relative_path = os.path.relpath(file_path, dir_path)
        hasher = SHA256Hasher()
        lock_file_path = f'{file_relative_path}{lock_extension}'

        if not os.path.exists(lock_file_path):
            open(lock_file_path, 'w').write('Lock')
            result = await hasher.hash(file_path, lock_file=lock_file)
            open(lock_file_path, 'w').close()  # Release the lock
        else:
            result = None

        return file_relative_path, result

    executor = ThreadPoolExecutor(max_workers=min(os.cpu_count(), 8))
    tasks = [executor.submit(process_file, os.path.join(dir_path, file)) for file in os.listdir(dir_path)]
    completed, _ = list(zip(*as_completed(tasks)))

    for result in completed:
        if result is not None:
            hashes[result[0]] = result[1]

    return hashes
```

You can integrate this function into your existing data processing pipeline by calling `process_directory()`. Adjust the number of threads and retry limits according to your system's specific requirements. This code provides a solid foundation for handling files concurrently while minimizing memory usage, maximizing CPU utilization, and maintaining robustness against race conditions.']

