#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>
#include <semaphore.h>
#include <atomic>

struct CRC_INDICATION_PDU {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    std::atomic<bool> CRCFLAG{false};
};

class DynamicArray {
private:
    size_t capacity_;
    size_t size_;
    struct CRC_INDICATION_PDU** data_;
    pthread_mutex_t mutex_;
    sem_t semaphore_;

public:
    DynamicArray() : capacity_(1024), size_(0), data_(nullptr), mutex_(), semaphore_(sem_init(0, 0, 1)) {}

    ~DynamicArray() {
        for (size_t i = 0; i < capacity_; ++i) {
            free(data_[i]);
        }
        free(data_);
        sem_destroy(&semaphore_);
    }

    void resize() {
        if (capacity_ * 2 >= size_) {
            capacity_ *= 2;
        } else {
            capacity_ = size_ * 2;
        }

        struct CRC_INDICATION_PDU** newData = (struct CRC_INDICATION_PDU**)realloc(data_, sizeof(struct CRC_INDICATION_PDU*) * capacity_);
        if (!newData) {
            // Handle memory allocation failure
        }

        data_ = newData;
    }

    void addElement(const struct CRC_INDICATION_PDU& element) {
        sem_wait(&semaphore_);

        if (size_ == capacity_) {
            resize();
        }

        data_[size_++] = (struct CRC_INDICATION_PDU*)malloc(sizeof(struct CRC_INDICATION_PDU));
        if (!data_[size_ - 1]) {
            // Handle memory allocation failure
        }

        std::memcpy(data_[size_ - 1], &element, sizeof(struct CRC_INDICATION_PDU));

        pthread_mutex_unlock(&mutex_);
    }

    struct CRC_INDICATION_PDU* findElementByRNTI(uint32_t rnti) {
        pthread_mutex_lock(&mutex_);

        for (size_t i = 0; i < size_; ++i) {
            if (data_[i]->RNTI == rnti) {
                break;
            }
            if (i + 1 == size_) {
                continue; // Not found
            }
        }

        pthread_mutex_unlock(&mutex_);
        return data_[...]; // Return the found element's pointer or NULL if not found
    }

    void updateCRCFlag(uint32_t rnti, bool value) {
        struct CRC_INDICATION_PDU* element = findElementByRNTI(rnti);
        if (element) {
            element->CRCFLAG.store(value, std::memory_order_relaxed);
        }
    }
};
```

