    auth.records = malloc(MAX_RECORDS * sizeof(Record));
    auth.mutex = PTHREAD_MUTEX_INITIALIZER;
    auth.file_pointers = malloc(MAX_RECORDS * sizeof(FILE*));
    memset(auth.records, 0, MAX_RECORDS * sizeof(Record));
    memset(auth.file_pointers, 0, MAX_RECORDS * sizeof(FILE*));
    auth.num_records = 0;
    auth.current_record = -1;
    return auth;
}

void update_session(Authenticator* auth, int key) {
    pthread_mutex_lock(&auth->mutex);
    if (auth->current_record < MAX_RECORDS && auth->num_records != MAX_RECORDS) {
        Record* record = &auth->records[auth->num_records];
        record->key = key;
        time(&record->last_active);
        record->language[0] = 'en'; // Default language setting
        auth->num_records++;
        auth->current_record++;
    }
    pthread_mutex_unlock(&auth->mutex);
}

Record* get_session(Authenticator* auth, int key) {
    Record* result = NULL;
    pthread_mutex_lock(&auth->mutex);
    for (int i = 0; i < auth->num_records; ++i) {
        if (auth->records[i].key == key) {
            result = &auth->records[i];
            break;
        }
    }
    pthread_mutex_unlock(&auth->mutex);
    return result;
}

