import os
import hashlib
import cryptography
from cryptography.fernet import Fernet
import logging
import time
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed

# Set up logging
logging.basicConfig(filename='file_processing.log', level=logging.INFO)

def is_skip_ext(file):
    """Check if file extension should be skipped."""
    return file.lower().endswith(('zip', 'exe'))

def chunker(seq, size):
    """Yield successive chunks from the input sequence."""
    for i in range(0, len(seq), size):
        yield seq[i:i + size]

def md5_hash(filepath):
    """Calculate MD5 hash of file in chunks."""
    with open(filepath, 'rb') as f:
        h = hashlib.md5()
        for chunk in chunker(f.read(), 65536):
            h.update(chunk)
        return h.hexdigest()

def process_file(filepath, chunk_size, aes_key, camellia_key):
    """Process single file using given parameters."""
    h = hashlib.md5()

    with open(filepath, 'rb') as f:
        for chunk in chunker(f.read(), chunk_size):
            h.update(chunk)
            time.sleep(0.1)  # Simulate resource-intensive task
            logging.info(f'Processing {filepath} - Chunk #{len(h.digest())//chunk_size}')

    if os.path.islink(filepath):
        target = os.readlink(filepath)
        logging.info(f'Symbolic link found: {filepath} -> {target}')
        return process_file(target, chunk_size, aes_key, camellia_key)
    elif any([os.path.samefile(filepath, parent) for parent in sys.path]):
        # Handle case where file is on system path (e.g., python scripts)
        return process_file(os.path.realpath(filepath), chunk_size, aes_key, camellia_key)

def process_directory(dirpath, max_chunk_size, skip_extensions=('zip', 'exe'), log_aes_key=True, log_camellia_key=False):
    """Process given directory."""
    f = Fernet(AES_KEY) if log_aes_key else None
    c = cryptography.cipher.Cipher(cryptography.algorithms.Camellia(keysize=256), cryptography.padding.OAEP(mgf=cryptography.hazmat.primitives.asymmetric.rsa.RSAGeneratorBase.hashes.SHA256())) if log_camellia_key else None
    processed_files = set()

    def process_file_with_context(filepath):
        if is_skip_ext(filepath) or filepath in processed_files:
            return
        processed_files.add(filepath)
        if not os.path.isdir(filepath):
            process_file(filepath, max_chunk_size, f, c)
        else:
            for root, dirs, files in os.walk(filepath):
                for file in files:
                    process_file_with_context(os.path.join(root, file))

    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = {executor.submit(process_file_with_context, path) for path in (f for f in os.listdir(dirpath) if not is_skip_ext(f))}
        for _ in as_completed(futures):
            pass

def main():
    AES_KEY = Fernet.generate_key()
    # Add your own Camellia key or use a service like AWS Key Management Service (KMS)
    CAMELLIA_KEY = ...

    process_directory('/path/to/your/directory', max_chunk_size=65536, skip_extensions=('zip', 'exe'))

if __name__ == "__main__":
    main()
