```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <sys/mman.h>
#include <errno.h>
#include <stdbool.h>
#include <openssl/md5.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} record;

typedef struct {
    char description[1024];
    char source[1024];
} metadata;

typedef struct node {
    record data;
    struct node *prev, *next;
} node;

node* create_list(size_t size) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    node *head = malloc(sizeof(node));
    head->prev = head->next = head;
    size_t step = size / 10000;
    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&lock);
        node *new_node = malloc(sizeof(node));
        new_node->prev = head;
        new_node->next = head->next;
        head->next->prev = new_node;
        head->next = new_node;
        new_node->data.offset = i * step;
        new_node->data.key = i;
        new_node->data.timestamp = rand() % 1001;
        pthread_mutex_unlock(&lock);
    }

    // Asynchronous API calls for metadata here, omitted for brevity

    node *current = head->next;
    bool *visited = malloc(sizeof(bool) * size);
    memset(visited, false, sizeof(visited));
    node **stack = malloc(size * sizeof(node*));
    size_t stack_index = 0;

    while (current != head) {
        if (!visited[current->data.key]) {
            visited[current->data.key] = true;
            stack[stack_index++] = current;
            current = current->next;
        } else {
            node *temp = current;
            while (temp != stack[stack_index - 1]) {
                if (temp == head) return NULL; // Cycle detected
                temp = temp->prev;
            }
            current = stack[--stack_index];
        }
    }

    free(visited);
    free(stack);

    return head->next;
}

void deallocate(node **head) {
    while (*head != NULL) {
        node *temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

