import os
import threading
from concurrent.futures import ThreadPoolExecutor
import hashlib

def md5_file(file_path):
    if not os.path.isfile(file_path) or not os.access(file_path, os.R_OK):
        raise FileNotFoundError("Invalid or inaccessible file path.")

    chunk_size = 64 * (1024)
    with open(file_path, "rb") as f:
        hasher = hashlib.md5()
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            hasher.update(data)

    return hasher.hexdigest()

def parallel_md5(file_paths, chunk_size=64*1024):
    with ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
        results = list(executor.map(md5_file, file_paths))
    return results
