class FileProcessor:
    def __init__(self, max_chunk_size=65536, log_file='process.log', skip_extensions=('.exe', '.dll'), **kwargs):
        self.max_chunk_size = max_chunk_size
        self.skip_extensions = set(skip_extensions)
        self.log_file = log_file
        self.sha256 = hashlib.sha256()
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        handler = logging.FileHandler(self.log_file, mode='w')
        handler.setFormatter(logging.Formatter('%(asctime)s - %(message)s'))
        self.logger.addHandler(handler)
        self.chacha20 = None
        self.crypto_key_service = kwargs.get('crypto_key_service', None)

    def _hash_file(self, filepath):
        if not filepath or filepath in self.skip_extensions:
            return
        try:
            with open(filepath, 'rb') as f:
                enc = chardet.detect(f.read())['encoding']
                f.seek(0)
                for chunk in iter(lambda: f.read(self.max_chunk_size), b''):
                    if not self.chacha20:
                        self.chacha20 = self._get_chacha20_key()
                    hmac_obj = hmac.new(self.chacha20, chunk, hashes.SHA256).digest()
                    self.sha256.update(hmac_obj)
                    if self.logger:
                        self.logger.info(f'Processing {filepath}: {len(chunk)} bytes')
            self.sha256.hexdigest()
            self._save_crypto_key()
        except Exception as e:
            self.logger.error(f'Error processing {filepath}: {e}')

    def _get_chacha20_key(self):
        if not self.crypto_key_service:
            return None
        try:
            key_url = self.crypto_key_service
            with urlopen(key_url) as response, open('crypto_key.pem', 'wb') as key_file:
                key_file.write(response.read())
            with open('crypto_key.pem', 'rb') as key_file:
                return serialization.load_pem_private_key(
                    key_file.read(),
                    backend=default_backend()
                ).encrypt(hashes.SHA256(), None)
        except Exception as e:
            self.logger.error(f'Error getting Chacha20 key from {self.crypto_key_service}: {e}')
            return None

    def _save_crypto_key(self):
        if not self.chacha20:
            return
        with open('crypto_key.pem', 'wb') as key_file:
            key_file.write(self.chacha20.private_bytes(
                encoding=serialization.Encoding.PEM,
                encryptable=False,
                encryption_algorithm=hashes.SHA256(),
                fmt=serialization.PrivateFormat.TraditionalOpenSSL
            ))

    def process_directory(self, directory):
        if not os.path.isdir(directory):
            return
        executor = ThreadPoolExecutor()
        future_to_file = {}
        for root, dirs, files in os.walk(directory):
            for file in files:
                filepath = os.path.join(root, file)
                if filepath in future_to_file:
                    continue
                future_to_file[os.path.relpath(filepath, directory)] = self._hash_file(filepath)
        for _ in range(executor._max_workers):
            executor.submit(_hash_file, None)
        for future in as_completed(future_to_file):
            executor.shutdown()
