// Function to calculate the polynomial rolling hash of RNTI value.
static uint32_t rolling_hash(uint16_t rnti) {
    const uint32_t prime = 0x9E3779B9;
    uint32_t hash = 0;

    for (size_t i = 0; i < sizeof(uint16_t); ++i) {
        hash = hash * prime + rnti >> i & 0xff;
    }

    return hash;
}

