bool is_reachable(const NFAPI_CRHC_INDICATION_PDU_T *node) {
    const NFAPI_CRHC_INDICATION_PDU_T *curr = list_head;

    while (curr != node && curr) {
        curr = curr->next;
    }

    return curr != NULL;
}

// Function to check if a list cycle exists.
bool has_cycle() {
    // Use Floyd's cycle-finding algorithm.
    NFAPI_CRHC_INDICATION_PDU_T *slow = list_head, *fast = list_head;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;

        if (slow == fast) {
            return true;
        }
    }

    return false;
}

