                    # If metadata is provided, use it to update the hash object accordingly
                    # e.g., decoding the chunk using the specified encoding
                    temp_file.write(chunk)
                    temp_file.seek(0)
                    data = temp_file.read()
                    data = data.decode(metadata['encoding']).encode(metadata['encoding'])
                    hash_obj.update(hmac.new(b'', msg=data, digestmod=hash_obj).digest())
                else:
                    # If metadata is not provided, skip decoding and update the hash object directly
                    hash_obj.update(chunk)
            except Exception as e:
