record *records = NULL;
size_t record_count = 0, list_capacity = 0;
size_t valid_entries = 0, invalid_entries = 0;

void log_error(const char *msg) {
    printf("[ERROR] %s\n", msg);
}

// Function to calculate non-standard CRCFLAG value
uint8_t calc_crcflag(uint16_t rnti) {
    uint32_t seed = 0x12345678; // Seed value for CRC calculation
    const uint32_t poly = 0xEDB88320; // Polynomial used for rolling hash

    for (int i = 16; i > 0; --i) {
        if (rnti & (1 << (i - 1)))
            seed = (seed * poly) ^ 0xABCD;
    }

    return seed >> 24;
}

// Function to create a new NFAPI_CRC_INDICATION_PDU_T node
NFAPI_CRC_INDICATION_PDU_T *create_node(uint16_t rnti) {
    assert(rnti >= 1 && rnti <= 65535);

    NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        log_error("Out of memory");
        return NULL;
    }

    node->valid = 1;
    node->RNTI = rnti;
    node->CRC_INDICATION_REL8_TAG.CRCFLAG = calc_crcflag(rnti);

    return node;
}

// Function to add a new record to the array (thread-safe)
void add_record(long offset, int key, double timestamp, const char *metadata) {
    pthread_mutex_lock(&list_mutex);
    if (record_count >= list_capacity) {
        // Resize the records array and reallocate head pointer if necessary
        if (record_count == list_capacity) {
            record *new_records = realloc(records, list_capacity * 2 * sizeof(record));
            if (!new_records) {
                log_error("Out of memory");
                pthread_mutex_unlock(&list_mutex);
                return;
            }
            records = new_records;
        }

        list_capacity *= 2;
    }

    records[record_count].offset = offset;
    records[record_count].key = key;
    records[record_count].timestamp = timestamp;
    strcpy(records[record_count].metadata, metadata);
    ++record_count;
    pthread_mutex_unlock(&list_mutex);
}

// Function to process a batch of NFAPI_CRC_INDICATION_PDU_T structures
void process_batch(NFAPI_CRC_INDICATION_PDU_T *data, size_t data_size) {
    for (size_t i = 0; i < data_size; ++i) {
        if (create_node(data[i].RNTI)) {
            add_record(i, data[i].RNTI, data[i].timestamp, ""); // Placeholder metadata
            if (data[i].RNTI <= 65535)
                ++valid_entries;
            else
                ++invalid_entries;
        }
    }
}

// Function to free memory and log statistics on exit
void cleanup() {
    for (size_t i = 0; i < record_count; ++i)
        free(records[i].metadata);
    free(records);
    free(head);
}

