from cachetools import TTLCache

class HashFunction:
    def __init__(self, max_cache_size=1024):
        self.metadata_cache = TTLCache(maxsize=max_cache_size, ttl=60)

    def _get_metadata(self, file_path):
        metadata_key = f"{file_path}-metadata"
        if metadata_key in self.metadata_cache:
            return self.metadata_cache[metadata_key]

        try:
            response = urlopen(f"https://file-metadata-api.com/{file_path}")
            content = response.read().decode('utf-8') if response else b""
            metadata = {k: v for k, v in json.loads(content).items() if k not in {"filename", "checksum"}}
            self.metadata_cache[metadata_key] = metadata
            return metadata
        except Exception as e:
            print(f"Error retrieving metadata: {e}")
            return {}

    def _hash_chunk(self, file_path, chunk):
        metadata = self._get_metadata(file_path)
        hasher = hashlib.sha256()

        # Add file type and compression algorithm to the hash if present in metadata
        hasher.update((f"{chunk}-type" + metadata.get("filetype", "")).encode('utf-8'))
        hasher.update((f"{chunk}-compression" + metadata.get("compression", "")).encode('utf-8'))

        # Add chunk data to the hash
        hasher.update(chunk)

        return hasher.hexdigest()

    def hash_file(self, file_path):
        if not os.access(file_path, os.R_OK):
            raise PermissionError("File cannot be read.")

        chunk_size = 64 * (1024 ** 2)  # 64MB chunks
        with open(file_path, "rb") as f:
            hasher = hashlib.sha256()
            while True:
