} NFAPI_CRC_INDICATION_PDU_T;

typedef struct thread_data {
    int start, end;
    NFAPI_CRC_INDICATION_PDU_T** list;
    pthread_mutex_t* mutex;
} ThreadData;

void generate_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    uint32_t hash = (uint32_t)((pdu->tag ^ pdu->rnti) * 1234567);
    pdu->crc_indication.crcflag = (hash & 0x1) ? 1 : 0;
}

void* populate_list(void* data) {
    ThreadData* td = (ThreadData*)data;
    int i;

    for (i = td->start; i < td->end; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &td->list[i];
        pdu->tag.id = i;
        pdu->tag.length = 2;
        pdu->rnti = i % 5 + 1; // Replace this with appropriate RNTI generation logic
        generate_crc(pdu);
    }

    return NULL;
}

int create_list(NFAPI_CRC_INDICATION_PDU_T** list, int N) {
    if (N > MAX_LIST_SIZE) {
        fprintf(stderr, "Error: Requested list size exceeds the maximum allowed.\n");
        return -1;
    }

    *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        fprintf(stderr, "Error: Failed to allocate memory for the list.\n");
        return -1;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    ThreadData td[N];
    int step = (int)ceil((double)N / phread_getaffinity_max()); // Divide the work among available processors

    for (int i = 0; i < N; ++i) {
        td[i].list = *list;
        td[i].start = i * step;
        td[i].end = (i * step + step > N) ? N : (i * step + step);
        td[i].mutex = &mutex;
    }

    pthread_t threads[N];
    for (int i = 0; i < N; ++i) {
        if (pthread_create(&threads[i], NULL, populate_list, &td[i])) {
            fprintf(stderr, "Error: Failed to create thread.\n");
            return -1;
        }
    }

    for (int i = 0; i < N; ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error: Failed to join thread.\n");
            return -1;
        }
    }

    // Implement cleanup logic for the list here.

    return 0;
}
