    private static final int RETRY_ATTEMPTS = 3;
    private static final long BACKOFF_FACTOR = 2L;
    private static final long LOGGING_THROTTLE = 5L; // seconds between logs
    private static final long BACKOFF_INITIAL = 1000L; // initial delay between retries in milliseconds

    public MoSTState loadState(String filePath) throws IOException {
        FileInputStream fis = null;
        ObjectInputStream ois = null;
        try {
            File file = new File(filePath);
            if (file.length() > MAX_FILE_SIZE) {
                throw new IllegalArgumentException("File size exceeds maximum allowed limit.");
            }

            long startTime = System.currentTimeMillis();
            for (int i = 0; i < RETRY_ATTEMPTS; ++i) {
                fis = new FileInputStream(file);
                ois = getObjectInputStream(fis);

                Object obj = ois.readObject();
                if (!(obj instanceof MoSTState)) {
                    continue;
                }

                return (MoSTState) obj;
            }

            // If we reached the maximum number of retries, throw an exception indicating a more permanent issue.
            long elapsedTime = System.currentTimeMillis() - startTime;
            if (elapsedTime > BACKOFF_INITIAL * Math.pow(BACKOFF_FACTOR, RETRY_ATTEMPTS)) {
                throw new IOException("Failed to load state after multiple attempts.");
            }
        } catch (IOException | ClassNotFoundException e) {
            LOGGER.error("Error while loading state: {}", e.getMessage());
            // Implement logging frequency throttling here
            long currentTime = System.currentTimeMillis();
            if (currentTime - lastLoggedErrorTime > LOGGING_THROTTLE * 1000) {
                lastLoggedErrorTime = currentTime;
                LOGGER.error("", e);
            }
        } finally {
            if (ois != null) {
                try {
                    ois.close();
                } catch (IOException e) {
                    // Ignore exceptions while closing ObjectInputStream
                }
            }
            if (fis != null) {
                fis.close();
            }
        }

        return null;
    }

    private ObjectInputStream getObjectInputStream(FileInputStream fis) throws IOException, ArchiveException {
        // Support .gz and .zip file formats by checking the file extension and using appropriate decompression mechanisms.
        String fileName = fis.getFileName().toString();
        if (fileName.toLowerCase().endsWith(".gz")) {
