            TarArchiveOutputStream tarOS = new TarArchiveOutputStream(fis);
            ArchiveStreamFactory factory = new ArchiveStreamFactory();
            JarFile jarFile = factory.createArchiveInputStream(tarOS, fis).getJarEntry().getName() + ".jar");
            return new ObjectInputStream(jarFile.getInputStream());
        } else {
            return new ObjectInputStream(fis);
        }
    }

    private long lastLoggedErrorTime = 0L; // Maintain a variable to throttle logging frequency

