    pthread_mutex_unlock(&nfapi_mutex);
}

int add_pdu(const RX_UE_INFORMATION_TAG tag, const RNTI rnti) {
    // Find available slot in the array
    size_t i;
    for (i = 0; i < nfapi_count; ++i) {
        if (!nfapi_array[i].rnti.rnti == rnti) break;
    }
    // Resize and copy elements if necessary
    if (i == nfapi_count) {
        if (nfapi_capacity <= nfapi_count * GROWTH_FACTOR) {
            size_t new_capacity = nfapi_capacity + (nfapi_capacity >> 1);
            NFAPI_CRC_INDICATION_PDU_T* tmp = realloc(nfapi_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
            if (!tmp) return MEMORY_ERROR;
            nfapi_array = tmp;
            nfapi_capacity = new_capacity;
        }
        // Copy existing elements
        memmove(nfapi_array + i + 1, nfapi_array + i, (nfapi_count - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    // Initialize new element
    nfapi_array[i].tag = tag;
    nfapi_array[i].rnti = rnti;
    reset_crcflag(&nfapi_array[i]);
    ++nfapi_count;
    return 0;
}

int remove_pdu(const RNTI rnti) {
    pthread_mutex_lock(&nfapi_mutex);
    size_t i;
    for (i = 0; i < nfapi_count; ++i) {
        if (nfapi_array[i].rnti.rnti == rnti) break;
    }
    // Not found
    if (i == nfapi_count) {
        pthread_mutex_unlock(&nfapi_mutex);
        return NOT_FOUND;
    }
    // Move remaining elements to fill the gap
    memmove(nfapi_array + i, nfapi_array + i + 1, (nfapi_count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    --nfapi_count;
    pthread_mutex_unlock(&nfapi_mutex);
    return 0;
}

void iterate_pdu(void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&nfapi_mutex);
    for (size_t i = 0; i < nfapi_count; ++i) {
        func(&nfapi_array[i]);
    }
    pthread_mutex_unlock(&nfapi_mutex);
}

