["Here is a C++11 solution using `std::vector`, `std::mutex` for synchronization, and `std::condition_variable` for notifying when changes are made. I've also included a circular buffer-like mechanism using `std::deque` to limit the number of concurrent operations.

```cpp
#include <iostream>
#include <vector>
#include <deque>
#include <mutex>
#include <condition_variable>

struct NFAPI_L2_RX_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    PHY_LAYER_STATUS status;
    int receptionQuality; // dynamically assigned value
};

class DynamicArray {
private:
    std::vector<NFAPI_L2_RX_INDICATION_PDU_T> data;
    std::deque<size_t> operationQueue;
    std::mutex mtx;
    std::condition_variable cvDataChanged, cvEmptySpace;

public:
    size_t size() const { return data.size(); }
    bool empty() const { return data.empty(); }

    void add(const NFAPI_L2_RX_INDICATION_PDU_T& elem) {
        std::unique_lock<std::mutex> lock(mtx);
        while (!operationQueue.empty()) cvEmptySpace.wait(lock);
        data.push_back(elem);
        operationQueue.push_back(data.size() - 1);
        lock.unlock();
        cvDataChanged.notify_one();
    }

    void removeByRnti(uint32_t rnti) {
        std::unique_lock<std::mutex> lock(mtx);
        while (!operationQueue.empty() && operationQueue.front() >= data.size()) cvEmptySpace.wait(lock);
        auto it = std::find_if(data.begin(), data.end(), [rnti](const NFAPI_L2_RX_INDICATION_PDU_T& e) { return e.rnti == rnti; });
        if (it != data.end()) {
            data.erase(it);
            for (size_t i = operationQueue.front(); i < data.size(); ++i) {
                --(*operationQueue[i]);
                if (*operationQueue[i] == -1) operationQueue.pop_back();
            }
        }
        lock.unlock();
        cvDataChanged.notify_one();
    }

    void iterate(std::function<void(NFAPI_L2_RX_INDICATION_PDU_T&)> lambda) {
        std::unique_lock<std::mutex> lock(mtx);
        while (!operationQueue.empty() && operationQueue.front() >= data.size()) cvEmptySpace.wait(lock);
        for (auto it = data.begin(); it != data.end(); ) {
            if ((*it).rnti == rnti) { // signal strength condition
                lambda((*it));
                it = data.erase(it);
            } else {
                ++it;
            }
        }
        lock.unlock();
        cvDataChanged.notify_one();
    }
};
```

