typedef struct {
    uint32_t PID;
    time_t timestamp;
    size_t payload_len;
    char* payload;
} packet_header;

struct packet_list {
    packet_header** headers;
    size_t size;
    size_t capacity;
};

void packet_list_init(struct packet_list* list) {
    list->headers = NULL;
    list->size = 0;
    list->capacity = 0;
}

void packet_list_destroy(struct packet_list* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->headers[i]->payload);
        free(list->headers[i]);
    }
    free(list->headers);
}

void packet_list_resize(struct packet_list* list, size_t new_capacity) {
    if (new_capacity <= list->capacity) return;

    packet_header** new_array = realloc(list->headers, sizeof(packet_header*) * new_capacity);
    if (!new_array) {
        fprintf(stderr, "Failed to allocate memory for packet headers\n");
        exit(EXIT_FAILURE);
    }
    list->headers = new_array;
    memset(&list->headers[list->size], 0, sizeof(packet_header*) * (new_capacity - list->size));
    list->capacity = new_capacity;
}

void packet_list_push(struct packet_list* list, const packet_header* header) {
    if (list->size == list->capacity) packet_list_resize(list, list->capacity * 2);
    list->headers[list->size++] = malloc(sizeof(packet_header));
    memcpy(list->headers[list->size - 1], header, sizeof(packet_header));
}

void serialize(const struct packet_list* list, uint8_t* buffer, size_t* offset) {
    for (size_t i = 0; i < list->size; ++i) {
        const packet_header* header = list->headers[i];
        memcpy(buffer + *offset, &header->PID, sizeof(uint32_t));
        *offset += sizeof(uint32_t);
        memcpy(buffer + *offset, &header->timestamp, sizeof(time_t));
        *offset += sizeof(time_t);
        memcpy(buffer + *offset, &header->payload_len, sizeof(size_t));
        *offset += sizeof(size_t);
        memcpy(buffer + *offset, header->payload, header->payload_len);
        *offset += header->payload_len;
    }
}

int deserialize(const uint8_t* buffer, size_t offset, struct packet_list* list) {
    if (offset % sizeof(packet_header) != 0) return -1;

    for (size_t i = 0; i < list->capacity && offset < sizeof(uint8_t)*list->size * sizeof(packet_header); ++i) {
        const packet_header* header = &list->headers[i];
        memcpy(&header->PID, buffer + offset, sizeof(uint32_t));
        offset += sizeof(uint32_t);
        memcpy(&header->timestamp, buffer + offset, sizeof(time_t));
        offset += sizeof(time_t);
        memcpy(&header->payload_len, buffer + offset, sizeof(size_t));
        offset += sizeof(size_t);

        if (header->payload_len > 0) {
            header->payload = malloc(header->payload_len);
            memcpy(header->payload, buffer + offset, header->payload_len);
            offset += header->payload_len;
        } else {
            header->payload = NULL;
        }
    }
    return offset;
}
