#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    uint32_t PID;
    time_t timestamp;
    size_t payload_len;
    char* payload;
} packet_header;

typedef struct packet_list {
    packet_header** headers;
    size_t capacity;
    size_t size;
} packet_list;

void packet_list_init(packet_list* list, size_t initial_capacity) {
    list->headers = malloc(initial_capacity * sizeof(packet_header*));
    list->capacity = initial_capacity;
    list->size = 0;
}

void packet_list_add(packet_list* list, const packet_header* header) {
    if (list->size >= list->capacity) {
        list->capacity *= 2;
        list->headers = realloc(list->headers, list->capacity * sizeof(packet_header*));
    }
    list->headers[list->size] = malloc(sizeof(packet_header));
    memcpy(list->headers[list->size], header, sizeof(packet_header));
    ++list->size;
}

void packet_list_free(packet_list* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->headers[i]->payload);
        free(list->headers[i]);
    }
    free(list->headers);
}

void packet_header_serialize(const packet_header* header, char** buffer) {
    *buffer = realloc(*buffer, sizeof(uint32_t) + header->payload_len + 1);

    memcpy(*buffer, &header->PID, sizeof(uint32_t));
    memcpy((*buffer) + sizeof(uint32_t), &(header->timestamp), sizeof(time_t));
    memcpy((*buffer) + sizeof(uint32_t) + sizeof(time_t), header->payload, header->payload_len);
}

packet_header* packet_header_deserialize(const char* buffer) {
    const uint32_t PID = *(uint32_t*)buffer;
    const size_t timestamp_size = sizeof(time_t);
    const size_t payload_len = (buffer + sizeof(uint32_t) + timestamp_size) - buffer;

    packet_header* header = malloc(sizeof(packet_header));
    header->PID = PID;
    header->timestamp = *(time_t*)(buffer + sizeof(uint32_t));
    header->payload = malloc(payload_len);
    memcpy(header->payload, buffer + sizeof(uint32_t) + timestamp_size, payload_len);
    header->payload_len = payload_len;

    return header;
}
