        keys = Enumerable.Range(0, 1000).ToArray();
        records = new List<Record>(1000);
    }

    private void SeedRecords()
    {
        ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount - 2 };
        Parallel.ForEach(Enumerable.Range(0, records.Capacity), options, i =>
        {
            records[i] = new Record { Key = keys[i], Value = new Random(offsets[i]).Next(100) };
        });
    }

    private void ChunkAndHashFile(string path)
    {
        using (var reader = File.OpenRead(path))
        using (var writer = new MemoryStream())
        using (var hasher = MD5.Create())
        {
            var chunkSize = 1 * 1024 * 1024; // 1MB
            var buffer = new byte[chunkSize];

            int bytesRead;
            while ((bytesRead = reader.Read(buffer, 0, buffer.Length)) > 0)
            {
                writer.Write(buffer, 0, bytesRead);
                if (writer.Length >= chunkSize)
                {
                    hasher.TransformBlock(writer.ToArray(), 0, (int)writer.Length, Array.Empty<byte>(), out _);
                    writer.SetLength(0);
                }
            }

            if (writer.Length > 0)
            {
                hasher.TransformFinalBlock(writer.ToArray(), 0, (int)writer.Length);
            }
        }
    }

    private Task<bool> HashAndStoreFileAsync(string path, CancellationToken cancellationToken)
    {
        return Task.Run(async () =>
        {
            var hasher = MD5.Create();
            using (var reader = File.OpenRead(path))
            {
                while (!cancellationToken.IsCancellationRequested)
                {
                    var buffer = new byte[4096];
                    int bytesRead;
                    if ((bytesRead = await reader.ReadAsync(buffer, cancellationToken)) > 0)
                    {
                        hasher.TransformBlock(buffer, 0, bytesRead, Array.Empty<byte>(), out _);
                    }
                }
            }

            var hashBytes = hasher.Hash;
            return HashIds.Decode(hashBytes) == path || RetryHashCalculation(path, cancellationToken);
        }, cancellationToken);
    }

    private async Task<bool> RetryHashCalculation(string path, CancellationToken cancellationToken)
    {
        for (int i = 1; i <= 3; i++)
        {
            await Task.Delay((long)(Math.Pow(2, i - 1) * 500), cancellationToken);
            if (await HashAndStoreFileAsync(path, cancellationToken))
            {
                return true;
            }
        }

        return false;
    }

