#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Packet header struct
typedef struct {
    uint32_t pid;
    time_t timestamp;
    char* payload;
} packet_header;

// Doubly-linked list node structure
typedef struct dlnode {
    packet_header data;
    struct dlnode *prev, *next;
} dlnode;

// Global variable for the head of the linked list
dlnode* list_head = NULL;
dlnode* list_tail = NULL;
size_t list_len = 0;

// Allocate memory for a new packet header and initialize its fields
packet_header* create_packet_header() {
    packet_header* ph = malloc(sizeof(packet_header));
    if (!ph) return NULL;
    memset(ph, 0, sizeof(packet_header));
    return ph;
}

// Allocate memory for a new dlnode with the given packet header and initialize its links
dlnode* create_dlnode(packet_header* ph) {
    dlnode* dln = malloc(sizeof(dlnode));
    if (!dln) return NULL;
    dln->data = *ph;
    dln->prev = dln->next = NULL;
    return dln;
}

// Insert a new dlnode at the head of the list
void insert_head(dlnode* dln) {
    if (list_len == 0) {
        list_head = dln;
        list_tail = dln;
    } else {
        dln->next = list_head;
        list_head->prev = dln;
        list_head = dln;
    }
    list_len++;
}

// Insert a new dlnode at the tail of the list
void insert_tail(dlnode* dln) {
    if (list_len == 0) {
        list_head = dln;
        list_tail = dln;
    } else {
        list_tail->next = dln;
        dln->prev = list_tail;
        list_tail = dln;
    }
    list_len++;
}

// Remove a dlnode from the list and free its memory
void remove_dlnode(dlnode* dln) {
    if (dln == list_head) {
        list_head = dln->next;
        if (list_head) list_head->prev = NULL;
        else list_tail = NULL;
    } else if (dln == list_tail) {
        list_tail = dln->prev;
        list_tail->next = NULL;
    } else {
        dln->prev->next = dln->next;
        dln->next->prev = dln->prev;
    }
    free(dln);
    list_len--;
}

// Free the memory of all nodes in the list and set the list to an empty state
void clear_list() {
    dlnode* current = list_head;
    while (current != NULL) {
        dlnode* temp = current;
        current = current->next;
        free(temp);
    }
    list_head = list_tail = NULL;
    list_len = 0;
}

