typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    enum PHY_LAYER_STATUS phy_status;
    int RECEPTION_QUALITY;
    bool is_active;
} NFAPI_L2_RX_INDICATION_PDU_T;

typedef struct {
    NFAPI_L2_RX_INDICATION_PDU_T* data;
    size_t capacity;
    size_t length;
    sem_t semaphore;
} DYNAMIC_ARRAY;

DYNAMIC_ARRAY* dynamic_array_init(size_t min_buffer) {
    DYNAMIC_ARRAY* da = (DYNAMIC_ARRAY*)malloc(sizeof(DYNAMIC_ARRAY));
    da->data = (NFAPI_L2_RX_INDICATION_PDU_T*)calloc(min_buffer, sizeof(NFAPI_L2_RX_INDICATION_PDU_T));
    sem_init(&da->semaphore, 0, 5); // Limit concurrent operations to 5
    da->capacity = min_buffer;
    da->length = 0;
    return da;
}

void dynamic_array_push(DYNAMIC_ARRAY* da, NFAPI_L2_RX_INDICATION_PDU_T element) {
    if (sem_wait(&da->semaphore) != 0) { // Wait for semaphore to avoid data races
        fprintf(stderr, "Error: Semaphore wait failed\n");
        exit(EXIT_FAILURE);
    }
    if (da->length + 1 > da->capacity * 4 / 5) { // Ensure no more than 20% reserved for inactive entries
        size_t new_capacity = da->capacity * 2;
        NFAPI_L2_RX_INDICATION_PDU_T* new_data = (NFAPI_L2_RX_INDICATION_PDU_T*)realloc(da->data, new_capacity * sizeof(NFAPI_L2_RX_INDICATION_PDU_T));
        if (!new_data) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        da->data = new_data;
        da->capacity = new_capacity;
    }
    element.is_active = true; // Mark entry as active
    memcpy(&da->data[da->length], &element, sizeof(NFAPI_L2_RX_INDICATION_PDU_T));
    da->length++;
    sem_post(&da->semaphore); // Signal semaphore to release lock
}

bool dynamic_array_remove(DYNAMIC_ARRAY* da, uint16_t rnti) {
    if (sem_wait(&da->semaphore) != 0) { // Wait for semaphore to avoid data races
        fprintf(stderr, "Error: Semaphore wait failed\n");
        exit(EXIT_FAILURE);
    }
    size_t i;
    for (i = 0; i < da->length; i++) {
        if (da->data[i].RNTI == rnti) {
            memmove(&da->data[i], &da->data[i + 1], (da->length - i - 1) * sizeof(NFAPI_L2_RX_INDICATION_PDU_T));
            da->length--;
            break;
        }
    }
    if (i == da->length) { // RNTI not found
        sem_post(&da->semaphore); // Signal semaphore to release lock
        return false;
    }
    da->data[i].is_active = false; // Mark entry as inactive
    sem_post(&da->semaphore); // Signal semaphore to release lock
    return true;
}

void dynamic_array_iterate(DYNAMIC_ARRAY* da, void(*callback)(NFAPI_L2_RX_INDICATION_PDU_T)) {
    if (sem_wait(&da->semaphore) != 0) { // Wait for semaphore to avoid data races
        fprintf(stderr, "Error: Semaphore wait failed\n");
        exit(EXIT_FAILURE);
    }
    size_t i;
    int sum = 0;
    int active_count = 0;
