    mutable std::mutex mtx;
    std::unordered_map<int, node_ptr> m_nodes;
public:
    void add_node(const LTE_ENB_NODE& node) {
        node_ptr ptr = m_list.push_front(node);
        if (ptr) {
            std::unique_lock lock(mtx);
            m_nodes[node.enb_id] = ptr;
