    Node *head;
    Node *tail;
    size_t size;
    pthread_mutex_t mutex;
};

void init_list(struct list* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(struct list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node *new_node = create_node(data);
    if (new_node == NULL) {
        printf("Error: Could not allocate memory for new node.\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void remove_from_list(struct list* list, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);
    Node *current = list->head;
    Node *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Error: RNTI not found.\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;
    pthread_mutex_unlock(&list->mutex);
}

