    Node *current = list->head;
    while (current != NULL) {
        if (/*condition for updating CRCFLAG*/) {
            current->data.CRCFLAG = !current->data.CRCFLAG;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

