int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [block_size]\n", argv[0]);
        return EXIT_FAILURE;
    }

    block_size = atoi(argv[1]);
    if (block_size < BLOCK_SIZE_MIN || block_size > BLOCK_SIZE_MAX) {
        fprintf(stderr, "Error: Invalid block size. Valid range is [%d, %d].\n", BLOCK_SIZE_MIN, BLOCK_SIZE_MAX);
        return EXIT_FAILURE;
    }

    IntegerArray data = create_integer_array(block_size);
    pthread_t threads[getpagesize() / getpagesize()]; // Approximate the number of cores

    void *status;
    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_create(&threads[i], NULL, processBlock, &data);
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_join(threads[i], &status);
    }

    free_integer_array(data);

    return EXIT_SUCCESS;
}

void *processBlock(void *arg) {
    IntegerArray *array = arg;
    int current_block_size = array->capacity;
    size_t count = 0;

    while (count < current_block_size) {
        char buffer[128];
        ssize_t bytes_read = getline(&buffer, sizeof(buffer), stdin);
        if (bytes_read <= 0) break;

        // Handle error and skip the invalid input
        if (!is_integer(buffer)) continue;

        int value = atoi(buffer);
        array->data[count] = value;
        ++count;
    }

    pthread_mutex_lock(&log_mutex);
    log_event("ProcessBlock", json_object_to_json_string(json_object_new_object()));
    pthread_mutex_unlock(&log_mutex);

    return NULL;
}

