// Maximum number of concurrent DNS queries
#define MAX_QUERIES 10

// Mutex for protecting access to the query pool
pthread_mutex_t query_mutex;

// Query struct containing hostname, socket, and response buffer
typedef struct {
    char hostname[256];
    int sockfd;
    sockaddr_in addr;
} Query;

// Function to resolve a DNS query asynchronously
void dns_query(const char *hostname) {
    // Allocate and initialize query structure
    Query query = {0};
    strncpy(query.hostname, hostname, sizeof(query.hostname));

    // Acquire lock before adding the query to the pool
    pthread_mutex_lock(&query_mutex);

    // If the pool is full, wait for a spot to open up
    while (num_queries >= MAX_QUERIES) {
        pthread_cond_wait(&query_event_cond, &query_mutex);
    }

    // Add the query to the pool
    queries[num_queries++] = query;

    // Create a UDP socket for sending the DNS query
    int sockfd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (sockfd < 0) {
        perror("socket");
        return;
    }

    // Set the timeout for the socket to 5 seconds
    struct timeval tv = {5 * 1000, 0};
    setsockopt(sockfd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));

    // Send the DNS query to the network service
    const char *dns_server = "8.8.8.8";
    sockaddr_in dns_server_addr;
    memset(&dns_server_addr, 0, sizeof(dns_server_addr));
    dns_server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, dns_server, &dns_server_addr.sin_addr);
    dns_server_addr.sin_port = htons(53);

    // Assemble the DNS query and send it to the server
    char query[256] = {0};
    assemble_dns_query(query, hostname);
    sendto(sockfd, query, strlen(query), 0, (struct sockaddr *)&dns_server_addr, sizeof(dns_server_addr));

    // Set up the callback for handling DNS responses
    void *udata = &query;
    struct msghdr msg = {0};
    msg.msg_name = &query.addr;
    msg.msg_namelen = sizeof(query.addr);
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = 0;
    msg.msg_iov = &((struct iovec){{&query, sizeof(query)}});
    msg.msg_iovlen = 1;

    // Set up the callback function to handle DNS responses
    struct sigevent event = {0};
    event.sigev_notify = SIGEV_THREAD;
    event.sigev_value.sival_ptr = udata;
    event.sigev_signo = SIGUSR1;
    int ret = sigevent_tocontrol(sockfd, &event, sizeof(event), NULL);
    if (ret < 0) {
        perror("sigevent_tocontrol");
        close(sockfd);
        return;
    }
}

// Function to assemble a DNS query
void assemble_dns_query(char *buf, const char *hostname) {
    // Assemble the standard DNS header
    memset(buf, 0, sizeof(buf));
    buf[0] = ID; // Identifier for this query
    buf[1] = QR | OPCODE; // Query (standard operation code)
    buf[2] = AA; // Authoritative answers expected (optional class)
    buf[3] = TC; // Truncation not expected (optional class)
    buf[4] = PD; // Recursion desired (optional class)
    buf[5] = CD; // Checking disabled (optional class)
    buf[6] = SHORT(12); // Query type: A record (IPv4 address)
    buf[10] = SHORT(1);  // Query class: Internet (IN)
    buf[12] = strlen(hostname); // Length of the query name

    // Encode the query name into the buffer
    encode_domain_name(buf + 14, hostname);
}

// Function to encode a domain name into the DNS buffer
void encode_domain_name(char *buf, const char *name) {
    int len = strlen(name);
    for (int i = 0; i < len; ++i) {
        char c = name[i];
        if (c == '.') {
            buf[i] = '%';
            buf[i+1] = '2' + (buf[i-1] & 0xF0) >> 4;
            buf[i+2] = '2' + (buf[i-1] & 0x0F);
        } else {
            buf[i] = c;
        }
    }
}

// Function to handle DNS responses and return the IP address
void *dns_response_handler(void *udata) {
    Query *query = udata;
    int sockfd = query->sockfd;

    // Receive the DNS response and parse it for the IP address
    char buf[256] = {0};
    ssize_t len = recvfrom(sockfd, buf, sizeof(buf), 0, NULL, NULL);
    if (len > 0) {
        // Parse the DNS response for the A record
        int pos = 12;
        while (true) {
            int type = buf[pos];
            if (type != TA) break; // Type A record found
            if (buf[pos+1] & 0xC0) continue; // Ignore CNAME, MX, etc. records
            pos += SHORT(pos + 6);
        }
        if (pos + sizeof(struct in_addr) > len) goto error; // Incomplete response

        struct in_addr addr;
        memcpy(&addr, buf + pos, sizeof(addr));
        // Free the socket and return the IP address
        close(sockfd);
        return &addr;
    }
error:
    perror("recvfrom");
    free(query);
    return NULL;
}

// Function to resolve a hostname and return its corresponding IP address
int resolve_hostname(const char *hostname, struct in_addr *ip) {
    // Ensure the query pool is initialized
    if (!queries || !num_queries) initialize_queries();

    // Add the hostname to the list of pending queries and start a thread for it
    pthread_t thread_id;
    int ret = pthread_create(&thread_id, NULL, &dns_query, hostname);
    if (ret < 0) {
        perror("pthread_create");
        return -1;
    }

    // Wait for the result or a timeout
    struct timespec ts = {5 * NANOS_PER_SEC, 0};
    timespec_add(&ts, &ts);
    clock_gettime(CLOCK_REALTIME, &start_time);
    while (true) {
        pthread_mutex_lock(&query_mutex);
        for (int i = 0; i < num_queries; ++i) {
            if (!queries[i].hostname || queries[i].result != NULL) continue;

            // Found an active query, so process it and unlock the mutex
            struct in_addr *result = queries[i].result;
            ip_t *ip_ptr = &queries[i].ip;
            void *udata = &queries[i];
            pthread_t thread_id = queries[i].thread_id;
            pthread_cancel(thread_id);
            pthread_mutex_unlock(&query_mutex);

            // Spawn a new thread to handle the DNS response
            int ret = pthread_create(&thread_id, NULL, &dns_response_handler, udata);
            if (ret < 0) {
                perror("pthread_create");
                continue;
            }

            // Wait for the result or a timeout
            clock_gettime(CLOCK_REALTIME, &current_time);
            timespec_sub(&ts, &current_time);
            if (timespec_cmp(ts, ZERO) <= 0) break;

            // Check if the result has been set
            pthread_mutex_lock(&query_mutex);
            if (queries[i].result != NULL) {
                *ip = queries[i].ip;
                free(queries + i);
                memmove(queries + i, queries + i + 1, (num_queries - i - 1) * sizeof(Query));
                --num_queries;
                pthread_mutex_unlock(&query_mutex);
                return 0;
            }
            pthread_mutex_unlock(&query_mutex);
        }
        if (timespec_cmp(ts, ZERO) <= 0) break; // Timeout occurred
    }

    // No result was found, so set an error code and free the query data
    *ip = {0};
    return -2;
}
```

This code provides a basic implementation of asynchronous DNS resolution using UDP for communication. It ensures efficient resource utilization by limiting the number of concurrent queries, managing the query pool with mutexes, and utilizing threads for processing DNS responses. The function `resolve_hostname()` is used to resolve a given hostname to its corresponding IP address.

To further optimize this solution, you may want to consider implementing caching mechanisms for previously resolved hostnames or using more sophisticated DNS techniques such as multicasting and anycast. Additionally, you could investigate methods for reducing the overhead of creating new UDP sockets for each query by reusing them, if appropriate.']

