// Custom locking mechanism
class SpinLock {
public:
    void lock() { while (++m_count != 0) { std::this_thread::yield(); } m_count--; }
    bool try_lock() { return 0 == --m_count; }
    void unlock() { ++m_count; }
private:
    int m_count = 0;
};

// Summary report structure
struct Report {
    std::string path;
    size_t lineCount;
    size_t wordCount;
    size_t charCount;
};

void processFile(const fs::path& filePath, Report* report, SpinLock* lock) {
    // Read and count lines, words, and characters for the current file.
