void processDirectory(const fs::path& directory, Report* report, SpinLock* lock) {
    std::vector<fs::path> files;
    std::copy_if(std::recursive_directory_iterator{directory}, {}, std::back_inserter(files), [](const auto& entry) { return fs::is_regular_file(entry); });

    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> finished = false;
    int numThreads = std::thread::hardware_concurrency();

    std::vector<std::unique_ptr<std::thread>> threads;
    for (int i = 0; i < numThreads; ++i) {
        auto thread = std::make_unique<std::thread>([&, i]() {
            SpinLock lockGuard(*lock);
            lockGuard.lock();
            while (!finished) {
                if (threads.size() == numThreads && !files.empty()) {
                    auto fileIndex = static_cast<size_t>(i) % files.size();
                    processFile(files[fileIndex], report, lock);
                    lockGuard.unlock();
                    std::unique_lock<std::mutex> mtxLock(mtx);
                    cv.wait(mtxLock, [&]() { return finished || files.empty(); });
                } else {
                    lockGuard.unlock();
                    this_thread::yield();
                }
            }
        });
        threads.push_back(std::move(thread));
    }

    // Wait for all threads to finish processing.
    for (auto& thread : threads) {
        thread->join();
    }
}

