// Function to perform DNS resolution for a given hostname using standard library functions.
void dns_resolve(const char *hostname) {
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        exit(EXIT_FAILURE);
    }

    const struct sockaddr_in *sock_in = (const struct sockaddr_in *)res->ai_addr;
    memcpy(ip, &sock_in->sin_addr, sizeof(sock_in->sin_addr));
}

