                input_file = optarg;
                if ((output_fd = open(optarg, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) == -1) {
                    perror("open");
                    exit(EXIT_FAILURE);
                }
                break;
            default:
                printf("Invalid option\n");
                exit(EXIT_FAILURE);
        }
    }

    if (input_file == NULL && optind < argc) {
        fprintf(stderr, "Missing input file.\n");
        exit(EXIT_FAILURE);
    }

    char hostname[MAX_HOSTNAME_LENGTH];
    size_t hostname_len = 0;

    for (int i = optind; i < argc; ++i) {
        if (sscanf(argv[i], "%s", hostname) != 1) {
            fprintf(stderr, "Invalid hostname: %s\n", argv[i]);
            exit(EXIT_FAILURE);
        }
        dns_resolve(hostname);
        if (!opt_cs) printf("%s\n", ip);
        else printf("%s,%u\n", ip, ntohs(res->ai_addr->sa_family));
    }

    if (input_file && output_fd != STDOUT_FILENO) {
        for (FILE *fp = fopen(input_file, "r"); fp; fp = fp ? fp->next : NULL) {
            char line[BUFFER_SIZE];
            size_t len = fgets(line, BUFFER_SIZE, fp);
            if (len > 0) {
                printf("Line: %ld\n", len - 1); // Adjust for newline character
                fputs(line, stdout);
                fputc('\n', stdout);
            }
        }
    }

    return EXIT_SUCCESS;
}
