TCP_CONNECTION_RECORD_T* dynamic_array_get(size_t index) {
    if (index >= capacity) {
        resize();
    }
    pthread_mutex_lock(&lock);
    TCP_CONNECTION_RECORD_T* record = &connections[index];
    pthread_mutex_unlock(&lock);
    return record;
}

void dynamic_array_push(TCP_CONNECTION_RECORD_T* record) {
    sem_wait(&add_sem);
    pthread_mutex_lock(&lock);
    if (count == capacity) resize();
    memcpy(&connections[count], record, sizeof(TCP_CONNECTION_RECORD_T));
    count++;
    pthread_mutex_unlock(&lock);
    sem_post(&add_sem);
}

void dynamic_array_remove(const char* client_ip) {
    size_t i;
    for (i = 0; i < count; ++i) {
        if (!strcmp(dynamic_array_get(i)->CLIENT_IP, client_ip)) {
            pthread_mutex_lock(&lock);
            memmove(&connections[i], &connections[i+1], (count-i-1)*sizeof(TCP_CONNECTION_RECORD_T));
            --capacity;
            --count;
            pthread_mutex_unlock(&lock);
            break;
        }
    }
}

void resize() {
    TCP_CONNECTION_RECORD_T* new_array = realloc(connections, capacity * GROWTH_FACTOR * sizeof(TCP_CONNECTION_RECORD_T));
    if (!new_array) return; // Handle error: out of memory
    connections = new_array;
    capacity *= GROWTH_FACTOR;
}
