["```python
import os
import sys
import hashlib
import time
import zipfile
import threading
from concurrent.futures import ThreadPoolExecutor
from shutil import ignore_patterns, copyfileobj, CopiedFileError
from subprocess import call

class SHA256Hash:
    def __init__(self, directory, vcs='', log_level='info', compress=False):
        self.directory = directory
        self.vcs = vcs
        self.log_level = log_level
        self.compress = compress
        self.hashmap = {}
        self.report = []

    def _get_chunked_fileobj(self, filepath, chunk_size=2 ** 22):
        with open(filepath, 'rb') as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                yield data

    def _hash_segment(self, hasher, segment):
        hasher.update(segment)

    def _hash_file(self, filepath):
        hasher = hashlib.sha256()
        segment_count = 0
        total_size = os.path.getsize(filepath)
        start = time.time()

        with self._get_chunked_fileobj(filepath) as segment:
            for chunk in segment:
                self._hash_segment(hasher, chunk)
                segment_count += 1

        end = time.time()
        file_size = total_size / (1024 ** 3)
        segment_size = segment_count * len(chunk) / (1024 ** 2)
        self.report.append({
            'file': filepath,
            'size': file_size,
            'segments': segment_count,
            'segment_size': segment_size,
            'time': end - start
        })

        return hasher.hexdigest()

    def _hash_dir(self, dirpath):
        if os.path.exists(dirpath) and self._exists_in_map(dirpath):
            print(f'{dirpath} already exists with the same hash. Skipping...')
            return None

        hasher = hashlib.sha256()

        for root, _, files in sorted(os.walk(dirpath), key=lambda x: x[0]):
            for file in files:
                file_path = os.path.join(root, file)
                if not self._is_ignore(file_path):
                    hashed = self._hash_file(file_path)
                    if hashed is not None:
                        self.hashmap[dirpath] = hashed
                        self.report.append({'type': 'file', 'path': file_path})

            for symlink in os.listdir(root):
                symlink_path = os.path.join(root, symlink)
                if os.path.islink(symlink_path):
                    target_path = os.readlink(symlink_path)
                    self._hash_dir(target_path)

        return hashed

    def _get_report(self):
        if not self.compress:
            return '\n'.join([str(item) for item in self.report])

        with zipfile.ZipFile('report.zip', mode='w') as zf:
            for item in self.report:
                if isinstance(item, dict):
                    if item['type'] == 'file':
                        file_path = item['path']
                        with open(file_path, 'rb') as f:
                            zf.writelines(f)
                    else:
                        zf.writestr(str(item).encode(), arcname='report.txt')
                elif isinstance(item, bytes):
                    zf.writestr(item, arcname='report.txt')

    def _is_ignore(self, path):
        return any(p in path for p in ('.svn', '.git', '_macosx'))

    def _exists_in_map(self, dirpath):
        return dirpath in self.hashmap

    def run(self):
        if self.vcs:
            call([self.vcs, 'checkout', '-f', self.directory])

        self._hash_dir(self.directory)

        if not self._exists_in_map(self.directory):
            if self.compress:
                print('Directory structure has changed. Generating new hash...')
            else:
                print(f'New directory structure generated with hash: {hex(int(hash(self.directory)))[2:].zfill(32)}')
        else:
            if self.compress:
                print(f'Directory structure unchanged with existing hash. Skipping commit...')
            else:
                print(f'No changes detected in the directory structure.')

        self._get_report()
```

