[' Here is a high-level design and implementation of the described Python function, leveraging libraries such as `os`, `json`, `shutil`, `Pillow` (for image processing), `hashlib` (for SHA-256 hashing), `threading` (for parallel processing), `multiprocessing` (for distributed processing), and `Redis` (for job tracking).

```python
import os, json, sys
from PIL import Image, ImageEnhance
import hashlib
import threading
from multiprocessing import Pool
import redis

def load_config(filepath):
    with open(filepath) as f:
        config = json.load(f)

    return config

def resize_and_enhance(image, dim, contrast, sharpen):
    img = Image.open(image).convert('RGB')
    img.thumbnail(dim)

    enhancer = ImageEnhance.Contrast(img)
    enhanced = enhancer.enhance(contrast / 100)

    sharpener = ImageEnhance.Sharpness(enhanced)
    enhanced = sharpener.enhance(sharpen)

    return enhanced

def process_image(image, dim, contrast, sharpen, output_dir):
    enhanced = resize_and_enhance(image, dim, contrast, sharpen)

    hashed = hash_image(enhanced)
    metadata = {'original': image, 'dimensions': dim, 'transformations': ['resize', 'contrast', 'sharpen']}

    output_path = os.path.join(output_dir, f"{os.path.basename(image)}_{'_enhanced' if '_enhanced' not in image else ''}.jpg")
    enhanced.save(output_path)

    return hashed, metadata

def hash_image(img):
    imgbytes = img.tobytes()
    return hashlib.sha256(imgbytes).hexdigest()

def check_integrity(output_dir, hashes):
    existing_hashes = set()

    for f in os.listdir(output_dir):
        if not f.endswith(".jpg"):
            continue

        hash_fname = f[:-4] + '_hash'
        if hash_fname in os.listdir(output_dir):
            existing_hashes.add(open(os.path.join(output_dir, hash_fname), 'r').read().strip())

    return not hashes <= existing_hashes

def save_metadata(image, metadata):
    # Save metadata to a database or file system of choice
    pass

def process_directory(config, redis_conn=None):
    output_dir = config['output']
    if os.path.exists(output_dir):
        os.makedirs(output_dir + '_temp', exist_ok=True)

    image_paths = [os.path.join(config['input'], path) for path in config['images']]
    dim, contrast, sharpen = config['dimensions'], config['contrast'], config['sharpen']
    threads = config.get('threads', 4)

    if redis_conn:
        job_queue = redis_conn.queue('image_processing')
        results_queue = redis_conn.queue('image_results')

    hashes, metadatas = [], []

    if threads == 1:
        for image in image_paths:
            try:
                hashed, metadata = process_image(image, dim, contrast, sharpen, output_dir + '_temp')
                hashes.append(hashed)
                metadatas.append(metadata)

                if redis_conn:
                    job_queue.enqueue((image, metadata))
            except Exception as e:
                print(f"Error processing {image}: {e}")
    else:
        with Pool(threads) as p:
            results = p.map(process_image, image_paths, chunksize=10)
            hashes, metadatas = list(zip(*results))

            if redis_conn:
                for result in results:
                    job_queue.enqueue(result)

    if not check_integrity(output_dir + '_temp', hashes):
        shutil.copytree(output_dir + '_temp', output_dir)
        os.remove(os.path.join(output_dir + '_temp', '_hash'))

        for hashed, metadata in zip(hashes, metadatas):
            save_metadata(hashed, metadata)
    else:
        print("Integrity check failed; skipping.")

def main():
    config = load_config(sys.argv[1])

    redis_conn = redis.StrictRedis(host=config['redis']['host'], port=config['redis']['port'])

    process_directory(config, redis_conn)

```

The code above defines a `process_image()` function that resizes and enhances an image, calculates its SHA-256 hash, and saves the result to a temporary directory. The function `process_directory()` handles processing all images in a given directory according to the provided configuration, ensuring integrity checks and handling exceptions gracefully.

The main entry point is the `main()` function that loads the JSON config, initializes a Redis connection (if necessary), and calls `process_directory()`. This can be easily extended for batch processing multiple directories by iterating over the list of input directories in the configuration file.

For large-scale deployments with distributed processing, you can modify the function to accept additional parameters such as a message queue name, number of worker machines, etc., and adapt the job submission and results handling accordingly. Additionally, implementing a priority level for each image file would require modifying the `process_directory()` function to dynamically adjust the worker assignment based on the specified priority levels.']

[" Here's a high-level design for the required Python function using the `concurrent.futures` and `pandas` libraries, which support asynchronous processing and handling heterogeneous datasets respectively. The code below doesn't include extensive error handling, detailed logging, or specific optimizations for varying execution times. You can add these features according to your project requirements.

```python
import concurrent.futures
import pandas as pd
import abc
import typing
from typing import Iterable, List, Dict, Any

class TransformStage(metaclass=abc.ABCMeta):
    @abc.abstractmethod
    def transform(self, data: DataType) -> DataType:
        pass

class DataChunk:
    def __init__(self, data: DataType, metadata: Dict[str, Any] = None):
        self.data = data
        self.metadata = metadata or {}

class StreamProcessor:
    def __init__(self, stages: List[TransformStage], chunk_size: int):
        self.stages = stages
        self.chunk_size = chunk_size

    async def _process_chunk(self, data_chunk: DataChunk) -> DataChunk:
        output = data_chunk.data
        for stage in self.stages:
            output = await stage.transform(output)
        return DataChunk(output, data_chunk.metadata)

    async def process(self, input_data: Iterable[DataType]) -> List[DataChunk]:
        if isinstance(input_data, pd.core.frame.DataFrame):
            chunks = [DataChunk(data) for i, data in enumerate(pd.iterate_chunks(input_data, self.chunk_size))]
        else:
            chunks = [DataChunk(data) for data in itertools.islice(input_data, None, None, self.chunk_size)]

        processed_chunks = []
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = {executor.submit(self._process_chunk, chunk) for chunk in chunks}
            for future in concurrent.futures.as_completed(futures):
                processed_chunks.append(future.result())
        return processed_chunks

# Usage:
stages = [MyFilterStage(), MyAggregateStage(), MyTransformStage()]
processor = StreamProcessor(stages, chunk_size=1024)
processed_data = processor.process(large_heterogeneous_dataset)
```

