2. Implement the dynamic array functions:

```c
DYNAMIC_ARRAY_T* create_dynamic_array(size_t initial_capacity) {
    DYNAMIC_ARRAY_T* array = (DYNAMIC_ARRAY_T*)malloc(sizeof(DYNAMIC_ARRAY_T));
    if (!array) return NULL;

    array->capacity = initial_capacity;
    array->size = 0;
    array->elements = (NR_RRC_UE_CONTEXT_T*)calloc(initial_capacity, sizeof(NR_RRC_UE_CONTEXT_T));
    if (!array->elements) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->array_lock, NULL);
    pthread_spin_init(&array->spin_lock, PTHREAD_SPIN_TRYLOCK);

    return array;
}

void destroy_dynamic_array(DYNAMIC_ARRAY_T* array) {
    if (!array || !array->elements) return;

    for (size_t i = 0; i < array->size; ++i) {
        free(array->elements[i].phich_resource.phich_config_index);
    }
    free(array->elements);
    free(array);
}

void resize_dynamic_array(DYNAMIC_ARRAY_T* array, size_t new_capacity) {
    if (new_capacity <= array->size) return;

    NR_RRC_UE_CONTEXT_T* temp_elements = realloc(array->elements, new_capacity * sizeof(NR_RRC_UE_CONTEXT_T));
    if (!temp_elements) {
        pthread_mutex_lock(&array->array_lock);
        return;
    }

    array->elements = temp_elements;
    memset(array->elements + array->size, 0, (new_capacity - array->size) * sizeof(NR_RRC_UE_CONTEXT_T));
    array->capacity = new_capacity;
}
```

3. Implement the add and remove functions:

```c
size_t find_cell_id(const DYNAMIC_ARRAY_T* array, int cell_id) {
    for (size_t i = 0; i < array->size; ++i) {
        pthread_mutex_lock(&array->elements[i].lock);
        if (array->elements[i].cell_id == cell_id) {
            pthread_mutex_unlock(&array->elements[i].lock);
            return i;
        }
        pthread_mutex_unlock(&array->elements[i].lock);
    }
    return -1;
}

void add_context(DYNAMIC_ARRAY_T* array, const NR_RRC_UE_CONTEXT_T* context) {
    // Resize if necessary
    pthread_mutex_lock(&array->array_lock);
    if (array->size == array->capacity) resize_dynamic_array(array, array->capacity * 2);
    pthread_mutex_unlock(&array->array_lock);

    // Lock the context and the array for concurrent access safety
    pthread_mutex_lock(&context->lock);
    pthread_mutex_lock(&array->array_lock);

    // Assign random values for PAGING_REQUEST_FLAG, PHICH配置索引
    context->paging_request_flag = rand() % 2;
    context->phich_resource.phich_config_index = malloc(sizeof(int));
    *context->phich_resource.phich_config_index = rand() % PHICH_CONFIG_INDEX_MAX;

    // Add the context to the array
    array->elements[array->size++] = *context;

    pthread_mutex_unlock(&array->array_lock);
    pthread_mutex_unlock(&context->lock);
}

void remove_context(DYNAMIC_ARRAY_T* array, int cell_id) {
    size_t index = find_cell_id(array, cell_id);
    if (index == -1) return;

    pthread_mutex_lock(&array->array_lock);
    pthread_mutex_lock(&array->elements[index].lock);

    // Move the last element to the vacated position and update the size
    NR_RRC_UE_CONTEXT_T temp = array->elements[array->size - 1];
    array->elements[index] = temp;
    --array->size;

    pthread_mutex_unlock(&array->elements[index].lock);
    pthread_mutex_unlock(&array->array_lock);
}
```

