['```c
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <sys/socket.h>
#include <time.h>
#include <unistd.h>

#define MAX_QUERIES_PER_SECOND 10
#define TIMEOUT 5

static pthread_mutex_t queries_mutex = PTHREAD_MUTEX_INITIALIZER;
static int queries_count = 0;
static time_t last_query_time = 0;

typedef struct {
    sockaddr_storage addr;
    size_t len;
} ip_address;

int dns_resolve(const char *hostname, ip_address *ip, int resolve_ipv6) {
    struct addrinfo hints, *res, *ptr;
    int err = 0;
    timeval timeout = {TIMEOUT, 0};

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = resolve_ipv6 ? AF_INET6 : AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_NUMERICHOST | AI_CANONNAME;

    err = getaddrinfo(hostname, NULL, &hints, &res);
    if (err != 0) {
        return errno;
    }

    pthread_mutex_lock(&queries_mutex);
    queries_count++;
    struct timeval now;
    gettimeofday(&now, NULL);
    double elapsed = (now.tv_sec - last_query_time.tv_sec) + (now.tv_usec - last_query_time.tv_usec) / 1000000.0;
    if (elapsed < 1.0 / MAX_QUERIES_PER_SECOND) {
        pthread_mutex_unlock(&queries_mutex);
        usleep(1000000 * (1.0 / MAX_QUERIES_PER_SECOND - elapsed));
        pthread_mutex_lock(&queries_mutex);
    }
    last_query_time = now;
    ptr = res;
    ip->len = ptr->ai_addrlen;
    memcpy(&ip->addr, ptr->ai_addr, ip->len);
    freeaddrinfo(res);
    pthread_mutex_unlock(&queries_mutex);

    return 0;
}
```
