    da->capacity = 0;
    da->size = 0;
    return da;
}

void da_push(DYNAMIC_ARRAY_T* da, NR_RRC_UE_CONTEXT_T context) {
    pthread_mutex_lock(&da->lock);
    if (da->capacity == da->size) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : INITIAL_CAPACITY;
        NR_RRC_UE_CONTEXT_T* temp = realloc(da->data, new_capacity * sizeof(NR_RRC_UE_CONTEXT_T));
        if (!temp) {
            pthread_mutex_unlock(&da->lock);
            return;
        }
        da->data = temp;
        da->capacity = new_capacity;
    }
    da->data[da->size++] = context;
    pthread_mutex_unlock(&da->lock);
}

bool da_remove(DYNAMIC_ARRAY_T* da, uint32_t cell_id) {
    pthread_mutex_lock(&da->lock);
    if (da->size == 0) {
        pthread_mutex_unlock(&da->lock);
        return false;
    }

    size_t i = 0;
    for (; i < da->size; ++i) {
        if (da->data[i].cell_id == cell_id) break;
    }

    if (i == da->size) {
        pthread_mutex_unlock(&da->lock);
        return false;
    }

    memmove(da->data + i, da->data + i + 1, --da->size - i);
    pthread_mutex_unlock(&da->lock);
    return true;
}
