#include <pthread.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    int UE_ID;
    int SCTP_STREAM_ID;
    time_t LAST_TRANSACTION_TIME;
} UE_CONTEXT_T;

typedef struct NODE {
    UE_CONTEXT_T context;
    struct NODE* next;
    pthread_mutex_t mutex;
} NODE;

struct HEAP {
    NODE** array;
    int capacity;
    int size;
};

void init_heap(struct HEAP* heap, int capacity) {
    heap->capacity = capacity;
    heap->size = 0;
    heap->array = calloc(capacity, sizeof(NODE*));
}

void resize_heap(struct HEAP* heap) {
    int new_capacity = heap->capacity * 2;
    NODE** new_array = realloc(heap->array, new_capacity * sizeof(NODE*));
    if (new_array == NULL) {
        fprintf(stderr, "Failed to resize heap\n");
        exit(EXIT_FAILURE);
    }
    heap->array = new_array;
    heap->capacity = new_capacity;
}

int hash(int key) {
    return key % heap->capacity;
}

void insert(struct HEAP* heap, UE_CONTEXT_T context) {
    int index = hash(&context.UE_ID);
    if (heap->size == heap->capacity) resize_heap(heap);
    NODE** slot = &heap->array[index];
    while (*slot != NULL) slot = &((*slot)->next);
    *slot = malloc(sizeof(NODE));
    if (!(*slot)) {
        fprintf(stderr, "Failed to allocate memory for UE context\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&((*slot)->mutex), NULL);
    (*slot)->context = context;
    (*slot)->next = NULL;
}

UE_CONTEXT_T* find(struct HEAP* heap, int UE_ID) {
    int index = hash(UE_ID);
    NODE** slot = &heap->array[index];
    while (*slot != NULL) {
        if ((*slot)->context.UE_ID == UE_ID) {
            pthread_mutex_lock(&((*slot)->mutex));
            UE_CONTEXT_T* context = &(*slot)->context;
            pthread_mutex_unlock(&((*slot)->mutex));
            return context;
        }
        slot = &((*slot)->next);
    }
    return NULL;
}

void update(struct HEAP* heap, int UE_ID, time_t current_time) {
    UE_CONTEXT_T* context = find(heap, UE_ID);
    if (context == NULL) {
        fprintf(stderr, "Failed to find UE context\n");
        return;
    }
    context->LAST_TRANSACTION_TIME = current_time;
}

void delete(struct HEAP* heap, int UE_ID) {
    int index = hash(UE_ID);
    NODE** slot = &heap->array[index];
    NODE** prev = NULL;
    while (*slot != NULL) {
        if ((*slot)->context.UE_ID == UE_ID) {
            pthread_mutex_lock(&((*slot)->mutex));
            NODE* temp = *slot;
            if (prev == NULL) {
                *slot = (*slot)->next;
            } else {
                prev->next = (*slot)->next;
            }
            pthread_mutex_unlock(&((*slot)->mutex));
            free(temp);
            break;
        }
        prev = slot;
        slot = &(*slot)->next;
    }
}
```

This code provides a basic dynamic collection management using an array of linked lists (hash table). The `UE_CONTEXT_T` struct holds the necessary data for each UE session, and each element in the hash table is a node containing a single context. The `NODE` struct includes a mutex to ensure concurrent access safety.

The provided functions include initializing the heap, inserting new entries, finding an entry by UE_ID, updating an existing entry's transaction time, and deleting an entry by UE_ID. Error handling is rudimentary but sufficient for this task; it logs an error message and exits in case of failure.

For better performance under varying loads, the heap resizes itself when it reaches capacity. The hash function is simple but effective, using a single variable to index into the array based on UE_ID. Concurrent access to the data structures is managed through mutex locks.']

