#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemPoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct MemPoolNode *next;
} MemPoolNode;

struct MemPool {
    MemPoolNode *head, *tail;
    size_t size;
};

MemPool* createMemoryPool(size_t initialSize) {
    MemPool *pool = (MemPool *)malloc(sizeof(MemPool));
    if (!pool) return NULL;
    pool->head = pool->tail = NULL;
    pool->size = initialSize;
    pool->next = (MemPoolNode *)calloc(initialSize, sizeof(MemPoolNode));
    if (!pool->next) {
        free(pool);
        return NULL;
    }
    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* acquireFromMemoryPool(MemPool *pool) {
    if (pool->head == NULL) {
        MemPoolNode *newNode = (MemPoolNode *)malloc(sizeof(MemPoolNode));
        if (!newNode) return NULL;
        memcpy(&newNode->data, pool->next, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pool->head = newNode;
    }
    MemPoolNode *tmp = pool->head;
    pool->head = tmp->next;
    if (pool->head == NULL) pool->tail = NULL;
    return &tmp->data;
}

void releaseToMemoryPool(MemPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->crc_indication.crcflag = rand() % 2; // Set CRCFLAG randomly for reuse
    if (pool->tail == NULL) pool->head = pool->tail = (MemPoolNode *)pdu;
    else pool->tail->next = (MemPoolNode *)pdu;
}

typedef struct Container {
    NFAPI_CRC_INDICATION_PDU_T **data;
    size_t size, count;
    pthread_mutex_t lock;
    MemPool *pool;
} Container;

Container* createContainer(size_t maxSize, size_t concurrencyLimit) {
    Container *container = (Container *)malloc(sizeof(Container));
    if (!container) return NULL;
    container->data = (NFAPI_CRC_INDICATION_PDU_T**)calloc(maxSize, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!container->data) {
        free(container);
        return NULL;
    }
    container->size = maxSize;
    container->count = 0;
    container->pool = createMemoryPool(concurrencyLimit);
    if (!container->pool) {
        free(container->data);
        free(container);
        return NULL;
    }
    pthread_mutex_init(&container->lock, NULL);
    return container;
}

void populateNfapiCrcIndications(Container *container, RX_UE_INFORMATION_TAG rxInfo, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = acquireFromMemoryPool(container->pool);
    if (pdu) {
        pthread_mutex_lock(&container->lock);
        memcpy(&pdu->rx_ue_info, &rxInfo, sizeof(RX_UE_INFORMATION_TAG));
        pdu->rnti = rnti;
        container->data[rnti] = pdu;
        ++container->count;
        if (container->count == container->size) {
            size_t newSize = container->size * 2;
            NFAPI_CRC_INDICATION_PDU_T **newData = realloc(container->data, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            if (newData) {
                container->data = newData;
                container->size = newSize;
            } else {
                pthread_mutex_unlock(&container->lock);
                // Handle memory allocation failure here, e.g., log an error and return an appropriate status code
            }
        }
        pthread_mutex_unlock(&container->lock);
    } else {
        // Handle memory allocation failure here, e.g., log an error and return an appropriate status code
    }
}

NFAPI_CRC_INDICATION_PDU_T* getIndicationByRnti(Container *container, RNTI rnti) {
    pthread_mutex_lock(&container->lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = container->data[rnti];
    if (pdu) ++container->count;
    pthread_mutex_unlock(&container->lock);
    return pdu;
}

void removeIndicationByRnti(Container *container, RNTI rnti) {
    pthread_mutex_lock(&container->lock);
    if (container->count > 0 && container->data[rnti]) {
        --container->count;
        NFAPI_CRC_INDICATION_PDU_T *pdu = container->data[rnti];
        container->data[rnti] = NULL;
        releaseToMemoryPool(container->pool, pdu);
    }
    pthread_mutex_unlock(&container->lock);
}

void updateCrcFlagByRnti(Container *container, RNTI rnti) {
    pthread_mutex_lock(&container->lock);
    if (container->count > 0 && container->data[rnti]) {
        container->data[rnti]->crc_indication.crcflag = rand() % 2;
    }
    pthread_mutex_unlock(&container->lock);
}
```

