    uint8_t tx_power_level;
    uint8_t* tx_frame_tag;
    pthread_mutex_t lock;
} NFAPI_MESSAGE_T;

NFAPI_MESSAGE_T* init_linked_list(size_t N) {
    NFAPI_MESSAGE_T **head = (NFAPI_MESSAGE_T**) malloc(sizeof(NFAPI_MESSAGE_T*) * N);
    if (!head) {
        perror("Failed to allocate memory for linked list head");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        NFAPI_MESSAGE_T* msg = malloc(sizeof(NFAPI_MESSAGE_T));
        if (!msg) {
            perror("Failed to allocate memory for message");
            free(head); // Clean up in case of error
            return NULL;
        }

        msg->band_id = rand() % 0xFFFF + 1; // Valid band ID within the range (1-65535)
        msg->tx_power_level = (uint8_t)(rand() % TX_POWER_MAX);

        size_t alignment = sizeof(void*) + 64; // Align to a 64-byte boundary for improved cache utilization
        if (posix_memalign(msg->tx_frame_tag, alignment, sizeof(uint8_t) * MODULATION_TYPE_SIZE + BANDWIDTH_SIZE)) {
            perror("Failed to align memory for tx_frame_tag");
            free(msg); // Clean up in case of error
            free(head); // Clean up head in case of error
            return NULL;
        }

        pthread_mutex_init(&msg->lock, NULL); // Initialize mutex for concurrent access protection

        head[i] = msg;
    }

    return head[0];
}
