typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_size) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_size;
    array->length = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void add_to_dynamic_array(DynamicArray* array, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&array->mutex);

    if (array->length >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!temp_data) {
            pthread_mutex_unlock(&array->mutex);
            return;
        }

        array->data = temp_data;
        array->capacity = new_capacity;
    }

    memcpy(array->data + array->length, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->length++;
    pthread_mutex_unlock(&array->mutex);
}

bool remove_from_dynamic_array(DynamicArray* array, uint32_t rnti) {
    pthread_mutex_lock(&array->mutex);

    size_t i;
    for (i = 0; i < array->length; ++i) {
        if (array->data[i].rnti == rnti) {
            memmove(array->data + i, array->data + i + 1, (array->length - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --array->length;
            pthread_mutex_unlock(&array->mutex);
            return true;
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return false;
}

void update_crcflag(DynamicArray* array, uint32_t rnti, bool crcflag) {
    pthread_mutex_lock(&array->mutex);

    size_t i;
    for (i = 0; i < array->length; ++i) {
        if (array->data[i].rnti == rnti) {
            array->data[i].crc_indication.crcflag = crcflag;
            pthread_mutex_unlock(&array->mutex);
            return;
        }
    }

    pthread_mutex_unlock(&array->mutex);
}

