['```python
import hashlib
import threading
import queue
from Crypto.Cipher import AES, Camellia
from Crypto.PublicKey import RSA
from Crypto.Signature import pkcs1_15 as rsahash
from Crypto.Util.Padding import PKCS13_OAEP

class CryptographicLibrary:
    def __init__(self):
        self.resources = {}

    def get_cipher(self, cipher_type):
        if cipher_type not in self.resources:
            if cipher_type == 'AES':
                self.resources[cipher_type] = AES.new
            elif cipher_type == 'Camellia':
                self.resources[cipher_type] = Camellia.new
            else:
                raise ValueError(f"Invalid cipher type: {cipher_type}")
        return self.resources[cipher_type]

    def get_digest(self, digest_func):
        if digest_func not in self.resources:
            if digest_func == 'MD5':
                self.resources[digest_func] = hashlib.md5
            elif digest_func == 'SHA1':
                self.resources[digest_func] = hashlib.sha1
            else:
                raise ValueError(f"Invalid digest function: {digest_func}")
        return self.resources[digest_func]

    def get_rsa(self):
        if 'RSA' not in self.resources:
            self.resources['RSA'] = RSA.generate
        return self.resources['RSA']

    def md5_file(self, file_path):
        hash_obj = self.get_digest('MD5')()
        with open(file_path, 'rb') as f:
            chunk = f.read(4096)
            while chunk:
                hash_obj.update(chunk)
                chunk = f.read(4096)
        return hash_obj.hexdigest()

    def __del__(self):
        for res in self.resources.values():
            if hasattr(res, 'cleanup'):
                res.cleanup()

def threaded_function(queue, func, args=()):
    while True:
        task = queue.get()
        if not task: break
        result = func(*task)
        queue.task_done()
        print(f"Task {task} completed with result {result}")

if __name__ == "__main__":
    q = queue.Queue()
    t = threading.Thread(target=threaded_function, args=(q, CryptographicLibrary().md5_file, ('path/to/file',)))
    for i in range(4):
        t.start()
    q.join()
```

