#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PDU_COUNT 100
#define RNTI_START 123456
#define RNTI_END 987654

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint32_t rxiit;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t pdu_list_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;

void init_pdus(size_t count) {
    if (count > MAX_PDU_COUNT) {
        fprintf(stderr, "Error: Requested PDU count exceeds the maximum limit.\n");
        return;
    }

    pthread_mutex_lock(&pdu_list_mutex);

    free(pdu_list);
    pdu_list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_list) {
        fprintf(stderr, "Error: Failed to allocate memory for PDUs.\n");
        pthread_mutex_unlock(&pdu_list_mutex);
        return;
    }

    size_t index = 0;
    for (; index < count; ++index) {
        pdu_list[index].rxiit = index;
        pdu_list[index].rnti = RNTI_START + index;
        if ((RNTI_START + index) >= RNTI_END)
            pdu_list[index].crc_indication_rel8_tag = (uint8_t)(rand() % 2);
    }

    pthread_mutex_unlock(&pdu_list_mutex);
}

void destroy_pdus() {
    if (!pdu_list) return;

    pthread_mutex_lock(&pdu_list_mutex);
    free(pdu_list);
    pdu_list = NULL;
    pthread_mutex_unlock(&pdu_list_mutex);
}
```

