['```java
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.function.Function;
import java.util.stream.Collectors;

public class StreamAggregator {
    private Map<String, InputStream> inputStreams = new HashMap<>();
    private OutputStream outputStream;
    private ExecutorService executor = Executors.newFixedThreadPool(10);
    private Cache cache = new Cache();
    private Filter filter;
    private Aggregator aggregator;

    public StreamAggregator(OutputStream outputStream, Filter filter, Aggregator aggregator) {
        this.outputStream = outputStream;
        this.filter = filter;
        this.aggregator = aggregator;
    }

    public void addInputStream(String id, InputStream inputStream) {
        inputStreams.put(id, inputStream);
        executor.submit(inputStream::pollAndProcess);
    }

    public void process() throws InterruptedException {
        while (!Thread.currentThread().isInterrupted()) {
            // Poll metrics from each input stream and aggregate them based on user-defined criteria
            Metrics aggregatedMetrics = aggregator.aggregate(cache.getMetrics());

            // Filter the aggregated metrics based on user-defined criteria
            Metrics filteredMetrics = filter.apply(aggregatedMetrics);

            // Export the filtered metrics to an external monitoring system or data store
            outputStream.send(filteredMetrics);

            // Sleep for a short duration to allow time for other tasks and minimize CPU usage
            TimeUnit.MILLISECONDS.sleep(100);
        }
    }

    public interface InputStream {
        Metric pollAndProcess();
    }

    public static class Metric {
        private final String id;
        private final Instant timestamp;
        private final String name;
        private final Map<String, String> tags;
        private Object value; // T can vary based on the source

        public Metric(String id, Instant timestamp, String name, Map<String, String> tags, Object value) {
            this.id = id;
            this.timestamp = timestamp;
            this.name = name;
            this.tags = tags;
            this.value = value;
        }

        // Getters and setters for each field
    }

    public interface OutputStream {
        void send(Metrics metrics) throws InterruptedException;
    }

    public static class Cache {
        private final ConcurrentLinkedQueue<Metric> queue = new ConcurrentLinkedQueue<>();

        public Metrics getMetrics() {
            return queue.stream().collect(Collectors.groupingBy(Metric::getId, Collectors.toList()))
                    .entrySet().stream()
                    .map(entry -> new Metrics(entry.getKey(), Instant.now(), entry.getValue().stream()
                            .sorted((m1, m2) -> m1.getTimestamp().compareTo(m2.getTimestamp()))
                            .collect(Collectors.toList())))
                    .collect(Collectors.toMap(Metrics::getId, Function.identity()))
                    .values().stream().collect(Collectors.toList());
        }
    }

    public static class Metrics {
        private final String id;
        private final Instant timestamp;
        private final List<Metric> metrics;

        public Metrics(String id, Instant timestamp, List<Metric> metrics) {
            this.id = id;
            this.timestamp = timestamp;
            this.metrics = Collections.unmodifiableList(metrics);
        }

        // Getters for each field
    }

    public interface Filter {
        Metrics apply(Metrics metrics);
    }

    public interface Aggregator {
        Metrics aggregate(Metrics metrics);
    }
}
```

This Java code defines a `StreamAggregator` class that manages the ingestion, aggregation, and export of real-time metric data streams from multiple sources. It supports adding, filtering, and aggregating metrics based on user-defined criteria and handles high-throughput scenarios with low-latency guarantees using an ExecutorService and ConcurrentLinkedQueue.

The code includes a cache for buffering incoming metrics, a custom `Metrics` class to represent individual metric data, and interfaces for InputStream, OutputStream, Filter, Aggregator to allow modularity and extensibility. It also defines synchronous and asynchronous processing modes.

The error handling and recovery mechanisms are not explicitly defined in this code but could be implemented using try-catch blocks and retry policies for transient failures or by saving the state of the processing pipeline periodically to ensure fault-tolerance.

The choice of data format depends on the specific requirements and constraints of the application, but Prometheus, Graphite, or custom binary protocols can be easily integrated as InputStream implementations. The logging system can be implemented using java.util.logging, log4j2, or similar libraries for monitoring performance and health metrics.

The code is designed to handle concurrent processing, minimize memory footprint, and optimize for performance under high load conditions by efficiently managing incoming metric streams.']

