using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography.OpenSsl;
using System.Xml.Serialization;
using System.Threading;
using System.Diagnostics;

public class GameInitialization
{
    [XmlElement("TileSize")]
    public int TileSize { get; set; }

    [XmlElement("WorldWidth")]
    public int WorldWidth { get; set; }

    [XmlElement("WorldHeight")]
    public int WorldHeight { get; set; }

    [XmlElement("CameraSpeed")]
    public float CameraSpeed { get; set; }

    private CancellationTokenSource cts;
    private HashAlgorithm hashAlg = SHA256.Create();
    private OpenSslCipher cipher;

    public GameInitialization()
    {
        // Load configuration settings from XML file
        using (var xmlReader = XmlReader.Create("config.xml"))
        {
            var serializer = new XmlSerializer(typeof(GameInitialization));
            this = serializer.Deserialize(xmlReader) as GameInitialization;
        }
    }

    public unsafe OpenSslCipher processLevelWithCipher(string levelFilePath, int chunkSize, string openSslOperation)
    {
        cts = new CancellationTokenSource();
        var progressPercentage = new Progress<double>(percentage => Console.WriteLine($"Processing: {percentage}%"));
        using (var fileStream = File.OpenRead(levelFilePath))
        {
            var buffer = stackalloc byte[chunkSize];
            var cipherBuilder = OpenSslCipher.CreateBuilder();
            long totalRead = 0;

            try
            {
                await Task.Run(() =>
                {
                    while (true)
                    {
                        int readBytes = fileStream.Read(buffer, 0, buffer.Length);
                        if (readBytes <= 0) break;

                        totalRead += readBytes;

                        var md5Hash = MD5Hasher.CalculateHash(buffer);

                        // Perform OpenSSL operation here based on the provided command line option
                        // For simplicity, we'll assume "encrypt" and "decrypt" are the valid operations.
                        if (openSslOperation == "encrypt")
                            cipherBuilder.Update(buffer);
                        else if (openSslOperation == "decrypt")
                            cipherBuilder.Decrypt(buffer);

                        double percentage = Math.Round((totalRead * 100.0 / fileStream.Length), MidpointRounding.AwayFromZero);
                        progressPercentage.Report(percentage);

                        if (Thread.CurrentThread.IsInterrupted || cts.IsCancellationRequested)
                            throw new OperationCanceledException();
                    }
                }, cts.Token);

                // Finalize OpenSSL operation and get the cipher object
                cipher = cipherBuilder.ToCipher();
                cipher.Finalize();
            }
            catch (OperationCanceledException)
            {
                Console.WriteLine("Process interrupted or timed out.");
                if (cipher != null)
                    cipher.Dispose();
            }
        }

        return cipher;
    }

    private class MD5Hasher
    {
        public static byte[] CalculateHash(byte[] data)
        {
            var hash = hashAlg.ComputeHash(data);
            return hash;
        }
    }
}
```

