import json
import time
import concurrent.futures
from threading import Lock
import socket

class NodeStatus:
    def __init__(self, id, last_ping_time=0):
        self.id = id
        self.last_ping_time = last_ping_time
        self.status = "up"

def ping(node):
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    timeout = 5 # seconds
    result = sock.connect_ex((node.ip, node.port))
    if result == 0:
        sock.sendall(b"ping")
        response = sock.recv(1024).decode()
        if response != "pong":
            node.status = "down"
    else:
        node.status = "down"
    sock.close()

def monitorNetworkHealth(topology, num_concurrent_pings=100, interval=5):
    locked_nodes = {}
    locks = {node.id: Lock() for node in topology.nodes}
    with open("config.json", "r") as f:
        config = json.load(f)
        ping_interval = config["ping_interval"] * interval
        timeout = config["timeout"] * interval

    def worker(node):
        while True:
            locked_nodes[node.id].acquire()
            if node.status == "up":
                ping(node)
            locked_nodes[node.id].release()
            time.sleep(ping_interval)

    with concurrent.futures.ThreadPoolExecutor(max_workers=num_concurrent_pings) as executor:
        futures = {executor.submit(worker, node): node for node in topology.nodes}
        for future in concurrent.futures.as_completed(futures):
            if not future.result().exception():
                pass
            else:
                print("Error:", future.exception())
    # Generate the report and export it to a JSON file
