void manage_dataset() {
    size_t dataset_size = get_dataset_size();
    void *buffer = mmap(NULL, dataset_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (buffer == MAP_FAILED) {
        log("Error: Failed to allocate memory for the dataset");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    size_t chunk_size = get_chunk_size();
    size_t num_threads = get_num_threads();

    worker_arg_t *worker_args = malloc(num_threads * sizeof(worker_arg_t));
    if (!worker_args) {
        log("Error: Failed to allocate memory for worker arguments");
        exit(EXIT_FAILURE);
    }

    size_t remaining_data = dataset_size;
    size_t start = 0;
    size_t end;

    pthread_t *threads = malloc(num_threads * sizeof(pthread_t));
    if (!threads) {
        log("Error: Failed to allocate memory for threads");
        exit(EXIT_FAILURE);
    }

    // Initialize and start worker threads
    for (size_t i = 0; i < num_threads; ++i) {
        end = start + chunk_size > remaining_data ? remaining_data : start + chunk_size;
        worker_args[i].buffer = buffer;
        worker_args[i].buffer_size = dataset_size;
        worker_args[i].start = start;
        worker_args[i].end = end;
        worker_args[i].mutex = &mutex;
        pthread_create(&threads[i], NULL, worker, &worker_args[i]);

        start += chunk_size;
        remaining_data -= chunk_size;
    }

    // Wait for all worker threads to finish
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    munmap(buffer, dataset_size);
    free(worker_args);
    free(threads);
}

