    while (job_queue.size == sizeof(job_queue.jobs) && job_queue.front != job_queue.rear) {
        pthread_cond_wait(&job_queue.queue_cv, &job_queue.queue_lock);
    }

    if (job_queue.size == sizeof(job_queue.jobs)) {
        job_queue.rear = (job_queue.rear + 1) % sizeof(job_queue.jobs);
    }

    memcpy(&job_queue.jobs[job_queue.front], job, sizeof(*job));
    job_queue.front = (job_queue.front + 1) % sizeof(job_queue.jobs);
    job_queue.size++;
    pthread_cond_signal(&job_queue.queue_cv);
    pthread_mutex_unlock(&job_queue.queue_lock);
}

struct job pop_job() {
    struct job job;
    pthread_mutex_lock(&job_queue.queue_lock);
    while (job_queue.size == 0) {
        pthread_cond_wait(&job_queue.queue_cv, &job_queue.queue_lock);
    }

    memcpy(&job, &job_queue.jobs[job_queue.front], sizeof(job));
    job_queue.front = (job_queue.front + 1) % sizeof(job_queue.jobs);
    job_queue.size--;
