    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _memory_pool {
    size_t capacity;
    size_t allocated;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* memory_pool_init(size_t capacity) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for memory pool.\n");
        return NULL;
    }

    pool->capacity = capacity;
    pool->allocated = 0;
    pool->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        fprintf(stderr, "Failed to allocate memory for data in memory pool.\n");
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* memory_pool_acquire(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;

    if (pool->allocated < pool->capacity) {
        pdu = &pool->data[pool->allocated];
        pool->allocated++;
    } else {
        fprintf(stderr, "Memory pool is full. Cannot allocate more structures.\n");
    }

    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

void memory_pool_release(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    if (pdu >= pool->data && pdu < pool->data + pool->capacity) {
        pool->allocated--;
    } else {
        fprintf(stderr, "Trying to release invalid structure from memory pool.\n");
    }
    pthread_mutex_unlock(&pool->lock);
}

void serialize(const NFAPI_CRC_INDICATION_PDU_T *pdu, char *buffer, size_t buffer_size) {
    // Implement binary serialization here
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_pdu_manager_init(size_t num_structures, MemoryPool **memory_pool_ptr) {
    *memory_pool_ptr = memory_pool_init(num_structures);
    if (!*memory_pool_ptr) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = calloc(num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for pdus.\n");
        free(*memory_pool_ptr);
        *memory_pool_ptr = NULL;
        return NULL;
    }

    return pdus;
}
