from queue import Queue
from collections import defaultdict

class PrefixLeaf:
    def __init__(self, data=None):
        self.data = data
        self.children = [None] * 8

class OctreeNode:
    def __init__(self, level, parent=None):
        self.level = level
        self.parent = parent
        self.prefix_leaf = PrefixLeaf() if level == 0 else None
        self.children = [None] * 8

class Octree:
    def __init__(self, max_chunk_size=1e6):
        self.root = OctreeNode(-1)
        self.max_chunk_size = max_chunk_size
        self.current_chunk_data = []
        self.current_chunk_hash = None
        self.file_path = None
        self.sequence_number = None

    def _allocate_node(self, node):
        if not hasattr(node, 'children'):
            node.children = [None] * 8
            for i in range(8):
                self._allocate_node(node.children[i])

    def initialize(self, file_path):
