    sem_wait(&cache_mutex);
    size_t index = hash(num_frames, frame_width, frame_height, framerate) % cache_capacity;
    sem_post(&cache_mutex);

    if (index < num_cache_entries && memcmp(*config, &cache[index], sizeof(VIDEO_PROCESSOR_CONFIG)) == 0) {
        // Cache hit, return the existing configuration
        return SUCCESS;
    }

    // Perform synchronization before allocating resources to ensure thread-safety
    pthread_mutex_lock(&cache_map_mutex);

    if (num_cache_entries == cache_capacity) {
        // Cache is full, expand it and rehash the entries
