        pthread_mutex_unlock(&cache_map_mutex);
        return ERROR_MEMORY_ALLOCATION;
    }

    memcpy(*config, &cache[index], sizeof(VIDEO_PROCESSOR_CONFIG));
    // Customize the configuration based on priority and seed
    customize_configuration(*config, priority, seed);

    pthread_mutex_unlock(&cache_map_mutex);

    return SUCCESS;
}
