            xmlDocument.Load(reader);

            if (namespaceContext != null)
                xmlDocument.PreserveWhitespace = false;

            var nodes = xmlDocument.SelectNodes(xpathExpression, namespaceContext != null ? xmlDocument.CreateNavigator() : null);

            int index = 0;
            var nodeEnumerator = nodes.GetEnumerator();

            if (!nodeEnumerator.MoveNext())
                throw new Exception("No elements found.");

            var cacheKey = CreateCacheKey(xpathExpression, attributeFilter);
            ObjectEntry entry = _cache.Get(cacheKey);

            while (nodeEnumerator.MoveNext())
