                {
                    result.AddRange((await ProcessNodeAsync(nodeEnumerator.Current, attributeFilter)).ToList());

                    if (result.Count > 50) // Limit the number of elements returned to 50 for efficiency
                        break;

                    entry = _cache.Add(cacheKey, result, new CacheItemPolicy { AbsoluteExpiration = DateTimeOffset.Now.AddMinutes(1) });
                }
                else
                {
                    result.AddRange(entry.Value as List<ElementData>);
                }

                index++;
            }
        }

        return result;
    }

    private static string CreateCacheKey(string xpathExpression, string attributeFilter) => $"{xpathExpression}:{attributeFilter}";

    private async Task<IEnumerable<ElementData>> ProcessNodeAsync(XmlNode node, string attributeFilter = null)
    {
        var elementDataList = new List<ElementData>();

        foreach (var child in node.ChildNodes.OfType<XmlElement>())
        {
            elementDataList.AddRange(await ProcessNodeAsync(child, attributeFilter));
        }

        foreach (var attribute in node.Attributes)
        {
            if (attributeFilter == null || attributeFilter.Equals(attribute.Name, StringComparison.OrdinalIgnoreCase))
                elementDataList.Add(new ElementData { Name = node.Name, AttributeValues = new Dictionary<string, string> { { attribute.Name, attribute.Value } }, ChildElements = elementDataList, Data = node });
        }

