#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 5000
#define RNTI_RANGE (1 << 16) // Define your preferred RNTI range here
#define MEMORY_THRESHOLD 0.8

typedef struct {
    uint32_t LBR_ID;
    uint16_t RNTI;
    int SNR;
    time_t timestamp;
    struct PacketInfo PACKET_INFO;
} LTE_PDCP_RX_PDU;

typedef struct MemPool {
    LTE_PDCP_RX_PDU* buffer;
    size_t capacity;
    size_t count;
} MemPool;

MemPool mem_pool;
pthread_rwlock_t rwlock; // Read-write lock
pthread_mutex_t memory_mutex; // Mutex for memory pool management

void init() {
    mem_pool.buffer = malloc(MAX_ELEMENTS * sizeof(LTE_PDCP_RX_PDU));
    if (!mem_pool.buffer) {
        fprintf(stderr, "Failed to allocate memory for data array.\n");
        exit(EXIT_FAILURE);
    }
    mem_pool.capacity = MAX_ELEMENTS;
    mem_pool.count = 0;

    pthread_rwlock_init(&rwlock, NULL);
    pthread_mutex_init(&memory_mutex, NULL);
}

void garbage_collection() {
    // Implement memory garbage collection when memory usage exceeds MEMORY_THRESHOLD.
}

int validate(const LTE_PDCP_RX_PDU* data) {
    if (data->LBR_ID < 0 || data->SNR < -100 || data->SNR > 60 || data->RNTI >= RNTI_RANGE) {
        fprintf(stderr, "Invalid input data: LBR_ID=%u, SNR=%d, RNTI=%u\n", data->LBR_ID, data->SNR, data->RNTI);
        return 1;
    }
    return 0;
}

void add(LTE_PDCP_RX_PDU* data) {
    if (validate(data)) return;

    pthread_rwlock_wrlock(&rwlock);
    if (mem_pool.count == mem_pool.capacity) {
        LTE_PDCP_RX_PDU* new_buffer = realloc(mem_pool.buffer, (mem_pool.capacity * 2) * sizeof(LTE_PDCP_RX_PDU));
        if (!new_buffer) {
            fprintf(stderr, "Failed to resize memory pool.\n");
            pthread_rwlock_unlock(&rwlock);
            return;
        }
        mem_pool.capacity *= 2;
        mem_pool.buffer = new_buffer;
    }
    memcpy(&mem_pool.buffer[mem_pool.count], data, sizeof(LTE_PDCP_RX_PDU));
    mem_pool.count++;
    pthread_rwlock_unlock(&rwlock);
}

void remove_by_rnti(uint16_t rnti) {
    pthread_rwlock_wrlock(&rwlock);
    size_t i;
    for (i = 0; i < mem_pool.count; ++i) {
        if (mem_pool.buffer[i].RNTI == rnti) {
            memmove(&mem_pool.buffer[i], &mem_pool.buffer[i + 1], (mem_pool.count - i - 1) * sizeof(LTE_PDCP_RX_PDU));
            --mem_pool.count;
        }
    }
    pthread_rwlock_unlock(&rwlock);
}

void update_packet_info(uint16_t rnti, const PacketInfo* new_info) {
    pthread_rwlock_rdlock(&rwlock);
    size_t i;
    for (i = 0; i < mem_pool.count; ++i) {
        if (mem_pool.buffer[i].RNTI == rnti) {
            mem_pool.buffer[i].PACKET_INFO = *new_info;
            break;
        }
    }
    pthread_rwlock_unlock(&rwlock);
}

size_t get_unique_rntis() {
    pthread_rwlock_rdlock(&rwlock);
    size_t unique_rntis = 0;
    uint16_t rnti;
    for (size_t i = 0; i < mem_pool.count; ++i) {
        rnti = mem_pool.buffer[i].RNTI;
        if (!(unique_rntis & (1 << rnti))) {
            unique_rntis |= 1 << rnti;
        }
    }
    pthread_rwlock_unlock(&rwlock);
    return unique_rntis;
}

// Implement functions for historical data retrieval, querying by timestamp range, and concurrency control as per your requirements.
