        auto it = std::remove_if(data.begin(), data.end(),
                                [&](const PHY_STATS_T& stat) { return stat.TIMESTAMP <= timestamp; });
        data.erase(it, data.end());
    }

    void update_load_factor(std::chrono::steady_clock::time_point start_timestamp, std::chrono::steady_clock::time_point end_timestamp) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = data.cbegin();
        int count = 0;
        while (it != data.cend() && it->TIMESTAMP <= end_timestamp) {
            ++count;
            if (++it == data.cend()) break;
        }
        loadFactor = static_cast<double>(data.size() - count) / data.capacity();
    }

