    std::atomic<size_t> invalid_count_{0};
};

void readFile(const std::string& filename, DynamicList& list) {
    boost::asio::io_service ios;
    boost::asio::aio_callback_handle<char> h;
    std::vector<char> buffer(1024);
    size_t bytes_read = 0;
    size_t total_bytes = 0;

    auto read = [&](boost::system::error_code ec, size_t /*length*/) {
        if (!ec) {
            list.push(NFAPI_CRC_INDICATION_PDU_T{
                .rx_ue_info = readRxUeInfo(),
                .rnti = readRNTI(),
                .crc_indication = CRC_INDICATION_REL8_TAG{} // Initialize the CRC_INDICATION_REL8_TAG
            });
            total_bytes += buffer.size();
            if (total_bytes >= bytes_read) {
                readNextChunk(filename, ios, h, buffer);
            }
        } else {
            BLT_ERROR("Error reading file: " << ec.message());
        }
    };

    auto readNextChunk = [&](const std::string& filename, boost::asio::io_service& ios, boost::asio::aio_callback_handle<char>& h, std::vector<char>& buffer) {
        boost::system::error_code ec;
        size_t length = buffer.size();
        if (ios.post(boost::asio::read_some(boost::asio::ip::udp::socket(ios), boost::asio::buffer(buffer), boost::bind(read, std::placeholders::_1, length)), h)) {
            // Async read is already in progress
        } else if (!ec) {
            ios.run_one();
        }
    };

    readNextChunk(filename, ios, h, buffer);
}

int main() {
    DynamicList list;
    std::string filename = "data.bin";
    readFile(filename, list);

    // Other code for logging, configuration, etc...

    return 0;
}
