TCP_Connection_State* createConnection(int connectionID, struct sockaddr_in peerAddress) {
    TCP_Connection_State *newConnection = (TCP_Connection_State*) malloc(sizeof(TCP_Connection_State));
    if (!newConnection) return NULL;

    newConnection->connectionID = connectionID;
    newConnection->peerAddress = peerAddress;
    newConnection->lastActivityTimestamp = time(NULL);
    newConnection->currentDataTransferRate = 0.0;
    newConnection->next = NULL;
    return newConnection;
}

void addConnection(TCP_Connection_State** head, TCP_Connection_State* connection) {
    if (!connection || !head) return;

    if (*head == NULL) {
        *head = connection;
        return;
    }

    connection->next = *head;
    *head = connection;
}

TCP_Connection_State* getMostRecentConnection(TCP_Connection_State* head) {
    TCP_Connection_State* mostRecent = NULL;
    TCP_Connection_State* current = head;

    if (!current) return NULL;

    while (current != NULL) {
        if (!mostRecent || current->lastActivityTimestamp > mostRecent->lastActivityTimestamp) {
            mostRecent = current;
        }
        current = current->next;
    }

    return mostRecent;
}

