    if (!head || !connection) return;

    TCP_Connection_State *current = *head;

    while (current != NULL) {
        if (current->connectionID == connection->connectionID) {
            current->lastActivityTimestamp = newTimestamp;
            break;
        }
        current = current->next;
    }
}
