Let's start by creating a function that calculates MD5 hash for a file:

```python
import hashlib
import os

def md5_hash(file):
    hasher = hashlib.md5()
    with open(file, "rb") as f:
        chunkSize = 1048576  # 1MB chunk size
        while True:
            data = f.read(chunkSize)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()
```

Next, let's create a function that calculates MD5 hashes for all files in a directory recursively and handles large files gracefully:

```python
import os
import glob
import concurrent.futures

def md5_files(directory, limit=os.cpu_count()):
    hashes = {}

    def hash_file(file):
        file_path = os.path.abspath(file)
        if os.path.islink(file_path) or not os.access(file_path, os.R_OK):
            return None
        try:
            return md5_hash(file_path)
        except Exception as e:  # Handle transient I/O errors with retries
            if len(hashes[file_path]) == 0:
                for _ in range(3):
                    try:
                        return md5_hash(file_path)
                    except Exception as e:
                        time.sleep(2 ** (_ + 1))
            return hashes[file_path]

    with concurrent.futures.ThreadPoolExecutor(max_workers=limit) as executor:
        file_list = glob.glob(os.path.join(directory, "*"), recursive=True)
        hashes[directory] = executor.map(hash_file, file_list)
    return hashes
