#include <openssl/sha.h>

void calculate_md5(const char* path, unsigned char digest[16]) {
    FILE *file = fopen(path, "rb");
    if (!file) return;

    unsigned char buffer[4096]; // Optimize for 4KB chunks
    size_t bytes_read;
    SHA256_CTX ctx;
    SHA256_Init(&ctx);

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        SHA256_Update(&ctx, buffer, bytes_read);
    }

    SHA256_Final(digest, &ctx);
    fclose(file);
}
