import os
import hashlib
import time
import threading
import csv
from multiprocessing import Pool

def processDirectory(directoryPath):
    start_time = time.time()
    totalFiles = 0
    failedFiles = 0
    averageTime = 0

    with open('results.csv', 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(['File Path', 'Hash Value', 'Verification Status'])

        def process_file(filePath):
            nonlocal totalFiles, failedFiles, averageTime
            file_hash = hashlib.md5()
            try:
                with open(filePath, 'rb') as file:
                    for chunk in iter(lambda: file.read(4096), b''):
                        file_hash.update(chunk)

                csvfile.write(os.path.abspath(filePath).encode('utf-8'))
                csvfile.write(','.encode('utf-8'))
                csvfile.write(file_hash.hexdigest().encode('utf-8'))
                csvfile.write(',' + ('Passed' if checksum == file_hash.hexdigest() else 'Failed').encode('utf-8'))
                csvfile.write('\n')

                totalFiles += 1
                elapsed = time.time() - start_time
                averageTime += elapsed
            except Exception as e:
                failedFiles += 1
                print(f'Error processing file {filePath}: {e}')

        pool = Pool(processes=5) // Adjust the number of processes based on available resources
        pool.map(process_file, [os.path.join(directoryPath, fname) for fname in next(os.walk(directoryPath))[2] if not fname.startswith('.')])

        averageTime /= totalFiles

        print(f'Total files processed: {totalFiles}, Average time per file: {averageTime}, Failed files: {failedFiles}')
