```python
import os
import hashlib
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
import csv
import sys

def md5sum(filepath):
    hasher = hashlib.md5()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def processDirectory(directory, checksums):
    start = time.time()
    total_files = 0
    failed_hashes = 0

    with ThreadPoolExecutor(max_workers=4) as executor:
        for root, dirs, files in os.walk(directory):
            for file in [f for f in files if not f.startswith('.')]:
                filepath = os.path.join(root, file)
                result = executor.submit(md5sum, filepath)
                checksum = result.result()
                if checksum in checksums:
                    print(f'Verified: {filepath} ({checksum})')
                else:
                    print(f'Failed Verification: {filepath} ({checksum})')
                    failed_hashes += 1
            total_files += len(files)

        average_time = (time.time() - start) / total_files
        print(f'Average Time: {average_time:.4f} seconds')
        print(f'Total Files: {total_files}, Failed Hashes: {failed_hashes}')

        with open('report.csv', 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(['File Path', 'Hash Value', 'Verification Status'])
            for root, dirs, files in os.walk(directory):
                for file in [f for f in files if not f.startswith('.')]:
                    filepath = os.path.join(root, file)
                    checksum = md5sum(filepath)
                    status = 'Verified' if checksum in checksums else 'Failed Verification'
                    writer.writerow([filepath, checksum, status])
