#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <pthread.h>
#include <openssl/md5.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    uint8_t crcflag;
    uint8_t padding[4]; // alignment consideration
} NFAPI_CRC_INDICATION_PDU;

typedef struct file_hash {
    char *path;
    MD5_CTX md5;
    uint32_t priority;
    bool processed, checksum_matched;
    time_t start_time, hash_time;
} FILE_HASH;

int create_pdu_array(NFAPI_CRC_INDICATION_PDU **pdus, size_t N) {
    if (N <= 0) return -1; // Invalid input: N must be positive

    *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!*pdus) return -2; // Memory allocation error

    for (size_t i = 0; i < N; ++i) {
        (*pdus)[i].tag = rand();
        (*pdus)[i].rnti = rand();
        (*pdus)[i].crc_tag = rand();
        (*pdus)[i].crcflag = (rand() % 2) + 1; // random boolean value
    }

    return 0; // Success
}

void *hash_file(void *arg) {
    FILE_HASH *fh = arg;
    char buffer[4096];
    size_t bytes_read;

    MD5_Init(&fh->md5);

    while ((bytes_read = fread(buffer, sizeof(char), sizeof(buffer), fopen(fh->path, "rb"))) > 0) {
        MD5_Update(&fh->md5, buffer, bytes_read);
    }

    if (ferror(fh->path)) { // File I/O error
        perror("Error reading file");
        return NULL;
    }

    fh->hash_time = time(NULL);
    fh->checksum_matched = MD5_Final(&fh->md5, &fh->md5.digest); // Calculate hash digest

    char *hexdigest = calloc(33, sizeof(char)); // Store hexadecimal representation of digest
    for (size_t i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        snprintf(&hexdigest[i*2], 3, "%02x", fh->md5.digest[i]);
    }

    free(fh->path); // Free original file path
    fh->path = strdup(hexdigest); // Renaming the temporary buffer as a new string

    return fh;
}

int main() {
    FILE_HASH *files = NULL;
    size_t num_files = 10;
    NFAPI_CRC_INDICATION_PDU *pdus = NULL;
    int error, i;

    srand(time(NULL)); // Seed random number generator

    error = create_pdu_array(&pdus, num_files);
    if (error < 0) {
        perror("Error creating PDUs");
        return -1;
    }

    files = malloc(num_files * sizeof(FILE_HASH));
    if (!files) {
        perror("Memory allocation error");
        free(pdus);
        return -2;
