import os
import hashlib
import md5
import zlib
import gzip
import bz2
import pycryptodome
from concurrent.futures import ThreadPoolExecutor
import time
import random
import numpy as np

class NFAPI_CRCI_PDU:
    def __init__(self, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG):
        self.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG
        self.RNTI = RNTI
        self.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG
        self.crcflag = np.random.randint(0, 2)

def decompress(filepath, compress_type):
    if compress_type == 'gzip':
        with gzip.open(filepath, 'rb') as f:
            return f.read()
    elif compress_type == 'bz2':
        with bz2.open(filepath, 'rb') as f:
            return f.read()
    else:
        return zlib.decompress(open(filepath, 'rb').read())

def decrypt(data, key):
    iv = bytes([random.randint(0, 255) for _ in range(16)])
    cipher = pycryptodome.Crypto.Cipher.AES.new(key, pycryptodome.util.Padding.PKCS7(16), iv)
    return cipher.decrypt(data)

def process_file(filepath, config):
    with open(filepath, 'rb') as f:
        hash = md5.new()
        h = hashlib.md5()
        chunksize = 65536
        while True:
            data = f.read(chunksize)
            if not data:
                break
            decompressed_data = decompress(filepath, config[filepath]['compression'])
            decrypted_data = config[filepath].get('encryption') and decrypt(decompressed_data, config[filepath]['key']) or decompressed_data
            hash.update(decriminated_data)
            h.update(hash.digest())
    return filepath, h.hexdigest(), config[filepath]['priority']

def process_files(config):
    executor = ThreadPoolExecutor(max_workers=10)
    results = {}
    for filepath in config:
        result = executor.submit(process_file, filepath, config)
        results[filepath] = result.result()
    return results

def main():
    # Load configuration file
    with open('config.txt') as f:
        lines = [line.strip().split(',') for line in f]
        config = {line[0]: {'compression': line[1], 'encryption': bool(int(line[2])), 'key': line[3].encode('utf-8')} for line in lines if line}

    start_time = time.time()
    results = process_files(config)

    # Populate NFAPI_CRCI_PDU structures here based on your requirements

    for filepath, hash, priority in results.values():
        print(f'File: {filepath}, Hash: {hash}, Priority: {priority}')
        if hash != config[filepath]['expected']:
            print(f'Mismatch! Expected: {config[filepath]["expected"]}, Got: {hash}')
    print(f'Processing time: {time.time() - start_time} seconds')

if __name__ == '__main__':
    main()
```

This code assumes the configuration file is in a specific format, each line being a comma-separated list with the following structure:

- File path (no quotes)
- Compression type ('gzip', 'bz2', or 'none')
- Encryption status (0 for not encrypted, 1 for encrypted)
- Encryption key (base64 encoded)']

