typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    struct _NFAPI_CRC_INDICATION_PDU_T *prev;
    struct _NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T **elements;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} MemoryPool;

MemoryPool* memory_pool_create(size_t capacity) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->capacity = capacity;
    mp->count = 0;
    mp->elements = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    mp->mutex = PTHREAD_MUTEX_INITIALIZER;
    mp->not_full = PTHREAD_COND_INITIALIZER;
    mp->not_empty = PTHREAD_COND_INITIALIZER;
    return mp;
}

NFAPI_CRC_INDICATION_PDU_T* memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->mutex);
    while (mp->count == mp->capacity) {
        pthread_cond_wait(&mp->not_full, &mp->mutex);
    }
    NFAPI_CRC_INDICATION_PDU_T *element = NULL;
    if (mp->count < mp->capacity) {
        element = mp->elements[mp->count++];
        element->prev = NULL;
        element->next = NULL;
    } else {
        size_t index = (mp->count - 1) % mp->capacity;
        element = mp->elements[index];
    }
    pthread_cond_signal(&mp->not_empty);
    pthread_mutex_unlock(&mp->mutex);

    // Initialize the CRC flag randomly.
    srand(time(NULL) + (uintptr_t) element);
    element->crc_indication.crcFlag = rand() % 2;

    return element;
}

void memory_pool_free(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&mp->mutex);

    if (element->prev == NULL) {
        mp->elements[mp->count--] = element;
    } else {
        element->prev->next = element->next;
        if (element->next != NULL) {
            element->next->prev = element->prev;
        }
        size_t index = (mp->capacity + mp->count - 1) % mp->capacity;
        mp->elements[index] = element;
    }

    pthread_cond_signal(&mp->not_full);
    pthread_mutex_unlock(&mp->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* find_next_rnti(NFAPI_CRC_INDICATION_PDU_T *start, RNTI rnti) {
    for (; start != NULL && start->rnti == rnti; start = start->next);
    return start;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T **head, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *element = memory_pool_alloc(*head->memoryPool);
    element->rnti = rnti;
    if (*head == NULL) {
        *head = element;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = *head;
        for (; current->next != NULL && current->next->rnti == rnti; current = current->next);
        if (current->next == NULL) {
            current->next = element;
            element->prev = current;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *next = find_next_rnti(current->next, rnti);
            if (next != NULL) {
                next->prev->next = element;
                element->prev = next->prev;
                element->next = next;
                next->prev = element;
            }
        }
    }
}

void remove_from_list(NFAPI_CRC_INDICATION_PDU_T **head, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T *element = find_next_rnti(*head, rnti);
    if (element == NULL) return;

    pthread_mutex_lock(&(*head)->memoryPool->mutex);

    memory_pool_free((*head)->memoryPool, element);

    pthread_mutex_unlock(&(*head)->memoryPool->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* iterate_forward(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    if (current != NULL) {
