LTE_STAT* memory_pool_alloc(struct MEMORY_POOL *pool) {
    pthread_mutex_lock(&pool->mutex);
    while (pool->used == pool->capacity && pool->data[pool->used - 1] != NULL) {
        pthread_cond_wait(&pool->not_full, &pool->mutex);
    }

    LTE_STAT *stat = pool->data[pool->used];
    if (stat == NULL) {
        if (pool->used < pool->capacity) {
            stat = malloc(sizeof(LTE_STAT));
            memset(stat, 0, sizeof(LTE_STAT));
            pool->used++;
        } else {
            size_t new_capacity = pool->capacity * 2;
            LTE_STAT **new_data = realloc(pool->data, new_capacity * sizeof(LTE_STAT*));
            if (new_data == NULL) {
                pthread_mutex_unlock(&pool->mutex);
                return NULL;
            }
            pool->data = new_data;
            pool->capacity = new_capacity;
        }
    }
    pool->mutex_unlock(&pool->mutex);
    return stat;
}

