#include <pthread.h>
#include <time.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Statistic {
    time_t timestamp;
    int cqi;
    int mcs;
    float evm;
    struct Statistic *prev, *next;
    size_t age; // in seconds
} Statistic;

struct Node {
    Statistic *stat;
    struct Node *prev, *next;
};

typedef struct MemoryPool {
    size_t capacity, usage;
    Statistic** buffer;
    pthread_mutex_t lock;
    pthread_cond_t notEmpty, notFull;
} MemoryPool;

MemoryPool* createMemoryPool(size_t initialCapacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->capacity = initialCapacity;
    pool->usage = 0;
    pool->buffer = (Statistic**)calloc(initialCapacity, sizeof(Statistic*));
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
    pool->notEmpty = PTHREAD_COND_INITIALIZER;
    pool->notFull = PTHREAD_COND_INITIALIZER;
    return pool;
}

Statistic* allocateFromPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    while (pool->usage == pool->capacity) {
        pthread_cond_wait(&pool->notEmpty, &pool->lock);
    }

    Statistic* stat = pool->buffer[pool->usage++];
    memset(stat, 0, sizeof(Statistic));
    pthread_mutex_unlock(&pool->lock);

    return stat;
}

void freeToPool(MemoryPool* pool, Statistic* stat) {
    pthread_mutex_lock(&pool->lock);
    stat->prev = NULL;
    stat->next = NULL;
    pool->buffer[pool->usage--] = stat;
    if (pool->usage < pool->capacity / 2 && pool->capacity > 10) { // adjust capacity based on usage
        reallocateMemoryPool(pool, pool->capacity / 2);
    }
    pthread_cond_signal(&pool->notFull);
    pthread_mutex_unlock(&pool->lock);
}

void reallocateMemoryPool(MemoryPool* pool, size_t newCapacity) {
    Statistic** oldBuffer = pool->buffer;
    pool->capacity = newCapacity;
    pool->buffer = (Statistic**)realloc(oldBuffer, newCapacity * sizeof(Statistic*));
}

// Circular doubly linked list implementation for LTE PHY statistics
void insertStat(Statistic** head, Statistic* stat) {
    // Ensure no two consecutive entries have identical CQI values
    if (*head && ((*head)->cqi == stat->cqi)) {
        stat->prev = *head;
        stat->next = (*head)->next;
        (*head)->next = stat;
        stat->next->prev = stat;
        return;
    }

    size_t i;
    Statistic* current = *head;
    for (i = 0; i < 10000; ++i) { // adjust loop limit based on desired max list size
        if (!current || current->cqi != stat->cqi) {
            break;
        }
        current = current->next;
    }

    stat->prev = current ? current->prev : NULL;
    stat->next = current;
    if (current) {
        current->prev->next = stat;
        current->prev = stat;
    } else {
        *head = stat;
    }
}

void removeStat(Statistic** head, Statistic* stat) {
    if (!stat || !*head) return;

    if (stat == *head) {
        *head = stat->next;
        if (*head) {
            (*head)->prev = NULL;
        }
        return;
    }

    Statistic* current = *head;
    while (current && current != stat) {
        current = current->next;
    }

    if (!current) return;

    current->prev->next = current->next;
    if (current->next) {
        current->next->prev = current->prev;
    }
}

// Concurrent traversal support using tail pointers and lock-free reversing
Statistic* getFirst(Statistic** head) {
    pthread_mutex_lock(&head[1]->lock); // acquire lock on the tail node
    Statistic* first = *head;
    pthread_mutex_unlock(&head[1]->lock);
    return first;
}

Statistic* getLast(Statistic** head) {
    pthread_mutex_lock(&head[0]->lock); // acquire lock on the head node
    Statistic* last = *head;
    while (last->next) {
        last = last->next;
    }
    pthread_mutex_unlock(&head[0]->lock);
    return last;
}

// Periodic garbage collection, age tracking, and rolling window maintenance
void maintainStats(Statistic** head, time_t currentTime, size_t thresholdAge) {
    Statistic* current = *head;
    while (current && current->age < thresholdAge) {
        removeStat(head, current);
        freeToPool(pool, current);
        current = *head;
    }
}
```

