    def __init__(self, device_identifier, connection_successful, priority_level):
        self.device_identifier = device_identifier
        self.connection_successful = connection_successful
        self.priority_level = priority_level

def process_devices(config_file, transport_library, protocol_negotiation_library):
    devices = parse_config(config_file)
    device_connections = {}

    with concurrent.futures.ThreadPoolExecutor(max_workers=len(devices)) as executor:
        results = [executor.submit(establish_connection, device, transport_library, protocol_negotiation_library) for device in devices]

        for future in concurrent.futures.as_completed(results):
            try:
                connection_status = future.result()
                device_identifier = connection_status[0]
                connection_successful = connection_status[1]
                priority_level = connection_status[2]

                device_connections[device_identifier] = DeviceConnectionStatus(device_identifier, connection_successful, priority_level)
            except Exception as e:
                print(f"Error while establishing connection with device {device_identifier}: {e}")

    return device_connections

def establish_connection(device, transport_library, protocol_negotiation_library):
