        # Populate ProtocolStackStatus structure based on device and network details
        protocol_stack_status = ProtocolStackStatus(device['identifier'], network_version, supported_features)

        # Establish persistent connection with the device
        connection.set_persistent()

        return (device['identifier'], True, device['priority_level'])
    except Exception as e:
