    uint32_t rnti;
    uint16_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct worker_args {
    size_t chunk_size;
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t data_len;
    pthread_mutex_t *mutex;
    int log_level;
};

void *worker(void *arg) {
    struct worker_args *wa = arg;
    size_t i, chunk_start = 0, chunk_end;
    NFAPI_CRC_INDICATION_PDU_T *data = wa->data;

    while (chunk_start < wa->data_len) {
        chunk_end = chunk_start + wa->chunk_size > wa->data_len ? wa->data_len : chunk_start + wa->chunk_size;
        pthread_mutex_lock(wa->mutex);
        for (i = chunk_start; i < chunk_end; ++i) {
            data[i].crcflag = rand() % 2 == 0 ? true : false;
        }
        pthread_mutex_unlock(wa->mutex);
        chunk_start = chunk_end;
    }

    return NULL;
}

void log(int level, const char *msg) {
    if (level <= wa->log_level) {
        time_t rawtime;
        struct tm *timeinfo;
        char time_string[26];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] [%d] %s\n", time_string, level, msg);
    }
}

int main(int argc, char **argv) {
    size_t chunk_size, num_threads;
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <chunk_size> <num_threads> <log_level>\n", argv[0]);
        return 1;
    }

    chunk_size = atoi(argv[1]);
    num_threads = atoi(argv[2]);
    int log_level = argc > 3 ? atoi(argv[3]) : 0;

    // Load and process the data from an external source
    // ...

    NFAPI_CRC_INDICATION_PDU_T *data = mmap(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_threads, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    struct worker_args *wa = malloc(num_threads * sizeof(*wa));
    if (!wa) {
        perror("malloc");
        return 1;
    }

    for (size_t i = 0; i < num_threads; ++i) {
        wa[i].chunk_size = chunk_size;
        wa[i].data = data + i * chunk_size;
        wa[i].data_len = chunk_size;
        wa[i].mutex = &mutex;
        wa[i].log_level = log_level;
    }

    pthread_t thread_ids[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&thread_ids[i], NULL, worker, &wa[i])) {
            perror("pthread_create");
            return 1;
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_join(thread_ids[i], NULL)) {
            perror("pthread_join");
            return 1;
        }
    }

    munmap(data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_threads);
    free(wa);

    log(log_level, "Operation completed successfully.");

    return 0;
}
