#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <gmp.h>
#include <time.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static Node* head = NULL;
static uint32_t max_elements = 10000;
static Node** list = malloc(max_elements * sizeof(Node*));
static mpz_t seed, poly;

void init() {
    for (size_t i = 0; i < max_elements; ++i) {
        list[i] = NULL;
    }

    mpz_init(seed);
    mpz_init(poly);
    mpz_set_str(poly, "18000003", 10);
}

void roll_hash(mpz_srcptr out, const mpz_srcptr in) {
    mpz_powm(out, in, poly, MPZ_MAX);
    mpz_add(out, out, seed);
}

void set_seed() {
    time_t now;
    struct tm *tmp;
    char buf[64];

    time(&now);
    tmp = localtime(&now);
    strftime(buf, sizeof(buf), "%Y%m%d%H%M%S", tmp);
    mpz_set_str(seed, buf, 10);
}

void update_seed() {
    set_seed();
    roll_hash(seed, seed);
}

void log_entry(const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (data->RNTI <= 65535 && data->RNTI > 0) {
        printf("Valid RNTI: %d\n", data->RNTI);
    } else {
        printf("Invalid RNTI: %d\n", data->RNTI);
    }
}

void insert(const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list_mutex);
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation error");
        return;
    }

    new_node->data = *data;
    new_node->next = NULL;

    mpz_clear(data->CRC_INDICATION_REL8_TAG);
    roll_hash(data->CRC_INDICATION_REL8_TAG, mpz_get_str(seed, 10));
    roll_hash(data->CRC_INDICATION_REL8_TAG, mpz_get_str(data->RNTI, 10));
    update_seed();

    if (head == NULL) {
        head = new_node;
    } else {
        Node *iter = head;
        while (iter->next != NULL) {
            iter = iter->next;
        }
        iter->next = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

void resize() {
    // Implement dynamic resizing strategy here.
}

// Batch processing function for high-throughput scenarios.
void process(const NFAPI_CRC_INDICATION_PDU_T* buffer, size_t len) {
    if (len > 1000) {
        perror("Invalid buffer length");
        return;
    }

    pthread_mutex_lock(&list_mutex);
    Node *iter = head;
    for (size_t i = 0; i < len; ++i) {
        if (!iter) break;

        log_entry(&iter->data);
        insert(&iter->data);
        iter = iter->next;
    }
    pthread_mutex_unlock(&list_mutex);
}
