#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>
#include <sys/time.h>

typedef struct SubscriberConnection {
    int SID;
    enum ServiceTier { LOW, MEDIUM, HIGH } service_tier;
    enum NetworkStatus { DISCONNECTED, CONNECTED } network_status;
    time_t last_status_update;
    pthread_mutex_t status_lock;
} SubscriberConnection;

typedef struct TaskQueue {
    SubscriberConnection *subscriber;
    void (*status_check)(SubscriberConnection*);
    struct TaskQueue *next;
} TaskQueue;

TaskQueue *task_queue_head = NULL;
pthread_mutex_t task_queue_lock;
pthread_cond_t task_queue_cond;

void initialize_subscriber(SubscriberConnection* subscriber, int SID, enum ServiceTier service_tier) {
    if (SID <= 0 || service_tier < LOW || service_tier > HIGH) {
        fprintf(stderr, "Invalid subscriber data provided\n");
        exit(1);
    }

    subscriber->SID = SID;
    subscriber->service_tier = service_tier;
    subscriber->network_status = DISCONNECTED;
    time(&subscriber->last_status_update);
    pthread_mutex_init(&subscriber->status_lock, NULL);
}

void enqueue_task(SubscriberConnection* subscriber, void (*status_check)(SubscriberConnection*)) {
    TaskQueue *new_node = malloc(sizeof(TaskQueue));

    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }

    new_node->subscriber = subscriber;
    new_node->status_check = status_check;
    new_node->next = task_queue_head;
    task_queue_head = new_node;

    pthread_mutex_lock(&task_queue_lock);
    pthread_cond_signal(&task_queue_cond);
    pthread_mutex_unlock(&task_queue_lock);
}

void process_tasks() {
    TaskQueue *current, *next;

    while (true) {
        pthread_mutex_lock(&task_queue_lock);

        while (task_queue_head == NULL && pthread_cond_wait(&task_queue_cond, &task_queue_lock) != 0) {}

        current = task_queue_head;
        next = current ? current->next : NULL;
        task_queue_head = next;

        pthread_mutex_unlock(&task_queue_lock);

        if (current == NULL) break;

        process_subscriber(current->subscriber, current->status_check);
        free(current);
    }
}

void process_subscriber(SubscriberConnection* subscriber, void (*status_check)(SubscriberConnection*)) {
    struct timeval start, end;
    gettimeofday(&start, NULL);

    pthread_mutex_lock(&subscriber->status_lock);

    status_check(subscriber);

    gettimeofday(&end, NULL);

    time_t elapsed = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec - start.tv_usec) / 1000;

    printf("Subscriber %d: Network status updated, Elapsed time: %d ms\n", subscriber->SID, elapsed);
}

// Add your custom service interaction functions here, e.g., check_network_status()

int main(int argc, char** argv) {
    // Initialize any required services here

    SubscriberConnection connections[100];

    for (size_t i = 0; i < sizeof(connections) / sizeof(SubscriberConnection); ++i) {
        initialize_subscriber(&connections[i], i + 1, LOW);
        enqueue_task(&connections[i], check_network_status);
    }

    pthread_t worker;
    pthread_create(&worker, NULL, process_tasks, NULL);

    // Main application logic goes here

    pthread_join(worker, NULL);

    // Finalize and clean up any required services here

    return 0;
}
```

