            auto token = bj::parse(tokenJson);
            if (!token.is_object()) throw std::invalid_argument("Invalid JSON");

            auto it = token.items().find("access_token");
            if (it == token.items().end()) throw std::invalid_argument("Missing access_token");

            it = token.items().find("expires_in");
            if (it == token.items().end()) throw std::invalid_argument("Missing expires_in");

            int expiresIn;
            try {
                expiresIn = it->second.get<int>();
            } catch (const std::exception& e) {
                throw std::invalid_argument("Invalid expires_in value");
            }

            if (expiresIn <= 0) throw std::invalid_argument("expires_in must be a positive integer");

            it = token.items().find("token_type");
            if (it == token.items().end() || it->second.get<std::string>() != "Bearer")
