            it = token.items().find("refresh_token");
            if (it != token.items().end()) {
                try {
                    it->second.get<std::string>();
                } catch (const std::exception& e) {
                    throw std::invalid_argument("Invalid refresh_token value");
                }
            }

            return true;
        } catch (const std::exception& e) {
            BOOST_LOG_TRIVIAL(error) << "Error validating token: " << e.what();
            return false;
        }
