static pthread_mutex_t array_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t capacity = 0;
static NFAPI_CRC_INDICATION_PDU_T* data = NULL;

void push_data(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&array_mutex);

    if (capacity == 0) {
        capacity = 32;
        data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    if (capacity <= size) {
        capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T* tmp = (NFAPI_CRC_INDICATION_PDU_T*) realloc(data, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (tmp != NULL) {
            data = tmp;
        }
    }

    data[size] = *pdu;
    size++;

    pthread_mutex_unlock(&array_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* pop_data() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    pthread_mutex_lock(&array_mutex);

    if (size > 0) {
        pdu = &data[0];
        memmove(data, data + 1, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        size--;
    }

    pthread_mutex_unlock(&array_mutex);
    return pdu;
}

