struct log_level {
    const char *short_option;
    int level;
};

const struct log_level log_levels[] = {
    { ".DEBUG", LOG_DEBUG },
    { ".INFO", LOG_INFO },
    { ".NOTICE", LOG_NOTICE },
    { ".WARNING", LOG_WARNING },
    { ".ERR", LOG_ERR },
    { ".CRIT", LOG_CRIT },
    { ".ALERT", LOG_ALERT },
    { ".EMERG", LOG_EMERG },
    { NULL, 0 }
};

void usage() {
    fprintf(stderr, "Usage: %s [options]\n", program_name);
    fprintf(stderr, "\t-l, --log-level <level>\n");
    fprintf(stderr, "\t-f, --file <filename>\n");
    fprintf(stderr, "\t-v, --verbose\n");
    exit(1);
}

int main(int argc, char *argv[]) {
    program_name = argv[0];
    int opt;
    const char *log_file = NULL;
    struct log_level log_level = { .short_option = NULL };
    int verbose = 0;

    openlog(program_name, LOG_PID | LOG_NDELAY, LOG_DAEMON);
    while ((opt = getopt_long(argc, argv, log_option, log_levels, NULL)) != -1) {
        switch (opt) {
            case 'l':
                log_level.short_option = optarg;
                break;
            case 'f':
                log_file = optarg;
                break;
            case 'v':
                verbose++;
                syslog(LOG_NOTICE, "Verbosity level increased");
                break;
            default:
                usage();
        }
    }

    if (!log_level.short_option) {
        log_level.short_option = ".INFO";
    }

    if (!log_file && optind != argc) {
        usage();
    }

    int fd;
    if (log_file) {
        fd = open(log_file, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (fd == -1) {
            syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
            exit(1);
        }
    } else {
        fd = STDOUT_FILENO;
    }

    setlogmask(LOG_UPTO(log_level.level));
    openlog("main program", LOG_PID | LOG_CONS, LOG_DAEMON);

    if (verbose) {
        syslog(LOG_NOTICE, "Starting processing...");
    }

    int line_number = 0;
    char line[1024];
    ssize_t bytes_read;

    if (fd != STDOUT_FILENO) {
        while ((bytes_read = getline(&line, sizeof(line), fd)) != -1) {
            syslog(LOG_INFO, "Processing line %d: %s", ++line_number, &line[0]);
        }
    } else {
        FILE *file;
        if ((file = fopen(optarg, "r")) == NULL) {
            syslog(LOG_ERR, "Failed to open input file: %s", strerror(errno));
            exit(1);
        }

        while (fgets(line, sizeof(line), file)) {
            ++line_number;
            syslog(LOG_INFO, "Processing line %d: %s", line_number, line);
        }

        fclose(file);
    }

    closedir(fd);

    if (verbose) {
        syslog(LOG_NOTICE, "Finished processing.");
        syslog(LOG_INFO, "Number of processed lines: %d", line_number);
    }

    exit(0);
}
