typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_CHUNK 1024
#define CHUNK_SIZE (sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_CHUNK)

void* worker(void* arg);

void progress_indicator(int processed, int total, bool enable_log) {
    if (!enable_log) return;
    double percent = (double)processed / total * 100;
    printf("\rProgress: %.2f%%", percent);
}

void log_error(const char* message, bool enable_log) {
    if (!enable_log) return;
    fprintf(stderr, "[ERROR] %s\n", message);
}

int main(int argc, char **argv) {
    int chunk_size = CHUNK_SIZE;
    int num_workers = sysconf(_SC_NPROCESSORS_ONLINE);
    bool enable_log = false;
    int max_structures = 1000000;

    struct option long_options[] = {
        {"chunk-size", required_argument, NULL, 'c'},
        {"num-workers", required_argument, NULL, 'w'},
        {"log", no_argument, NULL, 'l'},
        {"max-structures", required_argument, NULL, 'm'},
        {0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "c:w:lm:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'c':
                chunk_size = atoi(optarg);
                break;
            case 'w':
                num_workers = atoi(optarg);
                break;
            case 'l':
                enable_log = true;
                break;
            case 'm':
                max_structures = atoi(optarg);
                break;
            case '?':
                log_error("Invalid option.", enable_log);
                return EXIT_FAILURE;
        }
    }

    if (chunk_size <= 0 || num_workers <= 0 || max_structures <= 0) {
        log_error("Invalid parameter.", enable_log);
        return EXIT_FAILURE;
    }

    pthread_t* threads = malloc(num_workers * sizeof(pthread_t));
    NFAPI_CRC_INDICATION_PDU_T* data = mmap(NULL, chunk_size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);
    if (!data) {
        log_error("Failed to allocate memory.", enable_log);
        return EXIT_FAILURE;
    }

    int total = max_structures / CHUNK_SIZE * chunk_size;
    progress_indicator(0, total, enable_log);

    clock_t start = clock();

    for (int i = 0; i < total; i += chunk_size) {
        for (int j = 0; j < num_workers; ++j) {
            pthread_create(&threads[j], NULL, worker, &data + i);
        }
        for (int k = 0; k < num_workers; ++k) {
            pthread_join(threads[k], NULL);
        }
    }

    munmap(data, chunk_size);
    free(threads);

    clock_t end = clock();
    printf("\nProcessed: %d\nTime taken: %.2fs\n", total, (double)(end - start) / CLOCKS_PER_SEC);

    return EXIT_SUCCESS;
}

void* worker(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    for (int i = 0; i < MAX_CHUNK; ++i) {
