        std::unique_lock<std::mutex> lock(mtx);
        for (auto it = inventory.begin(); it != inventory.end(); ++it) {
            if ((*it)->product_id == product_id) {
                (*it) = std::make_shared<PRODUCT_INVENTORY_RECORD>(record);
                break;
