        update_tasks.emplace(task);
        if (update_tasks.size() == 1 ||
            std::chrono::system_clock::now().time_since_epoch().count() > frequency * 1000) {
            std::unique_lock<std::mutex> lock(mtx);
            update_price_history_worker();
        }
    }

private:
    void update_price_history_worker() {
        while (!update_tasks.empty()) {
            auto task = update_tasks.front();
            update_tasks.pop();
            std::thread(task).detach();
        }
    }
};
