// Function to dynamically allocate and initialize an array of record structures
record* create_record_array(size_t num_records) {
    if (num_records > max_records) {
        sem_wait(&memory_semaphore);
        max_records = num_records;
    }

    record *arr = (record *)((char *)malloc_array + (max_records - num_records) * sizeof(record));

    if (!arr) {
        fprintf(stderr, "Error: Out of memory\n");
        pthread_exit(NULL);
    }

    for (size_t i = 0; i < num_records; ++i) {
        arr[i].value = 0;
    }

    return arr;
}

// Custom malloc function that allocates a continuous block of memory and manages it efficiently
void *malloc_array(size_t nmemb, size_t size) {
    void *ptr = my_malloc(nmemb * size);

    if (ptr != MAP_FAILED) {
        max_records += nmemb;
    }

    return ptr;
}

// Function to handle potential delays or failures from external data sources
void handle_external_source_failure(const char *source, int attempts, int timeout) {
