typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

void* gen_pdu(void *arg) {
    int index = *(int *) arg;
    NFAPI_CRC_INDICATION_PDU_T *data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    data->tag = (RX_UE_INFORMATION_TAG) index;
    data->rnti = index + 100; // example RNTI generation
    data->crc_indication.crcflag = rand() % 2;
    return data;
}

void gen_pdus(int n, int seed, int m, NFAPI_CRC_INDICATION_PDU_T** out) {
    pthread_t threads[m];
    srand(seed);
    *out = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < m && n > 0; ++i) {
        int* arg = (int*) malloc(sizeof(int));
        *arg = n - 1;
        n--;
        pthread_create(&threads[i], NULL, gen_pdu, arg);
    }
    for (int i = 0; i < m; ++i) {
        pthread_join(threads[i], out + *out - threads[i]);
    }
}
