void generateNfadPduList(size_t numUsers) {
    std::random_device seed;
    std::mt19937 gen(seed());
    std::uniform_int_distribution<> distribution(0, 1);

    concurrentUsersMutex.lock();

    for (size_t i = 0; i < numUsers; ++i) {
        auto rnti = rntiCounts.empty() ? 1 : rntiCounts.rbegin()->first + 1;
        auto pdu = { RX_UE_INFORMATION_TAG, rnti, static_cast<uint8_t>(distribution(gen)) };

        concurrentUsersList.push_back(pdu);
