public class MessageProcessor {
    private final MessagingService messagingService;
    private final TileRenderingService tileRenderingService;
    private final Library library;

    public MessageProcessor(MessagingService messagingService, TileRenderingService tileRenderingService, Library library) {
        this.messagingService = messagingService;
        this.tileRenderingService = tileRenderingService;
        this.library = library;
    }

    public Response processMessagesAndGenerateTiles(String filePath, Pokemon pokemon, String configFilePath) {
        Response response = new Response();

        try {
            Document document = DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(new File(configFilePath));
            Element root = document.getDocumentElement();
            NodeList tileSizeNodeList = root.getElementsByTagName("tileSize");
            NodeList worldWidthNodeList = root.getElementsByTagName("worldWidth");
            NodeList worldHeightNodeList = root.getElementsByTagName("worldHeight");
            NodeList cameraSpeedNodeList = root.getElementsByTagName("cameraSpeed");

            int tileSize = parsePositiveInteger(tileSizeNodeList);
            int worldWidth = parseNonZeroInteger(worldWidthNodeList);
            int worldHeight = parseNonZeroInteger(worldHeightNodeList);
            float cameraSpeed = parseCameraSpeed(cameraSpeedNodeList);

            response.setTileSize(tileSize);
            response.setWorldDimensions(worldWidth, worldHeight);
            response.setCameraSpeed(cameraSpeed);

            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] fileBytes;
            List<String> hashes = new ArrayList<>();
            int chunkSize = 8192;
            try (FileInputStream inputStream = new FileInputStream(new File(filePath))) {
                while ((fileBytes = new byte[chunkSize]) > 0) {
                    inputStream.read(fileBytes);
                    md5.update(fileBytes);
                    hashes.add(bytesToHex(md5.digest()));
                }
            }
            response.setHashes(hashes);

            // Implement the logic for integration with the messaging service, tile rendering, Pokemon weakness determination, and error handling here.

        } catch (Exception e) {
            response.addError(e.getMessage());
        }

        return response;
    }

    private int parsePositiveInteger(NodeList nodeList) throws Exception {
        for (int i = 0; i < nodeList.getLength(); i++) {
            Element element = (Element) nodeList.item(i);
            String textContent = element.getTextContent().trim();
            int number = Integer.parseInt(textContent);
            if (number > 0) {
                return number;
            }
        }
        throw new IllegalArgumentException("Invalid tileSize value");
    }

    private int parseNonZeroInteger(NodeList nodeList) throws Exception {
        for (int i = 0; i < nodeList.getLength(); i++) {
            Element element = (Element) nodeList.item(i);
            String textContent = element.getTextContent().trim();
            int number = Integer.parseInt(textContent);
            if (number > 0) {
                return number;
            }
        }
        throw new IllegalArgumentException("Invalid worldWidth, worldHeight, or cameraSpeed value");
    }

    private float parseCameraSpeed(NodeList nodeList) throws Exception {
        for (int i = 0; i < nodeList.getLength(); i++) {
            Element element = (Element) nodeList.item(i);
            String textContent = element.getTextContent().trim();
            try {
                float number = Float.parseFloat(textContent);
                if (number > 0 && number < 100) {
                    return number;
                }
            } catch (NumberFormatException e) {
                // Ignore non-numeric input, as it would be an error in the XML file.
            }
        }
        throw new IllegalArgumentException("Invalid cameraSpeed value");
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
