#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>

#define MAX_QUEUE_SIZE 1000
#define VALIDATION_ERROR_MESSAGE "Invalid transaction data."
#define RESOURCE_EXCEEDED_MESSAGE "Insufficient resources to process transactions."

typedef struct {
    int transaction_id;
    int user_id;
    void* request_data; // Schema-validated data
} TRANSACTION_REQUEST_T;

// Custom compare function for qsort()
static int compare_transaction(const void *a, const void *b) {
    return ((TRANSACTION_REQUEST_T *)a)->transaction_id - ((TRANSACTION_REQUEST_T *)b)->transaction_id;
}

// External analytics service callback function
typedef void (*analytics_callback)(const TRANSACTION_REQUEST_T *, const char *metadata);

pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t queue_not_full, queue_not_empty, transactions_to_process;
analytics_callback analytics_func;
int num_transactions = 0;
TRANSACTION_REQUEST_T *queue = NULL;

void cleanup() {
    if (queue != NULL) {
        free(queue);
        queue = NULL;
    }
}

void validate_and_add_transaction(const TRANSACTION_REQUEST_T *request) {
    // Validate the request data here...
    sem_wait(&queue_not_full);
    pthread_mutex_lock(&queue_mutex);
    queue[num_transactions] = *request;
    num_transactions++;
    pthread_mutex_unlock(&queue_mutex);
    sem_post(&transactions_to_process);
}

TRANSACTION_REQUEST_T dequeue() {
    TRANSACTION_REQUEST_t transaction;

    sem_wait(&transactions_to_process);
    pthread_mutex_lock(&queue_mutex);
    if (num_transactions == 0) {
        pthread_mutex_unlock(&queue_mutex);
        sem_post(&queue_not_empty);
        return (TRANSACTION_REQUEST_T){0};
    }

    transaction = queue[0];
    memmove(queue, queue + 1, --num_transactions * sizeof(TRANSACTION_REQUEST_T));
    pthread_mutex_unlock(&queue_mutex);

    sem_post(&queue_not_empty);
    return transaction;
}

void process_transaction(const TRANSACTION_REQUEST_T *request, const char *metadata) {
    analytics_func(request, metadata);
    // Update metrics here...
}

void* manage_queue(void *input) {
    int *N = input;
    TRANSACTION_REQUEST_T *new_queue = mmap(NULL, MAX_QUEUE_SIZE * sizeof(TRANSACTION_REQUEST_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_queue == MAP_FAILED) {
        perror(RESOURCE_EXCEEDED_MESSAGE);
        cleanup();
        pthread_exit(NULL);
    }

    sem_init(&queue_not_full, 0, MAX_QUEUE_SIZE);
    sem_init(&queue_not_empty, 0, num_transactions);
    sem_init(&transactions_to_process, 0, 0);

    while (*N-- > 0) {
        TRANSACTION_REQUEST_T request;

        sem_wait(&queue_not_full);
        pthread_mutex_lock(&queue_mutex);
        if (num_transactions == MAX_QUEUE_SIZE) {
            pthread_mutex_unlock(&queue_mutex);
            sem_post(&queue_not_empty);
            continue;
        }

        memcpy(&request, &queue[num_transactions], sizeof(TRANSACTION_REQUEST_T));
        if (validate_transaction(&request)) {
            printf("%s\n", VALIDATION_ERROR_MESSAGE);
            pthread_mutex_unlock(&queue_mutex);
            sem_post(&queue_not_empty);
            continue;
        }

        queue[num_transactions++] = request;
        pthread_mutex_unlock(&queue_mutex);
        sem_post(&transactions_to_process);
    }

    cleanup();
    munmap(new_queue, MAX_QUEUE_SIZE * sizeof(TRANSACTION_REQUEST_T));
    pthread_exit(NULL);
}

void set_analytics_callback(analytics_callback func) {
    analytics_func = func;
}
