int InitializeVideoProcessorConfig(VIDEO_PROCESSOR_CONFIG* config, int num_frames, size_t frame_size, int seed, enum PRIORITY priority) {
    // Validate configuration parameters
    if (num_frames <= 0 || frame_size <= 0 || !(frame_size % sizeof(unsigned char))) {
        fprintf(stderr, "Invalid buffer size or unsupported resolution\n");
        return -1;
    }

    // Allocate and fill pseudo-random pixel sequence
    config->frame_buffer = mmap(NULL, frame_size * num_frames, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (config->frame_buffer == MAP_FAILED) {
        fprintf(stderr, "Memory allocation failed\n");
        return -2;
    }

    srand(seed);
    unsigned char* buffer = config->frame_buffer;
    for (size_t i = 0; i < frame_size * num_frames; ++i) {
        if (priority == SPEED) {
            // Speed-oriented pseudo-random generation
            buffer[i] = rand() & 0xFF;
        } else {
            // Accuracy-oriented pseudo-random generation
            buffer[i] = rand_r(&seed) & 0xFF;
        }
    }

    // Store configuration in the cache
    sem_wait(&buffer_mutex);
    for (size_t i = 0; i < CACHE_MAX_SIZE; ++i) {
        if (!cache[i].frame_buffer) {
            cache[i] = *config;
            break;
        }
    }
    sem_post(&buffer_mutex);

    // Log initialization parameters and return success code
    // ... (Integrate with existing logging framework here)

    return 0;
}
