int main(int argc, char *argv[]) {
    struct opt_args args = {.logfile = NULL, .loglevel = LOG_INFO, .verbose = 0};
    int c;
    const char *short_opts = "l:v";
    const struct option long_opts[] = {
        {"log-level", required_argument, NULL, 'l'},
        {"verbose", no_argument, NULL, 'v'},
        {0}
    };

    while ((c = getopt_long(argc, argv, short_opts, long_opts, NULL)) != -1) {
        switch (c) {
            case 'l':
                args.loglevel = strtoul(optarg, NULL, 10);
                break;
            case 'v':
                args.verbose++;
                break;
            default:
                log(LOG_ERR, "Unknown option: -%c", optopt);
                usage();
        }
    }

    if (argc - optind < 1) {
        usage();
        return EXIT_FAILURE;
    }

    const char *inputfile = argv[optind];
    int inputfd = open(inputfile, O_RDONLY);

    if (inputfd == -1) {
        perror("Opening file");
        exit(EXIT_FAILURE);
    }

    struct stat st;
    fstat(inputfd, &st);
    off_t filesize = st.st_size;
    char *buffer = mmap(NULL, filesize + 4096, PROT_READ, MAP_PRIVATE, inputfd, 0);
    close(inputfd);

    if (buffer == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    char *line = buffer;
    size_t line_len = filesize;
    size_t lines_processed = 0;

    while (lines_processed < filesize) {
        size_t newline = strcspn(line, "\n");
        if (newline >= line_len) {
            log(LOG_ERR, "Malformed line in file: %s", line);
            break;
        }

        char *next_line = line + newline;
        line[newline] = '\0';
        process_line(line);

        lines_processed += newline + 1;
        line = next_line;
        line_len -= newline + 1;
    }

    munmap(buffer, filesize + 4096);

    if (args.verbose) {
        printf("Processed %" PRIuMAX " lines\n", lines_processed);
    }

    closelog();
    return EXIT_SUCCESS;
}
