```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

char* readFileSync(const char *filename) {
    int fd = open(filename, O_RDONLY);

    if (fd == -1) {
        perror("Error opening the file");
        return NULL;
    }

    struct stat file_stat;
    if (fstat(fd, &file_stat) == -1) {
        perror("Error getting file size");
        close(fd);
        return NULL;
    }

    char *content = malloc(file_stat.st_size + 1);

    if (!content) {
        perror("Error allocating memory for the content");
        close(fd);
        return NULL;
    }

    ssize_t bytes_read = read(fd, content, file_stat.st_size);

    if (bytes_read != file_stat.st_size) {
        perror("Error reading the file");
        free(content);
        close(fd);
        return NULL;
    }

    content[file_stat.st_size] = '\0';
    close(fd);

    return content;
}
```

