#ifdef _WIN32
#include <windows.h>
#else
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#endif
#include <iconv.h>

/* Define LTE_DL_FRAME_MSG structure */
typedef struct {
    uint16_t DL_FRAME_TAG;
    uint16_t CELL_ID;
    PHY_DOWNLINK_FRAME phyFrame;
} LTE_DL_FRAME_MSG;

/* Function prototypes */
void* safeMalloc(size_t size);
void readFileSync(const char *filePath, char **contents, size_t *length, const char *encoding);

/* initializeLteFrames function implementation */
LTE_DL_FRAME_MSG* initializeLteFrames(size_t numFrames) {
    LTE_DL_FRAME_MSG *frames = safeMalloc(numFrames * sizeof(LTE_DL_FRAME_MSG));
    for (size_t i = 0; i < numFrames; ++i) {
        frames[i].DL_FRAME_TAG = i + 1;
        frames[i].CELL_ID = rand() % 500 + 1; // Valid cell ID range: 1 - 500

        /* Initialize PHY_DOWNLINK_FRAME structure with random data */
        PHY_DOWNLINK_FRAME *phyFrame = &frames[i].phyFrame;
        phyFrame->numPDUs = rand() % 20 + 10; // Valid range: 10 - 30 PDU instances
        phyFrame->pdus = safeMalloc(phyFrame->numPDUs * sizeof(PHY_DOWNLINK_FRAME_PDU));

        for (size_t j = 0; j < phyFrame->numPDUs; ++j) {
            PHY_DOWNLINK_FRAME_PDU *pdu = &phyFrame->pdus[j];
            pdu->length = rand() % 150 + 50; // Valid range: 50 - 200 bytes per PDU
            pdu->data = safeMalloc(pdu->length);
            memset(pdu->data, (unsigned char)rand(), pdu->length);
        }
    }
    return frames;
}

/* readFileSync function implementation */
void readFileSync(const char *filePath, char **contents, size_t *length, const char *encoding) {
#ifdef _WIN32
    HANDLE file = CreateFile(filePath, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, 0, NULL);
#else
    int file = open(filePath, O_RDONLY | O_CLOEXEC);
#endif

    if (file == INVALID_FILE_HANDLE || file == -1) {
        perror("Error opening file");
        return;
    }

#ifdef _WIN32
    DWORD fileSize = GetFileSize(file, NULL);
#else
    struct stat fileStat;
    fstat(file, &fileStat);
    off_t fileSize = fileStat.st_size;
#endif

    *contents = safeMalloc(fileSize + 1);
    memset(*contents, 0, fileSize + 1);

#ifdef _WIN32
    DWORD readBytes;
    ReadFile(file, *contents, fileSize, &readBytes, NULL);
#else
    ssize_t bytesRead = read(file, *contents, fileSize);
    if (bytesRead == -1) {
        perror("Error reading file");
        return;
    }
#endif

    if (encoding && iconv_t icd = iconv_open(encoding, "UTF-8")) {
        size_t inbufLen = 0, outbufLen = 1024;
        char *inbuf = safeMalloc(outbufLen * sizeof(char));
        char *outbuf = safeMalloc(outbufLen * sizeof(char));

        while (readBytes > 0 || inbufLen > 0) {
            if (readBytes > 0) {
                memcpy(inbuf + inbufLen, *contents + fileSize - readBytes, readBytes);
                readBytes = 0;
            }

            size_t converted = iconv(icd, inbufLen ? &inbuf : NULL, inbufLen ? &(const char *)&inbufLen : NULL, outbuf, &outbufLen);
            if (converted == -1) {
                perror("Error converting encoding");
                free(*contents);
                *length = 0;
                return;
            }

            memcpy(*contents + fileSize - readBytes, outbuf, converted);
            inbufLen = outbufLen - converted;
            readBytes -= converted;
        }

        iconv_close(icd);
    }

#ifdef _WIN32
    CloseHandle(file);
#else
    close(file);
#endif

    *length = fileSize;
}
```

