import java.time.Instant;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class SessionTokenManager {
    private final ConcurrentHashMap<String, Session> sessions = new ConcurrentHashMap<>();
    private final AtomicLong tokenCounter = new AtomicLong();
    private final long tokenExpirySeconds = 300; // Adjust as needed

    public String createSession(User user) {
        Long tokenId = tokenCounter.incrementAndGet();
        Instant expiryTime = Instant.now().plusSeconds(tokenExpirySeconds);
        Session session = new Session(user, tokenId, expiryTime);
        sessions.putIfAbsent(session.getId(), session);
        return session.getId();
    }

    public void invalidateSession(String sessionId) {
        sessions.remove(sessionId);
    }
}
