import hashlib
import os
from tqdm import tqdm

def crc32(file_path):
    with open(file_path, "rb") as f:
        buffer = f.read(4096)
        while len(buffer):
            h = hashlib.new('crc32')
            h.update(buffer)
            buffer = f.read(4096)
    return h.hexdigest()
