    time_t timestamp;
    struct in_addr remote_ip;
    struct in_addr local_ip;
    unsigned long flags;
} TCP_CONNECTION_RECORD_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int num_elements, start_index, end_index, seed;

TCP_CONNECTION_RECORD_T* generate_tcp_connections() {
    TCP_CONNECTION_RECORD_T *arr;
    if (!(arr = calloc(num_elements, sizeof(TCP_CONNECTION_RECORD_T)))) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    for (int i = start_index; i < end_index; ++i) {
        arr[i].connection_id = i + 1;
        arr[i].timestamp = time(NULL);
        arr[i].remote_ip.s_addr = htonl(rand() % (INADDR_MAX - start_index) + start_index);
        arr[i].local_ip.s_addr = htonl(rand() % INADDR_MAX);
        arr[i].flags = rand(); // Assuming flags are 32-bit, adjust as needed for larger values
    }
    pthread_mutex_unlock(&mutex);

    return arr;
}
