```python
import time
from functools import reduce
from itertools import islice, count

def calculate_tcp_connection_probability(data):
    connection_establishment = 0
    total_packets = sum(1 for _ in data)

    progress = lambda current, chunk: f"Analyzing {current*100/total_packets}%"

    def is_connection(packet):
        return packet.flags & (1 << 5) == 1 << 5 # SYN flag set

    packets_by_seconds = sorted(data, key=lambda x: x.timestamp)
    connections = [packet for _, group in itertools.groupby(packets_by_seconds, key=is_connection) if True in group]
    connection_stream = (conn for conn in connections if len(connections) > 1 and is_sequential(connections, conn))

    def is_sequential(connections, current):
        return all([current.timestamp - prev.timestamp <= 5.0 for prev in connections if prev < current])

    for connection in connection_stream:
        connection_establishment += 1
        yield progress(connection_establishment / len(data), count())

def main():
    # Load the generated C data into Python
    # ...

    probability = list(calculate_tcp_connection_probability(data))[0]
    print(f"Connection establishment probability: {probability}")
