void handleLTE_RRC_CU_MESSAGE(LTE_RRC_CU_MESSAGE *msg) {
    // Enqueue if the limit is reached
    if (total_allocated >= MAX_ALLOCATED_MESSAGES) {
        sem_wait(&queue_sem);
        queue[queue_head] = msg;
        queue_head = (queue_head + 1) % MAX_ALLOCATED_MESSAGES;
        sem_post(&msg_sem);
    } else {
        // Allocate memory and handle the message
