        sem_wait(&msg_sem);

        // Process the file in chunks
        char *file_data = mmap(NULL, msg->mac_msg.payload_length, PROT_READ, MAP_PRIVATE, open(msg->config.filename, O_RDONLY), 0);
        unsigned int chunk_size = 1 << 20; // 1 MB chunks
        SHA256_CTX ctx;
        unsigned char hash[SHA256_DIGEST_LENGTH];

        SHA256_Init(&ctx);
        unsigned int bytes_processed = 0, max_bytes = msg->mac_msg.payload_length;

        while (bytes_processed < max_bytes) {
            const size_t this_chunk = (max_bytes - bytes_processed > chunk_size) ? chunk_size : (max_bytes - bytes_processed);
            SHA256_Update(&ctx, file_data + bytes_processed, this_chunk);
            bytes_processed += this_chunk;
        }

        SHA256_Final(hash, &ctx);

        // Use the hashed value and process the message further

        sem_post(&msg_sem);
    }
}

