void init_connection_pool(unsigned int elements, unsigned int seed) {
    connections = malloc(elements * sizeof(TCP_CONNECTION_RECORD_T));
    srand(seed);
}

TCP_CONNECTION_RECORD_T* get_next_connection() {
    pthread_mutex_lock(&mutex);
    TCP_CONNECTION_RECORD_T* connection = &connections[0];
    for (unsigned int i = 1; i < MAX_ELEMENTS; ++i) {
        if (!connections[i].id) {
            connection = &connections[i];
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
    return connection;
}

void populate_connection(TCP_CONNECTION_RECORD_T* record, time_t timestamp, const struct in_addr* remote_ip, const struct in_addr* local_ip, unsigned short tcp_flags) {
    record->id = rand();
    record->timestamp = timestamp;
    *record->remote_ip = *remote_ip;
    *record->local_ip = *local_ip;
