```python
import os
import sys
from collections import defaultdict
import concurrent.futures
import numpy as np

class ConnectionDataStream:
    def __init__(self, filepath):
        self.filepath = filepath
        self.data = []

    def read(self):
        with open(self.filepath, 'r') as f:
            for line in f:
                parts = line.strip().split('\t')
                self.data.append((int(parts[0]), int(parts[1]), tuple(map(int, parts[2:6])), int(parts[-1])))

    def __iter__(self):
        return self

    def next(self):
        if not self.data:
            raise StopIteration
        connection = self.data.pop(0)
        return connection

def calculate_probability(data_streams, establishment_threshold):
    total_connections = sum([len(d) for d in data_streams])
    connection_counts = defaultdict(int)
    established_connections = 0

    with concurrent.futures.ProcessPoolExecutor() as executor:
        results = []
        for data_stream in data_streams:
            future = executor.submit(process_connection, data_stream)
            results.append(future)

        for future in concurrent.futures.as_completed(results):
            result = future.result()
            connection_counts[result] += 1

    for key, count in connection_counts.items():
        if key >= establishment_threshold:
            established_connections += count

    return established_connections / total_connections

def process_connection(data_stream):
    syn = data_stream.next()
    ack = None

    while True:
        try:
            syn_ack = data_stream.next()
            if syn_ack[0] == syn[0] + 1 and syn_ack[3] & 0x15 == 0x12:  # SYN+ACK
                ack = syn_ack
                break
        except StopIteration:
            if ack is not None:
                return ack[0] + 1, ack[3] & 0x15

    return None
```"]

