// Define the structure
struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
    std::atomic<bool> crcFlag{ false };
};

class CRCManager {
public:
    void addElement(const NFAPI_CRC_INDICATION_PDU_T& element) {
        data.push_back(element);
        resizeIfNeeded();
    }

    bool removeElementByRNTI(int rnti) {
        for (auto it = data.begin(); it != data.end(); ++it) {
            if (it->rnti == rnti) {
                data.erase(it);
                return true;
            }
        }
        return false;
    }

    void updateCRCFlags() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return shouldUpdateCRC(); });

        for (auto& element : data) {
            if (element.crcIndicationTag == CR_INDICATION_NEEDED) {
                element.crcFlag = true;
            }
        }

        cv.notify_all();
    }

private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> shouldUpdateCRC{ false };

    bool shouldUpdateCRC() {
        return shouldUpdateCRC.load(std::memory_order_acquire) && !data.empty();
    }

    void resizeIfNeeded() {
        if (data.size() >= MAX_ELEMENTS * 0.75) {
            auto newData = std::vector<NFAPI_CRC_INDICATION_PDU_T>(data);
            data.reserve(newData.size() * 2);
            for (auto& element : newData) {
                if (element.crcIndicationTag == CR_INDICATION_NEEDED) {
                    element.crcFlag = true;
                }
            }
        }
    }
};
```

