['1. Python Function (Processing log files):

```python
import json
from typing import List, Dict, Any
import itertools as it

def parse_log_files(log_files: List[str], schema: Dict[str, Any]) -> Dict[str, Dict[str, float]]:
    kpis = {"average_response_time": 0, "request_latency_distribution": {}, "error_rate": 0}
    for log in (line.strip() for line in it.chain.from_iterable(open(file) for file in log_files)):
        try:
            data = json.loads(log, parse_float=float, object_hook=lambda d: {k.lower(): v for k, v in d.items() if k in schema})
            validate_data(data, schema)
            process_data(data, kpis)
        except Exception as e:
            print(f"Error while processing log file: {e}")
    return kpis

def validate_data(data: Dict[str, Any], schema: Dict[str, Any]):
    for key in data.keys():
        if key not in schema or isinstance(schema[key], str) and type(data[key]) != schema[key]:
            raise ValueError(f"Invalid format for key '{key}'")

def process_data(data: Dict[str, Any], kpis: Dict[str, float]):
    response_time = data["response_time"] if "response_time" in data else None
    latency = data["latency"] if "latency" in data else None
    error = 0.0 if "error" not in data or not data["error"] else 1.0
    update_kpis(kpis, response_time, latency, error)

def update_kpis(kpis: Dict[str, float], response_time=None, latency_dist=None, error_rate=None):
    if response_time is not None:
        kpis["average_response_time"] += response_time / len(log_files)
    if latency_dist is not None:
        for bucket, count in latency_dist.items():
            kpis["request_latency_distribution"][bucket] = (kpis["request_latency_distribution"].get(bucket, 0) + count) / len(log_files)
    if error_rate is not None:
        kpis["error_rate"] += error_rate / len(log_files)
```

