```python
from collections import defaultdict, Counter
from datetime import datetime, timedelta

def process_logs(logs, interval, severities, message_threshold):
    grouped = defaultdict(lambda: defaultdict(Counter, total=0))
    for log in logs:
        timestamp = datetime.strptime(log['timestamp'], '%Y-%m-%d %H:%M:%S')
        grouped[timestamp - timestamp.resolution + interval][log['severity'][0]][log['message']].updates(1)
        grouped[timestamp - timestamp.resolution + interval]['total'][log['severity'][0]] += 1
    outliers = []
    for k, v in grouped.items():
        if any([v['total']['critical'] > 5 or v['total']['error'] > 3 or v['total']['warning'] > 2]):
            outliers.append(k)
    frequent_messages = {message: freq for message, freq in Counter([e[0] for e in grouped[interval[0]] if e[1]['total']['info'] < message_threshold]).most_common(5)}
    return {'outliers': outliers, 'frequent_messages': frequent_messages}
```

