```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void reverse_file(const char *inputFile, const char *outputFile)
{
    FILE *in = fopen(inputFile, "rb");
    if (!in)
    {
        fprintf(stderr, "Failed to open input file: %s\n", inputFile);
        return;
    }

    FILE *out = fopen(outputFile, "wb");
    if (!out)
    {
        fprintf(stderr, "Failed to open output file: %s\n", outputFile);
        fclose(in);
        return;
    }

    char buffer[256];
    size_t bytesRead;

    while ((bytesRead = fread(buffer, sizeof(char), sizeof(buffer), in)) > 0)
    {
        fwrite(buffer + bytesRead - 1, sizeof(char), bytesRead, out);
    }

    fclose(in);
    fclose(out);
}
