#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdbool.h>
#include <sys/stat.h>
#include <ffmpeg/avcodec.h>
#include <ffmpeg/avformat.h>
#include <ffmpeg/swresample.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    AVFormatContext* pFormatCtx;
    AVCodecContext* pCodecCtx;
    AVCodec* pCodec;
    AVFrame* pFrame;
    AVPacket* packet;
    FILE *logFile;
} VideoConverterContext;

static int my_ffprobe(const char *filename, unsigned long *width, unsigned long *height) {
    AVProbeData probe;
    memset(&probe, 0, sizeof(AVProbeData));
    strncpy(probe.filename, filename, FF_MAXINPUTSIZE - 1);
    probe.size = strlen(filename);

    if (avprobe_probe(&probe, 0, 0, NULL, 0, 0) < 0) {
        return -1;
    }

    *width = probe.video_stream_index >= 0 ? probe.format_ctx->streams[probe.video_stream_index]->codecpar->width : 0;
    *height = probe.video_stream_index >= 0 ? probe.format_ctx->streams[probe.video_stream_index]->codecpar->height : 0;

    return 0;
}

static int my_ffmpeg(const char *input, const char *output, unsigned long maxSize, FILE *logFile) {
    VideoConverterContext ctx = {0};
    int ret = 0;

    ctx.pFormatCtx = avformat_alloc_context();
    if (!ctx.pFormatCtx) {
        goto fail;
    }

    ctx.logFile = logFile;

    // Open input file
    if (avio_open(&ctx.pFormatCtx->pb, input, AVIO_FLAG_READ, 0, 0) < 0) {
        ret = 1;
        goto fail;
    }

    // Retrieve stream information
    if (avformat_find_stream_info(ctx.pFormatCtx, 0) < 0) {
        ret = 1;
        goto fail;
    }

    unsigned long width, height;
    if (my_ffprobe(input, &width, &height) < 0) {
        ret = 1;
        goto fail;
    }

    // Define the output codec parameters
    ctx.pCodecCtx = avcodec_alloc_context3(av_find_best_video_codec(ctx.pFormatCtx, &ctx.pCodec, NULL, 0, 0));
    if (!ctx.pCodecCtx) {
        ret = 1;
        goto fail;
    }

    ctx.pCodecCtx->bit_rate = maxSize;
    ctx.pCodecCtx->width = width;
    ctx.pCodecCtx->height = height;
    ctx.pCodecCtx->time_base = (AVRational){1, 25}; // 25 fps
    ctx.pCodecCtx->gop_size = 25;
    ctx.pCodecCtx->pix_fmt = AV_PIX_FMT_YUV420P;

    // Open output file
    if (avio_open(&ctx.pFormatCtx->ostream, output, AVIO_FLAG_WRITE, 0, 0) < 0) {
        ret = 1;
        goto fail;
    }

    ctx.pFormatCtx->oformat = av_guess_format(NULL, output, NULL);
    if (!ctx.pFormatCtx->oformat) {
        ret = 1;
        goto fail;
    }

    // Write the stream header at output file
    if (avformat_write_header(&ctx.pFormatCtx, NULL) < 0) {
        ret = 1;
        goto fail;
    }

    ctx.pCodec = avcodec_find_encoder(ctx.pCodecCtx->codec_id);
    if (!ctx.pCodec) {
        ret = 1;
        goto fail;
    }

    ctx.pFrame = av_frame_alloc();
    if (!ctx.pFrame) {
        ret = 1;
        goto fail;
    }

    ctx.packet = (AVPacket *)av_malloc(sizeof(AVPacket));
    if (!ctx.packet) {
        ret = 1;
        goto fail;
    }

    AVDictionary* options = NULL;
    av_dict_set(&options, "crf", "23", 0); // Quality settings for the encoder

    // Open codec
    if (avcodec_open2(ctx.pCodecCtx, ctx.pCodec, &options) < 0) {
        ret = 1;
        goto fail;
    }

    // Prepare for encoding and save data to output file
    while (AV_READ_FRAME(ctx.pFormatCtx, ctx.packet) >= 0) {
        if (ctx.packet->stream_index == ctx.pFormatCtx->video_stream_index) {
            // Process video frames only
            avcodec_send_packet(ctx.pCodecCtx, ctx.packet);

            while (avcodec_receive_frame(ctx.pCodecCtx, ctx.pFrame) == 0) {
                // Save the encoded frame to output file
                if (av_interleaved_write_frame(ctx.pFormatCtx, ctx.pFrame) < 0) {
                    ret = 1;
                    goto fail;
                }
            }
        }

        av_packet_unref(ctx.packet);
    }

fail:
    // Cleanup and log errors
    if (ctx.pFormatCtx) {
        avformat_free_context(ctx.pFormatCtx);
    }

    if (ctx.pCodecCtx) {
        avcodec_free_context(&ctx.pCodecCtx);
    }

    if (ctx.pFrame) {
        av_frame_free(&ctx.pFrame);
    }

    if (ctx.packet) {
        av_free(ctx.packet);
    }

    if (ctx.logFile && ret == 1) {
        time_t now = time(NULL);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(ctx.logFile, "[%s] Error converting video: %s\n", buf, av_err2str(av_errno()));
    }

    if (ret == 1) {
        return 1;
    }

    // Check if the output file exceeded the maximum size
    struct stat st;
    if (stat(output, &st) < 0 || st.st_size > maxSize) {
        fprintf(stderr, "Output file size exceeded the maximum allowed limit: %llu bytes\n", maxSize);
        return 1;
    }

    return 0;
}

int convertVideoToWebM(const char *input, const char *outputDir, const char *logFile, unsigned long maxSize) {
    char output[256] = "";
    snprintf(output, sizeof(output), "%s/%s.webm", outputDir, basename(input));

    FILE *logFd = fopen(logFile, "w");
    if (!logFd) {
        return 1;
    }

    int ret = my_ffmpeg(input, output, maxSize, logFd);
    fclose(logFd);

    return ret;
}
```
