typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    int sequence_number;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _ListNode* next;
    pthread_mutex_t mutex;
} ListNode;

enum ErrorCodes {
    ERROR_CODE_SUCCESS = 0,
    ERROR_CODE_OUT_OF_MEMORY = -1,
    ERROR_CODE_CRC_THRESHOLD_EXCEEDED = -2,
    ERROR_CODE_LIST_ALLOCATION_FAILURE = -3
};

ListNode* create_list() {
    ListNode *head = NULL;
    pthread_mutex_init(&head->mutex, NULL); // Initialize head node's mutex
    return head;
}

int add_to_list(ListNode **list, NFAPI_CRC_INDICATION_PDU_T *data) {
    ListNode *new_node = (ListNode *)malloc(sizeof(ListNode));
    if (!new_node) return ERROR_CODE_OUT_OF_MEMORY;

    pthread_mutex_init(&new_node->mutex, NULL); // Initialize new node's mutex

    new_node->data = *data;
    new_node->next = NULL;

    pthread_mutex_lock(&list[0]->mutex); // Lock the head node's mutex
    if (!head) {
        head = new_node;
    } else {
        ListNode *current = head;
        while (current->next) current = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&list[0]->mutex); // Unlock the head node's mutex

    return ERROR_CODE_SUCCESS;
}

int validate_crc(NFAPI_CRC_INDICATION_PDU_T *data) {
    // Implement your CRC validation logic here. Return 0 if valid, non-zero otherwise.
    return data->crc_indication.crcflag > CRC_THRESHOLD;
}

void *process_element(void *arg) {
    ListNode **list = (ListNode **)arg;
    NFAPI_CRC_INDICATION_PDU_T data;

    // Generate random RNTI, sequence number and CRCFLAG for the structure.
    data.tag = generate_tag();
    data.rnti = generate_rnti();
    data.sequence_number = generate_sequence_number();
    data.crc_indication.crcflag = random() % 10 + 5; // Set CRCFLAG between 5 and 14 (inclusive)

    if (validate_crc(&data)) return NULL; // If validation fails, skip this element

    int result = add_to_list(list, &data);
    if (result != ERROR_CODE_SUCCESS) {
        fprintf(stderr, "Error adding to the list: %d\n", result);
        return NULL;
    }

    return NULL;
}

int populate_list(ListNode **list, unsigned int num_elements, pthread_t *threads) {
    for (unsigned int i = 0; i < num_elements; ++i) {
        pthread_create(&threads[i], NULL, process_element, list);
    }

    for (unsigned int i = 0; i < num_elements; ++i) {
        pthread_join(threads[i], NULL);
    }

    return ERROR_CODE_SUCCESS;
}
