        streams.putIfAbsent(streamId, provider.createConnectionStream());
    }

    public void processEvents(List<Event> events) {
        Spliterator<Event> spliterator = events.spliterator();
        while (spliterator.tryAdvance((event) -> processSingleEvent(event)));
    }

    private void processSingleEvent(Event event) {
        Pair nodePair = new Pair(event.getNode1(), event.getNode2());
        Connection connection = event.getConnection();

        if (connection.isBidirectional()) {
            intervalTree.insert(event.getTimestamp(), nodePair, connection);
        }

        priorityQueue.add(event);
    }

    private void processPriorityQueue() {
        while (!priorityQueue.isEmpty()) {
            Event event = priorityQueue.poll();
            processSingleEvent(event);
        }
    }

