import heapq
import time
import sys

class SlidingWindow:
    def __init__(self, max_memory=4e9, min_window_size_ms=100, max_window_size_ms=500):
        self.max_memory = max_memory
        self.min_window_size_ms = min_window_size_ms
        self.max_window_size_ms = max_window_size_ms
        self.event_queue = []
        self.stock_windows = {}

    def add_event(self, timestamp, stock, transaction):
        event = (timestamp, stock, transaction)
        now = int(time.time() * 1000)
        window_key = f"{now - self.min_window_size_ms}_{now}"

        if window_key not in self.stock_windows:
            self.stock_windows[window_key] = {stock: 0 for stock in set(self.event_queue)}

        self.event_queue.append(event)

        while len(self.event_queue) > self.max_memory // (self.min_window_size_ms * len(self.stock_windows)):
            earliest_timestamp = heapq.heappop(self.event_queue)[0]
            oldest_window_key = f"{earliest_timestamp}_{earliest_timestamp + self.min_window_size_ms}"
            del self.stock_windows[oldest_window_key]

        if now - self.event_queue[0][0] > self.max_window_size_ms:
            heapq.heappop(self.event_queue)

        self.stock_windows[window_key][stock] += 1 if transaction == "buy" else -1 * self.stock_windows[window_key][stock]

    def get_trade_volumes(self, window_size_ms=None):
        if window_size_ms is not None:
            self.min_window_size_ms = max(self.min_window_size_ms, window_size_ms)
            self.max_window_size_ms = min(self.max_window_size_ms, window_size_ms * 2)

        results = []
        for stock, volume in self.stock_windows[list(self.stock_windows.keys())[-1]].items():
            results.append((stock, volume))

        return results

    def log_processing_time(self):
        if sys.version_info >= (3, 8):
            print(f"Processed {len(self.event_queue)} events in {(time.monotonic() - self.start_time) * 1000:.2f} ms")
            self.start_time = time.monotonic()
        else:
            print(f"Processed {len(self.event_queue)} events in {(time.clock() - self.start_time) * 1000:.2f} ms")
            self.start_time = time.clock()
