import requests
import time

def get_metadata(file_path):
    # Placeholder for the external metadata service request
    try:
        response = requests.get(f'https://metadata-service.com/api/v1/files/{os.path.basename(file_path)}')
        if response.status_code != 200:
            raise Exception(f"Failed to retrieve metadata for file: {response.status_code}")
        return response.json()
    except Exception as e:
        print(f"Error retrieving metadata for file: {e}")
        return None

def process_chunk(file, hash_obj, chunk_size=65536):
    block = file.read(chunk_size)
    if not block:
        return hash_obj.digest()
    hash_obj.update(block)

def calculate_md5(file_path, chunk_size=65536):
    metadata = get_metadata(file_path)
    if metadata is None or 'chunked' not in metadata:
        with open(file_path, "rb") as file:
            hash_obj = md5()
            with concurrent.futures.ThreadPoolExecutor() as executor:
                for chunk in executor.chunks(len(file), lambda: process_chunk(file, hash_obj, chunk_size)):
                    pass
        return hash_obj.hexdigest()

    # If the file is already chunked, read it as-is from memory
    with open(file_path, "rb") as file:
        hash_obj = md5()
        for line in file:
            hash_obj.update(line)
        return hash_obj.hexdigest()

# Usage example:
if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python md5_large_file.py <file_path>")
        sys.exit(1)

    file_path = sys.argv[1]
    print(calculate_md5(file_path))
