class LogProcessor:
    def __init__(self, api):
        self.api = api
        self.cache = {}
        self.chunk_size = 10000
        self.time_window = timedelta(minutes=15)

    async def _process_file(self, filepath):
        events = []
        with open(filepath, "r") as f:
            for line in f:
                event = process_log_line(line)
                if event:
                    events.append(event)
        return events

    async def _process_chunk(self, files):
        events = []
        for filepath in files:
            events += await self._process_file(filepath)

        # Classify and normalize events using the API
        event_ids = [event["id"] for event in events]
        if event_ids:
            response = await self.api.get("/events", params={"event_ids": ",".join(event_ids)})
            if response:
                for event, normalized_event in zip(events, response):
                    event["normalized"] = normalized_event
        return events

    async def process_directory(self, directory):
        started = time.time()
        total_events = 0
        aggregated_metrics = {}

        file_batches = list(chunkify(os.listdir(directory), self.chunk_size))

        with concurrent.futures.ThreadPoolExecutor() as executor:
            future_to_file = {executor.submit(self._process_chunk, batch): batch for batch in file_batches}

            for future in concurrent.futures.as_completed(future_to_file):
                batch = future_to_file[future]
                events = future.result()
                total_events += len(events)

                for event in events:
                    timestamp = event["timestamp"]
                    if timestamp not in aggregated_metrics:
                        aggregated_metrics[timestamp] = {"count": 0, "events": []}

                    aggregated_metrics[timestamp]["count"] += 1
                    aggregated_metrics[timestamp]["events"].append(event)

                # Cache classified events for a short time to reduce API calls
                cache_key = f"{event.get('id')}-{event.get('type')}"
                if cache_key in self.cache:
                    elapsed = time.time() - started
                    print(f"Cached event {cache_key} | Elapsed time: {elapsed:.2f} seconds")
                    event["normalized"] = self.cache[cache_key]
                else:
                    try:
                        normalized_event = await self.api.get(f"/events/{event['id']}/classify")
                        if normalized_event:
                            self.cache[cache_key] = normalized_event
                            event["normalized"] = normalized_event
                    except Exception as e:
                        print(f"Failed to classify event {cache_key}: {e}")

        return {"aggregated_metrics": aggregated_metrics, "total_events": total_events}

def process_log_line(line):
    # Implement logic for parsing a single line from the log file into an event dictionary
    pass

def chunkify(iterable, chunk_size):
    chunk = []
    for item in iterable:
        chunk.append(item)
        if len(chunk) >= chunk_size:
            yield chunk
            chunk = []
    if chunk:
        yield chunk
