using OpenTK;
using OpenTK.Crypto;
using static System.Console;

namespace GameInitialization
{
    public class GameConfig
    {
        public int TileSize { get; set; }
        public Vector2 WorldSize { get; set; }
        public float CameraSpeed { get; set; }
        public int ChunkSize { get; set; }
    }

    public class CipherObject
    {
        // Implement cipher object here
    }

    public class GameInitialization
    {
        private Dictionary<string, GameConfig> _configs = new Dictionary<string, GameConfig>();
        private readonly Object _lock = new Object();

        public GameInitialization(string configFilePath)
        {
            LoadConfigurations(configFilePath);
        }

        private void LoadConfigurations(string configFilePath)
        {
            var xDoc = XDocument.Load(configFilePath);
            foreach (var el in xDoc.Root.Elements("Configuration"))
            {
                _configs[el.Attribute("name").Value] = new GameConfig
                {
                    TileSize = int.Parse(el.Element("TileSize").Value),
                    WorldSize = new Vector2(int.Parse(el.Element("WorldWidth").Value), int.Parse(el.Element("WorldHeight").Value)),
                    CameraSpeed = float.Parse(el.Element("CameraSpeed").Value),
                    ChunkSize = int.Parse(el.Element("ChunkSize").Value)
                };
            }
        }

        public CipherObject processLevelWithCipher(string levelFilePath, int chunkSize, string openSslOperation)
        {
            var cipherObject = new CipherObject();
            var progressInterval = chunkSize * 10;
            long processedBytes = 0;

            using (var reader = new StreamReader(levelFilePath))
            {
                byte[] buffer = new byte[chunkSize];
                MD5 md5Hasher = MD5.Create();
                var cipher = CryptoFactory.CreateCipher(openSslOperation);

                while (!reader.EndOfStream)
                {
                    int bytesRead = reader.ReadExact(buffer, 0, buffer.Length);
                    processedBytes += bytesRead;

                    if (ProcessCanceled || processedBytes % progressInterval == 0)
                        Write($"Processed: {processedBytes} of {levelFilePath} ({((float)processedBytes / reader.BaseStream.Length) * 100}%)");

                    md5Hasher.TransformBlock(buffer, 0, bytesRead, null, 0);

                    using (var memoryStream = new MemoryStream(buffer))
                    {
                        cipher.Process(memoryStream, CryptoMode.Encrypt);
                        buffer = memoryStream.ToArray();
                    }
                }

                md5Hasher.TransformFinalBlock(buffer, 0, buffer.Length);
                var md5HashBytes = md5Hasher.Hash;
                cipherObject.Md5Hash = BitConverter.ToString(md5HashBytes).Replace("-", "");
            }

            return cipherObject;
        }

        private bool ProcessCanceled { get; set; }

        public void Start()
        {
            var tasks = new List<Task>();

            foreach (var config in _configs.Values)
            {
                tasks.Add(Task.Factory.StartNew(() => processLevelWithCipher($"Levels/{config.WorldSize.X}_{config.WorldSize.Y}.txt", config.ChunkSize, "Aes128Cbc"));
            }

            Task.WaitAll(tasks.ToArray());
        }
    }
}
