import java.io.*;
import java.time.Instant;
import java.util.*;
import com.fasterxml.jackson.databind.JsonSerializer;
import com.fasterxml.jackson.databind.ObjectMapper;

public class ResourceCache {
    private static final int MAX_CACHE_SIZE = 1000;
    private final LruCache<String, ResourceItem> cache;
    private final ObjectMapper objectMapper;
    private final File jsonFile;

    public ResourceCache() {
        this.cache = new LruCache<>(MAX_CACHE_SIZE);
        this.objectMapper = new ObjectMapper();
        this.jsonFile = new File("resource-cache.json");
    }

    public void addResource(String key, Instant timestamp, ResponseDetails responseDetails) {
        ResourceItem resourceItem = new ResourceItem(key, timestamp, responseDetails);
        cache.put(key, resourceItem);
        saveCacheToFile();
    }

    public void evictResources() {
        cache.trimToSize(MAX_CACHE_SIZE);
        saveCacheToFile();
    }

    public void updateResponseDetails(String key, ResponseDetails newResponseDetails) {
        ResourceItem resourceItem = cache.get(key);
        if (resourceItem != null) {
            resourceItem.setResponseDetails(newResponseDetails);
            saveCacheToFile();
        }
    }

    private void saveCacheToFile() {
        try {
            objectMapper.writeValue(jsonFile, cache);
        } catch (IOException e) {
            throw new RuntimeException("Failed to serialize cache data", e);
        }
    }

    public void loadCacheFromFile() {
        try {
            ResourceCache loadedCache = objectMapper.readValue(jsonFile, ResourceCache.class);
            for (Map.Entry<String, ResourceItem> entry : loadedCache.cache.entrySet()) {
                cache.put(entry.getKey(), entry.getValue());
            }
        } catch (IOException e) {
            if (!jsonFile.exists()) {
                System.out.println("Resource cache file not found, creating a new one.");
            } else {
                throw new RuntimeException("Failed to deserialize cache data", e);
            }
        }
    }

    static class ResourceItem extends HashMap<String, Object> implements Serializable {
        private static final long serialVersionUID = 1L;

        public ResourceItem(String key, Instant timestamp, ResponseDetails responseDetails) {
            put("key", key);
            put("timestamp", timestamp.toEpochMilli());
            put("responseDetails", responseDetails);
        }

        public void setResponseDetails(ResponseDetails newResponseDetails) {
            put("responseDetails", newResponseDetails);
        }
    }

    static class LruCache<K, V> extends LinkedHashMap<K, V> {
        private final int cacheSize;

        public LruCache(int cacheSize) {
            super(cacheSize + 1, 0.75f, true); // Use a load factor of 0.75 to reduce resizing frequency
            this.cacheSize = cacheSize;
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > cacheSize;
        }
    }
}
```

