#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <openssl/md5.h>

typedef struct {
    double value;
    size_t len;
    char str[1]; // dynamic array for string buffer
} entry;

entry* load_entries(const char *filename, size_t *num_entries) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    size_t total_size = 0; // for string buffer allocation
    entry *data = NULL;
    int entry_count = 0;

    while (!feof(file)) {
        entry *new_entry = realloc(data, sizeof(entry) * (entry_count + 1));
        if (!new_entry) {
            free(data);
            fclose(file);
            return NULL;
        }
        data = new_entry;

        size_t read = fscanf(file, "%lf%*[^\n]\n", &data[entry_count].value);
        if (read != 1) break;

        char c;
        while ((c = fgetc(file)) != '\n' && !feof(file)) {} // skip string until newline

        rewind(file); // move back to the start of the line to read the string
        size_t len = 0;
        char str[4096]; // large buffer for string reading
        while ((c = fgetc(file)) != '\n' && !feof(file)) {
            if (len >= sizeof(str) - 1) break; // avoid buffer overflow
            str[len++] = c;
        }
        data[entry_count].len = len;
        if (data + entry_count + 1 == data) { // reallocate for string buffer growth
            total_size += len + sizeof(entry);
            data = realloc(data, total_size);
        }
        memcpy(data[entry_count].str, str, len + 1); // copy the string into the entry struct

        entry_count++;
    }
    *num_entries = entry_count;
    fclose(file);

    return data;
}

double calculate_average(const entry *data, size_t num_entries) {
    double sum = 0.0;
    for (size_t i = 0; i < num_entries; ++i) {
        sum += data[i].value;
    }
    return sum / num_entries;
}

char* md5_hash(const void *data, size_t len) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, data, len);
    MD5_Final(digest, &ctx);

    static char hash[33 + 1]; // +1 for null-terminator
    for (size_t i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&hash[2*i], "%02x", digest[i]);
    }
    hash[64] = '\0'; // null-terminate the string
    return hash;
}

char* process_file(const char *filename) {
    size_t num_entries = 0;
    entry *data = load_entries(filename, &num_entries);

    if (!data) return "Error: Unable to load data.";

    double average = calculate_average(data, num_entries);
    free(data); // deallocate memory

    char md5[MD5_DIGEST_LENGTH * 2 + 1]; // md5 hash string
    strcpy(md5, md5_hash((const void *)&average, sizeof(double)));

    // handle exceptions gracefully when performing the MD5 conversion
    if (strchr(md5, ':')) return "Error: MD5 calculation failed.";

    return md5;
}
