```python
import hashlib
import threading
import os

def calculate_md5(filepath):
    block_size = 65536
    md5 = hashlib.md5()
    with open(filepath, 'rb') as f:
        while True:
            data = f.read(block_size)
            if not data:
                break
            md5.update(data)
    return md5.hexdigest()

class MD5Lock:
    def __init__(self):
        self.lock = threading.Lock()

    def update(self, md5, data):
        with self.lock:
            md5.update(data)

    def hexdigest(self, md5):
        with self.lock:
            return md5.hexdigest()

calculate_md5_threadsafe = lambda filepath: calculate_md5(filepath, MD5Lock())
```

