#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int frame_width;
    int frame_height;
    double framerate;
    void* buffer;
} VIDEO_PROCESSOR_CONFIG;

struct video_frame_cache {
    pthread_mutex_t mutex;
    VIDEO_PROCESSOR_CONFIG** cache;
    size_t num_frames;
};

VIDEO_PROCESSOR_CONFIG* initialize_video_frame(const VIDEO_PROCESSOR_CONFIG* config, struct video_frame_cache* cache) {
    // Perform validation and logging here
    if (config->framerate <= 0 || !(is_allowed_resolution(config->frame_width, config->frame_height))) {
        fprintf(stderr, "Error: Invalid configuration parameters\n");
        return NULL;
    }

    pthread_mutex_lock(&cache->mutex);

    // Reuse previously allocated buffer if available or allocate a new one
    size_t index = get_frame_index(config, cache);
    VIDEO_PROCESSOR_CONFIG* prev_config = cache->cache[index];

    if (prev_config && memcmp(prev_config, config, sizeof(VIDEO_PROCESSOR_CONFIG)) == 0) {
        void** buffer_ptr = &(prev_config->buffer);
        cache->cache[index] = NULL; // Mark as available
        --cache->num_frames;
        void* buffer = *buffer_ptr;
        *buffer_ptr = NULL;
        pthread_mutex_unlock(&cache->mutex);
        return (VIDEO_PROCESSOR_CONFIG){ .frame_width = config->frame_width, .frame_height = config->frame_height, .framerate = config->framerate, .buffer = buffer };
    }

    pthread_mutex_unlock(&cache->mutex);

    // Allocate a new buffer and return the configuration
    void* buffer = malloc(config->frame_width * config->frame_height * sizeof(unsigned char));
    if (!buffer) {
        fprintf(stderr, "Error: Failed to allocate memory for video frame\n");
        return NULL;
    }

    VIDEO_PROCESSOR_CONFIG* frame = malloc(sizeof(VIDEO_PROCESSOR_CONFIG));
    if (!frame) {
        free(buffer);
        fprintf(stderr, "Error: Failed to allocate memory for video frame configuration\n");
        return NULL;
    }

    frame->frame_width = config->frame_width;
    frame->frame_height = config->frame_height;
    frame->framerate = config->framerate;
    frame->buffer = buffer;

    // Add to the cache and return the configuration
    pthread_mutex_lock(&cache->mutex);
    cache->cache[index] = frame;
    ++cache->num_frames;
