static pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* list = NULL;
static size_t count = 0;
static size_t maxSize = MAX_LIST_SIZE;

void validateStructure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    if (!structure || !structure->tag.present || !structure->rnti.present || !structure->crcIndicationTag.present) {
        fprintf(stderr, "Invalid structure\n");
        return;
    }
}

void addStructureToList(NFAPI_CRC_INDICATION_PDU_T* structure) {
    pthread_mutex_lock(&listMutex);
    if (count >= maxSize) {
        fprintf(stderr, "List is full\n");
        validateStructure(structure);
        free(structure);
        pthread_mutex_unlock(&listMutex);
        return;
    }

    list[count++] = *structure;
    validateStructure(structure);
    pthread_mutex_unlock(&listMutex);
}

void destroyList() {
    pthread_mutex_lock(&listMutex);
    for (size_t i = 0; i < count; ++i) {
        free(list + i);
    }
    list = NULL;
    count = 0;
    pthread_mutex_unlock(&listMutex);
}

NFAPI_CRC_INDICATION_PDU_T* createListAndPopulate(size_t size) {
    if (size > maxSize) {
        fprintf(stderr, "List size exceeds maximum limit\n");
        return NULL;
    }

    pthread_mutex_lock(&listMutex);
    NFAPI_CRC_INDICATION_PDU_T* tempList = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!tempList) {
        fprintf(stderr, "Failed to allocate memory for temporary list\n");
        pthread_mutex_unlock(&listMutex);
        return NULL;
    }

    maxSize = size;
    count = size;
    list = tempList;
    pthread_mutex_unlock(&listMutex);

