void init_pool() {
    pthread_mutex_init(&pool_mutex, NULL);
    pool = (NFAPI_MESSAGE_T**)calloc(MAX_POOL_SIZE, sizeof(NFAPI_MESSAGE_T*));
}

void destroy_pool() {
    for (int i = 0; i < pool_size; ++i) {
        free(pool[i]);
    }
    free(pool);
    pthread_mutex_destroy(&pool_mutex);
}

NFAPI_MESSAGE_T* get_message() {
    pthread_mutex_lock(&pool_mutex);
    if (pool_size < MAX_POOL_SIZE) {
        NFAPI_MESSAGE_T *message = (NFAPI_MESSAGE_T*)calloc(1, sizeof(NFAPI_MESSAGE_T));
        if (message != NULL) {
            pool[pool_size++] = message;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
    return pool[--pool_size];
}

void free_message(NFAPI_MESSAGE_T* message) {
    if (message != NULL) {
        pthread_cleanup_push(free, message);
    }
}

void cleanup() {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < pool_size; ++i) {
        if (pool[i] == NULL) continue;
        free_message(pool[i]);
    }
    pool_size = 0;
    pthread_mutex_unlock(&pool_mutex);
}
