    bool paging_request_flag;
} NR_RRC_UE_CONTEXT_T;

typedef struct node {
    NR_RRC_UE_CONTEXT_T data;
    struct node* next;
} Node;

typedef struct {
    Node** array;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DynamicArray;

void dynamic_array_init(DynamicArray* arr, size_t initial_capacity) {
    arr->array = malloc(initial_capacity * sizeof(Node*));
    memset(arr->array, 0, initial_capacity * sizeof(Node*));
    arr->capacity = initial_capacity;
    arr->length = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    pthread_cond_init(&arr->cond, NULL);
}

void dynamic_array_add(DynamicArray* arr, const NR_RRC_UE_CONTEXT_T* data) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->length >= arr->capacity) {
        arr->capacity *= 2;
        Node** new_array = realloc(arr->array, arr->capacity * sizeof(Node*));
        if (!new_array) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&arr->mutex);
            return;
        }
        arr->array = new_array;
    }
    Node* node = malloc(sizeof(Node));
    if (!node) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&arr->mutex);
        return;
    }
    node->data = *data;
    node->next = arr->array[arr->length];
    arr->array[arr->length] = node;
    arr->length++;
    pthread_mutex_unlock(&arr->mutex);
}

Node* dynamic_array_remove(DynamicArray* arr, int cell_id) {
    pthread_mutex_lock(&arr->mutex);
    size_t i;
    for (i = 0; i < arr->length; ++i) {
        if (arr->array[i]->data.cell_id == cell_id) {
            Node* node_to_remove = arr->array[i];
            arr->array[i] = arr->array[i]->next;
            --arr->length;
            pthread_mutex_unlock(&arr->mutex);
            return node_to_remove;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    return NULL;
}

void dynamic_array_update(DynamicArray* arr, int cell_id, bool set_paging_request) {
    pthread_mutex_lock(&arr->mutex);
    size_t i;
    for (i = 0; i < arr->length; ++i) {
        if (arr->array[i]->data.cell_id == cell_id) {
            arr->array[i]->data.paging_request_flag = set_paging_request;
            break;
        }
    }
    pthread_mutex_unlock(&arr->mutex);
}

