typedef struct {
    NAS_MESSAGE_T nas_message;
    RRC_STATE rrc_state;
    int cell_id;
    bool paging_request_flag;
} NR_RRC_UE_CONTEXT_T;

typedef std::vector<NR_RRC_UE_CONTEXT_T> DynamicArray;

void dynamic_array_init(DynamicArray& arr, size_t initial_capacity) {
    arr.reserve(initial_capacity);
}

void dynamic_array_add(DynamicArray& arr, const NR_RRC_UE_CONTEXT_T& data) {
    std::unique_lock<std::mutex> lock(arr.mut_);
    arr.cond_.wait(lock, [&]() { return arr.size() < arr.capacity_; });
    arr.push_back(data);
    lock.unlock();
}

NR_RRC_UE_CONTEXT_T* dynamic_array_remove(DynamicArray& arr, int cell_id) {
    std::unique_lock<std::mutex> lock(arr.mut_);
    auto it = std::find_if(arr.begin(), arr.end(), [cell_id](const NR_RRC_UE_CONTEXT_T& e) { return e.cell_id == cell_id; });
    if (it != arr.end()) {
        arr.erase(it);
        lock.unlock();
        return &*it;
    }
    lock.unlock();
    return nullptr;
}

void dynamic_array_update(DynamicArray& arr, int cell_id, bool set_paging_request) {
    std::unique_lock<std::mutex> lock(arr.mut_);
    for (auto it = arr.begin(); it != arr.end(); ++it) {
        if (it->cell_id == cell_id) {
            it->paging_request_flag = set_paging_request;
            break;
        }
    }
    lock.unlock();
}
