        return NULL;
    }

    pdu_list_t *list = malloc(sizeof(pdu_list_T));
    if (!list) {
        return NULL;
    }

    list->capacity = num_entries;
    list->size = 0;
    list->entries = calloc(num_entries, ENTRY_SIZE);
    if (!list->entries) {
        free(list);
        return NULL;
    }

    sem_init(&list->lock, 0, 1);

    return list;
}

void pdu_list_add_entry(pdu_list_t *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (list->size >= list->capacity || pdu->RNTI > UINT16_MAX) {
        return;
    }

    sem_wait(&list->lock);

    memcpy((char *)list->entries + ENTRY_SIZE * list->size, pdu, ENTRY_SIZE);
    nfapi_crc_indication_pdu_t_init(pdu); // reset RNTI for next use
    list->size++;

    sem_post(&list->lock);
}

void pdu_list_destroy(pdu_list_t **list) {
    if (!*list) {
        return;
    }

    free(*list->entries);
    free(*list);
    *list = NULL;
}

