    private final ObjectLock lock = new ObjectLock();
    private final LRUCache<ResourceKey, ResourceItem> cache;
    private GraphDatabase graph;
    private Random random;
    private int maxCacheSize;
    private float inclusiveRange, exclusiveRange;
    private Vector3 rangeVector3;
    private Quaternion rangeQuaternion;

    public DynamicCacheGraphBuilder(int maxCacheSize) {
        this.maxCacheSize = maxCacheSize;
        cache = new LRUCache<>(maxCacheSize);
        random = new ThreadLocalRandom();
    }

    public void setInclusiveRange(float inclusiveRange) {
        this.inclusiveRange = inclusiveRange;
    }

    public void setExclusiveRange(float exclusiveRange) {
        this.exclusiveRange = exclusiveRange;
    }

    // Implement methods for setting rangeVector3 and rangeQuaternion

    public void addResource(ResourceKey key, Timestamp timestamp, ResponseDetails response) {
        lock.lock();
        try {
            ResourceItem item = new ResourceItem(key, timestamp, response);
            cache.put(key, item);
        } finally {
            lock.unlock();
        }
    }

    public void updateResponse(ResourceKey key, ResponseDetails newResponse) {
        lock.lock();
        try {
            ResourceItem item = cache.get(key);
            if (item != null) {
                item.setResponse(newResponse);
            }
        } finally {
            lock.unlock();
        }
    }

    public void evictLeastRecentlyUsed() {
        lock.lock();
        try {
            ResourceItem leastRecentlyUsed = null;
            for (ResourceItem item : cache.asMap().values()) {
                if (leastRecentlyUsed == null || item.getTimestamp().toEpochMilli() < leastRecentlyUsed.getTimestamp().toEpochMilli()) {
                    leastRecentlyUsed = item;
                }
            }
            if (leastRecentlyUsed != null) {
                cache.evict(leastRecentlyUsed.getKey());
            }
        } finally {
            lock.unlock();
        }
    }

    // Implement serialization, deserialization and graph modification methods here

    @Override
    public String toString() {
        // Return a string representation of the current configuration and status
    }
}
