    if (protocols[index].handle == NULL && protocols[index].init != NULL) {
        handle = protocols[index].init();
        if (handle) {
            protocols[index].deinit = free;
            protocols[index].handle = handle;
        }
    } else {
        handle = protocols[index].handle;
    }
    pthread_mutex_unlock(&protocol_mutex);
    return handle;
}

Connection* allocateConnection(void) {
    Connection* connection;
    void* buf;
    size_t size;

    if (max_connections > 0) {
        sem_wait(&connections_mutex);
        if (max_connections <= num_connections) {
            connection = realloc(connection_list[num_connections - 1], sizeof(ConnectionNode) * max_connections);
            if (!connection) {
                fprintf(stderr, "Buffer exhausted. Maximum capacity reached.\n");
                sem_post(&connections_mutex);
                return NULL;
            }
            connection_list = connection;
        }
        num_connections++;
    } else {
        size = malloc_usable_size(connection_list) + sizeof(ConnectionNode);
        buf = realloc(connection_list, size);
        if (!buf) {
            fprintf(stderr, "Failed to allocate memory for connections list.\n");
            return NULL;
        }
        connection_list = buf;
    }

    connection = &connection_list[num_connections - 1]->connection;
    connection->connectionID = num_connections;
    connection->state = DISCONNECTED;

    sem_post(&connections_mutex);
    return connection;
}

