import hashlib
import os
from io import BytesIO
import threading
import logging

logger = logging.getLogger(__name__)

def md5_file(file_path, chunk_size=64*1024):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

def video_processor_config(num_frames=100, buffer_len=4*1024*1024, seed=None):
    if num_frames <= 0 or buffer_len <= 0:
        raise ValueError("Invalid parameters")

    resolutions = [(640, 360), (1280, 720), (1920, 1080)]
    framerates = [25, 30]

    if seed is not None:
        try:
            import random
            random.seed(seed)
        except ImportError:
            logger.error("Random library not available, falling back to system randomness")

    config = []
    for i in range(num_frames):
        w, h = resolutions[random.randint(0, len(resolutions))], resolutions[random.randint(0, len(resolutions))]
        fps = framerates[random.randint(0, len(framerates))]
        if (w,h) not in [(640, 360), (1280, 720), (1920, 1080)] or fps not in framerates:
            continue
        config.append({"FRAME_WIDTH": w, "FRAME_HEIGHT": h, "FRAMERATE": fps})
    return config
