import os
import sys
import hashlib
import concurrent.futures
import logging
from io import BytesIO

def md5_hasher(file_path, buffer_size=65536):
    digest = hashlib.md5()
    with open(file_path, 'rb') as file:
        for chunk in iter(lambda: file.read(buffer_size), b''):
            digest.update(chunk)
    return digest.hexdigest()

def md5_hasher_multi(directory, buffer_size=65536, workers=os.cpu_count() * 2, log_level=logging.INFO):
    logging.basicConfig(format='%(asctime)s - %(message)s', level=log_level)

    result = {}
    processed_files = set()

    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
            for file in os.listdir(directory):
                if os.path.isfile(os.path.join(directory, file)):
                    processed_files.add(file)
                    future = executor.submit(md5_hasher, os.path.join(directory, file), buffer_size)
                    result[file] = future

        for future in concurrent.futures.as_completed(result):
            file_path = list(result.keys())[list(result.values()).index(future)]
            try:
                result[file_path] = future.result()
                logging.info(f'File {file_path} processed successfully. MD5 Hash: {result[file_path]}')
            except Exception as e:
                logging.error(f'Error processing file {file_path}: {e}')

    except KeyboardInterrupt:
        logging.warning('Interrupted, cleaning up...')
        for file in processed_files:
            try:
                result[file].cancel()
            except Exception as e:
                logging.error(f'Error cancelling processing of file {file}: {e}')

    return result
```

This code defines a function `md5_hasher_multi` that calculates the MD5 hash for multiple files in a given directory, using a buffer size as specified by the user. The function utilizes a ThreadPoolExecutor to handle concurrent file operations safely and can be easily integrated into an existing data pipeline without causing significant bottlenecks. It logs progress and any errors encountered during the hashing process, including errors related to file access permissions and invalid file paths. The results are returned as a dictionary with file paths as keys."]

