import os
import sys
import hashlib
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
import functools
import zipfile
import logging
import shutil
import tempfile
import pickle

class MD5Hasher:
    def __init__(self, directory, cache_file=None, chunk_size=1024 * 1024, compress=False):
        self.directory = directory
        self.cache_file = cache_file or f"{directory}/md5_cache.pickle"
        self.chunk_size = chunk_size
        self.compress = compress
        self.log = logging.getLogger(__name__)
        self.results = {}
        self.lock = threading.Lock()

    def _hash(self, filepath):
        with open(filepath, "rb") as f:
            hasher = hashlib.md5()
            while True:
                data = f.read(self.chunk_size)
                if not data:
                    break
                hasher.update(data)
            return hasher.hexdigest()

    def _load_cache(self):
        if os.path.exists(self.cache_file):
            with open(self.cache_file, "rb") as f:
                results = pickle.load(f)
            self.results.update(results)

    def _save_cache(self):
        with open(self.cache_file, "wb") as f:
            pickle.dump(self.results, f)

    def _is_modified(self, filepath):
        mtime = os.stat(filepath).st_mtime
        return mtime > self.last_mod_time

    @functools.lru_cache()
    def get_hash(self, filepath):
        with self.lock:
            if filepath in self.results:
                return self.results[filepath]
        if not self._is_modified(filepath):
            return self.results[filepath]
        self.log.debug(f"Recalculating hash for {filepath}")
        hasher = self._hash(filepath)
        with self.lock:
            self.results[filepath] = hasher
        return hasher

    def _process_file(self, filepath):
        try:
            hasher = self.get_hash(filepath)
            if not os.path.islink(filepath):
                self.log.debug(f"Processing {filepath} - Hash: {hasher}")
            else:
                symlink_target = os.readlink(filepath)
                hasher = self._process_file(symlink_target)
                os.makedirs(os.path.dirname(filepath), exist_ok=True)
                with open(filepath, "w") as symlink:
                    symlink.write(symlink_target)
        except Exception as e:
            self.log.error(f"Error processing {filepath}: {e}")
        return hasher

    def _process_directory(self, directory):
        for root, dirs, files in os.walk(directory):
            for file in files:
                filepath = os.path.join(root, file)
                if not self._is_modified(filepath):
                    continue
                hasher = self._process_file(filepath)
                self.results[os.path.relpath(filepath, self.directory)] = hasher
            for dir in dirs:
                self._process_directory(os.path.join(root, dir))

    def run(self):
        self._load_cache()
        self._process_directory(self.directory)
        self._save_cache()

    def rehash(self):
        if not os.path.exists(self.cache_file):
            return True
        last_mod_time = os.stat(self.cache_file).st_mtime
        current_mod_time = time.time()
        if current_mod_time - last_mod_time > 60 * 60:  # One hour gap for rehashing
            return True
        self.log.debug(f"Skipping rehash since cache is less than an hour old")
        return False

    def background_task(self):
        while True:
            if self.rehash():
                self.run()
            time.sleep(60 * 60)  # One hour interval for checking directory changes

if __name__ == "__main__":
    import threading

    hasher = MD5Hasher("path/to/directory")
    hasher.background_task().start()
    hasher.run()
```

This code provides a `MD5Hasher` class that can calculate the MD5 hash of a directory recursively, handle symbolic links safely, and caches results to avoid rehashing unchanged files. The function supports chunked processing for large directories, background threading to monitor changes to the directory, concurrent access from multiple processes or threads without conflicts, robust logging, resumable operations, and optional compression of the hash map.']

