import os
import hashlib
import hmac
from concurrent.futures import ThreadPoolExecutor, as_completed
import aiofiles
import time
import zipfile
import logging
import sys
import functools
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import hashes, ciphers
from cryptography.hazmat.primitives.asymmetric import padding

class HashWorker:
    def __init__(self, digests, key=None):
        self.digests = digests
        self.key = key
        self.hashes = {}
        self.lock = asyncio.Lock()

    async def _hash_file(self, filepath):
        if filepath in self.hashes:
            return self.hashes[filepath]

        try:
            with aiofiles.open(filepath, 'rb') as f:
                chunk = await aiofiles.readall(f, 65536)
                while chunk:
                    data = chunk.read()
                    if self.key:
                        h = hmac.new(self.key, data, hashlib.md5).digest()
                    else:
                        h = hashlib.md5(data).digest()
                    for digest in self.digests:
                        hasher = getattr(hmac, digest) if self.key else getattr(hashlib, digest)
                        chunk = await aiofiles.readall(f, 65536)
                        while chunk:
                            data = chunk.read()
                            h = hasher(data + h).digest()
                    self.hashes[filepath] = binascii.hexlify(h).decode('utf-8')
        except Exception as e:
            logging.error(f'Error while hashing file {filepath}: {e}')

        return self.hashes[filepath]

    async def _monitor_directory(self, directory, delay=1):
        while True:
            await asyncio.sleep(delay)
            for entry in os.scandir(directory):
                if not entry.is_dir():
                    await self._hash_file(entry.path)

def calculate_hashes(directory, key=None, digests=['md5', 'sha256'], compression=True, delay=1, num_workers=4):
    executor = ThreadPoolExecutor(max_workers=num_workers)
    tasks = [executor.submit(HashWorker, digests, key) for _ in range(num_workers)]

    worker_results = dict((t.result(), w) for t, w in zip(as_completed(tasks), tasks))

    hashed_files = {}
    processed_files = set()
    root_files = set(os.listdir(directory))

    def hash_file(filepath):
        if filepath not in processed_files:
            worker = worker_results[len(worker_results)]
            processed_files.add(filepath)
            hashed_file = worker._hash_file(os.path.join(directory, filepath))
            return hashed_file
        else:
            return hashed_files.get(filepath, None)

    for root, dirs, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            hashed_files[file] = hash_file(file)

    if compression:
        with zipfile.ZipFile('hashes.zip', 'w') as zf:
            for file, hexdigest in hashed_files.items():
                with open(file, 'rb') as f:
                    zf.writestr(f, hexdigest)

    thread = threading.Thread(target=_monitor_directory, args=(directory, delay))
    thread.daemon = True
    thread.start()

    return hashed_files
```

