import boto3
from botocore.exceptions import NoCredentialsError, ClientError

class FileHash:
    def __init__(self, directory, buffer_size=65536, num_workers=os.cpu_count(), output_format='json', autoscale=True, max_concurrency=None, cloud_storage=False, cloud_auth={}, cache_enabled=True):
        self.directory = directory
        self.buffer_size = buffer_size
        self.num_workers = num_workers if max_concurrency is None else min(max_concurrency, num_workers)
