        self.autoscale = autoscale
        self.cache_enabled = cache_cached_hashes = {}

        self.s3 = None if not cloud_storage else boto3.client('s3', **cloud_auth)

    @lru_cache(maxsize=128)
    def get_file_stats(self, filepath):
        try:
            stats = os.stat(filepath)
        except FileNotFoundError:
            return None
        return {
            'mtime': stats.st_mtime,
            'size': stats.st_size,
            'extension': os.path.splitext(filepath)[1]
        }

    async def hash_file(self, filepath):
        if filepath in self.cache_cached_hashes:
            return self.cache_cached_hashes[filepath]

        try:
            with aiofiles.open(filepath, mode='rb') as f:
                hasher = hashlib.md5()
                for chunk in iter(lambda: f.read(self.buffer_size), b''):
                    if not self.autoscale or not self.is_system_under_load():
                        hasher.update(chunk)

            result = {
                'filepath': filepath,
                'md5': hasher.hexdigest()
            }

            if self.s3:
                await self.upload_to_s3(result, f'{os.path.basename(filepath)}.hash')

            self.cache_cached_hashes[filepath] = result
            return result
        except Exception as e:
            logging.error(f"Error while hashing {filepath}: {e}")
            return None

    def is_system_under_load(self):
        # Implement a mechanism to check system load and network bandwidth, returning True when the system is under heavy load or network bandwidth is low
        pass

    async def hash_files(self):
        if not self.autoscale:
            worker = self.hash_file
        else:
            worker = self._async_autoscaling_worker

        with concurrent.futures.ThreadPoolExecutor(max_workers=self.num_workers) as executor:
            results = list(executor.map(worker, [f for f in os.listdir(self.directory) if not f.startswith('.')]))
        return {r['filepath']: r['md5'] for r in results if r is not None}

    async def _async_autoscaling_worker(self, filepath):
        file_stats = self.get_file_stats(filepath)
        if file_stats is None or (time.time() - file_stats['mtime'] > 60 * 60):  # 1 hour old
            return await self.hash_file(filepath)

    def run(self, sync=True):
        if sync:
            results = self.hash_files()
        else:
            asyncio.run(self.hash_files())

        if self.output_format in ['json', 'yaml']:
            output_format = f'{self.output_format}://'
        elif self.output_format == 'parquet':
            output_format = h5py.File

        if results:
            with open('file_hashes.%s' % self.output_format, 'w') as f:
                if self.output_format == 'json':
                    import json
                    json.dump(results, f)
                elif self.output_format == 'yaml':
                    import yaml
                    yaml.dump(results, f)
                else:  # parquet
                    for filepath, md5 in results.items():
                        dataset = h5py.Dataset(f'{filepath}_hash', dtype=h5py.special_dtype(vlen=md5))
                        dataset[()] = md5
            logging.info(f"File hashes saved to file_hashes.%s", self.output_format)
        else:
            logging.error("No valid file hashes could be generated")
