#include <list>
#include <memory>
#include <boost/circular_buffer.hpp>
#include <boost/mutex.hpp>
#include <chrono>
#include <mutex>
#include <utility>

struct PHY_CHANNEL_STATE_T {
    int CHANNEL_ID;
    double SINR, BER, RSSI;
    std::chrono::time_point<std::chrono::steady_clock> timestamp;
    boost::circular_buffer<std::pair<std::chrono::time_point<std::chrono::steady_clock>, int>> history; // (timestamp, action: ADD, REMOVE, UPDATE)
};

class ChannelManager {
private:
    std::list<std::shared_ptr<PHY_CHANNEL_STATE_T>> channels_;
    mutex data_mutex_;
public:
    void addChannel(int id, double sinr, double ber, double rssi) {
        std::shared_ptr<PHY_CHANNEL_STATE_T> channel = std::make_shared<PHY_CHANNEL_STATE_T>();
        channel->CHANNEL_ID = id;
        channel->SINR = sinr;
        channel->BER = ber;
        channel->RSSI = rssi;
        channel->timestamp = std::chrono::steady_clock::now();
        data_mutex_.lock();
        channels_.push_back(channel);
        data_mutex_.unlock();
    }

    bool removeChannel(int id) {
        auto it = std::remove_if(channels_.begin(), channels_.end(),
                                [&](const auto& channel) { return channel->CHANNEL_ID == id; });
        if (it != channels_.end()) {
            data_mutex_.lock();
            channels_.erase(it);
