import os
import hashlib
import logging
import sys
import time
from tqdm import tqdm
from functools import lru_cache

BUFFER_SIZE = 4 * (1024 ** 2)  # 4MB buffer size for efficient memory usage and I/O

@lru_cache(maxsize=None)
def get_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(BUFFER_SIZE)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def walk_and_hash(root_path, log=logging.getLogger(__name__)):
    start_time = time.time()
    results = {}
    for root, dirs, files in tqdm(os.walk(root_path), desc='Walking directory'):
        for file in files:
            file_path = os.path.join(root, file)
            if file.startswith('.'):  # Skip hidden files and directories (e.g., .git)
                continue
            try:
                results[file_path] = get_md5(file_path)
            except Exception as e:
                log.error(f'Error calculating MD5 for {file_path}: {e}')

    elapsed_time = time.time() - start_time
    log.info(f'Finished calculating MD5 hashes for {root_path}. Elapsed: {elapsed_time} seconds')
    return results

def main():
    root_path = sys.argv[1] if len(sys.argv) > 1 else '.'
    log_level = logging.INFO
    if len(sys.argv) > 2:
        log_level = getattr(logging, sys.argv[2].upper(), None)
    if not log_level:
        log_level = logging.getLevelName('WARNING')

    logging.basicConfig(format='%(asctime)s - %(name)s - %(levelname)s - %(message)s', level=log_level)
    results = walk_and_hash(root_path, logging.getLogger(__name__))
    print(results)

if __name__ == '__main__':
    main()
