    valid_keys = {'metrics', 'interval', 'threshold', 'storage_path', 'notification_method'}

    if not set(config.keys()) <= valid_keys:
        raise ValueError("Invalid configuration file. Missing necessary keys.")

    collectors = cachetools.TTLCache(maxsize=100, ttl=60)  # Cache parsed configurations for 1 minute
    collector_notifications = {}

    for metric in config['metrics']:
        if metric not in collectors:
            collector = MetricCollector(**config['metrics'][metric])
            collectors[metric] = collector
            collector_notifications[metric] = config['metrics'][metric]['notification_method']
        else:
            collector = collectors[metric]

