            collector.fetch_and_store()
            collectors[metric] = collector
        except Exception as e:
            print(f"Error initializing metric '{metric}': {e}")

    while True:
        for collector in collectors.values():
            try:
                collector.fetch_and_store()
                collector.check_threshold()
            except Exception as e:
                print(f"Error during metric '{collector.name}' collection and threshold check: {e}")
        time.sleep(60)  # Adjust interval as needed

    return collectors, collector_notifications
