struct node {
    struct connection* conn;
    struct metadata* meta;
    struct node* next;
};

// Thread-safe linked list for efficient memory management
struct thread_safe_list {
    pthread_mutex_t lock;
    struct node* head;
};

// Initialize the thread-safe list and network protocols
void initialize() {
