        if (load_protocol(i) != 0) {
            LOG_ERROR("Failed to load protocol %d", i);
        }
    }
}

// Function to allocate a new connection object and metadata record, compressing metadata if necessary
struct connection* new_connection() {
    struct connection* conn = malloc(sizeof(struct connection));
    if (!conn) {
        LOG_WARNING("Failed to allocate memory for new connection");
        return NULL;
    }

    conn->connectionID = getpid();
    conn->socket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (conn->socket == -1) {
        LOG_ERROR("Failed to create socket");
        free(conn);
        return NULL;
    }

    struct metadata* meta = malloc(sizeof(struct metadata));
    if (!meta) {
        LOG_WARNING("Failed to allocate memory for new metadata record");
        close(conn->socket);
        free(conn);
        return NULL;
    }

    meta->timestamp = (time_t)rand() % 1001;
    memset(meta->clientIP, 0, sizeof(meta->clientIP));
    memset(meta->serverIP, 0, sizeof(meta->serverIP));

    // Compress metadata if space is constrained
    if (sizeof(struct metadata) > COMPRESSION_RATIO * MAX_BUFFER_SIZE) {
        compress(meta);
    }

    return conn;
}

// Function to handle dynamic resource management in a multi-threaded environment
void handleDynamicResourceManagement() {
    struct thread_safe_list list = { .head = NULL };
    pthread_mutex_init(&list.lock, NULL);

    // Performance metrics variables
    clock_t start, end;
    double elapsed_time;
    int successful_allocations = 0;

    start = clock();

    while (1) {
        // Allocate a new connection and metadata pair and add them to the thread-safe list
        struct connection* new_conn = new_connection();
        if (!new_conn) continue;

        pthread_mutex_lock(&list.lock);
        struct node* new_node = malloc(sizeof(struct node));
        if (new_node == NULL) {
            LOG_WARNING("Failed to allocate memory for new node");
            free(new_conn->meta);
            close(new_conn->socket);
            free(new_conn);
            pthread_mutex_unlock(&list.lock);
            continue;
        }

        new_node->conn = new_conn;
        new_node->next = list.head;
        list.head = new_node;
        successful_allocations++;
        pthread_mutex_unlock(&list.load_balancer_lock);
    }

    end = clock();
    elapsed_time = (double)(end - start) / CLOCKS_PER_SEC;

    // Log performance metrics and deinitialize resources
    LOG_INFO("Allocated %d connections in %.6f seconds", successful_allocations, elapsed_time);

    for (int i = 0; i < NUM_PROTOCOLS; ++i) {
        unload_protocol(i);
    }

    logger_deinit();
}
