  for await (const chunk of readableStreamFromPath(path)) {
    chunks.push(chunk);
  }

  let h = crypto.createHash('md5');
  for (let i = 0; i < chunks.length; i++) {
    h.update(chunks[i]);
  }

  return h.digest('hex');
}

async function md5Dir(path, extensions) {
  const promises = [];

  for await (const entry of readableStreamFromDirectory(path)) {
    if (!entry.isDir && extensions.some(ext => entry.name.endsWith(ext))) {
      if (!(await isHidden(entry.path))) {
        promises.push(getFileMd5(entry.path));
      }
    } else if (entry.isDir && !entry.path.endsWith('__pycache__')) {
      promises.push(md5Dir(entry.path, extensions));
    } else if (entry.isSymlink) {
