        const linkedPath = await readlink(entry.path);
        promises.push(md5Dir(linkedPath, extensions));
      } catch (err) {
        // Handle errors appropriately, e.g., skip the symlink and continue processing other entries
      }
    }
  }

  const hashes = await Promise.allSettled(promises);
  let md5 = crypto.createHash('md5');
  for (const res of hashes) {
    if (res.status === 'fulfilled') {
      md5.update(Buffer.from(res.value, 'hex'));
    }
  }

  return md5.digest('hex');
}
