from pathlib import Path
import glob

def md5_hash(directory):
    m = hashlib.md5()
    for entry in sorted(os.scandir(directory)):
        if not entry.is_file():
            continue
        ext = entry.name.lower().split('.')[-1]
        if ext not in ['txt', 'log'] or entry.name.startswith('.'):
            continue
        with open(entry, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                m.update(chunk)
    return m.hexdigest()

def md5_tree(root, recursive=True):
    if not root or not os.path.isdir(root):
        return None

    path = Path(root)
    hashes = {}

    for entry in sorted(os.scandir(path)):
        if not entry.is_file():
            continue
        ext = entry.name.lower().split('.')[-1]
        if ext not in ['txt', 'log'] or entry.name.startswith('.'):
            continue
        hash_key = path / entry.name
        hashes[hash_key] = md5_hash(str(hash_key))

        if recursive and entry.is_dir():
            sub_hashes = md5_tree(entry, recursive=recursive)
            hashes.update(sub_hashes or {})

    return hashes
