def md5sum(directory, filter_func=lambda x: True):
    m = hashlib.md5()
    for root, _, files in sorted(os.walk(directory)):
        if root == directory and not root.endswith("."):  # exclude hidden directories
            continue
        for name in sorted(files):
            if not name.endswith(('.txt', '.log')) or not name.startswith('.'):  # consider only .txt & .log files
                continue
            if not filter_func(name):
                continue
            path = os.path.join(root, name)
            try:
                with open(path, "rb") as f:
                    chunk = f.read(65536)  # read files in chunks
                    while chunk:
                        m.update(chunk)
                        chunk = f.read(65536)
            except Exception as e:
                print(f"Error reading {path}: {e}")
                continue

    return m.hexdigest()

# For JavaScript part, I'm providing a separate function for API integration and parallel processing
async function processNumbers(numbers, apiUrl, maxConcurrentTasks=4, retries=3) {
    const chunkSize = Math.ceil(numbers.length / maxConcurrentTasks);
    let tasks = numbers.map((number, i) =>
        new Promise((resolve, reject) => {
            let attempt = 0;
            function process() {
                if (attempt >= retries) {
                    return reject(new Error(`Failed to process ${number} after ${retries} attempts`));
                }
                fetch(`${apiUrl}/${number}`)
                    .then((response) => response.json())
                    .then(data => resolve({ number, data }))
                    .catch(() => {
                        attempt++;
                        setTimeout(process, 1000);
                    });
            }
            if (attempt === 0) process();
        })
    );

    await Promise.allSettled(tasks, { concurrency: maxConcurrentTasks });

    return tasks.map((promise, i) => promise.then(result => ({ ...result, number: numbers[i * chunkSize + (promise.length > 1 ? Math.floor(promise.length / 2) : 0)] })));
}
