from concurrent.futures import ThreadPoolExecutor, as_completed
from functools import lru_cache

@lru_cache(maxsize=128)  # Cache function results for performance
def md5sum(filename):
    hasher = hashlib.md5()
    with open(filename, "rb") as f:
        while True:
            data = f.read(4096)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def get_file_extension(filename):
    _, ext = os.path.splitext(filename)
    return ext.lower()

def is_valid_file(filename, filter_func=lambda x: True):
    return (os.path.isfile(filename) and
            not filename.startswith(".") and
            get_file_extension(filename) in [".txt", ".log"] and
            filter_func(get_file_extension(filename)))

def process_dir(root_dir, filter_func=lambda x: True, **kwargs):
    md5 = hashlib.md5()
    executor = ThreadPoolExecutor(max_workers=kwargs.get("num_threads"))

    def process_file(filepath):
        try:
            if not os.path.exists(filepath) or not is_valid_file(filepath, filter_func):
                return None

            file_hash = md5sum(filepath)
            with open(filepath, "rb") as f:
                compressed = gzip.SniffFile(f).read() in [b'\x1f\x8b', b'\xf9\x37\x31']  # gzip magic numbers
                if compressed:
                    with gzip.open(filepath, "rb") as f:
                        data = f.read(4096)
                        while data:
                            md5.update(data)
                            data = f.read(4096)
                else:
                    with open(filepath, "rb") as f:
                        data = f.read(4096)
                        while data:
                            md5.update(data)
                            data = f.read(4096)

            return file_hash
        except Exception as e:  # Handle errors and log them
            print(f"Error processing {filepath}: {e}")
            if kwargs["retry"] > 0:
                return executor.submit(process_file, filepath, **kwargs)

    for root, _, files in os.walk(root_dir):
        for file in files:
            filepath = os.path.join(root, file)
            futures.append(executor.submit(process_file, filepath, **kwargs))

    for future in as_completed(futures):
        if future.exception() is None:
            md5.update(future.result().encode())

    executor.shutdown()
    return md5.hexdigest()
